import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";

/** Compact horizontal pipeline funnel */
function BidPipelineFunnelDiagram({ funnel, totalActive, layout = "horizontal" }) {
  if (!funnel || !funnel.length) {
    return (
      <div className="lux-bid-funnel-diagram lux-bid-funnel-diagram--empty">
        No pipeline data
      </div>
    );
  }

  if (layout === "vertical") {
    const maxCount = Math.max(...funnel.map((s) => s.count), 1);
    return (
      <div className="lux-bid-funnel-diagram lux-bid-funnel-diagram--vertical" role="img" aria-label="Pipeline funnel">
        <div className="lux-bid-funnel-diagram__stages">
          {funnel.map((stage, index) => (
            <div
              key={stage.key}
              className={classNames("lux-bid-funnel-diagram__stage", `is-${stage.tone}`)}
              style={{ "--lux-funnel-width": `${Math.max(28, Math.round((stage.count / maxCount) * 92))}%` }}
            >
              <div className="lux-bid-funnel-diagram__stage-inner">
                <span className="lux-bid-funnel-diagram__stage-label">{stage.label}</span>
                <strong className="lux-bid-funnel-diagram__stage-value">
                  <CountUp end={stage.count} duration={0.7} />
                </strong>
              </div>
              {index < funnel.length - 1 && (
                <div className="lux-bid-funnel-diagram__connector" aria-hidden="true">
                  <i className="fe fe-chevron-down" />
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="lux-bid-funnel-diagram lux-bid-funnel-diagram--horizontal" role="img" aria-label="Pipeline funnel">
      {funnel.map((stage, index) => (
        <React.Fragment key={stage.key}>
          <div className={classNames("lux-bid-funnel-diagram__h-stage", `is-${stage.tone}`)}>
            <span className="lux-bid-funnel-diagram__h-label">{stage.label}</span>
            <strong className="lux-bid-funnel-diagram__h-value">
              <CountUp end={stage.count} duration={0.7} />
            </strong>
            {totalActive > 0 && (
              <span className="lux-bid-funnel-diagram__h-pct">
                {Math.round((stage.count / totalActive) * 100)}%
              </span>
            )}
          </div>
          {index < funnel.length - 1 && (
            <span className="lux-bid-funnel-diagram__h-arrow" aria-hidden="true">
              <i className="fe fe-chevron-right" />
            </span>
          )}
        </React.Fragment>
      ))}
    </div>
  );
}

export default BidPipelineFunnelDiagram;
