import { EMPLOYEE_360_TABS, isEmployee360RouteEnabled } from "config/employee360.config";
import {
  canViewEmployee360 as canViewEmployee360Scope,
  getVisibleEmployee360Tabs as resolveVisibleEmployee360Tabs,
} from "config/employee360-access.utils";

export { resolveVisibleEmployee360Tabs as getVisibleEmployee360Tabs };
export {
  buildEmployee360ViewerContext,
  canViewEmployee360,
  resolveEmployee360AccessDeniedReason,
} from "config/employee360-access.utils";

export function canShowEmployee360Entry(menuAccessControl, activePersona) {
  if (!isEmployee360RouteEnabled(menuAccessControl)) {
    return false;
  }
  return resolveVisibleEmployee360Tabs(activePersona).length > 0;
}

export function canViewEmployee360ForPage(viewerContext, targetEmployeeId, employee, accessAllowed) {
  return canViewEmployee360Scope(viewerContext, targetEmployeeId, employee, accessAllowed);
}

export function resolveEmployee360Id(match, fallbackUserId) {
  const paramId = match && match.params && match.params.employeeId;
  return paramId || fallbackUserId || null;
}

export function getEmployeeDisplayName(employee) {
  if (!employee) {
    return "Employee";
  }
  const first = employee.firstName || employee.fname || "";
  const last = employee.lastName || employee.lname || "";
  const full = `${first} ${last}`.trim();
  return full || employee.name || employee.empCode || "Employee";
}

export function buildEmployee360OverviewMetrics(employee, summary, activePersona) {
  if (!employee && !summary) {
    return [];
  }

  const metrics = [
    {
      id: "status",
      label: "Status",
      value: (employee && employee.active === false) ? "Inactive" : "Active",
      tone: (employee && employee.active === false) ? "warning" : "success",
      hint: "Employment status",
    },
    {
      id: "team",
      label: "Team",
      value:
        (employee && employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name) ||
        (summary && summary.teamName) ||
        "—",
      tone: "primary",
    },
    {
      id: "role",
      label: "Role",
      value:
        (employee && employee.userAccessDetails && employee.userAccessDetails.name) ||
        (summary && summary.roleName) ||
        "—",
    },
    {
      id: "attendance",
      label: "Attendance",
      value: (summary && summary.attendanceToday) || "—",
      tone: summary && summary.attendanceToday === "Present" ? "success" : undefined,
    },
    {
      id: "leave",
      label: "Leave balance",
      value:
        summary && summary.leaveBalanceDays != null
          ? `${summary.leaveBalanceDays} days`
          : "—",
      tone: "info",
    },
    {
      id: "timesheet",
      label: "Timesheet",
      value: (summary && summary.timesheetStatus) || "—",
      tone: summary && summary.timesheetStatus === "Submitted" ? "success" : "warning",
    },
    {
      id: "approvals",
      label: "Pending approvals",
      value: summary && summary.pendingApprovals != null ? String(summary.pendingApprovals) : "—",
      tone: summary && summary.pendingApprovals > 0 ? "warning" : "success",
    },
    {
      id: "profile",
      label: "Profile completion",
      value:
        summary && summary.profileCompletionPct != null
          ? `${summary.profileCompletionPct}%`
          : "—",
    },
  ];

  if (["PAYROLL_MANAGER", "FINANCE_MANAGER", "HR_ADMIN", "ADMIN"].includes(activePersona)) {
    metrics.push({
      id: "payroll",
      label: "Payroll group",
      value: (summary && summary.payrollGroup) || "—",
    });
  }

  return metrics;
}

export function buildEmployee360AttentionItems(summary) {
  if (!summary || !Array.isArray(summary.attentionItems)) {
    return [];
  }
  return summary.attentionItems;
}

export function buildEmployee360ContextLine(employee) {
  if (!employee) {
    return "";
  }
  const parts = [];
  if (employee.userAccessDetails && employee.userAccessDetails.name) {
    parts.push(employee.userAccessDetails.name);
  }
  if (employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name) {
    parts.push(employee.defaultUserTeamDetails.name);
  }
  if (employee.empCode) {
    parts.push(employee.empCode);
  }
  return parts.join(" · ");
}

export function getEmployee360PageTitle(employee, activePersonaLabel) {
  const name = getEmployeeDisplayName(employee);
  if (activePersonaLabel) {
    return `${name} · ${activePersonaLabel} view`;
  }
  return name;
}
