import React, { Component } from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";
import { approvalPolicyService } from "_services/approvalPolicy.service";
import {
  buildApprovalMatchContextTemplate,
  parseApprovalMatchContextJson,
} from "config/approval-policy.config";
import "./ApprovalPolicySimulationPanel.css";

function resultTone(value) {
  return value ? "is-success" : "is-muted";
}

function transitionEntries(step) {
  return step && step.transitions ? Object.entries(step.transitions) : [];
}

export function ApprovalPolicySimulationResult({ result }) {
  if (!result) {
    return (
      <div className="lux-appr-policy-sim__result-empty">
        <i className="fe fe-play-circle" aria-hidden="true" />
        <strong>Ready to simulate</strong>
        <span>Select a stored draft and provide a canonical match context.</span>
      </div>
    );
  }
  const warnings = [...(result.errors || []), ...(result.warnings || [])];
  return (
    <div className="lux-appr-policy-sim__result" data-testid="approval-policy-simulation-result">
      <div className="lux-appr-policy-sim__verdict">
        <span className={result.matched ? "is-success" : "is-warning"}>
          <i
            className={result.matched ? "fe fe-check-circle" : "fe fe-alert-triangle"}
            aria-hidden="true"
          />
        </span>
        <div>
          <small>Simulation verdict</small>
          <strong>{result.matched ? "Policy matched" : "Policy did not match"}</strong>
          <em>
            {[result.policyRef, result.policyVersion != null ? `v${result.policyVersion}` : null]
              .filter(Boolean)
              .join(" · ") || "Stored draft"}
          </em>
        </div>
      </div>

      <div className="lux-appr-policy-sim__checks" aria-label="Policy match checks">
        {[
          ["Valid", result.valid],
          ["Domain", result.domainMatched],
          ["Scope", result.scopeMatched],
          ["Rules", result.ruleMatched],
        ].map(([label, value]) => (
          <span key={label} className={resultTone(value)}>
            <i className={value ? "fe fe-check" : "fe fe-minus"} aria-hidden="true" />
            {label}
          </span>
        ))}
      </div>

      <section className="lux-appr-policy-sim__result-section">
        <header>
          <strong>Resolver preview</strong>
          <span>
            {result.scopeType || "No scope"} · {result.steps.length} step(s)
          </span>
        </header>
        <div className="lux-appr-policy-sim__steps">
          {result.steps.length ? (
            result.steps.map((step, index) => (
              <article
                key={`${step.stepKey || "step"}-${index}`}
                className={classNames({ "is-unresolved": step.unresolved })}
              >
                <div className="lux-appr-policy-sim__step-head">
                  <span>{step.stepOrder != null ? step.stepOrder : index + 1}</span>
                  <div>
                    <strong>{step.label || step.stepKey || "Unnamed step"}</strong>
                    <em>
                      {step.resolverType || "No resolver"}
                      {step.entry ? " · entry" : ""}
                    </em>
                  </div>
                  <small>
                    {step.unresolved
                      ? "Unresolved"
                      : `${step.resolvedApproverIds.length} approver(s)`}
                  </small>
                </div>
                {transitionEntries(step).length > 0 ? (
                  <div className="lux-appr-policy-sim__transitions">
                    {transitionEntries(step).map(([action, target]) => (
                      <span key={action}>
                        <em>{action.replace(/_/g, " ")}</em>
                        <i className="fe fe-arrow-right" aria-hidden="true" />
                        <strong>{target}</strong>
                      </span>
                    ))}
                  </div>
                ) : null}
              </article>
            ))
          ) : (
            <p>No resolver steps were returned.</p>
          )}
        </div>
      </section>

      <section className="lux-appr-policy-sim__result-section">
        <header>
          <strong>Resolver &amp; transition warnings</strong>
          <span>{warnings.length ? `${warnings.length} found` : "Clear"}</span>
        </header>
        {warnings.length ? (
          <ul className="lux-appr-policy-sim__warnings">
            {warnings.map((warning, index) => (
              <li key={`${warning}-${index}`}>
                <i className="fe fe-alert-circle" aria-hidden="true" />
                {warning}
              </li>
            ))}
          </ul>
        ) : (
          <p className="lux-appr-policy-sim__clear">
            No resolver or transition warnings were returned.
          </p>
        )}
      </section>
    </div>
  );
}

export default class ApprovalPolicySimulationPanel extends Component {
  state = {
    drafts: [],
    loading: false,
    loadError: null,
    selectedDraftId: "",
    contextText: "",
    validationError: null,
    running: false,
    result: null,
  };

  componentDidMount() {
    this.mounted = true;
    if (this.props.enabled) {
      this.loadDrafts();
    }
  }

  componentDidUpdate(previousProps) {
    if (!previousProps.enabled && this.props.enabled) {
      this.loadDrafts();
    }
  }

  componentWillUnmount() {
    this.mounted = false;
  }

  loadDrafts = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const response = await approvalPolicyService.listStoredPolicies();
      if (!this.mounted) return;
      const drafts = (response.payload || []).filter(
        (policy) => String(policy.status).toUpperCase() === "DRAFT"
      );
      const selected = drafts[0] || null;
      this.setState({
        drafts,
        loading: false,
        selectedDraftId: selected ? String(selected.id) : "",
        contextText: selected ? this.contextTemplate(selected) : "",
      });
    } catch (error) {
      if (!this.mounted) return;
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load stored approval drafts.",
        drafts: [],
      });
    }
  };

  contextTemplate = (policy) =>
    JSON.stringify(
      buildApprovalMatchContextTemplate(policy, commonUtils.getCurrentUserTeamId()),
      null,
      2
    );

  handleDraftChange = (event) => {
    const selectedDraftId = event.target.value;
    const selected = this.state.drafts.find(
      (policy) => String(policy.id) === selectedDraftId
    );
    this.setState({
      selectedDraftId,
      contextText: selected ? this.contextTemplate(selected) : "",
      validationError: null,
      result: null,
    });
  };

  parseContext = () =>
    parseApprovalMatchContextJson(this.state.contextText, {
      expectedUserTeamId: commonUtils.getCurrentUserTeamId(),
    });

  handleFormat = () => {
    const parsed = this.parseContext();
    this.setState({
      validationError: parsed.error,
      contextText: parsed.payload
        ? JSON.stringify(parsed.payload, null, 2)
        : this.state.contextText,
    });
  };

  handleRun = async () => {
    if (!this.state.selectedDraftId) {
      this.setState({ validationError: "Select a stored draft to simulate." });
      return;
    }
    const parsed = this.parseContext();
    if (parsed.error) {
      this.setState({ validationError: parsed.error, result: null });
      return;
    }
    this.setState({ running: true, validationError: null, result: null });
    try {
      const response = await approvalPolicyService.simulateStoredDraft(
        this.state.selectedDraftId,
        parsed.payload
      );
      if (!this.mounted) return;
      this.setState({ running: false, result: response.payload });
    } catch (error) {
      if (!this.mounted) return;
      this.setState({
        running: false,
        validationError: (error && error.message) || "Policy simulation failed.",
      });
    }
  };

  render() {
    if (!this.props.enabled) {
      return null;
    }
    const {
      drafts,
      loading,
      loadError,
      selectedDraftId,
      contextText,
      validationError,
      running,
      result,
    } = this.state;
    return (
      <section className="lux-appr-policy-sim" data-testid="approval-policy-simulation">
        <header className="lux-appr-policy-sim__head">
          <span aria-hidden="true">
            <i className="fe fe-play" />
          </span>
          <div>
            <p>Draft evaluation</p>
            <h2>Approval policy test bench</h2>
            <small>
              Evaluate a persisted draft against canonical match context without publishing or
              activating it.
            </small>
          </div>
          <em>Does not publish</em>
        </header>

        <div className="lux-appr-policy-sim__body">
          <div className="lux-appr-policy-sim__setup">
            {loadError ? (
              <p className="lux-appr-policy-sim__error" role="alert">
                {loadError}
              </p>
            ) : null}
            <label>
              <span>Stored draft</span>
              <select
                value={selectedDraftId}
                onChange={this.handleDraftChange}
                disabled={loading || running || !drafts.length}
                data-testid="approval-policy-simulation-draft"
              >
                {!drafts.length ? (
                  <option value="">{loading ? "Loading drafts…" : "No stored drafts available"}</option>
                ) : null}
                {drafts.map((policy) => (
                  <option key={policy.id} value={String(policy.id)}>
                    {policy.name} · {policy.domain || "No domain"} · v
                    {policy.policyVersion != null ? policy.policyVersion : "—"}
                  </option>
                ))}
              </select>
            </label>

            <label>
              <span>Match context JSON</span>
              <textarea
                rows={13}
                value={contextText}
                onChange={(event) =>
                  this.setState({
                    contextText: event.target.value,
                    validationError: null,
                    result: null,
                  })
                }
                spellCheck={false}
                disabled={running || !selectedDraftId}
                data-testid="approval-policy-match-context"
              />
            </label>
            <small className="lux-appr-policy-sim__context-hint">
              Required: organizationId, userTeamId, domain, sourceId, sourceRef, and attributes.
              Current-team scope is enforced locally and by the server.
            </small>
            {validationError ? (
              <p className="lux-appr-policy-sim__error" role="alert">
                {validationError}
              </p>
            ) : null}
            <div className="lux-appr-policy-sim__actions">
              <button
                type="button"
                className="is-ghost"
                onClick={this.handleFormat}
                disabled={running || !contextText}
              >
                <i className="fe fe-code" aria-hidden="true" />
                Validate &amp; format
              </button>
              <button
                type="button"
                className="is-primary"
                onClick={this.handleRun}
                disabled={running || !selectedDraftId}
                data-testid="approval-policy-simulate"
              >
                <i className="fe fe-play" aria-hidden="true" />
                {running ? "Simulating…" : "Run simulation"}
              </button>
            </div>
          </div>
          <ApprovalPolicySimulationResult result={result} />
        </div>
      </section>
    );
  }
}
