import React from "react";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import { getDeliverableDetailsReturnTarget } from "../deliverableDetailsNavigation.utils";

export default function DeliverableDetailsBackNav({ location, taskInfo, deliverableRef }) {
  const { path, label } = getDeliverableDetailsReturnTarget(location, taskInfo);

  return (
    <LuxBackNav
      to={path}
      destinationLabel={label}
      currentLabel={deliverableRef || undefined}
    />
  );
}
