import React, { useEffect, useMemo, useState } from "react";
import classNames from "classnames/bind";
import moment from "moment";
import dateUtils from "_helpers/date.utils";
import { commonUtils } from "_helpers";
import { workItemService } from "_services/workitem.service";
import {
  buildTimesheetApprovalPreviewModel,
  resolveTimesheetApprovalItemContext,
} from "./timesheetApprovalPreview.utils";
import { toIsoDate } from "./timesheetApproval.utils";

function UniversalApprovalTimesheetPreview({ item }) {
  const context = useMemo(() => resolveTimesheetApprovalItemContext(item), [item]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [timeSheetRequest, setTimeSheetRequest] = useState(null);

  useEffect(() => {
    let cancelled = false;

    async function loadPreview() {
      if (!context.employeeId || !context.weekStartDate) {
        setLoading(false);
        setError("Timesheet week details are missing for this approval request.");
        setTimeSheetRequest(null);
        return;
      }

      setLoading(true);
      setError(null);
      setTimeSheetRequest(null);

      try {
        const weekStart = moment(context.weekStartDate).startOf("isoWeek");
        if (!weekStart.isValid()) {
          throw new Error("Invalid week start date on approval request.");
        }
        const startDate = weekStart.format(dateUtils.SERVER_DATE_FORMAT);
        const endDate = weekStart.clone().endOf("isoWeek").format(dateUtils.SERVER_DATE_FORMAT);
        const userTeamIds = commonUtils.getCurrentUserTeamIds();
        const response = await workItemService.loadTimeSheetData({
          startDate,
          endDate,
          employeeIds: [context.employeeId],
          userTeamIds,
        });
        if (cancelled) {
          return;
        }
        const payload = (response && response.payload) || response;
        if (!payload) {
          setError("Unable to load submitted timesheet hours.");
          return;
        }
        setTimeSheetRequest(payload);
      } catch (loadError) {
        if (!cancelled) {
          setError((loadError && loadError.message) || "Unable to load submitted timesheet hours.");
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    }

    loadPreview();
    return () => {
      cancelled = true;
    };
  }, [context.employeeId, context.weekStartDate]);

  const preview = useMemo(
    () => (timeSheetRequest ? buildTimesheetApprovalPreviewModel(timeSheetRequest, item) : null),
    [timeSheetRequest, item]
  );

  if (loading) {
    return (
      <section
        className="lux-appr-drawer__card lux-appr-ts-preview"
        aria-label="Submitted timesheet hours"
        data-testid="approval-timesheet-preview-loading"
      >
        <header className="lux-appr-drawer__card-head">
          <h3>Submitted hours</h3>
          <p>Loading day-wise entries for this approval request…</p>
        </header>
        <div className="lux-appr-ts-preview__skeleton" aria-hidden="true" />
      </section>
    );
  }

  if (error) {
    return (
      <section
        className="lux-appr-drawer__card lux-appr-ts-preview is-error"
        aria-label="Submitted timesheet hours"
        data-testid="approval-timesheet-preview-error"
      >
        <header className="lux-appr-drawer__card-head">
          <h3>Submitted hours</h3>
          <p>{error}</p>
        </header>
      </section>
    );
  }

  if (!preview) {
    return null;
  }

  return (
    <section
      className="lux-appr-drawer__card lux-appr-ts-preview"
      aria-label="Submitted timesheet hours"
      data-testid="approval-timesheet-preview"
    >
      <header className="lux-appr-drawer__card-head">
        <h3>Submitted hours</h3>
        <p>
          {preview.hasHours
            ? `${preview.batchTotalLabel} across ${preview.daySummaries.length} day${
                preview.daySummaries.length === 1 ? "" : "s"
              } in this approval batch.`
            : "No pending hours were found for this batch on the loaded week."}
        </p>
      </header>

      {preview.daySummaries.length > 0 && (
        <div className="lux-appr-ts-preview__days" role="list" aria-label="Daily totals">
          {preview.daySummaries.map((day) => (
            <div
              key={day.dateKey}
              className={classNames("lux-appr-ts-preview__day", {
                "has-hours": day.totalMins > 0,
                "is-empty": day.totalMins <= 0,
              })}
              role="listitem"
            >
              <span className="lux-appr-ts-preview__day-label">{day.label}</span>
              <strong className="lux-appr-ts-preview__day-hours">{day.hoursLabel}</strong>
              <em>{day.entryCount > 0 ? `${day.entryCount} entr${day.entryCount === 1 ? "y" : "ies"}` : "—"}</em>
            </div>
          ))}
        </div>
      )}

      {preview.entries.length > 0 ? (
        <div className="lux-appr-ts-preview__entries-wrap">
          <table className="lux-appr-ts-preview__entries">
            <thead>
              <tr>
                <th scope="col">Entry</th>
                {preview.previewDates.map((dateKey) => {
                  const iso = toIsoDate(dateKey);
                  const dayMeta = preview.daySummaries.find((day) => day.iso === iso);
                  return (
                    <th key={dateKey} scope="col">
                      {dayMeta ? dayMeta.label : iso ? iso.slice(5) : dateKey}
                    </th>
                  );
                })}
                <th scope="col">Total</th>
              </tr>
            </thead>
            <tbody>
              {preview.entries.map((entry) => (
                <tr key={entry.key}>
                  <td>
                    <strong>{entry.label}</strong>
                    {entry.groupLabel ? <em>{entry.groupLabel}</em> : null}
                    {entry.category ? <span>{entry.category}</span> : null}
                  </td>
                  {preview.previewDates.map((dateKey) => {
                    const iso = toIsoDate(dateKey);
                    const mins = entry.hoursByDate[iso] || 0;
                    return (
                      <td key={`${entry.key}-${dateKey}`} className={mins > 0 ? "has-hours" : "is-empty"}>
                        {mins > 0 ? dateUtils.minuteToHourString(mins) : "—"}
                      </td>
                    );
                  })}
                  <td className="is-total">{entry.totalLabel}</td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr>
                <th scope="row">Batch total</th>
                {preview.previewDates.map((dateKey) => {
                  const iso = toIsoDate(dateKey);
                  const day = preview.daySummaries.find((itemDay) => itemDay.iso === iso);
                  return (
                    <td key={`total-${dateKey}`} className="is-total">
                      {day && day.totalMins > 0 ? day.hoursLabel : "—"}
                    </td>
                  );
                })}
                <td className="is-total">{preview.batchTotalLabel}</td>
              </tr>
            </tfoot>
          </table>
        </div>
      ) : (
        <p className="lux-appr-ts-preview__empty">
          Open the full timesheet board to review the weekly grid if hours are missing here.
        </p>
      )}
    </section>
  );
}

export default UniversalApprovalTimesheetPreview;
