/**
 * F25 — Policy hub registry, versioning, campaigns, and analytics.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import envconfig from "env.config";
import { documentVaultService } from "./documentVault.service";
import { orgStructureService } from "./orgStructure.service";
import { normalizePolicy, normalizePolicyCampaign, POLICY_AUDIT_ACTIONS } from "config/policy-hub.config";
import { buildOrgPolicyAnalytics } from "config/policy-hub.utils";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import { apiErrorResult } from "config/mock-fallback.utils";

export const policyHubService = {
  listPolicies,
  getPolicy,
  listCampaigns,
  publishVersion,
  launchCampaign,
  acknowledgeCampaign,
  listAcknowledgments,
  getAnalytics,
};

const HUB_API_BASE = `${urlConfig.DOCUMENT_VAULT_API_PATH}/policies/hub`;
const CAMPAIGNS_API_BASE = `${urlConfig.DOCUMENT_VAULT_API_PATH}/policies/campaigns`;

function policyTeamQuery(extra = {}) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId(), ...extra };
  return query;
}

function policyActorQuery(extra = {}) {
  const query = {
    userTeamId: commonUtils.getCurrentUserTeamId(),
    actorId: commonUtils.getCurrentUserId(),
    ...extra,
  };
  return query;
}

function policyActorQueryString(extra = {}) {
  const query = policyActorQuery(extra);
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

async function listPolicies() {

  if (envconfig.USE_POLICY_HUB_API === true) {
    try {
      return await (async () => {
        const response = await axiosUtils.getWithParam(HUB_API_BASE, policyTeamQuery());
        const rows = (response && response.payload) || response || [];
        return {
          payload: (Array.isArray(rows) ? rows : []).map(normalizePolicy).filter(Boolean),
          source: "api",
        };
      })();
    } catch (e) {
      return apiErrorResult([]);
    }
  }
  return apiErrorResult([]);
}

async function getPolicy(policyId) {

  if (envconfig.USE_POLICY_HUB_API === true) {
    try {
      return await (async () => {
        const response = await axiosUtils.getWithParam(`${HUB_API_BASE}/${policyId}`, policyTeamQuery());
        const row = (response && response.payload) || response;
        return { payload: normalizePolicy(row), source: "api" };
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }
  return apiErrorResult(null);
}

async function listCampaigns() {

  if (envconfig.USE_POLICY_HUB_API === true) {
    try {
      return await (async () => {
        const response = await axiosUtils.getWithParam(CAMPAIGNS_API_BASE, policyTeamQuery());
        const rows = (response && response.payload) || response || [];
        return {
          payload: (Array.isArray(rows) ? rows : []).map(normalizePolicyCampaign).filter(Boolean),
          source: "api",
        };
      })();
    } catch (e) {
      return apiErrorResult([]);
    }
  }
  return apiErrorResult([]);
}

async function publishVersion(policyId, payload) {
  if (envconfig.USE_POLICY_HUB_API === true) {
    try {
      return await (async () => {
        const response = await axiosUtils.post(
          `${HUB_API_BASE}/${policyId}/versions?${policyActorQueryString()}`,
          payload || {}
        );
        const result = {
          payload: normalizePolicy((response && response.payload) || response),
          source: "api",
        };
        recordAuditEvent({
          actionType: POLICY_AUDIT_ACTIONS.PUBLISHED,
          entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
          entityId: policyId,
          entityRef: result.payload && result.payload.title,
          metadata: {
            version: result.payload && result.payload.currentVersion,
            publishedBy: payload && payload.publishedBy,
          },
        });
        return result;
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }
  return apiErrorResult(null);
}

async function launchCampaign(payload) {
  if (envconfig.USE_POLICY_HUB_API === true) {
    try {
      return await (async () => {
        const response = await axiosUtils.post(
          `${HUB_API_BASE}/campaigns?${policyActorQueryString()}`,
          payload || {}
        );
        const result = {
          payload: normalizePolicyCampaign((response && response.payload) || response),
          source: "api",
        };
        recordAuditEvent({
          actionType: "CREATED",
          entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
          entityRef: result.payload && result.payload.policyTitle,
          metadata: {
            campaignId: result.payload && result.payload.id,
            audience: result.payload && result.payload.audience,
          },
        });
        return result;
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }
  return apiErrorResult(null);
}

async function acknowledgeCampaign(campaignId, employeeName) {
  if (envconfig.USE_POLICY_HUB_API === true) {
    try {
      return await (async () => {
        const response = await axiosUtils.post(
          `${HUB_API_BASE}/campaigns/${campaignId}/acknowledge?${policyActorQueryString({
            employeeName: employeeName || undefined,
          })}`
        );
        const result = {
          payload: normalizePolicyCampaign((response && response.payload) || response),
          source: "api",
        };
        recordAuditEvent({
          actionType: POLICY_AUDIT_ACTIONS.ACKNOWLEDGED,
          entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
          entityRef: result.payload && result.payload.policyTitle,
          correlationId: campaignId,
          metadata: { employeeName },
        });
        return result;
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }
  return apiErrorResult(null);
}

async function listAcknowledgments() {
  return documentVaultService.listPolicies();
}

async function getAnalytics() {
  const [policiesResult, campaignsResult, ackResult, chartResult] = await Promise.all([
    listPolicies(),
    listCampaigns(),
    listAcknowledgments(),
    orgStructureService.getOrgChart(),
  ]);
  const employees = (chartResult.payload && chartResult.payload.employees) || [];
  const orgUnits = (chartResult.payload && chartResult.payload.orgUnits) || [];
  return {
    payload: buildOrgPolicyAnalytics(
      employees,
      orgUnits,
      policiesResult.payload,
      campaignsResult.payload,
      ackResult.payload
    ),
    source: policiesResult.source || campaignsResult.source || chartResult.source || "client",
  };
}
