import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

export default function PerformanceLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo performance data",
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  pageHeaderNameChangeHandler,
  shellTitle,
  testId,
  pageId,
  children,
  moduleClass = "lux-perf-module",
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "rose",
    icon: "fe fe-award",
    eyebrow: "Talent",
    titleLead: "Performance",
    titleAccent: "dashboard",
    lede: "Goals, reviews, and growth across the organization.",
  };

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div
      className={classNames("lux-register-page", moduleClass, "lux-perf-lux", meta.tone && `is-${meta.tone}`)}
      data-testid={testId || (pageId ? `page-performance-${pageId}` : undefined)}
    >
      <div className="lux-perf-lux__ambient" aria-hidden="true">
        <span className="lux-perf-lux__orb lux-perf-lux__orb--a" />
        <span className="lux-perf-lux__orb lux-perf-lux__orb--b" />
        <span className="lux-perf-lux__orb lux-perf-lux__orb--c" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />

      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <LuxKpiStrip cards={kpiCards} loading={loading} className="lux-perf-lux__kpi-strip" />
        ) : null}

        <div className="lux-perf-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function PerformanceActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-perf-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function PerformanceLuxPanel({ title, meta, icon, accent, featured, actions, children, className }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-perf-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-perf-lux__panel--featured",
        className
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-perf-lux__panel-head">
        <div className="lux-perf-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-perf-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-perf-lux__panel-body">{children}</div>
    </section>
  );
}

export function PerformanceInsightPanel({ insights, className }) {
  if (!insights || !insights.length) {
    return null;
  }
  return <AdminInsightStrip insights={insights} className={classNames("lux-perf-lux__insights", className)} />;
}

export function PerformanceStatusBadge({ status }) {
  const label = String(status || "").replace(/_/g, " ");
  return <span className={classNames("lux-perf-badge", status && `lux-perf-badge--${status}`)}>{label}</span>;
}
