import { accessUtils } from "_helpers";
import { shouldUseSystemErrorsAdmin } from "config/tracopus-pilot.config";

/** Org master for System Errors (default on). */
export function isSystemErrorsAdminEnabled() {
  return shouldUseSystemErrorsAdmin();
}

/**
 * Role + org gate for Admin → System errors (`adminModules.systemErrorsEnabled`).
 * Default on when the role key is unset; set the role flag to false to hide.
 */
export function isSystemErrorsEnabled() {
  const menu = accessUtils.getMenuAccessControl() || {};
  const admin = menu.adminModules || {};
  if (Object.prototype.hasOwnProperty.call(admin, "systemErrorsEnabled")) {
    return admin.systemErrorsEnabled === true;
  }
  return isSystemErrorsAdminEnabled();
}

