import React from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { KnowledgeActionButton, RcaStatusBadge } from "views/knowledge/components/KnowledgeLuxShared";
import KnowledgeAiRcaPanel from "views/knowledge/components/KnowledgeAiRcaPanel";

export default function RcaDetailDrawer({
  record,
  aiDraft,
  aiLoading,
  busy,
  onClose,
  onSubmit,
  onApprove,
  onReject,
}) {
  if (!record) {
    return null;
  }

  const accent = record.status === "approved" ? "emerald" : record.severity === "high" ? "danger" : "rose";
  const openPreventive = (record.preventiveActions || []).filter((item) => item.status !== "closed").length;
  const openCorrective = (record.correctiveActions || []).filter((item) => item.status !== "done").length;

  return createPortal(
    <div className="lux-krca-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className={classNames("lux-krca-drawer", `lux-krca-drawer--${accent}`)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="lux-krca-drawer-title"
        onClick={(e) => e.stopPropagation()}
      >
        <span className="lux-krca-drawer__accent" aria-hidden="true" />

        <header className="lux-krca-drawer__head">
          <div className="lux-krca-drawer__head-main">
            <span className="lux-krca-drawer__category-icon" aria-hidden="true">
              <i className="fe fe-target" />
            </span>
            <div className="lux-krca-drawer__head-copy">
              <span className="lux-krca-drawer__eyebrow">{record.number} · {record.projectName}</span>
              <h2 id="lux-krca-drawer-title">{record.title}</h2>
              <div className="lux-krca-drawer__badges">
                <RcaStatusBadge status={record.status} />
                <span className="lux-krca-drawer__severity">{record.severity} severity</span>
              </div>
            </div>
          </div>
          <button type="button" className="lux-krca-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-krca-drawer__body">
          <p className="lux-krca-drawer__lede">{record.summary}</p>

          <div className="lux-krca-drawer__metrics">
            <article>
              <span>Category</span>
              <strong>{record.category}</strong>
            </article>
            <article>
              <span>Open corrective</span>
              <strong>{openCorrective}</strong>
            </article>
            <article>
              <span>Open preventive</span>
              <strong>{openPreventive}</strong>
            </article>
          </div>

          {record.rootCause ? (
            <section className="lux-krca-drawer__section">
              <h3>Root cause</h3>
              <div className="lux-krca-drawer__notes-card">
                <p>{record.rootCause}</p>
              </div>
            </section>
          ) : null}

          {(record.correctiveActions || []).length ? (
            <section className="lux-krca-drawer__section">
              <h3>Corrective actions</h3>
              <ul className="lux-krca-action-list">
                {record.correctiveActions.map((item) => (
                  <li key={item.id} className={classNames("lux-krca-action-row", item.status === "done" && "is-done")}>
                    <span>{item.label}</span>
                    <span className="lux-krca-action-row__status">{item.status}</span>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}

          {(record.preventiveActions || []).length ? (
            <section className="lux-krca-drawer__section">
              <h3>Preventive actions</h3>
              <ul className="lux-krca-action-list">
                {record.preventiveActions.map((item) => (
                  <li key={item.id} className={classNames("lux-krca-action-row", item.status === "closed" && "is-done")}>
                    <span>{item.label}</span>
                    <span className="lux-krca-action-row__status">{item.status}</span>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}

          {(record.evidenceLinks || []).length ? (
            <section className="lux-krca-drawer__section">
              <h3>Evidence links</h3>
              <ul className="lux-krca-link-list">
                {record.evidenceLinks.map((path) => (
                  <li key={path}>
                    <Link to={path} className="lux-krca-link-chip">
                      <i className="fe fe-external-link" aria-hidden="true" />
                      {path}
                    </Link>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}

          <KnowledgeAiRcaPanel draft={aiDraft} loading={aiLoading} embedded />
        </div>

        <footer className="lux-krca-drawer__footer">
          {record.status === "draft" ? (
            <KnowledgeActionButton variant="primary" onClick={() => onSubmit && onSubmit(record)} disabled={busy}>
              Submit for approval
            </KnowledgeActionButton>
          ) : null}
          {record.status === "in_review" ? (
            <>
              <KnowledgeActionButton variant="primary" onClick={() => onApprove && onApprove(record)} disabled={busy}>
                Approve RCA
              </KnowledgeActionButton>
              <KnowledgeActionButton onClick={() => onReject && onReject(record)} disabled={busy}>
                Return to draft
              </KnowledgeActionButton>
            </>
          ) : null}
          <KnowledgeActionButton onClick={onClose}>Close</KnowledgeActionButton>
        </footer>
      </aside>
    </div>,
    document.body
  );
}
