import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import {
  AnalyticsEvents,
  trackTimesheetAction,
} from "config/analytics-events.config";
import { normalizeTimesheetGovernance, buildTimesheetWorkflowBody } from "views/hrms/components/timesheet/timesheetGovernance.utils";

function withGovernance(result) {
  if (!result || typeof result !== "object") {
    return result;
  }
  const payload = result.payload && typeof result.payload === "object"
    ? result.payload
    : result;
  const governance = normalizeTimesheetGovernance(payload.governance);
  if (!governance) {
    return result;
  }
  if (result.payload && typeof result.payload === "object") {
    return {
      ...result,
      payload: {
        ...result.payload,
        governance,
      },
    };
  }
  return {
    ...result,
    governance,
  };
}

export const timesheetApprovalService = {
  submitWeek,
  resubmitWeek,
  listPending,
  approveWeek,
  rejectWeek,
  approveSubmission,
  rejectSubmission,
  rejectLine,
  listConflicts,
  resolveConflict,
  getHoursConsistency,
  runDataQualityScan,
  lockWeeks,
  unlockWeeks,
  reopenWeek,
  withdrawWeek,
  listDefaulters,
};

async function submitWeek(weekId, actorId, activityDates, workflow) {
  const body = buildTimesheetWorkflowBody({
    activityDates,
    lateReason: workflow && workflow.lateReason,
    lateReasonDetail: workflow && workflow.lateReasonDetail,
  });
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/submit?actorId=${actorId}`,
    body
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_SUBMIT, weekId);
  return withGovernance(result);
}

async function resubmitWeek(weekId, actorId, activityDates, workflow) {
  const body = buildTimesheetWorkflowBody({
    activityDates,
    lateReason: workflow && workflow.lateReason,
    lateReasonDetail: workflow && workflow.lateReasonDetail,
  });
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/resubmit?actorId=${actorId}`,
    body
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_RESUBMIT, weekId);
  return withGovernance(result);
}

async function listPending(userTeamIds, managerId) {
  const params = { managerId };
  if (userTeamIds && userTeamIds.length) {
    params.userTeamIds = userTeamIds;
  }
  return axiosUtils.getWithParam(`${urlConfig.TIMESHEETS_API_PATH}/pending`, params);
}

async function approveWeek(weekId, approverId, approvalComment) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/approve?approverId=${approverId}`,
    { approvalComment: approvalComment || null }
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_APPROVE, weekId);
  return result;
}

async function rejectWeek(weekId, approverId, rejectionComment) {
  const result = await axiosUtils.patch(
    `${urlConfig.TIMESHEETS_API_PATH}/${weekId}/reject?approverId=${approverId}`,
    { rejectionComment }
  );
  trackTimesheetAction(AnalyticsEvents.TIMESHEET_REJECT, weekId);
  return result;
}

