import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isEmployeeFinanceEnabled } from "config/employee-finance.config";
import { EMPLOYEE_FINANCE_PAGE_META } from "config/employee-finance-nav.config";
import { employeeFinanceService } from "_services/employeeFinance.service";
import EmployeeFinanceLuxPage, {
  EmployeeFinanceActionButton,
  EmployeeFinanceInsightPanel,
  EmployeeFinanceLuxPanel,
} from "views/payroll/components/EmployeeFinanceLuxShared";
import EmployeeFinanceOverviewPanel from "views/payroll/components/EmployeeFinanceOverviewPanel";
import CostToRevenueAnalyticsPanel from "views/payroll/components/CostToRevenueAnalyticsPanel";
import EmployeeFinanceMarginRiskPanel from "views/payroll/components/EmployeeFinanceMarginRiskPanel";

class EmployeeFinancePage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    profiles: [],
    advances: [],
    loans: [],
    deductions: [],
    marginSeries: [],
    costToRevenue: null,
    marginRiskFlags: [],
    kpiCards: [],
    insights: [],
    filters: { query: "", hasOpenBalance: false },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Employee finance");
    }
    this.loadData();
  }

  loadData = async (filters = this.state.filters) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await employeeFinanceService.getEmployeeFinanceOverview(filters);
      const overview = result.payload || {};
      this.setState({
        loading: false,
        profiles: overview.profiles || [],
        advances: overview.advances || [],
        loans: overview.loans || [],
        deductions: overview.deductions || [],
        marginSeries: overview.marginSeries || [],
        costToRevenue: overview.costToRevenue || null,
        marginRiskFlags: overview.marginRiskFlags || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load employee finance overview.",
      });
    }
  };

  handleFilterChange = (patch) => {
    const filters = { ...this.state.filters, ...patch };
    this.setState({ filters }, () => this.loadData(filters));
  };

  render() {
    if (!isEmployeeFinanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Employee finance" />;
    }

    const {
      loading,
      loadError,
      dataSource,
      profiles,
      advances,
      loans,
      deductions,
      marginSeries,
      costToRevenue,
      marginRiskFlags,
      kpiCards,
      insights,
      filters,
    } = this.state;
    const meta = EMPLOYEE_FINANCE_PAGE_META.employeeFinance;

    return (
      <EmployeeFinanceLuxPage
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo employee finance profiles"
        loading={loading}
        kpiCards={kpiCards}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={
          <>
            <EmployeeFinanceActionButton to="/payroll/benefits" icon="fe fe-heart" variant="ghost">
              Benefits
            </EmployeeFinanceActionButton>
            <EmployeeFinanceActionButton to="/finance/project-financials" icon="fe fe-briefcase" variant="primary">
              Project financials
            </EmployeeFinanceActionButton>
          </>
        }
      >
        <EmployeeFinanceInsightPanel insights={insights} />
        {loadError ? (
          <EmployeeFinanceLuxPanel title="Employee finance load issue" meta={loadError} accent="rose">
            <EmployeeFinanceActionButton icon="fe fe-refresh-cw" variant="primary" onClick={() => this.loadData()}>
              Retry
            </EmployeeFinanceActionButton>
          </EmployeeFinanceLuxPanel>
        ) : null}
        <EmployeeFinanceLuxPanel
          title="Cost-to-revenue analytics"
          meta="project revenue, loaded cost, and portfolio margin roll-ups"
          icon="fe fe-bar-chart-2"
          accent="indigo"
        >
          <CostToRevenueAnalyticsPanel analytics={costToRevenue} loading={loading} />
        </EmployeeFinanceLuxPanel>
        <EmployeeFinanceLuxPanel
          title="Margin risk intelligence"
          meta="AI-assisted margin compression signals with evidence"
          icon="fe fe-zap"
          accent="rose"
        >
          <EmployeeFinanceMarginRiskPanel flags={marginRiskFlags} loading={loading} />
        </EmployeeFinanceLuxPanel>
        <EmployeeFinanceLuxPanel title={meta.panelTitle} meta={meta.panelMeta} icon="fe fe-pie-chart" accent="violet">
          <EmployeeFinanceOverviewPanel
            profiles={profiles}
            advances={advances}
            loans={loans}
            deductions={deductions}
            marginSeries={marginSeries}
            loading={loading}
            filters={filters}
            onFilterChange={this.handleFilterChange}
          />
        </EmployeeFinanceLuxPanel>
      </EmployeeFinanceLuxPage>
    );
  }
}

export default EmployeeFinancePage;
