export function isDataRetentionAdminEnabled() {
  return shouldUseDataRetentionAdmin();
}

export function normalizeRetentionPolicy(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    entityType: row.entityType || row.id,
    name: row.name || row.entityType || "Retention policy",
    domain: row.domain || "Compliance",
    retentionDays: Object.prototype.hasOwnProperty.call(row, "retentionDays") ? row.retentionDays : 365,
    legalHold: row.legalHold === true || row.status === RETENTION_STATUSES.LEGAL_HOLD,
    status: row.status || (row.legalHold ? RETENTION_STATUSES.LEGAL_HOLD : RETENTION_STATUSES.ACTIVE),
    autoPurge: row.autoPurge !== false,
    recordsHeld: row.recordsHeld != null ? row.recordsHeld : 0,
    nextPurgeAt: row.nextPurgeAt || null,
    owner: row.owner || "Compliance",
    description: row.description || "",
    updatedAt: row.updatedAt || null,
  };
}
