import React, { Component, createRef } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";

export const DELIVERABLE_STATUS_OPTIONS = [
  {
    value: "NEW",
    label: "New",
    level: 0,
    tone: "sky",
    icon: "fe fe-plus-circle",
    hint: "Created and ready to set up",
  },
  {
    value: "ASSIGNED",
    label: "Assigned",
    level: 1,
    tone: "indigo",
    icon: "fe fe-user-check",
    hint: "Owned and waiting to start",
  },
  {
    value: "INPROGRESS",
    label: "In progress",
    level: 2,
    tone: "amber",
    icon: "fe fe-play-circle",
    hint: "Actively being worked",
  },
  {
    value: "COMPLETED",
    label: "Completed",
    level: 3,
    tone: "green",
    icon: "fe fe-check-circle",
    hint: "Work finished",
  },
  {
    value: "CLOSED",
    label: "Closed",
    level: 4,
    tone: "slate",
    icon: "fe fe-lock",
    hint: "Locked / archived",
  },
];

const MENU_GAP = 8;
const VIEWPORT_PAD = 12;
const ESTIMATED_MENU_HEIGHT = 320;
const MENU_Z_INDEX = 10060;

function mergeOptionMeta(option) {
  const defaults = DELIVERABLE_STATUS_OPTIONS.find((o) => o.value === option.value) || {};
  return {
    tone: "slate",
    icon: "fe fe-circle",
    hint: "",
    ...defaults,
    ...option,
  };
}

class LuxStatusControl extends Component {
  constructor(props) {
    super(props);
    this.rootRef = createRef();
    this.triggerRef = createRef();
    this.menuRef = createRef();
    this.state = { open: false, menuCoords: null };
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
    document.addEventListener("keydown", this.handleKeyDown);
    window.addEventListener("scroll", this.handleReposition, true);
    window.addEventListener("resize", this.handleReposition);
  }

  componentDidUpdate(prevProps, prevState) {
    if (this.state.open && !prevState.open) {
      this.schedulePosition();
    }
    if (!this.state.open && prevState.open) {
      this.setState({ menuCoords: null });
    }
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
    document.removeEventListener("keydown", this.handleKeyDown);
    window.removeEventListener("scroll", this.handleReposition, true);
    window.removeEventListener("resize", this.handleReposition);
  }

  schedulePosition = () => {
    requestAnimationFrame(() => {
      requestAnimationFrame(this.updateMenuPosition);
    });
  };

  handleReposition = () => {
    if (this.state.open) {
      this.updateMenuPosition();
    }
  };

  updateMenuPosition = () => {
    const trigger = this.triggerRef.current;
    if (!trigger) return;

    const rect = trigger.getBoundingClientRect();
    const menu = this.menuRef.current;
    const menuWidth = menu ? menu.offsetWidth : Math.min(18.5 * 16, window.innerWidth * 0.84);
    const menuHeight = menu ? menu.offsetHeight : ESTIMATED_MENU_HEIGHT;

    let top = rect.bottom + MENU_GAP;
    let left = rect.right - menuWidth;

    const spaceBelow = window.innerHeight - rect.bottom - VIEWPORT_PAD;
    if (spaceBelow < menuHeight + MENU_GAP && rect.top > menuHeight + MENU_GAP) {
      top = rect.top - menuHeight - MENU_GAP;
    }

    left = Math.max(
      VIEWPORT_PAD,
      Math.min(left, window.innerWidth - menuWidth - VIEWPORT_PAD)
    );
    top = Math.max(
      VIEWPORT_PAD,
      Math.min(top, window.innerHeight - menuHeight - VIEWPORT_PAD)
    );

    const next = { top, left };
    const changed =
      !this.state.menuCoords ||
      this.state.menuCoords.top !== next.top ||
      this.state.menuCoords.left !== next.left;

    if (changed) {
      this.setState({ menuCoords: next }, () => {
        if (menu && menu.offsetHeight !== menuHeight) {
          requestAnimationFrame(this.updateMenuPosition);
        }
      });
    }
  };

  handleOutsideClick = (event) => {
    if (!this.state.open) return;
    const inRoot = this.rootRef.current && this.rootRef.current.contains(event.target);
    const inMenu = this.menuRef.current && this.menuRef.current.contains(event.target);
    if (!inRoot && !inMenu) {
      this.setState({ open: false });
    }
  };

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.state.open) {
      this.setState({ open: false });
    }
  };

  getOptions = () => (this.props.options || DELIVERABLE_STATUS_OPTIONS).map(mergeOptionMeta);

  getCurrentOption = () => {
    const options = this.getOptions();
    return (
      options.find((option) => option.value === this.props.value) || {
        value: this.props.value || "UNKNOWN",
        label: this.props.value || "Unknown",
        tone: "slate",
        icon: "fe fe-help-circle",
        hint: "",
      }
    );
  };

  isOptionEnabled = (option) => {
    const { changeableStatus, allowLevelDown, value, isReadOnly } = this.props;
    if (isReadOnly) return false;
    if (option.value === value) return false;
    if (changeableStatus && !changeableStatus.includes(option.value)) return false;

    if (allowLevelDown === false) {
      const current = this.getOptions().find((o) => o.value === value);
      if (
        current &&
        typeof current.level === "number" &&
        typeof option.level === "number" &&
        current.level > option.level
      ) {
        return false;
      }
    }
    return true;
  };

  toggleOpen = () => {
    if (this.props.isReadOnly) return;
    this.setState((prev) => ({ open: !prev.open }));
  };

  selectOption = (option) => {
    if (!this.isOptionEnabled(option)) return;
    this.setState({ open: false });
    if (typeof this.props.onChange === "function") {
      this.props.onChange(this.props.itemId, option.value);
    }
  };

  disabledReason = (option) => {
    if (option.value === this.props.value) return "Current status";
    if (this.props.changeableStatus && !this.props.changeableStatus.includes(option.value)) {
      return "Not allowed for your role";
    }
    if (this.props.allowLevelDown === false) {
      const current = this.getOptions().find((o) => o.value === this.props.value);
      if (
        current &&
        typeof current.level === "number" &&
        typeof option.level === "number" &&
        current.level > option.level
      ) {
        return "Cannot move backwards";
      }
    }
    return "Unavailable";
  };

  renderMenu = () => {
    const { open, menuCoords } = this.state;
    if (!open || this.props.isReadOnly) return null;

    const options = this.getOptions();
    const positioned = Boolean(menuCoords);
    const coords = menuCoords || { top: 0, left: 0 };

    return createPortal(
      <div
        ref={this.menuRef}
        className="lux-status-control__menu lux-status-control__menu--portal"
        role="listbox"
        aria-label="Choose status"
        style={{
          position: "fixed",
          top: coords.top,
          left: coords.left,
          right: "auto",
          zIndex: MENU_Z_INDEX,
          visibility: positioned ? "visible" : "hidden",
        }}
      >
        <div className="lux-status-control__menu-head">
          <strong>Update status</strong>
          <span>Pick the next stage for this item</span>
        </div>
        <ul className="lux-status-control__list">
          {options.map((option) => {
            const enabled = this.isOptionEnabled(option);
            const isCurrent = option.value === this.props.value;
            return (
              <li key={option.value}>
                <button
                  type="button"
                  role="option"
                  aria-selected={isCurrent}
                  disabled={!enabled && !isCurrent}
                  className={classNames(
                    "lux-status-control__option",
                    `is-${option.tone}`,
                    {
                      "is-current": isCurrent,
                      "is-disabled": !enabled && !isCurrent,
                    }
                  )}
                  onClick={() => this.selectOption(option)}
                >
                  <span className="lux-status-control__option-icon" aria-hidden="true">
                    <i className={option.icon} />
                  </span>
                  <span className="lux-status-control__option-copy">
                    <strong>{option.label}</strong>
                    <span>
                      {isCurrent
                        ? "Current status"
                        : enabled
                          ? option.hint
                          : this.disabledReason(option)}
                    </span>
                  </span>
                  {isCurrent && (
                    <span className="lux-status-control__option-check" aria-hidden="true">
                      <i className="fe fe-check" />
                    </span>
                  )}
                </button>
              </li>
            );
          })}
        </ul>
      </div>,
      document.body
    );
  };

  render() {
    const { isReadOnly, className, label = "Status" } = this.props;
    const current = this.getCurrentOption();
    const { open } = this.state;

    return (
      <div
        ref={this.rootRef}
        className={classNames("lux-status-control", className, {
          "is-open": open,
          "is-readonly": isReadOnly,
        })}
      >
        <span className="lux-status-control__eyebrow">{label}</span>
        <button
          ref={this.triggerRef}
          type="button"
          className={classNames(
            "lux-status-control__trigger",
            `is-${current.tone}`,
            { "is-readonly": isReadOnly }
          )}
          onClick={this.toggleOpen}
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-label={`${label}: ${current.label}${isReadOnly ? "" : ". Change status"}`}
          disabled={isReadOnly}
        >
          <span className="lux-status-control__dot" aria-hidden="true" />
          <span className="lux-status-control__icon" aria-hidden="true">
            <i className={current.icon} />
          </span>
          <span className="lux-status-control__label">{current.label}</span>
          {!isReadOnly && (
            <span className="lux-status-control__chevron" aria-hidden="true">
              <i className={open ? "fe fe-chevron-up" : "fe fe-chevron-down"} />
            </span>
          )}
        </button>
        {this.renderMenu()}
      </div>
    );
  }
}

export default LuxStatusControl;
