let accessControlJson = null;

function reload() {
  let accessControlItem = authGetItem("ac");
  let key = authGetItem("authToken");
  if (accessControlItem == null || accessControlItem === "") {
    accessControlJson = {};
    return;
  }
  try {
    const decrypted = commonUtils.decryptString(accessControlItem, key);
    if (!decrypted || typeof decrypted !== "string") {
      accessControlJson = {};
      return;
    }
    const trimmed = decrypted.trim();
    if (!trimmed || (trimmed[0] !== "{" && trimmed[0] !== "[")) {
      accessControlJson = {};
      return;
    }
    accessControlJson = JSON.parse(trimmed);
  } catch (_err) {
    // Corrupt/missing role access blob must not crash the app shell.
    accessControlJson = {};
  }
}
function getAccessControll(name) {
  if (accessControlJson == null) {
    reload();
  }

  return accessControlJson && accessControlJson[name]
    ? accessControlJson[name]
    : {};
}

