import React, { Component } from "react";
import classNames from "classnames/bind";
import { formatApiKeyScopesLabel } from "config/developer-portal.config";
import { DeveloperStatusBadge } from "views/developer/components/DeveloperLuxShared";

export default class ApiKeyRegister extends Component {
  state = {
    confirmDeleteId: null,
  };

  componentDidUpdate(prevProps) {
    if (prevProps.keys !== this.props.keys && this.state.confirmDeleteId != null) {
      this.setState({ confirmDeleteId: null });
    }
  }

  handleDeleteClick = (row) => {
    const { onDelete, busy } = this.props;
    if (!onDelete || busy || !row) return;
    const keyId = row.id != null ? row.id : row.prefix;
    if (!keyId) return;
    if (this.state.confirmDeleteId === keyId) {
      this.setState({ confirmDeleteId: null });
      onDelete({ ...row, id: keyId });
      return;
    }
    this.setState({ confirmDeleteId: keyId });
  };

  render() {
    const { keys, loading, onRevoke, onDelete, busy } = this.props;
    const { confirmDeleteId } = this.state;

    if (loading) {
      return (
        <div className="lux-dev-register lux-dev-register--loading">
          {[1, 2, 3].map((key) => (
            <div key={key} className="lux-dev-skeleton lux-dev-skeleton--row" />
          ))}
        </div>
      );
    }

    const rows = keys || [];
    if (!rows.length) {
      return (
        <div className="lux-dev-empty">
          <i className="fe fe-key" aria-hidden="true" />
          <p>No API keys yet.</p>
        </div>
      );
    }

    return (
      <div className="lux-dev-register">
        {rows.map((row, index) => {
          const keyId = row.id != null ? row.id : row.prefix;
          const confirmDelete = confirmDeleteId === keyId;
          return (
            <article key={row.id} className={classNames("lux-dev-register__row", row.tone && `is-${row.tone}`)}>
              <span className="lux-dev-register__index">{String(index + 1).padStart(2, "0")}</span>
              <span className="lux-dev-register__rail">
                <i className="fe fe-key" aria-hidden="true" />
              </span>
              <div className="lux-dev-register__main">
                <span className="lux-dev-register__eyebrow">{row.prefix} · {row.appName}</span>
                <h3>{row.name}</h3>
                <p>{formatApiKeyScopesLabel(row.scopes)}</p>
                <div className="lux-dev-register__meta">
                  <DeveloperStatusBadge status={row.status} />
                  <span>{(row.requestCount || 0).toLocaleString()} requests</span>
                  {row.ownerName ? <span>{row.ownerName}</span> : null}
                  <span>{row.lastUsedAt ? `Last used ${row.lastUsedAt}` : "Never used"}</span>
                </div>
              </div>
              <div className="lux-dev-register__actions">
                {row.status === "active" && onRevoke ? (
                  <button
                    type="button"
                    className="lux-onb-action lux-dev-action"
                    onClick={() => onRevoke({ ...row, id: keyId })}
                    disabled={busy || !keyId}
                  >
                    Revoke
                  </button>
                ) : null}
                {onDelete ? (
                  <button
                    type="button"
                    className={classNames("lux-onb-action lux-dev-action lux-dev-action--danger", {
                      "is-confirm": confirmDelete,
                    })}
                    onClick={() => this.handleDeleteClick(row)}
                    disabled={busy || !keyId}
                    title={confirmDelete ? "Confirm delete" : "Delete credential"}
                    aria-label={confirmDelete ? "Confirm delete" : "Delete credential"}
                  >
                    {confirmDelete ? "Confirm" : "Delete"}
                  </button>
                ) : null}
              </div>
            </article>
          );
        })}
      </div>
    );
  }
}
