import React from "react";
import { PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";

export default function PerformanceAnalyticsPanel({ analytics, loading }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  const statusBuckets = (analytics && analytics.statusBuckets) || [];
  const ratingBuckets = (analytics && analytics.ratingBuckets) || [];
  const feedbackMix = (analytics && analytics.feedbackMix) || [];
  const maxGoals = Math.max.apply(null, statusBuckets.map((row) => row.count).concat([1]));

  return (
    <div className="lux-perf-analytics-grid">
      <PerformanceLuxPanel title="Goal health" meta="Status distribution across active OKRs" icon="fe fe-target" accent="amber">
        <div className="lux-perf-density-bars">
          {statusBuckets.map((bucket) => (
            <div key={bucket.id} className="lux-perf-density-row">
              <span>{bucket.label}</span>
              <span className="lux-perf-density-row__track">
                <span className="lux-perf-density-row__fill" style={{ width: `${Math.round((bucket.count / maxGoals) * 100)}%` }} />
              </span>
              <strong>{bucket.count}</strong>
            </div>
          ))}
        </div>
      </PerformanceLuxPanel>

      <PerformanceLuxPanel title="Manager ratings" meta="Completed review score spread" icon="fe fe-star" accent="indigo">
        <div className="lux-perf-snapshot__metrics">
          {ratingBuckets.map((bucket) => (
            <div key={bucket.rating} className="lux-perf-snapshot__metric">
              <span>Rating {bucket.rating}</span>
              <strong>{bucket.count}</strong>
            </div>
          ))}
        </div>
      </PerformanceLuxPanel>

      <PerformanceLuxPanel title="Feedback mix" meta="Continuous recognition categories" icon="fe fe-message-circle" accent="emerald">
        <div className="lux-perf-snapshot__metrics">
          {feedbackMix.map((bucket) => (
            <div key={bucket.id} className="lux-perf-snapshot__metric">
              <span>{bucket.label}</span>
              <strong>{bucket.count}</strong>
            </div>
          ))}
        </div>
      </PerformanceLuxPanel>
    </div>
  );
}
