/**
 * Client-side PersonaContext builder (P00-T1/T5 bridge until backend ships).
 * @see docs/additionalfeatures/tracopus_final_master_implementation_plan_persona_ready.md §6.2
 */

import { commonUtils } from "_helpers";
import {
  resolveAllowedPersonas,
  resolveActivePersona,
  getPersonaLabel,
  isPersonaSwitchEnabled,
} from "config/persona-navigation.utils";
import { filterPersonasByOrgPolicy } from "config/org-access-policy.config";

export const SCOPE_TYPES = [
  "SELF",
  "TEAM",
  "DEPARTMENT",
  "PROJECT",
  "PROGRAM",
  "PORTFOLIO",
  "PAYROLL_GROUP",
  "FINANCE_ORG",
  "ORG",
  "ADMIN",
];

/** Default data scope per persona (§6.1). */
export const PERSONA_DEFAULT_SCOPE = {
  EMPLOYEE: "SELF",
  MANAGER: "TEAM",
  PROJECT_MANAGER: "PROJECT",
  RESOURCE_MANAGER: "PORTFOLIO",
  HR_ADMIN: "ORG",
  PAYROLL_MANAGER: "PAYROLL_GROUP",
  FINANCE_MANAGER: "FINANCE_ORG",
  EXECUTIVE: "ORG",
  ADMIN: "ADMIN",
};

/** Landing route per persona (§6.1 typical landing view). */
export const PERSONA_LANDING_ROUTES = {
  EMPLOYEE: "/workspace/home",
  MANAGER: "/workspace/home",
  PROJECT_MANAGER: "/project/dashboard",
  RESOURCE_MANAGER: "/project/capacity",
  HR_ADMIN: "/people/dashboard",
  PAYROLL_MANAGER: "/payroll/dashboard",
  FINANCE_MANAGER: "/finance/dashboard",
  EXECUTIVE: "/analytics/executive",
  ADMIN: "/admin/dashboard",
};

const MASK_HIDDEN = "HIDDEN";
const MASK_MASKED = "MASKED";
const MASK_VISIBLE = "VISIBLE";

/** Client-side masking policy stub (P00-T3 until FieldMaskingService ships). */
export function resolveMaskingPolicyForPersona(persona) {
  const hidden = {
    salary: MASK_HIDDEN,
    baseSalary: MASK_HIDDEN,
    hourlyRate: MASK_HIDDEN,
    bankAccount: MASK_HIDDEN,
    taxId: MASK_HIDDEN,
    payrollLines: MASK_HIDDEN,
    paycheckAmount: MASK_HIDDEN,
    financeMargin: MASK_HIDDEN,
    performanceReview: MASK_HIDDEN,
  };

  switch (persona) {
    case "PAYROLL_MANAGER":
      return {
        ...hidden,
        salary: MASK_VISIBLE,
        payrollLines: MASK_VISIBLE,
        paycheckAmount: MASK_VISIBLE,
        bankAccount: MASK_MASKED,
        taxId: MASK_MASKED,
      };
    case "FINANCE_MANAGER":
      return {
        ...hidden,
        financeMargin: MASK_VISIBLE,
        bankAccount: MASK_MASKED,
      };
    case "HR_ADMIN":
      return {
        ...hidden,
        bankAccount: MASK_MASKED,
        taxId: MASK_MASKED,
        performanceReview: MASK_MASKED,
      };
    case "EXECUTIVE":
      return {
        ...hidden,
        salary: MASK_MASKED,
        financeMargin: MASK_VISIBLE,
      };
    case "ADMIN":
      return {
        salary: MASK_MASKED,
        baseSalary: MASK_MASKED,
        bankAccount: MASK_MASKED,
        taxId: MASK_MASKED,
        payrollLines: MASK_MASKED,
        paycheckAmount: MASK_MASKED,
        financeMargin: MASK_MASKED,
        performanceReview: MASK_MASKED,
      };
    case "MANAGER":
    case "PROJECT_MANAGER":
    case "RESOURCE_MANAGER":
      return hidden;
    case "EMPLOYEE":
    default:
      return {
        ...hidden,
        paycheckAmount: MASK_VISIBLE,
      };
  }
}

export function getScopeLabel(scopeType) {
  const labels = {
    SELF: "Personal",
    TEAM: "Team",
    DEPARTMENT: "Department",
    PROJECT: "Project",
    PROGRAM: "Program",
    PORTFOLIO: "Portfolio",
    PAYROLL_GROUP: "Payroll group",
    FINANCE_ORG: "Finance org",
    ORG: "Organization",
    ADMIN: "System-wide",
  };
  return labels[scopeType] || scopeType;
}

/**
 * Build PersonaContext from RBAC menuAccessControl (client derivation).
 * @param {object} menuAccessControl
 * @param {string} [activePersonaOverride]
 * @param {'client'|'api'} [source]
 */
export function buildClientPersonaContext(menuAccessControl, activePersonaOverride, source = "client") {
  const allowedPersonas = resolveAllowedPersonas(menuAccessControl);
  const switchEnabled = isPersonaSwitchEnabled(menuAccessControl);
  let activePersona;
  if (activePersonaOverride && allowedPersonas.includes(activePersonaOverride)) {
    activePersona = activePersonaOverride;
  } else {
    activePersona = resolveActivePersona(menuAccessControl);
  }

  const user = (commonUtils.getCurrentUser && commonUtils.getCurrentUser()) || {};

  return {
    userId: user.id || user.userId || null,
    employeeId: user.id || null,
    activePersona,
    activePersonaLabel: getPersonaLabel(activePersona),
    allowedPersonas,
    personaSwitchEnabled: switchEnabled && allowedPersonas.length > 1,
    scopeType: PERSONA_DEFAULT_SCOPE[activePersona] || "SELF",
    scopeLabel: getScopeLabel(PERSONA_DEFAULT_SCOPE[activePersona] || "SELF"),
    scopeIds: [],
    permissions: [...allowedPersonas],
    featureFlags: {},
    maskingPolicy: resolveMaskingPolicyForPersona(activePersona),
    dashboardVariant: String(activePersona).toLowerCase(),
    landingRoute: PERSONA_LANDING_ROUTES[activePersona] || "/project/dashboard",
    source,
  };
}

/** True when an API payload has the minimum persona context shape. */
export function isValidPersonaContextPayload(apiPayload) {
  return Boolean(
    apiPayload &&
      typeof apiPayload === "object" &&
      !Array.isArray(apiPayload) &&
      typeof apiPayload.activePersona === "string" &&
      Array.isArray(apiPayload.allowedPersonas)
  );
}

/** Normalize API response into the same shape as buildClientPersonaContext. */
export function normalizeApiPersonaContext(apiPayload, menuAccessControl) {
  if (!isValidPersonaContextPayload(apiPayload)) {
    return buildClientPersonaContext(menuAccessControl);
  }
  const fallback = buildClientPersonaContext(menuAccessControl, apiPayload.activePersona);
  // Org kill switches always win — never surface disabled personas from the API.
  const allowedPersonas = filterPersonasByOrgPolicy(
    apiPayload.allowedPersonas && apiPayload.allowedPersonas.length
      ? apiPayload.allowedPersonas
      : fallback.allowedPersonas
  );
  let activePersona = apiPayload.activePersona || fallback.activePersona;
  if (!allowedPersonas.includes(activePersona)) {
    activePersona = allowedPersonas[0] || fallback.activePersona;
  }
  const scopeType =
    activePersona === apiPayload.activePersona && apiPayload.scopeType
      ? apiPayload.scopeType
      : PERSONA_DEFAULT_SCOPE[activePersona] || fallback.scopeType;
  return {
    ...fallback,
    ...apiPayload,
    activePersona,
    activePersonaLabel: getPersonaLabel(activePersona),
    allowedPersonas,
    personaSwitchEnabled:
      fallback.personaSwitchEnabled && allowedPersonas.length > 1,
    scopeType,
    scopeLabel: getScopeLabel(scopeType),
    maskingPolicy:
      activePersona === apiPayload.activePersona && apiPayload.maskingPolicy
        ? apiPayload.maskingPolicy
        : resolveMaskingPolicyForPersona(activePersona),
    permissions:
      apiPayload.permissions && apiPayload.permissions.length
        ? apiPayload.permissions
        : allowedPersonas,
    dashboardVariant: String(activePersona).toLowerCase(),
    landingRoute: PERSONA_LANDING_ROUTES[activePersona] || fallback.landingRoute,
    source: "api",
  };
}
