import React, { Component } from "react";
import classNames from "classnames/bind";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";
import {
  PROJECT_NOTIFICATION_PREFS,
  buildNotificationPrefState,
} from "./projectDetailsTab.utils";

const PREF_TONES = {
  status: "violet",
  assignments: "sky",
  comments: "mint",
  due: "amber",
  files: "slate",
};

class ProjectDetailsNotification extends Component {
  constructor() {
    super();
    this.state = { prefs: buildNotificationPrefState() };
  }

  handlePrefChange = (id, enabled) => {
    this.setState((prev) => ({
      prefs: { ...prev.prefs, [id]: enabled },
    }));
  };

  renderPrefCard = (pref) => {
    const { readOnly } = this.props;
    const enabled = !!this.state.prefs[pref.id];
    const disabled = readOnly || pref.comingSoon;
    const tone = PREF_TONES[pref.id] || "slate";

    return (
      <article
        key={pref.id}
        className={classNames("lux-pd-pref-card", `is-${tone}`, {
          "is-on": enabled && !pref.comingSoon,
          "is-off": !enabled && !pref.comingSoon,
          "is-soon": pref.comingSoon,
          "is-disabled": disabled,
        })}
      >
        <span className="lux-pd-pref-card__glow" aria-hidden="true" />
        <span className="lux-pd-pref-card__accent" aria-hidden="true" />

        <span className="lux-pd-pref-card__icon" aria-hidden="true">
          <i className={pref.icon} />
        </span>

        <div className="lux-pd-pref-card__copy">
          <div className="lux-pd-pref-card__title-row">
            <strong>{pref.label}</strong>
            {pref.comingSoon ? (
              <span className="lux-pd-pref-card__badge is-soon">Soon</span>
            ) : (
              <span className={classNames("lux-pd-pref-card__badge", enabled ? "is-on" : "is-off")}>
                {enabled ? "On" : "Off"}
              </span>
            )}
          </div>
          <p>{pref.description}</p>
        </div>

        {!pref.comingSoon && (
          <label
            className="lux-pd-pref-card__switch"
            aria-label={`${enabled ? "Disable" : "Enable"} ${pref.label}`}
          >
            <input
              type="checkbox"
              checked={enabled}
              disabled={disabled}
              onChange={(e) => this.handlePrefChange(pref.id, e.target.checked)}
            />
            <span className="lux-pd-pref-card__track" aria-hidden="true">
              <span className="lux-pd-pref-card__thumb" />
            </span>
          </label>
        )}
      </article>
    );
  };

  render() {
    const { projectInfo } = this.props;
    const enabledCount = Object.values(this.state.prefs).filter(Boolean).length;
    const availableCount = PROJECT_NOTIFICATION_PREFS.filter((p) => !p.comingSoon).length;

    return (
      <ProjectDetailsTabShell
        icon="fe fe-bell"
        tone="alerts"
        eyebrow="Alerts"
        title="Notification preferences"
        subtitle="Choose which project events should reach you. Preview only until notification settings are saved on the server."
        stats={[
          {
            key: "on",
            label: "Enabled",
            value: enabledCount,
            hint: "Local preview",
            tone: "mint",
          },
          {
            key: "total",
            label: "Channels",
            value: PROJECT_NOTIFICATION_PREFS.length,
            hint: "Available types",
            tone: "violet",
          },
          {
            key: "ready",
            label: "Ready",
            value: availableCount,
            hint: "Can toggle now",
            tone: "sky",
          },
        ]}
      >
        <div className="lux-pd-notifications">
          <div className="lux-pd-notifications__banner">
            <span className="lux-pd-notifications__banner-icon" aria-hidden="true">
              <i className="fe fe-info" />
            </span>
            <div>
              <strong>
                Preferences for {projectInfo ? projectInfo.name : "this project"}
              </strong>
              <span>
                Changes are shown for preview only and are not persisted until a notifications API
                is available.
              </span>
            </div>
          </div>

          <section className="lux-pd-notifications__section" aria-label="Alert channels">
            <header className="lux-pd-notifications__section-head">
              <span className="lux-pd-notifications__section-icon" aria-hidden="true">
                <i className="fe fe-sliders" />
              </span>
              <div>
                <strong>Alert channels</strong>
                <span>Toggle the updates you care about for this project</span>
              </div>
            </header>
            <div className="lux-pd-notifications__grid">
              {PROJECT_NOTIFICATION_PREFS.map(this.renderPrefCard)}
            </div>
          </section>
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsNotification;
