import { userConstants } from '../_constants';
import { userService } from '../_services';
import { notificationActions } from './';
import { accessUtils, clearAuthStorage, history, returnUrlUtils, resolvePostLoginPath, clearForcePasswordChangeRequired } from '../_helpers';
import { getApiErrorMessage } from '../_helpers/apiError.utils';

export const userActions = {
    login,
    logout,
    initiateAccountActivation,
    validateAccountActivation,
    changePassword,
    updatePassword,
    authRefresh
};

function login(email, password, type, callbackFunction) {
    return async (dispatch) => {
        dispatch(request({ email }));
        userService.login(email, password, type)
            .then(
                userResponse => {
                    if (userResponse && userResponse.payload) {
                        dispatch(success(userResponse.payload));
                        if (callbackFunction) {
                            callbackFunction(userResponse.payload);
                        }
                        const returnUrl = returnUrlUtils.consumeReturnUrl();
                        const nextPath = resolvePostLoginPath(userResponse.payload, returnUrl || "/");
                        window.location.href = nextPath;
                    } else if (userResponse && userResponse.error && userResponse.error.length > 0) {
                        dispatch(failure(getErrorMessage(userResponse.error[0].message)));
                    }
                },
                error => {
                    const message = getErrorMessage(error);
                    dispatch(failure(message));
                    dispatch(notificationActions.error(message));
                }
            );
    };

    function request(request) { return { type: userConstants.LOGIN_REQUEST, request } }
    function success(userResponse) { return { type: userConstants.LOGIN_SUCCESS, userResponse } }
    function failure(error) { return { type: userConstants.LOGIN_FAILURE, error } }
}

function authRefresh() {
    return async (dispatch) => {
        userService.authRefresh()
            .then(
                userResponse => {
                    if (userResponse && userResponse.payload) {
                        dispatch(notificationActions.success('Access Role Refreshed successful'));
                        accessUtils.reload();
                    }
                },
                error => {
                }
            );
    };
}

