import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isProjectGovernanceEnabled } from "config/project-governance.config";
import {
  buildDependencyValidationReport,
  buildMilestoneInsights,
  buildMilestoneMetrics,
  buildProjectOptions,
  computeCriticalPathAnalysis,
  enrichMilestonesWithScheduleAnalysis,
  filterMilestones,
  validateMilestoneReschedule,
} from "config/project-governance.utils";
import { projectGovernanceService } from "_services/projectGovernance.service";
import { GOVERNANCE_PAGE_IDS, getGovernanceQuickLinks } from "config/project-governance-nav.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import DeliveryGanttChart from "views/project/components/DeliveryGanttChart";
import DependencyRegister from "views/project/components/DependencyRegister";
import DependencyValidationPanel from "views/project/components/DependencyValidationPanel";
import MilestoneDrawer from "views/project/components/MilestoneDrawer";
import GovernanceLuxPage, {
  GovernanceLuxFilters,
  GovernanceLuxPanel,
} from "views/project/components/ProjectGovernanceLuxShared";

class ProjectTimelinePage extends Component {
  state = {
    milestones: [],
    dependencies: [],
    loading: true,
    loadError: null,
    dataSource: null,
    projectFilter: "ALL",
    drawerOpen: false,
    selectedMilestone: null,
    creatingDependency: false,
    dependencyError: null,
    rescheduleWarning: null,
  };

  componentDidMount() {
    const { pageHeaderNameChangeHandler } = this.props;
    if (pageHeaderNameChangeHandler) {
      pageHeaderNameChangeHandler("Timeline / Gantt");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [milestonesRes, dependenciesRes] = await Promise.all([
        projectGovernanceService.listMilestones(),
        projectGovernanceService.listDependencies(),
      ]);
      this.setState({
        milestones: milestonesRes.payload || [],
        dependencies: dependenciesRes.payload || [],
        loading: false,
        dataSource: milestonesRes.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load delivery timeline.", milestones: [] });
    }
  };

  handleReschedule = async (milestoneId, schedulePatch) => {
    const { milestones, dependencies } = this.state;
    const validation = validateMilestoneReschedule(milestones, dependencies, milestoneId, schedulePatch);
    if (!validation.valid) {
      this.setState({ rescheduleWarning: validation.reason });
    } else {
      this.setState({ rescheduleWarning: null });
    }
    await projectGovernanceService.updateMilestone(milestoneId, schedulePatch);
    await this.loadData();
  };

  handleCreateDependency = async (payload) => {
    this.setState({ creatingDependency: true, dependencyError: null });
    try {
      await projectGovernanceService.createDependency(payload);
      await this.loadData();
      this.setState({ creatingDependency: false, dependencyError: null });
    } catch (e) {
      this.setState({
        creatingDependency: false,
        dependencyError: (e && e.message) || "Unable to create dependency.",
      });
      throw e;
    }
  };

  handleSaveMilestone = async (milestoneId, payload) => {
    await projectGovernanceService.updateMilestone(milestoneId, payload);
    await this.loadData();
  };

  openDrawer = (milestone) => {
    this.setState({ drawerOpen: true, selectedMilestone: milestone });
  };

  closeDrawer = () => {
    this.setState({ drawerOpen: false, selectedMilestone: null });
  };

  render() {
    if (!isProjectGovernanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Project timeline" />;
    }

    const {
      milestones,
      dependencies,
      loading,
      loadError,
      dataSource,
      projectFilter,
      drawerOpen,
      selectedMilestone,
      creatingDependency,
      dependencyError,
      rescheduleWarning,
    } = this.state;

    const metrics = buildMilestoneMetrics(milestones, dependencies, { projectId: projectFilter });
    const validationIssues = buildDependencyValidationReport(milestones, dependencies, {
      projectId: projectFilter,
    });
    const analysis = computeCriticalPathAnalysis(milestones, dependencies, { projectId: projectFilter });
    const insights = buildMilestoneInsights(metrics, milestones, { validationIssues });
    const projectOptions = buildProjectOptions(milestones);
    const enrichedMilestones = enrichMilestonesWithScheduleAnalysis(milestones, dependencies, {
      projectId: projectFilter,
    });
    const registerRows = filterMilestones(enrichedMilestones, {
      projectId: projectFilter === "ALL" ? undefined : projectFilter,
    });
    const scopedDependencies =
      projectFilter === "ALL"
        ? dependencies
        : dependencies.filter((dep) => !dep.projectId || dep.projectId === projectFilter);

    return (
      <GovernanceLuxPage
        pageId={GOVERNANCE_PAGE_IDS.TIMELINE}
        dataSource={dataSource}
        demoLabel="Demo timeline data"
        loading={loading}
        insights={insights}
        quickLinks={getGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.TIMELINE)}
        kpiCards={[
          { id: "total", label: "Milestones", value: metrics.total, tone: "blue", icon: "fe fe-flag" },
          { id: "active", label: "In progress", value: metrics.inProgress, tone: "indigo", icon: "fe fe-activity" },
          { id: "risk", label: "At risk", value: metrics.atRisk, tone: "amber", icon: "fe fe-alert-triangle" },
          { id: "critical", label: "Critical path", value: metrics.onCriticalPath, tone: "rose", icon: "fe fe-git-branch" },
          { id: "deps", label: "Dependencies", value: metrics.dependencyCount, tone: "slate", icon: "fe fe-link" },
          {
            id: "duration",
            label: "Longest path",
            value: metrics.hasDependencyCycle ? "—" : `${metrics.projectDurationDays}d`,
            tone: "violet",
            icon: "fe fe-trending-up",
          },
        ]}
        heroActions={
          <ResourcesActionButton to="/project/milestones" icon="fe fe-flag" variant="ghost">
            Milestone register
          </ResourcesActionButton>
        }
      >
        <GovernanceLuxPanel
          title="Delivery Gantt"
          meta={`${registerRows.length} milestones · drag to reschedule`}
          icon="fe fe-bar-chart-2"
          accent="gantt"
          className="lux-gov-panel--gantt"
        >
          <GovernanceLuxFilters>
            <select
              className="lux-gov-filters__select"
              value={projectFilter}
              onChange={(e) => this.setState({ projectFilter: e.target.value })}
              aria-label="Filter Gantt by project"
            >
              {projectOptions.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </select>
          </GovernanceLuxFilters>

          {loadError ? (
            <LuxRegisterEmptyState title="Unable to load timeline" copy={loadError} onRetry={this.loadData} />
          ) : loading ? (
            <div className="lux-gov-gantt-loading" aria-busy="true">
              <div className="lux-persona-loading__pulse" />
            </div>
          ) : (
            <>
              {rescheduleWarning ? (
                <p className="lux-gov-deps-panel__hint is-error lux-gov-reschedule-warning">{rescheduleWarning}</p>
              ) : null}
              <DeliveryGanttChart
                milestones={enrichedMilestones}
                dependencies={dependencies}
                projectFilter={projectFilter}
                canEdit
                onReschedule={this.handleReschedule}
                onSelectMilestone={this.openDrawer}
              />
            </>
          )}
        </GovernanceLuxPanel>

        <GovernanceLuxPanel
          title="Dependency validation"
          meta={`${analysis.criticalDependencyIds.length} critical links · ${validationIssues.length} checks`}
          icon="fe fe-shuffle"
          accent="indigo"
        >
          <DependencyValidationPanel
            milestones={milestones}
            dependencies={dependencies}
            projectFilter={projectFilter}
            canEdit
            creating={creatingDependency}
            createError={dependencyError}
            onCreateDependency={this.handleCreateDependency}
          />
          <DependencyRegister
            rows={scopedDependencies}
            criticalDependencyIds={analysis.criticalDependencyIds}
            validationIssues={validationIssues}
            loading={loading}
          />
        </GovernanceLuxPanel>

        <MilestoneDrawer
          open={drawerOpen}
          milestone={selectedMilestone}
          onClose={this.closeDrawer}
          onSave={this.handleSaveMilestone}
        />
      </GovernanceLuxPage>
    );
  }
}

export default ProjectTimelinePage;
