import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { AUDIT_SCOPES } from "_constants/audit.constants";
import AuditTrailSection from "views/common/fragments/AuditTrailSection";
import { formatLeaveDateRange, getLeaveTypeLabel } from "./leave.utils";

const DRAWER_CLOSE_MS = 280;

class LeaveAuditDrawer extends Component {
  state = { visible: false, closing: false };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({ visible: true, closing: false });
    }
    if (!this.props.open && prevProps.open) {
      this.setState({ visible: false, closing: false });
    }
  }

  requestClose = () => {
    if (this.state.closing) return;
    this.setState({ closing: true });
    window.setTimeout(() => {
      this.setState({ visible: false, closing: false });
      this.props.onClose();
    }, DRAWER_CLOSE_MS);
  };

  render() {
    const { leave } = this.props;
    const { visible, closing } = this.state;

    if (!visible || !leave) return null;

    return createPortal(
      <div
        className={classNames("lux-onb-drawer-backdrop lux-leave-drawer-backdrop", { "is-closing": closing })}
        role="presentation"
        onClick={this.requestClose}
      >
        <aside
          className={classNames("lux-onb-drawer lux-leave-drawer lux-onb-drawer--neutral", { "is-closing": closing })}
          role="dialog"
          aria-label="Leave audit trail"
          onClick={(event) => event.stopPropagation()}
        >
          <header className="lux-onb-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span className="lux-onb-drawer__category-icon" aria-hidden="true">
                <i className="fe fe-shield" />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-leave-drawer__eyebrow">Compliance · Audit</span>
                <h2>Audit trail</h2>
                <p>
                  {getLeaveTypeLabel(leave.leaveTypeCode, leave.leaveTypeDescription)} ·{" "}
                  {formatLeaveDateRange(leave)}
                </p>
              </div>
            </div>
            <button type="button" className="lux-onb-drawer__close" onClick={this.requestClose} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-onb-drawer__body lux-leave-audit lux-leave-audit--rich">
            <AuditTrailSection
              scope={AUDIT_SCOPES.ENTITY}
              entityType="LEAVE"
              entityId={leave.id}
              eyebrow="Leave compliance"
              title="Request lifecycle"
              subtitle="Submission, approval, rejection, and cancellation events for this leave request."
              showEntityFilters={false}
              showToolbar={false}
              emptyState={{
                eyebrow: "Leave audit",
                title: "No audit events recorded yet",
                description:
                  "When audit logging is active, each step in the leave lifecycle will appear here with actor and decision details.",
                hints: [
                  "Approver actions show acting-for metadata when delegated",
                  "Sensitive fields may be redacted per policy",
                  "Events are immutable once written",
                ],
              }}
            />
          </div>
        </aside>
      </div>,
      document.body
    );
  }
}

export default LeaveAuditDrawer;
