import { ASSET_STATUSES, ACCESS_REQUEST_STATUSES } from "config/asset-register.config";

function normalizeStatus(value) {
  return String(value || "").toLowerCase();
}

export function filterAssets(assets, filters = {}) {
  const rows = assets || [];
  const { status, type, query, assigneeId, availableOnly } = filters;

  return rows.filter((row) => {
    if (availableOnly && row.status !== ASSET_STATUSES.AVAILABLE) {
      return false;
    }
    if (assigneeId && String(row.assigneeId) !== String(assigneeId)) {
      return false;
    }
    if (status && status !== "ALL" && row.status !== status) {
      return false;
    }
    if (type && type !== "ALL" && row.type !== type) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [row.name, row.tag, row.assigneeName, row.serialNumber, row.typeLabel]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function filterAccessRequests(requests, filters = {}) {
  const rows = requests || [];
  const { status, query } = filters;
  return rows.filter((row) => {
    if (status && status !== "ALL" && row.status !== status) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [row.title, row.requesterName, row.type, row.notes].filter(Boolean).join(" ").toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function buildAssetRegisterMetrics(assets) {
  const rows = assets || [];
  const assigned = rows.filter((row) => row.status === ASSET_STATUSES.ASSIGNED).length;
  const available = rows.filter((row) => row.status === ASSET_STATUSES.AVAILABLE).length;
  const blockers = rows.filter((row) => row.offboardingBlocker === true).length;
  const expiringWarranty = getExpiringWarranties(rows, 60).length;

  return {
    total: rows.length,
    assigned,
    available,
    blockers,
    expiringWarranty,
    utilizationPct: rows.length === 0 ? 0 : Math.round((assigned / rows.length) * 100),
  };
}

export function getExpiringWarranties(assets, withinDays = 60) {
  const now = Date.now();
  const windowMs = withinDays * 24 * 60 * 60 * 1000;
  return (assets || []).filter((row) => {
    if (!row.warrantyExpiresAt) {
      return false;
    }
    const expires = Date.parse(row.warrantyExpiresAt);
    if (Number.isNaN(expires)) {
      return false;
    }
    return expires >= now && expires <= now + windowMs;
  });
}

export function getOffboardingAssetBlockers(assets) {
  return (assets || []).filter(
    (row) =>
      row.offboardingBlocker === true ||
      (row.status === ASSET_STATUSES.ASSIGNED && row.assigneeId)
  );
}

export function buildAssetAnalyticsRows(assets) {
  const rows = assets || [];
  const buckets = {};
  rows.forEach((row) => {
    const key = row.typeLabel || row.type || "Other";
    if (!buckets[key]) {
      buckets[key] = { label: key, assigned: 0, available: 0, total: 0 };
    }
    buckets[key].total += 1;
    if (row.status === ASSET_STATUSES.ASSIGNED) {
      buckets[key].assigned += 1;
    }
    if (row.status === ASSET_STATUSES.AVAILABLE) {
      buckets[key].available += 1;
    }
  });
  return Object.values(buckets).sort((a, b) => b.total - a.total);
}

export function buildAccessRequestMetrics(requests) {
  const rows = requests || [];
  return {
    total: rows.length,
    pending: rows.filter((row) => row.status === ACCESS_REQUEST_STATUSES.PENDING).length,
    approved: rows.filter((row) => row.status === ACCESS_REQUEST_STATUSES.APPROVED).length,
    fulfilled: rows.filter((row) => row.status === ACCESS_REQUEST_STATUSES.FULFILLED).length,
  };
}

export function applyAssetAssignment(asset, assignee) {
  if (!asset) {
    return null;
  }
  return {
    ...asset,
    status: ASSET_STATUSES.ASSIGNED,
    assigneeId: assignee && assignee.id,
    assigneeName: assignee && (assignee.name || assignee.employeeName),
    assignedAt: new Date().toISOString().slice(0, 10),
    returnedAt: null,
    offboardingBlocker: true,
  };
}

export function applyAssetReturn(asset) {
  if (!asset) {
    return null;
  }
  return {
    ...asset,
    status: ASSET_STATUSES.AVAILABLE,
    assigneeId: null,
    assigneeName: "",
    returnedAt: new Date().toISOString().slice(0, 10),
    offboardingBlocker: false,
  };
}

export function toEmployee360AssetRow(asset) {
  if (!asset) {
    return null;
  }
  return {
    id: asset.id,
    name: asset.name,
    type: asset.typeLabel || asset.type,
    tag: asset.tag,
    assignedAt: asset.assignedAt,
    status: asset.status,
  };
}
