import { Component } from "react";
import { withRouter } from "react-router-dom";
import {
  captureProfileDetailsReturn,
  isProfileDetailsPath,
} from "views/hrms/profileDetailsNavigation.utils";

/**
 * Remembers the in-app route visited immediately before opening an employee profile.
 */
class ProfileDetailsReturnTracker extends Component {
  componentDidUpdate(prevProps) {
    const { location } = this.props;
    const prev = prevProps.location;
    if (!location || !prev) return;

    const entering =
      isProfileDetailsPath(location.pathname) &&
      !isProfileDetailsPath(prev.pathname);

    if (entering) {
      captureProfileDetailsReturn(prev.pathname, prev.search);
    }
  }

  render() {
    return null;
  }
}

export default withRouter(ProfileDetailsReturnTracker);
