import React, { Component } from "react";
import { connect } from "react-redux";
import { bidRequestsActions } from "_actions";
import { store } from "_helpers";
import { accessUtils } from "_helpers";
import { commonUtils } from "_helpers";
import BidRequestsDetailsGeneral from "./components/BidRequestsDetailsGeneral";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxDetailPageSkeleton from "views/common/fragments/LuxDetailPageSkeleton";

class BidRequestsDetailsPage extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getBidRequestsAccessControl(),
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(
      this.props.routeProp.name + " : " + this.props.match.params.bidRequestId
    );
    if (
      !this.props.bidRequestsInfo ||
      this.props.bidRequestsInfo.id !== this.props.match.params.bidRequestId
    ) {
      const bidRequestId = commonUtils.removeNameIntial(
        this.props.match.params.bidRequestId
      );
      store.dispatch(this.props.getBidRequestsInfo(bidRequestId));
      this.setState({ bidRequestId });
    }
  }

  render() {
    return (
      <div className="bidRequestDetails lux-bid-detail-page">
        {this.props.isLoading && (
          <div className="lux-bid-detail-page__loading">
            <LuxDetailPageSkeleton ariaLabel="Loading bid request" />
          </div>
        )}

        {!this.props.isLoading && this.props.bidRequestsInfo && (
          <BidRequestsDetailsGeneral
            permission={this.state.permission}
            item={this.props.bidRequestsInfo}
          />
        )}

        {!this.props.bidRequestsInfo && !this.props.isLoading && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-bid-requests-empty"
            variant="bid-requests"
            eyebrow="Sales pipeline"
            title="No bid request details found"
            description="You may not have permission to view this bid, or it does not exist."
            hints={[
              "Confirm the bid ID in the URL",
              "Return to the register and open the bid from the list",
              "Check team scope if the record was recently created",
            ]}
          />
        )}
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  bidRequestsInfo: state.bidRequests.selectedBidRequestsInfo,
  isLoading: state.bidRequests.getInfoLoading || state.bidRequests.loading,
});

const mapDispatchToProps = (dispatch) => ({
  getBidRequestsInfo: bidRequestsActions.getBidRequestsInfo,
});

export default connect(mapStateToProps, mapDispatchToProps)(BidRequestsDetailsPage);
