import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton from "react-loading-skeleton";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import dateUtils from "_helpers/date.utils";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";
import LuxSummaryPageSkeleton from "views/common/fragments/LuxSummaryPageSkeleton";

const STORAGE_KEY = "famstack-reports-summary-expanded";

class ReportsPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  getReportLabel = () => {
    const { filterOptions, reportOptions } = this.props;
    const selected = filterOptions && filterOptions.REPORT && filterOptions.REPORT.selected;
    const opt = (reportOptions || []).find((r) => r.name === selected);
    return (opt && opt.label) || selected || "—";
  };

  getDateRangeLabel = () => {
    const range = this.props.filterOptions && this.props.filterOptions.dateRangeValue;
    if (!range || !range.start || !range.end) return "—";
    return `${range.start.format("D MMM YYYY")} – ${range.end.format("D MMM YYYY")}`;
  };

  render() {
    const { expanded } = this.state;
    const { itemCount, totalItemCount, isLoading, metaInfo, filterOptions } = this.props;

    if (isLoading && itemCount == null) {
      return <LuxSummaryPageSkeleton className="lux-reports-summary" kpiCount={4} />;
    }
    const reportLabel = this.getReportLabel();
    const dateLabel = this.getDateRangeLabel();
    const filterText = (filterOptions && filterOptions.filterText) || "";
    const isFiltered =
      filterText.trim() &&
      totalItemCount != null &&
      itemCount != null &&
      totalItemCount !== itemCount;

    return (
      <section
        className={classNames("lux-bid-summary lux-po-summary lux-reports-summary", { "is-collapsed": !expanded })}
        aria-label="Reports overview"
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="reports" className="lux-bid-summary__eyebrow">
              Reporting intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                {isLoading ? (
                  <Skeleton width={160} height={20} borderRadius={6} />
                ) : (
                  <>
                    <CountUp end={itemCount || 0} duration={0.6} /> <span>rows · {reportLabel}</span>
                  </>
                )}
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">Reports workspace</h2>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-reports-summary-body"
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">
              {reportLabel} · {dateLabel}
              {itemCount != null
                ? ` · ${itemCount}${isFiltered ? ` of ${totalItemCount}` : ""} row${itemCount === 1 ? "" : "s"}`
                : ""}
              {filterText.trim() ? ` · “${filterText.trim()}”` : ""}
            </p>
          </div>
        )}

        <div id="lux-reports-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <p className="lux-bid-summary__subtitle">
            Choose a report type, team scope, and date range — then run View. Results below match server output exactly.
          </p>
          <div className="lux-reports-summary__context">
            <span className="lux-reports-summary__chip is-primary">
              <i className="fe fe-file-text" aria-hidden="true" />
              {reportLabel}
            </span>
            <span className="lux-reports-summary__chip">
              <i className="fe fe-calendar" aria-hidden="true" />
              {dateLabel}
            </span>
            <span className="lux-reports-summary__chip">
              <i className="fe fe-database" aria-hidden="true" />
              {isLoading
                ? <Skeleton width={72} height={12} borderRadius={4} />
                : isFiltered
                  ? `${itemCount || 0} of ${totalItemCount || 0} rows`
                  : `${itemCount || 0} rows`}
            </span>
            {filterText.trim() && (
              <span className="lux-reports-summary__chip">
                <i className="fe fe-search" aria-hidden="true" />
                {filterText.trim()}
              </span>
            )}
            {metaInfo && metaInfo.reportType && (
              <span className="lux-reports-summary__chip">
                <i className="fe fe-code" aria-hidden="true" />
                {metaInfo.reportType}
              </span>
            )}
          </div>
        </div>
      </section>
    );
  }
}

export default ReportsPageSummary;
