import { REGISTER_DEFAULT_PAGE_SIZE } from "_helpers/registerPagination.utils";

/** How many placeholder rows to show while a register list loads. */
export function getRegisterSkeletonRowCount(rowCount, pageSize) {
  const n = rowCount != null ? rowCount : pageSize != null ? pageSize : REGISTER_DEFAULT_PAGE_SIZE;
  const parsed = Number(n);
  return Math.min(Math.max(parsed || 12, 10), 25);
}

export function getRegisterSkeletonRowKeys(rowCount, pageSize) {
  return Array.from({ length: getRegisterSkeletonRowCount(rowCount, pageSize) }, (_, i) => i + 1);
}
