import React from "react";
import AsideExpandableChipList from "./profile/AsideExpandableChipList";
import ProfileLeaveSummary from "./leave/ProfileLeaveSummary";
import {
  getSortedTeamNames,
  parseDisplayValueList,
} from "./profile/profilePage.utils";

/** Sidebar: default team, additional teams, service lines — luxury panels */
const ProfilePageAside = ({ employee }) => {
  if (!employee) return null;

  const defaultTeam =
    employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name;
  const additionalTeams = getSortedTeamNames(employee.additionalUserTeamDetails) || [];
  const serviceLines = parseDisplayValueList(employee.serviceLines);

  const hasTeams = defaultTeam || additionalTeams.length > 0;
  const hasServiceLines = serviceLines.length > 0;

  if (!hasTeams && !hasServiceLines) return null;

  return (
    <aside className="pd-workspace__aside profile-aside" aria-label="Team context">
      {hasTeams && (
        <section className="lux-profile-aside-card">
          <header className="lux-profile-aside-card__head">
            <span className="lux-profile-aside-card__icon" aria-hidden="true">
              <i className="fe fe-users" />
            </span>
            <h2 className="lux-profile-aside-card__title">Teams</h2>
          </header>
          <div className="lux-profile-aside-card__body">
            <div className="lux-profile-aside-meta">
              <span className="lux-profile-aside-meta__label">Default team</span>
              <strong className="lux-profile-aside-meta__value">{defaultTeam || "—"}</strong>
            </div>
            <div className="lux-profile-aside-subblock">
              <span className="lux-profile-aside-subblock__label">Additional teams</span>
              <AsideExpandableChipList
                items={additionalTeams}
                emptyLabel="No additional team access"
              />
            </div>
          </div>
        </section>
      )}

      {employee.id && (
        <ProfileLeaveSummary
          employeeId={employee.id}
          employeeName={employee.name}
          userTeamId={employee.userTeamId}
        />
      )}

      {hasServiceLines && (
        <section className="lux-profile-aside-card">
          <header className="lux-profile-aside-card__head">
            <span className="lux-profile-aside-card__icon" aria-hidden="true">
              <i className="fe fe-layers" />
            </span>
            <h2 className="lux-profile-aside-card__title">Service lines</h2>
          </header>
          <div className="lux-profile-aside-card__body">
            <AsideExpandableChipList items={serviceLines} emptyLabel="No service lines" />
          </div>
        </section>
      )}
    </aside>
  );
};

export default ProfilePageAside;
