import React, { Component } from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import DeliverableListRow from "./DeliverableListRow";
import LuxRegisterPagination from "views/common/fragments/LuxRegisterPagination";
import { REGISTER_PAGE_SIZE_OPTIONS } from "_helpers/registerPagination.utils";

const LIST_COLUMNS = [
  { key: "index", label: "#", icon: "fe-hash" },
  { key: "id", label: "Ref", icon: "fe-hash" },
  { key: "name", label: "Deliverable", icon: "fe-layers" },
  { key: "category", label: "Category", icon: "fe-tag" },
  { key: "members", label: "Team", icon: "fe-users" },
  { key: "dates", label: "Timeline", icon: "fe-clock" },
  { key: "progress", label: "Progress", icon: "fe-activity" },
  { key: "status", label: "Status", icon: "fe-flag", center: true },
  { key: "actions", label: "", center: true },
];

class DeliverableListTable extends Component {
  render() {
    const count =
      this.props.totalCount != null
        ? this.props.totalCount
        : this.props.tasks
        ? this.props.tasks.length
        : 0;
    const rangeStart = this.props.pagination ? this.props.pagination.rangeStart : 1;

    return (
      <div className="lux-bid-list-shell lux-deliverable-register">
        <div className="lux-deliverable-register__toolbar">
          <span className="lux-deliverable-register__count">
            {this.props.isLoading ? (
              <LuxListCountSkeleton />
            ) : (
              <>
                <strong>{count}</strong>
                <em>{count === 1 ? "record" : "records"}</em>
              </>
            )}
          </span>
          <button
            type="button"
            className={classNames("lux-bid-list-shell__refresh lux-deliverable-register__refresh", {
              "is-loading": this.props.isLoading,
            })}
            title="Refresh list"
            aria-label="Refresh deliverables"
            onClick={() => this.props.reloadDeliverables && this.props.reloadDeliverables()}
          >
            <i className="fe fe-refresh-cw" aria-hidden="true" />
          </button>
        </div>

        <div className="lux-bid-list lux-deliverable-register__list" aria-label="Deliverables">
          <div className="lux-bid-list__head" role="row">
            {LIST_COLUMNS.map((col) => (
              <div
                key={col.key}
                className={[
                  "lux-bid-list__head-cell",
                  `lux-bid-list__head-cell--${col.key}`,
                  col.center ? "is-center" : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
                role="columnheader"
              >
                {col.icon && col.label ? (
                  <span className="lux-bid-list__head-label">
                    <i className={`fe ${col.icon}`} aria-hidden="true" />
                    {col.label}
                  </span>
                ) : (
                  <span className="lux-bid-list__head-label lux-bid-list__head-label--sr">
                    {col.key === "actions" ? "Actions" : col.label}
                  </span>
                )}
              </div>
            ))}
          </div>

          <div
            className={classNames("lux-bid-list__body", { "is-loading": this.props.isLoading })}
            role="list"
          >
            {this.props.isLoading && (
              <LuxRegisterListSkeletonRows
                variant="bid"
                pageSize={this.props.pagination && this.props.pagination.pageSize}
              />
            )}
            {!this.props.isLoading &&
              this.props.tasks &&
              this.props.tasks.map((task, index) => (
                <DeliverableListRow
                  key={task.id}
                  task={task}
                  rowIndex={rangeStart + index}
                  projectId={this.props.projectId}
                  permission={this.props.permission}
                  handleDeleteTask={this.props.handleDeleteTask}
                  handleEditTask={this.props.handleEditTask}
                  handleUpdateStatus={this.props.handleUpdateStatus}
                  handleDuplicateTask={this.props.handleDuplicateTask}
                  handleActivateTask={this.props.handleActivateTask}
                  handleRemoveTask={this.props.handleRemoveTask}
                  onViewTask={this.props.onViewTask}
                />
              ))}
          </div>
        </div>

        {this.props.pagination && !this.props.isLoading && this.props.pagination.total > 0 && (
          <LuxRegisterPagination
            pagination={this.props.pagination}
            onPageChange={this.props.onPageChange}
            onPageSizeChange={this.props.onPageSizeChange}
            pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
            summaryLabel={this.props.paginationSummaryLabel || "deliverables"}
            className="lux-register-list__pagination"
          />
        )}
      </div>
    );
  }
}

export default DeliverableListTable;
