import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import { accountActions } from "_actions";
import { appConfigActions } from "_actions";
import { projectConstants } from "_constants";
import { accessUtils } from "_helpers";
import { commonUtils } from "_helpers";
import { store } from "_helpers";
import CreateAccountModal from "./components/CreateAccountModal";
import { projectActions } from "_actions";
import { userUtils } from "_helpers";
import PageInnerHeaderAccounts from "views/common/PageInnerHeaderAccounts";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import PageCreateButton from "views/common/fragments/PageCreateButton";
import AccountsDirectoryList from "./components/AccountsDirectoryList";
import AccountDetailPopover from "./components/AccountDetailPopover";
import AccountsPageSummary from "./components/fragments/AccountsPageSummary";
import {
  buildAccountsSummaryStats,
  itemMatchesQualityFilter,
} from "./components/fragments/accountsSummary.utils";
import { buildAccountsSummaryCharts } from "./components/fragments/accountsSummary.charts";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxRegisterFetchError from "views/common/fragments/LuxRegisterFetchError";
import {
  getRegisterEmptyCopy,
  shouldShowRegisterEmptyState,
  shouldShowRegisterFetchError,
} from "_helpers/registerListError.utils";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class AccountsListPage extends PureComponent {
  constructor() {
    super();
    this.state = {
      pageNumber: 1,
      defaultNumberOfItemsInThePage: 24,
      parentItem: {},
      breadCrumps: [],
      viewName: "ACCOUNTS",
      viewByAccounts: true,
      /* false = hierarchy drill-down (account → team → client). Module key: userTeamAccountsDisabled */
      userTeamAccountsDisabled: false,
      permission: accessUtils.getAccountsAccessControl(),
      userTeamsPermission: accessUtils.getUserTeamsAccessControl(),
      isSalesForceEnabled: false,
      filterOptions: { filterText: null },
      typeFilter: "",
      qualityFilter: "",
      detailPopover: null,
      confirmRemoveId: null,
    };
  }

  processProjectModuleData = (moduleConfig) => {
    const configVal = commonUtils.getAppConfigValue(moduleConfig, "userTeamAccountsDisabled");
    const userTeamAccountsDisabled = configVal === true || configVal === "true";
    const syncDisabled =
      commonUtils.getAppConfigValue(moduleConfig, "accountsExtSyncDisabled") === true;
    const syncEnabledExplicit = commonUtils.getAppConfigValue(
      moduleConfig,
      "accountImportFromSalesForceEnabled"
    );
    const isSalesForceEnabled =
      !syncDisabled &&
      (syncEnabledExplicit === true ||
        syncEnabledExplicit === "true" ||
        syncEnabledExplicit === undefined ||
        syncEnabledExplicit === null);
    this.setState({ userTeamAccountsDisabled, isSalesForceEnabled });
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    store.dispatch(this.props.getProjectAllAccounts());
    store.dispatch(
      projectActions.getModuleConfigData(userUtils.getCurrentTeamId(), this.processProjectModuleData)
    );
  }

  onShowAllByAccounts = () => {
    this.setState({
      viewName: "ACCOUNTS",
      viewByAccounts: true,
      breadCrumps: [],
      parentItem: {},
      pageNumber: 1,
      detailPopover: null,
    });
    store.dispatch(this.props.getProjectAllAccounts());
  };

  onShowAllByUserTeams = () => {
    if (!this.props.userTeamsByGroup) {
      this.initializeUserTeams();
    }
    this.setState({
      viewName: "USERTEAMS",
      viewByAccounts: false,
      breadCrumps: [],
      parentItem: {},
      pageNumber: 1,
      detailPopover: null,
    });
  };

  onSelectItemBack = (currentItem, viewName, index) => {
    const breadCrumps = [...this.state.breadCrumps];
    this.setState({ parentItem: currentItem || {}, detailPopover: null, pageNumber: 1 });
    this.initializeAccounts(currentItem, viewName, index < 0 ? [] : breadCrumps.slice(0, index + 1));
  };

  onSelectItem = (currentItem, viewName, index) => {
    const breadCrumps = [...this.state.breadCrumps];
    breadCrumps.push({ viewName, currentItem });
    this.setState(
      { parentItem: currentItem, detailPopover: null, pageNumber: 1 },
      () => this.initializeAccounts(currentItem, viewName, breadCrumps)
    );
  };

  reloadAccountsList = () => {
    const { parentItem, viewName } = this.state;
    if (viewName === "ACCOUNT" && parentItem && parentItem.id) {
      store.dispatch(this.props.getProjectTeamAccounts(parentItem.id));
      return;
    }
    store.dispatch(this.props.getProjectAllAccounts());
  };

  initializeAccounts = (currentItem, viewName, breadCrumps) => {
    this.onCloseCreateItem();
    this.props.pageHeaderNameChangeHandler(
      viewName.charAt(0) + viewName.substr(1).toLowerCase()
    );
    if (viewName === "ACCOUNT") {
      if (currentItem) {
        store.dispatch(this.props.getProjectTeamAccounts(currentItem.id));
      } else {
        store.dispatch(this.props.getProjectAllAccounts());
        this.setState({ parentItem: {} });
      }
    } else if (viewName === "TEAM") {
      store.dispatch({
        type: projectConstants.GET_ALL_CURRENT_VIEW_ACCOUNTS_SUCCESS,
        items: currentItem.teams,
        viewName: "CLIENT",
      });
    } else if (viewName === "CLIENT") {
      store.dispatch({
        type: projectConstants.GET_ALL_CURRENT_VIEW_ACCOUNTS_SUCCESS,
        items: currentItem.clients,
        viewName: "CLIENT",
      });
    }
    this.setState({ viewName, breadCrumps });
  };

  initializeUserTeams = () => {
    store.dispatch(appConfigActions.getAllTeams(true));
  };

  handleRemoveAccountItem = (itemId) => {
    store.dispatch(this.props.removeAccountItem(itemId));
    this.setState({ confirmRemoveId: null, detailPopover: null });
  };

  handleRemoveUserTeamItem = (itemId) => {
    store.dispatch(this.props.removeUserTeamItem(itemId));
  };

  handleDeleteUserTeamItem = (itemId) => {
    store.dispatch(this.props.deleteUserTeamItem(itemId));
  };

  handleDetachFromTeam = (itemId) => {
    store.dispatch(
      this.props.detachFromAccountItem(
        itemId,
        this.state.breadCrumps[0].currentItem.id,
        this.state.parentItem.id
      )
    );
    this.setState({ detailPopover: null });
  };

  isHierarchyEnabled = () => this.state.userTeamAccountsDisabled === false;

  shouldInitializeCreateInHierarchy = () => {
    const { viewByAccounts, breadCrumps, parentItem, viewName } = this.state;
    if (!this.isHierarchyEnabled()) return false;
    if (viewName === "USERTEAMS") return false;
    if (!viewByAccounts) return breadCrumps && breadCrumps.length > 0;
    return (
      breadCrumps &&
      breadCrumps.length > 0 &&
      parentItem &&
      Object.keys(parentItem).length > 0
    );
  };

  getCreateMenuLabel = () => {
    const vn = this.state.viewName;
    if (vn === "ACCOUNTS" || vn === "ACCOUNT") return "Account";
    if (vn === "TEAM") return "Team";
    if (vn === "CLIENT") return "Client";
    if (!vn) return "Record";
    return vn.charAt(0) + vn.slice(1).toLowerCase();
  };

  isUserTeamsRoot = () =>
    this.state.viewName === "USERTEAMS" && this.state.breadCrumps.length === 0;

  initializeCreateContext = (userTeamId, parentId, createViewName) => {
    store.dispatch(
      this.props.initializeCreateAccounts(userTeamId, parentId, createViewName, true, false)
    );
  };

  createItemClickHandler = (e) => {
    e.preventDefault();
    const { breadCrumps, parentItem, viewName } = this.state;
    if (this.shouldInitializeCreateInHierarchy()) {
      this.initializeCreateContext(
        breadCrumps[0].currentItem.id,
        parentItem.id,
        viewName
      );
    }
    store.dispatch({ type: projectConstants.SHOW_PROJECT_ACCOUNT_ITEM_CREATE_WINDOW });
  };

  onCreateChildFromPopover = () => {
    const { detailPopover, breadCrumps, viewName } = this.state;
    if (!detailPopover || !detailPopover.item || !this.isHierarchyEnabled()) return;
    const { item } = detailPopover;
    const isUserTeam = viewName === "USERTEAMS" && !item.type;

    if (isUserTeam) {
      const nextCrumbs = [{ viewName: "ACCOUNT", currentItem: item }];
      this.setState(
        { parentItem: item, breadCrumps: nextCrumbs, viewName: "ACCOUNT", detailPopover: null },
        () => {
          this.initializeCreateContext(item.id, item.id, "ACCOUNT");
          store.dispatch({ type: projectConstants.SHOW_PROJECT_ACCOUNT_ITEM_CREATE_WINDOW });
        }
      );
      return;
    }

    const nextCrumbs = [...breadCrumps];
    let userTeamId = nextCrumbs[0] && nextCrumbs[0].currentItem && nextCrumbs[0].currentItem.id;

    if (item.type === "ACCOUNT" && nextCrumbs.length === 0) {
      nextCrumbs.push({ viewName: "ACCOUNT", currentItem: item });
      userTeamId = item.id;
    }
    if (!userTeamId) {
      userTeamId = item.id;
    }

    const createViewName = item.type === "ACCOUNT" ? "TEAM" : "CLIENT";

    this.setState(
      { parentItem: item, breadCrumps: nextCrumbs, viewName: createViewName, detailPopover: null },
      () => {
        this.initializeCreateContext(userTeamId, item.id, createViewName);
        store.dispatch({ type: projectConstants.SHOW_PROJECT_ACCOUNT_ITEM_CREATE_WINDOW });
      }
    );
  };

  onCloseCreateItem = () => {
    store.dispatch({ type: projectConstants.CLOSE_PROJECT_ACCOUNT_ITEM_CREATE_WINDOW });
  };

  handleSubmit = (accountsRequest, isNewItemSelected, createAnotherEnabled, submitCallBackFunction) => {
    if (isNewItemSelected) {
      store.dispatch(
        this.props.createAccountItem(accountsRequest, createAnotherEnabled, submitCallBackFunction)
      );
    } else {
      store.dispatch(
        this.props.addToAccountItem(
          accountsRequest.id,
          this.state.breadCrumps[0].currentItem.id,
          this.state.parentItem.id,
          createAnotherEnabled,
          submitCallBackFunction
        )
      );
    }
  };

  onFilterChange = (filterOptions) => {
    this.setState({ filterOptions, pageNumber: 1 }, () => {
      store.dispatch({ type: projectConstants.CHANGE_FILTER_ACCOUNTS, filterOptions });
    });
  };

  onFilterTextChange = (value) => {
    this.setState(
      (prevState) => ({
        filterOptions: { ...prevState.filterOptions, filterText: value },
        pageNumber: 1,
      }),
      () => this.onFilterChange(this.state.filterOptions)
    );
  };

  onTypeFilterChange = (typeFilter) => {
    this.setState({ typeFilter, pageNumber: 1 });
  };

  onQualityFilterChange = (qualityFilter) => {
    this.setState({ qualityFilter, pageNumber: 1 });
  };

  applyTypeFilter = (items) => {
    const { typeFilter } = this.state;
    if (!typeFilter || !items) return items;
    if (typeFilter === "SALES_FORCE") {
      return items.filter((item) => item.source === "SALES_FORCE");
    }
    return items.filter((item) => item.type === typeFilter);
  };

  applyQualityFilter = (items) => {
    const { qualityFilter } = this.state;
    if (!qualityFilter || !items) return items;
    return items.filter((item) => itemMatchesQualityFilter(item, qualityFilter));
  };

  getFilteredItems = () => {
    const base = commonUtils.filterAccounts(this.props.items, this.state.filterOptions);
    return this.applyQualityFilter(this.applyTypeFilter(base));
  };

  getPagedItems = () => {
    return this.paginateArray(commonUtils.sortArrayOfObjects(this.getFilteredItems(), true));
  };

  paginateArray = (data) => {
    if (!data) return [];
    return data.slice(0, this.state.pageNumber * this.state.defaultNumberOfItemsInThePage);
  };

  showMoreLoadButton = () => {
    const filtered = this.getFilteredItems();
    return (
      filtered && filtered.length > this.state.pageNumber * this.state.defaultNumberOfItemsInThePage
    );
  };

  onShowLoadButtonClick = () => {
    this.setState({ pageNumber: this.state.pageNumber + 1 });
  };

  getRemainingItemsCount = () => {
    const filtered = this.getFilteredItems();
    if (!filtered) return 0;
    return filtered.length - this.state.pageNumber * this.state.defaultNumberOfItemsInThePage;
  };

  importAccountsList = () => {
    if (this.props.accountsSyncLoading || this.props.accountLoading) {
      return;
    }
    store.dispatch(
      this.props.syncAccountsFromSalesforce(() => {
        this.setState({ pageNumber: 1, qualityFilter: "", typeFilter: "" });
        this.onShowAllByAccounts();
      })
    );
  };

  getUserTeamRows = () => {
    const rows = [];
    if (!this.props.allUserTeamsByGroup) return rows;
    commonUtils.sortArrayOfObjects(this.props.allUserTeamsByGroup, true).forEach((userTeamParent) => {
      if (!userTeamParent.nodes) return;
      commonUtils.sortArrayOfObjects(userTeamParent.nodes, true).forEach((userTeam) => {
        if (
          this.state.permission.showAllUserTeamsAccount ||
          commonUtils.getCurrentUserTeamIds().includes(userTeam.id)
        ) {
          rows.push({ item: userTeam, parentItem: userTeamParent });
        }
      });
    });
    return rows;
  };

  getSummaryViewLabel = () => {
    const { viewName, breadCrumps } = this.state;
    if (viewName === "USERTEAMS") return "User teams";
    if (breadCrumps.length === 0) return "All accounts";
    const last = breadCrumps[breadCrumps.length - 1];
    return last && last.currentItem ? last.currentItem.name : viewName;
  };

  openDetailPopover = (item, parentItem) => {
    this.setState({ detailPopover: { item, parentItem }, confirmRemoveId: null });
  };

  closeDetailPopover = () => {
    this.setState({ detailPopover: null, confirmRemoveId: null });
  };

  onRemoveRequest = (itemId, isConfirmed) => {
    if (isConfirmed) {
      this.handleRemoveAccountItem(itemId);
    } else {
      this.setState({ confirmRemoveId: itemId });
    }
  };

  onPopoverRemove = (isConfirmed) => {
    const { detailPopover, confirmRemoveId } = this.state;
    if (!detailPopover || !detailPopover.item) return;
    const id = detailPopover.item.id;
    if (isConfirmed || confirmRemoveId === id) {
      this.handleRemoveAccountItem(id);
    } else {
      this.setState({ confirmRemoveId: id });
    }
  };

  onPopoverDrillDown = () => {
    const { detailPopover, viewName: pageViewName } = this.state;
    if (!detailPopover) return;
    const { item } = detailPopover;
    const isUserTeam = pageViewName === "USERTEAMS" && !item.type;
    const drillViewName = isUserTeam ? "ACCOUNT" : this.props.viewName || pageViewName;
    const index = isUserTeam ? 0 : 2;
    this.closeDetailPopover();
    this.onSelectItem(item, drillViewName, index);
  };

  render() {
    const isUserTeamsRoot = this.isUserTeamsRoot();
    const isUserTeamsView = isUserTeamsRoot;
    const effectiveViewName = this.state.viewName || this.props.viewName;
    const filteredItems = this.getFilteredItems();
    const pagedItems = this.getPagedItems();
    const gridParent =
      this.state.parentItem && Object.keys(this.state.parentItem).length > 0
        ? this.state.parentItem
        : { name: isUserTeamsView ? "User teams" : "All accounts" };

    const summaryItems = isUserTeamsView
      ? this.getUserTeamRows().map((r) => r.item)
      : filteredItems;

    const summaryStat = buildAccountsSummaryStats(summaryItems, {
      isUserTeamsView,
      viewLabel: this.getSummaryViewLabel(),
      breadcrumbDepth: this.state.breadCrumps.length,
      breadcrumbLabel: this.getSummaryViewLabel(),
    });
    const summaryCharts = buildAccountsSummaryCharts(summaryStat);

    const hierarchyEnabled = this.isHierarchyEnabled();

    const showSalesforceSync =
      this.state.isSalesForceEnabled === true &&
      !isUserTeamsView &&
      this.state.viewByAccounts;
    const salesforceSyncBusy =
      this.props.accountsSyncLoading === true || this.props.accountLoading === true;

    const salesforceButton = showSalesforceSync ? (
      <button
        type="button"
        className="lux-page-header__action-btn lux-page-header__action-btn--accent"
        title="Refresh accounts from Salesforce"
        disabled={salesforceSyncBusy}
        onClick={() => this.importAccountsList()}
      >
        <i
          className={classNames(
            "fe",
            salesforceSyncBusy ? "fe-loader" : "fe-cloud",
            salesforceSyncBusy && "lux-spin"
          )}
          aria-hidden="true"
        />
        {salesforceSyncBusy ? "Syncing…" : "Sync Salesforce"}
      </button>
    ) : null;

    return (
      <div className="projectlist lux-accounts" data-testid="page-finance-accounts">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.accountsList}
          actions={
            this.state.permission.createEnabled && !isUserTeamsRoot ? (
              <PageCreateButton onClick={this.createItemClickHandler}>
                {`Create ${this.getCreateMenuLabel()}`}
              </PageCreateButton>
            ) : null
          }
        />

        <PageInnerHeaderAccounts
                  breadCrumps={this.state.breadCrumps}
                  showFilter={!isUserTeamsView}
                  viewByAccounts={this.state.viewByAccounts}
                  filterOptions={this.state.filterOptions}
                  isLoading={this.props.accountLoading}
                  onFilterTextChange={this.onFilterTextChange}
                  onSelectItem={this.onSelectItemBack}
                  showGridListMenu={
                  this.state.permission.showAllByAccounts && this.state.userTeamAccountsDisabled === false
                  }
                  gridClickHandler={this.onShowAllByUserTeams}
                  listClickHandler={this.onShowAllByAccounts}
                  additionalButtons={salesforceButton}
                />

        <AccountsPageSummary
          stat={summaryStat}
          charts={summaryCharts}
          visibleCount={isUserTeamsView ? summaryItems.length : (filteredItems && filteredItems.length) || 0}
          filterOptions={this.state.filterOptions}
          isLoading={this.props.accountLoading}
          typeFilter={this.state.typeFilter}
          onTypeFilter={this.onTypeFilterChange}
          qualityFilter={this.state.qualityFilter}
          onQualityFilter={this.onQualityFilterChange}
          viewLabel={this.getSummaryViewLabel()}
        />

        {shouldShowRegisterFetchError({
          error: this.props.error,
          isLoading: this.props.accountLoading,
          items: this.props.items,
        }) && (
          <LuxRegisterFetchError
            error={this.props.error}
            onRetry={this.reloadAccountsList}
          />
        )}

        <div className="lux-register-list-section">
          {isUserTeamsRoot ? (
            <AccountsDirectoryList
              itemRows={this.getUserTeamRows()}
              isLoading={false}
              viewName="USERTEAMS"
              viewByAccounts={false}
              hierarchyEnabled={hierarchyEnabled}
              permission={this.state.permission}
              userTeamsPermission={this.state.userTeamsPermission}
              isUserTeamsView
              onSelectItem={this.onSelectItem}
              onOpenDetail={(item, rowParent) => this.openDetailPopover(item, rowParent)}
            />
          ) : (
            <>
              <AccountsDirectoryList
                items={pagedItems}
                parentItem={gridParent}
                isLoading={this.props.accountLoading}
                viewName={this.props.viewName || effectiveViewName}
                viewByAccounts={this.state.viewByAccounts}
                hierarchyEnabled={hierarchyEnabled}
                permission={this.state.permission}
                userTeamsPermission={this.state.userTeamsPermission}
                confirmRemoveId={this.state.confirmRemoveId}
                onSelectItem={this.onSelectItem}
                onOpenDetail={this.openDetailPopover}
                onRemoveRequest={this.onRemoveRequest}
                onDetach={this.handleDetachFromTeam}
              />
              {this.showMoreLoadButton() && (
                <div className="lux-acct-load-more">
                  <button type="button" onClick={this.onShowLoadButtonClick}>
                    Load more ({this.getRemainingItemsCount()} remaining)
                  </button>
                </div>
              )}
            </>
          )}

          {shouldShowRegisterEmptyState({
            error: this.props.error,
            isLoading: this.props.accountLoading,
            items: isUserTeamsView ? this.getUserTeamRows() : filteredItems,
          }) && (() => {
            const emptyCopy = getRegisterEmptyCopy(this.props.error, {
              eyebrow: "Account directory",
              title: "No records in this view",
              description: isUserTeamsView
                ? "No user teams match your access. Switch to all accounts or ask an admin to grant team visibility."
                : "Try adjusting filters, drilling into another account, or create a new record from the toolbar.",
              notFoundTitle: "Item not available",
              notFoundDescription:
                "No accounts are available for the selected view or filters.",
            });
            return (
              <LuxRegisterEmptyState
                variant="projects"
                eyebrow={emptyCopy.eyebrow}
                title={emptyCopy.title}
                description={emptyCopy.description}
                hints={[
                  "Browse hierarchy: account → team → client",
                  "Filter by name or Salesforce ID (3+ characters)",
                  "Use Details on a row for quick actions and popover",
                ]}
                showCreate={this.state.permission.createEnabled && !isUserTeamsRoot}
                createLabel={`Create ${this.getCreateMenuLabel()}`}
                onCreate={this.createItemClickHandler}
                showSecondary={showSalesforceSync}
                secondaryLabel="Sync from Salesforce"
                onSecondary={this.importAccountsList}
                secondaryDisabled={salesforceSyncBusy}
                secondaryIcon="fe fe-cloud"
              />
            );
          })()}
        </div>

        {this.state.detailPopover && (
          <AccountDetailPopover
            show
            item={this.state.detailPopover.item}
            parentItem={this.state.detailPopover.parentItem}
            viewName={isUserTeamsRoot ? "USERTEAMS" : effectiveViewName}
            viewByAccounts={this.state.viewByAccounts}
            hierarchyEnabled={hierarchyEnabled}
            createEnabled={this.state.permission.createEnabled}
            permission={isUserTeamsView ? this.state.userTeamsPermission : this.state.permission}
            confirmRemove={this.state.confirmRemoveId === this.state.detailPopover.item.id}
            onClose={this.closeDetailPopover}
            onDrillDown={this.onPopoverDrillDown}
            onCreateChild={this.onCreateChildFromPopover}
            onRemove={this.onPopoverRemove}
            onDetach={() => this.handleDetachFromTeam(this.state.detailPopover.item.id)}
          />
        )}

        <CreateAccountModal
          show={this.props.showCreateModel === true}
          selectedUserTeamItem={
            this.state.breadCrumps &&
            this.state.breadCrumps.length > 0 &&
            this.state.breadCrumps[0].currentItem
          }
          selectedParentItem={this.state.parentItem}
          viewName={effectiveViewName === "ACCOUNTS" ? "ACCOUNT" : effectiveViewName}
          handleSubmit={this.handleSubmit}
          closeActionHandler={this.onCloseCreateItem}
        />
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  authentication: state.authentication,
  allUserTeamsByGroup: state.appconfig.allUserTeamsByGroup,
  items: state.accounts.currentViewItems,
  viewName: state.accounts.viewName,
  accountLoading: state.accounts.accountsLoading,
  error: state.accounts.error,
  accountsSyncLoading: state.accounts.accountsSyncLoading,
  allProjectTeamAccounts: state.accounts.allProjectTeamAccounts,
  showCreateModel: state.accounts.showCreateModel,
});
const mapDispatchToProps = (dispatch) => ({
  getProjectTeamAccounts: accountActions.getProjectTeamAccounts,
  getProjectAllAccounts: accountActions.getProjectAllAccounts,
  syncAccountsFromSalesforce: accountActions.syncAccountsFromSalesforce,
  initializeCreateAccounts: accountActions.initializeCreateAccounts,
  createAccountItem: accountActions.createAccountItem,
  updateAccountItem: accountActions.updateAccountItem,
  removeAccountItem: accountActions.removeAccountItem,
  detachFromAccountItem: accountActions.detachFromAccountItem,
  addToAccountItem: accountActions.addToAccountItem,
  removeUserTeamItem: appConfigActions.removeUserTeamItem,
  deleteUserTeamItem: appConfigActions.deleteUserTeamItem,
});
export default connect(mapStateToProps, mapDispatchToProps)(AccountsListPage);
