import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

function LeaveKpiStrip({ summary, pendingCount, loading, moduleEnabled }) {
  const s = summary || {};
  const pending = Number(pendingCount != null ? pendingCount : s.pending) || 0;

  const cards = [
    {
      id: "pending",
      label: "Pending approval",
      value: <CountUp end={pending} duration={0.75} separator="," />,
      hint: "Awaiting manager action",
      tone: "amber",
      icon: "fe fe-clock",
    },
    {
      id: "approved",
      label: "Approved",
      value: <CountUp end={Number(s.approved) || 0} duration={0.75} separator="," />,
      hint: "This period",
      tone: "green",
      icon: "fe fe-check-circle",
    },
    {
      id: "days",
      label: "Days approved",
      value: (
        <CountUp end={Number(s.totalDaysApproved) || 0} decimals={1} duration={0.75} separator="," />
      ),
      hint: "Working days taken",
      tone: "primary",
      icon: "fe fe-sun",
    },
    {
      id: "total",
      label: "Total requests",
      value: <CountUp end={Number(s.total) || 0} duration={0.75} separator="," />,
      hint: moduleEnabled ? "Tracopus + synced HR" : "Module preview",
      tone: "violet",
      icon: "fe fe-layers",
    },
  ];

  return (
    <LuxKpiStrip cards={cards} loading={loading} className={classNames("lux-leave-kpi-strip")} />
  );
}

export default LeaveKpiStrip;
