import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import { AdminInsightStrip, AdminQuickNav } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PayrollHubNav, PayrollKpiStrip } from "views/payroll/components/PayrollLuxShared";

export default function EmployeeFinanceLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo employee finance data",
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  children,
  showHubNav = true,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "violet",
    icon: "fe fe-pie-chart",
    eyebrow: "Payroll",
    titleLead: "Employee",
    titleAccent: "finance",
    lede: "Benefits, compensation, and employee finance workspace",
  };

  return (
    <div className={classNames("lux-register-page", "lux-payroll-module", "lux-empfin-lux", meta.tone && `is-${meta.tone}`)}>
      <div className="lux-empfin-lux__ambient" aria-hidden="true">
        <span className="lux-empfin-lux__orb lux-empfin-lux__orb--a" />
        <span className="lux-empfin-lux__orb lux-empfin-lux__orb--b" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        nav={showHubNav ? <PayrollHubNav /> : undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <PayrollKpiStrip cards={kpiCards} loading={loading} className="lux-empfin-lux__kpi-strip" />
        ) : null}

        <div className="lux-empfin-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function EmployeeFinanceActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-empfin-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function EmployeeFinanceLuxPanel({ title, meta, icon, accent, actions, children }) {
  return (
    <section className={classNames("lux-hrms-dash__panel", "lux-empfin-lux__panel", accent && `is-${accent}`)}>
      <header className="lux-hrms-dash__panel-head lux-empfin-lux__panel-head">
        <div className="lux-empfin-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-empfin-lux__panel-body">{children}</div>
    </section>
  );
}

export function EmployeeFinanceInsightPanel({ insights = [] }) {
  return <AdminInsightStrip insights={insights} className="lux-empfin-lux__insights" />;
}

export function EmployeeFinanceQuickNav({ links = [], eyebrow = "Employee finance drill-down" }) {
  return <AdminQuickNav eyebrow={eyebrow} links={links} className="lux-empfin-lux__quick-nav" />;
}
