import React from "react";
import classNames from "classnames/bind";

/**
 * Dashboard view switcher (personal vs team/manager).
 * Default matches /people/dashboard (segmented pill track).
 * Pass navClassName="lux-planner-nav" to keep planner layout with the same tab buttons.
 */
export default function LuxDashboardViewTabs({
  tabs,
  activeTab,
  onChange,
  showTabs = true,
  className,
  navClassName = "lux-hrms-dash__tabs",
  tabClassName = "lux-hrms-dash__tab",
  ariaLabel = "Dashboard views",
  labelWrap = false,
}) {
  if (!showTabs || !tabs || tabs.length === 0) {
    return null;
  }

  return (
    <nav className={classNames(navClassName, className)} aria-label={ariaLabel}>
      {tabs.map((tab) => (
        <button
          key={tab.id}
          type="button"
          className={classNames(tabClassName, { "is-active": activeTab === tab.id })}
          onClick={() => onChange && onChange(tab.id)}
          aria-selected={activeTab === tab.id}
        >
          <i className={`fe ${tab.icon}`} aria-hidden="true" />
          {labelWrap ? <span>{tab.label}</span> : tab.label}
        </button>
      ))}
    </nav>
  );
}
