import React from "react";
import classNames from "classnames/bind";
import { FEATURE_FLAG_STATUSES } from "config/feature-flag.config";
import { getFeatureFlagModuleMeta } from "config/feature-flag.utils";
import { AdminActionButton } from "views/admin/components/AdminLuxShared";

export default function FeatureFlagDetailPanel({ flag, saving, onToggle, onSetStatus, dependents = [] }) {
  if (!flag) {
    return (
      <div className="lux-fflag-detail lux-fflag-detail--empty">
        <span className="lux-fflag-detail__empty-icon" aria-hidden="true">
          <i className="fe fe-toggle-right" />
        </span>
        <strong>Select a feature flag</strong>
        <p>Inspect scope, dependencies, adoption, and rollout status before enabling org-wide.</p>
      </div>
    );
  }

  const meta = getFeatureFlagModuleMeta(flag.module);
  const adoption = Math.max(0, Math.min(100, Number(flag.adoptionPct) || 0));

  return (
    <aside className="lux-fflag-detail">
      <header className="lux-fflag-detail__head">
        <div className="lux-fflag-detail__identity">
          <span
            className={classNames("lux-fflag-detail__avatar", meta.tone && `is-${meta.tone}`)}
            aria-hidden="true"
          >
            <i className={meta.icon} />
          </span>
          <div>
            <h3>{flag.name}</h3>
            <p>
              {flag.key} · {flag.scope} scope · {flag.owner}
            </p>
          </div>
        </div>
        <span className={classNames("lux-fflag-detail__risk-pill", `is-${flag.risk}`)}>
          {flag.risk} risk
        </span>
      </header>

      <label
        className={classNames("lux-fflag-detail__switch", {
          "is-on": flag.enabled,
          "is-saving": saving,
        })}
      >
        <input
          type="checkbox"
          checked={flag.enabled}
          disabled={saving}
          onChange={(e) => onToggle && onToggle(e.target.checked)}
        />
        <span className="lux-fflag-detail__switch-track" aria-hidden="true">
          <span className="lux-fflag-detail__switch-thumb" />
        </span>
        <span className="lux-fflag-detail__switch-label">
          {flag.enabled ? "Enabled for org" : "Disabled"}
        </span>
      </label>

      <p className="lux-fflag-detail__copy">{flag.description}</p>

      <div className="lux-fflag-detail__adoption">
        <div className="lux-fflag-detail__adoption-head">
          <span>Adoption</span>
          <strong>{adoption}%</strong>
        </div>
        <div className="lux-fflag-detail__adoption-bar" aria-hidden="true">
          <span
            className={classNames("lux-fflag-detail__adoption-fill", {
              "is-on": flag.enabled,
            })}
            style={{ width: `${adoption}%` }}
          />
        </div>
      </div>

      <dl className="lux-fflag-detail__meta">
        <div>
          <dt>Module</dt>
          <dd>{flag.module || "—"}</dd>
        </div>
        <div>
          <dt>Status</dt>
          <dd>{flag.status || "—"}</dd>
        </div>
        <div>
          <dt>Org group</dt>
          <dd>{flag.group || "—"}</dd>
        </div>
        <div>
          <dt>Env key</dt>
          <dd>{flag.envKey || "—"}</dd>
        </div>
      </dl>

      {dependents.length > 0 && (
        <section className="lux-fflag-detail__deps">
          <div className="lux-fflag-detail__deps-head">
            <h4>Dependencies</h4>
            <span>{dependents.length}</span>
          </div>
          <ul role="list">
            {dependents.map((dep) => (
              <li key={dep.key} className={classNames({ "is-missing": !dep.enabled })} role="listitem">
                <i className={dep.enabled ? "fe fe-check-circle" : "fe fe-alert-circle"} aria-hidden="true" />
                <span>{dep.name || dep.key}</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      <div className="lux-fflag-detail__actions">
        <AdminActionButton
          variant="primary"
          className="lux-onb-action--sm"
          disabled={saving}
          onClick={() => onSetStatus && onSetStatus(FEATURE_FLAG_STATUSES.PILOT)}
        >
          Mark pilot
        </AdminActionButton>
        <AdminActionButton
          variant="ghost"
          className="lux-onb-action--sm"
          disabled={saving}
          onClick={() => onSetStatus && onSetStatus(FEATURE_FLAG_STATUSES.DISABLED)}
        >
          Disable
        </AdminActionButton>
      </div>
    </aside>
  );
}
