import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import {
  formatHoursDecimalForInput,
  hoursDecimalToMinutes,
  lookupDayCapacity,
  minutesToHoursDecimal,
  summarizePlannerTimeEntry,
} from "../plannerAssignForm.utils";
import { formatPlannerHours } from "../planner.utils";

function DayHoursEditorPopover({
  anchorEl,
  dateKey,
  entry,
  dayInfo,
  startTimeLabel,
  maxHoursAllowed,
  onSave,
  onRemove,
  onClose,
}) {
  const popoverRef = useRef(null);
  const [draftHours, setDraftHours] = useState(
    entry.timesheetTimeHours != null ? String(entry.timesheetTimeHours) : "8"
  );

  const allocated = dayInfo ? dayInfo.allocated : 0;
  const capacity = dayInfo ? dayInfo.capacity : 8 * 60;
  const draftMins = hoursDecimalToMinutes(draftHours);
  const availableAfter = dayInfo ? Math.max(0, capacity - allocated - draftMins) : null;
  const totalAfter = allocated + draftMins;
  const isOver = capacity > 0 && totalAfter > capacity;

  const position = useMemo(() => {
    if (!anchorEl || typeof window === "undefined") return { top: 80, left: 80 };
    const rect = anchorEl.getBoundingClientRect();
    const width = 300;
    let left = rect.left;
    let top = rect.bottom + 6;
    if (left + width > window.innerWidth - 12) {
      left = window.innerWidth - width - 12;
    }
    if (top + 280 > window.innerHeight - 12) {
      top = rect.top - 6;
    }
    return { top, left, width };
  }, [anchorEl]);

  useEffect(() => {
    const onDoc = (e) => {
      if (
        popoverRef.current &&
        !popoverRef.current.contains(e.target) &&
        anchorEl &&
        !anchorEl.contains(e.target)
      ) {
        onClose();
      }
    };
    const onKey = (e) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
    };
  }, [anchorEl, onClose]);

  const applyHours = (hours) => {
    setDraftHours(String(hours));
  };

  const maxFillHours = dayInfo
    ? minutesToHoursDecimal(Math.max(0, capacity - allocated))
    : maxHoursAllowed;

  return createPortal(
    <div
      ref={popoverRef}
      className="lux-planner-day-hours-popover"
      style={{ position: "fixed", top: position.top, left: position.left, width: position.width, zIndex: 13000 }}
      role="dialog"
      aria-label={`Edit hours for ${dateKey}`}
    >
      <header className="lux-planner-day-hours-popover__head">
        <div>
          <strong>{dayInfo ? `${dayInfo.weekday} ${dayInfo.dateLabel}` : dateKey}</strong>
          <span>Starts {startTimeLabel}</span>
        </div>
        <button type="button" className="lux-planner-day-hours-popover__close" onClick={onClose} aria-label="Close">
          <i className="fe fe-x" />
        </button>
      </header>

      <div className="lux-planner-day-hours-popover__stats">
        <div>
          <span>Already booked</span>
          <strong>{dayInfo ? dayInfo.allocatedLabel : "—"}</strong>
        </div>
        <div>
          <span>Day capacity</span>
          <strong>{dayInfo ? dayInfo.capacityLabel : "8h"}</strong>
        </div>
        <div className={classNames({ "is-good": availableAfter > 0 && !isOver, "is-warn": isOver })}>
          <span>{isOver ? "Over capacity" : "Still available"}</span>
          <strong>
            {isOver
              ? `+${formatPlannerHours(totalAfter - capacity)}`
              : availableAfter != null
                ? formatPlannerHours(availableAfter)
                : "—"}
          </strong>
        </div>
      </div>

      {dayInfo && capacity > 0 && (
        <div className="lux-planner-day-hours-popover__bar" aria-hidden>
          <span
            className="is-booked"
            style={{ width: `${Math.min(100, (allocated / capacity) * 100)}%` }}
          />
          <span
            className={classNames("is-new", { "is-over": isOver })}
            style={{ width: `${Math.min(100, (draftMins / capacity) * 100)}%` }}
          />
        </div>
      )}

      <label className="lux-planner-day-hours-popover__field">
        <span>Hours this day</span>
        <input
          type="number"
          min={0}
          max={maxHoursAllowed}
          step={0.25}
          value={draftHours}
          onChange={(e) => setDraftHours(e.target.value)}
          autoFocus
        />
      </label>

      <div className="lux-planner-day-hours-popover__quick">
        {[1, 2, 4, 6].map((h) => (
          <button key={h} type="button" onClick={() => applyHours(h)}>
            {h}h
          </button>
        ))}
        {maxFillHours > 0 && (
          <button type="button" onClick={() => applyHours(maxFillHours)}>
            Fill available
          </button>
        )}
      </div>

      {isOver && (
        <p className="lux-planner-day-hours-popover__warn">
          <i className="fe fe-alert-triangle" /> This exceeds day capacity by{" "}
          {formatPlannerHours(totalAfter - capacity)}.
        </p>
      )}

      <footer className="lux-planner-day-hours-popover__foot">
        <button type="button" className="lux-planner-btn lux-planner-btn--ghost" onClick={onRemove}>
          Remove day
        </button>
        <button
          type="button"
          className="lux-planner-btn lux-planner-btn--primary"
          onClick={() => onSave(dateKey, draftHours)}
        >
          Apply
        </button>
      </footer>
    </div>,
    document.body
  );
}

function DayHourRow({ dateKey, entry, dayInfo, startTimeLabel, maxHoursAllowed, onChange, onRemove }) {
  const triggerRef = useRef(null);
  const [open, setOpen] = useState(false);

  const draftMins = entry.timesheetTimeMins || hoursDecimalToMinutes(entry.timesheetTimeHours);
  const allocated = dayInfo ? dayInfo.allocated : 0;
  const capacity = dayInfo ? dayInfo.capacity : 0;
  const availableAfter = dayInfo ? Math.max(0, capacity - allocated - draftMins) : null;
  const totalAfter = allocated + draftMins;
  const isOver = capacity > 0 && totalAfter > capacity;
  const isWeekend = entry.dayNumber === 0 || entry.dayNumber === 6;

  return (
    <>
      <div
        className={classNames("lux-planner-day-hour-row", {
          "is-weekend": isWeekend,
          "is-leave": dayInfo && dayInfo.isOnLeave,
          "is-over": isOver,
          "is-open": open,
        })}
      >
        <div className="lux-planner-day-hour-row__date">
          <strong>{dayInfo ? dayInfo.weekday : ""}</strong>
          <span>{dayInfo ? dayInfo.dateLabel : dateKey}</span>
        </div>

        <div className="lux-planner-day-hour-row__capacity">
          {dayInfo && dayInfo.isOnLeave ? (
            <span className="lux-planner-day-hour-row__tag is-leave">Leave / no capacity</span>
          ) : (
            <>
              <span className="lux-planner-day-hour-row__tag is-booked">
                Other work {dayInfo ? dayInfo.allocatedLabel : "—"}
              </span>
              {draftMins > 0 && (
                <span className="lux-planner-day-hour-row__tag is-this">
                  This entry {formatPlannerHours(draftMins)}
                </span>
              )}
              {isOver ? (
                <span className="lux-planner-day-hour-row__tag is-over">
                  <i className="fe fe-alert-triangle" aria-hidden="true" />
                  Over by {formatPlannerHours(totalAfter - capacity)}
                  {capacity > 0 && (
                    <span className="lux-planner-day-hour-row__util">
                      {" "}
                      · {Math.round((totalAfter / capacity) * 100)}% utilized
                    </span>
                  )}
                </span>
              ) : (
                <span
                  className={classNames(
                    "lux-planner-day-hour-row__tag",
                    availableAfter > 0 ? "is-free" : "is-full"
                  )}
                >
                  {availableAfter != null && availableAfter > 0
                    ? `${formatPlannerHours(availableAfter)} free`
                    : "At capacity"}
                </span>
              )}
            </>
          )}
        </div>

        <button
          ref={triggerRef}
          type="button"
          className="lux-planner-day-hour-row__edit"
          onClick={() => setOpen(true)}
        >
          <span className="lux-planner-day-hour-row__hours">{formatPlannerHours(draftMins)}</span>
          <span className="lux-planner-day-hour-row__edit-label">Edit</span>
          <i className="fe fe-edit-2" aria-hidden />
        </button>

        <button
          type="button"
          className="lux-planner-day-hour-row__remove"
          onClick={() => onRemove(dateKey)}
          aria-label={`Remove ${dateKey}`}
        >
          <i className="fe fe-x" />
        </button>
      </div>

      {open && (
        <DayHoursEditorPopover
          anchorEl={triggerRef.current}
          dateKey={dateKey}
          entry={entry}
          dayInfo={dayInfo}
          startTimeLabel={startTimeLabel}
          maxHoursAllowed={maxHoursAllowed}
          onSave={(key, hours) => {
            onChange(key, hours);
            setOpen(false);
          }}
          onRemove={() => {
            onRemove(dateKey);
            setOpen(false);
          }}
          onClose={() => setOpen(false)}
        />
      )}
    </>
  );
}

export default function PlannerAssignDailyHours({
  timeEntry,
  dayCapacityMap,
  startTimeLabel,
  maxHoursAllowed,
  onHoursChange,
  onRemoveDay,
  onFillAvailableDays,
}) {
  const entries = useMemo(() => {
    if (!timeEntry) return [];
    return Object.keys(timeEntry)
      .map((dateKey) => ({ dateKey, entry: timeEntry[dateKey], dayInfo: lookupDayCapacity(dayCapacityMap, dateKey) }))
      .sort((a, b) => {
        const ma = a.dayInfo && a.dayInfo.dayKey ? a.dayInfo.dayKey : a.dateKey;
        const mb = b.dayInfo && b.dayInfo.dayKey ? b.dayInfo.dayKey : b.dateKey;
        return ma.localeCompare(mb);
      });
  }, [timeEntry, dayCapacityMap]);

  const summary = useMemo(
    () => summarizePlannerTimeEntry(timeEntry, dayCapacityMap),
    [timeEntry, dayCapacityMap]
  );

  if (!timeEntry || entries.length === 0) {
    return (
      <div className="lux-planner-day-hours lux-planner-day-hours--empty">
        <p>Select start and end dates to plan daily hours.</p>
      </div>
    );
  }

  return (
    <div className="lux-planner-day-hours">
      {summary && summary.hasOverUtilization && (
        <div className="lux-planner-day-hours__over-banner" role="status">
          <span className="lux-planner-day-hours__over-banner-icon" aria-hidden="true">
            <i className="fe fe-alert-triangle" />
          </span>
          <div>
            <strong>
              Over-utilization on {summary.overDayCount} day
              {summary.overDayCount === 1 ? "" : "s"}
            </strong>
            <p>
              Other work plus this entry exceeds the day&apos;s capacity ({summary.totalOverLabel}{" "}
              total excess). Adjust hours or remove days before assigning.
            </p>
          </div>
        </div>
      )}

      <div className="lux-planner-day-hours__toolbar">
        <p>
          <i className="fe fe-info" />
          Tap a day to set hours. Other work is existing load; free is capacity minus other work and this entry.
        </p>
        {onFillAvailableDays && (
          <button
            type="button"
            className="lux-planner-day-hours__fill-btn"
            onClick={onFillAvailableDays}
          >
            <span className="lux-planner-day-hours__fill-btn-icon" aria-hidden="true">
              <i className="fe fe-zap" />
            </span>
            <span className="lux-planner-day-hours__fill-btn-text">
              <strong>Fill available days</strong>
              <small>Auto-set each day to remaining capacity</small>
            </span>
          </button>
        )}
      </div>
      <ul className="lux-planner-day-hours__list">
        {entries.map(({ dateKey, entry, dayInfo }) => (
          <li key={dateKey}>
            <DayHourRow
              dateKey={dateKey}
              entry={entry}
              dayInfo={dayInfo}
              startTimeLabel={startTimeLabel}
              maxHoursAllowed={maxHoursAllowed}
              onChange={onHoursChange}
              onRemove={onRemoveDay}
            />
          </li>
        ))}
      </ul>
    </div>
  );
}
