function analyticsTeamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.assign(query, extra);
  }
  return query;
}

function analyticsTeamQueryString(extra) {
  const query = analyticsTeamQuery(extra);
  return Object.keys(query)
    .filter((key) => query[key] != null && query[key] !== "")
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

function writeAnalyticsAudit(actionType, message, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
    entityRef,
    message,
    metadata: {
      module: "analytics-platform",
      ...metadata,
    },
  });
}

async function getMetricCatalog() {
  if (!shouldUseAnalyticsPlatformApi()) {
    return apiErrorResult([]);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.ANALYTICS_PLATFORM_API_PATH}/metrics`,
    analyticsTeamQuery()
  );
  return { payload: (response && response.payload) || response || [], source: "api" };
}

