async function updateDashboardConfig(payload = {}) {
  validateDashboardConfigPayload(payload);
  if (!shouldUseAnalyticsPlatformApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.post(
    `${urlConfig.ANALYTICS_PLATFORM_API_PATH}/dashboards?${analyticsTeamQueryString()}`,
    payload
  );
  const row = normalizeDashboardConfig((response && response.payload) || response);
  writeAnalyticsAudit(AUDIT_ACTION_TYPES.UPDATED, `Dashboard config updated: ${row.name}`, row.id, {
    eventCode: "DASHBOARD_CONFIG_CHANGED",
    domain: row.domain,
  });
  return { payload: row, source: "api" };
}

