async function exportReport(query = {}, reportName = "analytics-report") {
  const result = await runReportQuery(query);
  const includeSensitive = query.filters && query.filters.includeSensitive === true;
  const csv = exportReportResultCsv(result.payload, { includeSensitive });
  writeAnalyticsAudit(AUDIT_ACTION_TYPES.EXPORTED, `Report exported: ${reportName}`, reportName, {
    eventCode: "REPORT_EXPORTED",
    rowCount: result.payload ? result.payload.rowCount : 0,
  });
  return {
    payload: csv,
    filename: `${reportName.replace(/\s+/g, "-").toLowerCase()}.csv`,
    source: result.source,
  };
}

