async function getAnalyticsAiInsight(domain, dashboard) {
  if (!isAnalyticsAiInsightsEnabled()) {
    return { payload: null, source: "disabled" };
  }
  if (!shouldUseAnalyticsPlatformApi()) {
    // Fail closed — never invent client-side insights.
    return { payload: null, source: "unavailable" };
  }
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.ANALYTICS_PLATFORM_API_PATH}/insights/${domain}`,
      analyticsTeamQuery()
    );
    return { payload: (response && response.payload) || response || null, source: "api" };
  } catch (error) {
    return { payload: null, source: "api-error" };
  }
}
