/**
 * SEC-VAPT C5I-008 — DOMPurify allowlist for rich HTML rendered via dangerouslySetInnerHTML.
 */
import DOMPurify from "dompurify";

export const RICH_HTML_PURIFY_CONFIG = {
  ALLOWED_TAGS: [
    "a",
    "b",
    "br",
    "div",
    "em",
    "i",
    "li",
    "mark",
    "ol",
    "p",
    "span",
    "strong",
    "u",
    "ul",
  ],
  ALLOWED_ATTR: ["href", "title", "class"],
  ALLOW_DATA_ATTR: false,
};

export function escapeHtml(text) {
  if (text == null) {
    return "";
  }
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function sanitizeRichHtml(html) {
  if (html == null || typeof html !== "string" || !html.trim()) {
    return html;
  }

  return DOMPurify.sanitize(html, RICH_HTML_PURIFY_CONFIG);
}
