/**
 * EH02 — Offer / Requisition master feature flags.
 */
import envconfig from "env.config";

export function shouldUseOfferApi() {
  return envconfig.USE_OFFER_API === true;
}

export function shouldUseRequisitionApi() {
  return envconfig.USE_REQUISITION_API === true;
}

export function isOfferApiEnabled() {
  return shouldUseOfferApi();
}

export function isRequisitionApiEnabled() {
  return shouldUseRequisitionApi();
}
