/**
 * EH17 — Vendors overview FE service. Fail closed when flag on.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseVendorsOverviewApi } from "config/vendors-overview.config";

export const vendorsOverviewService = {
  getOverview,
};

const API_ERROR = { payload: null, source: "api-error" };

async function getOverview() {
  if (!shouldUseVendorsOverviewApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.VENDORS_API_PATH}/overview`, {
      userTeamId: commonUtils.getCurrentUserTeamId(),
    });
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[VendorsOverview] API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}
