import React from "react";
import classNames from "classnames/bind";
import { WorkGraphLuxPanel } from "views/workgraph/components/WorkGraphLuxShared";

const TYPE_ICONS = {
  person: "fe fe-user",
  project: "fe fe-layers",
  task: "fe fe-check-square",
  approval: "fe fe-check-circle",
  document: "fe fe-file-text",
  asset: "fe fe-monitor",
  invoice: "fe fe-file",
  payroll: "fe fe-dollar-sign",
  risk: "fe fe-alert-triangle",
  ticket: "fe fe-life-buoy",
  ai_recommendation: "fe fe-cpu",
};

function buildNodeMap(nodes) {
  const map = {};
  (nodes || []).forEach((node) => {
    map[node.id] = node;
  });
  return map;
}

export default function GraphVisualizationPanel({ nodes, edges, selectedId, onSelectNode, loading }) {
  const nodeList = nodes || [];
  const edgeList = edges || [];
  const nodeMap = buildNodeMap(nodeList);

  return (
    <WorkGraphLuxPanel
      title="Relationship constellation"
      meta="Interactive entity map with cross-module edges"
      icon="fe fe-git-merge"
      accent="violet"
      featured
    >
      {loading ? (
        <div className="lux-wg-viz lux-wg-viz--loading">
          <div className="lux-wg-skeleton lux-wg-skeleton--viz" />
        </div>
      ) : (
        <div className="lux-wg-viz">
          <div className="lux-wg-viz__canvas" role="img" aria-label="Work graph constellation">
            <svg className="lux-wg-viz__edges" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">
              {edgeList.map((edge) => {
                const source = nodeMap[edge.sourceId];
                const target = nodeMap[edge.targetId];
                if (!source || !target) {
                  return null;
                }
                const isBlocked = edge.type === "blocked_by";
                return (
                  <line
                    key={edge.id}
                    x1={source.layoutX}
                    y1={source.layoutY}
                    x2={target.layoutX}
                    y2={target.layoutY}
                    className={classNames("lux-wg-viz__edge", isBlocked && "is-blocked", selectedId && (selectedId === edge.sourceId || selectedId === edge.targetId) && "is-active")}
                  />
                );
              })}
            </svg>
            {nodeList.map((node) => (
              <button
                key={node.id}
                type="button"
                className={classNames(
                  "lux-wg-node",
                  node.tone && `is-${node.tone}`,
                  selectedId === node.id && "is-selected"
                )}
                style={{ left: `${node.layoutX}%`, top: `${node.layoutY}%` }}
                onClick={() => onSelectNode && onSelectNode(node)}
              >
                <span className="lux-wg-node__icon" aria-hidden="true">
                  <i className={TYPE_ICONS[node.type] || "fe fe-circle"} />
                </span>
                <span className="lux-wg-node__label">{node.label}</span>
                <span className="lux-wg-node__type">{node.type}</span>
              </button>
            ))}
          </div>
          <div className="lux-wg-viz__legend">
            <span className="lux-wg-viz__legend-chip">
              <i className="fe fe-circle" aria-hidden="true" />
              {nodeList.length} nodes
            </span>
            <span className="lux-wg-viz__legend-chip">
              <i className="fe fe-link" aria-hidden="true" />
              {edgeList.length} edges
            </span>
            <span className="lux-wg-viz__legend-chip is-muted">Click a node to explore relationships</span>
          </div>
        </div>
      )}
    </WorkGraphLuxPanel>
  );
}
