
import { axiosUtils, commonUtils } from '../_helpers';
import urlConfig from 'url.config'

export const taskboardService = {
    getAllTaskboards,
    createTaskboard,
    updateTaskboard,
    removeTaskboard,
    activateTaskboard
};

async function getAllTaskboards(request) {
    const employeeId =
        request && (request.employeeId != null ? request.employeeId : request.emplyeeId);
    // Explicit null userTeamIds + employee → employee-scoped boards (omit team filter).
    if (request && request.userTeamIds == null && employeeId != null) {
        return await axiosUtils.get(urlConfig.TASKBOARD + `?employeeId=${employeeId}`);
    }
    const userTeamIds = commonUtils.resolveUserTeamIds(
        request && request.userTeamIds !== undefined ? request.userTeamIds : null
    );
    if (!userTeamIds.length) {
        return { payload: [] };
    }
    return await axiosUtils.get(urlConfig.TASKBOARD + `?userTeamIds=${userTeamIds}`);
}

async function createTaskboard(taskboardRequest) {
    return await axiosUtils.post(urlConfig.TASKBOARD,taskboardRequest);
}

async function updateTaskboard(taskboardRequest) {
    return await axiosUtils.put(urlConfig.TASKBOARD, taskboardRequest);
}

async function removeTaskboard(taskboardId) {
    return await axiosUtils.remove(urlConfig.TASKBOARD+`/${taskboardId}`);
 }

 async function activateTaskboard(taskboardId, isActive) {
    return await axiosUtils.put(urlConfig.TASKBOARD+`/${taskboardId}/${isActive}`);
 }
