import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import { leaveService } from '_services/leave.service';
import { accessUtils, commonUtils } from '_helpers';
import { shouldUseLeaveManagement } from '_helpers/leave.config';
import LeaveBalanceCards from '../leave/LeaveBalanceCards';
import LeaveHistoryTable from '../leave/LeaveHistoryTable';
import LeaveBalanceCalculationPanel from '../leave/LeaveBalanceCalculationPanel';
import {
  buildBalanceCardsFromApi,
  buildLeaveSummary,
  mergeBalanceCards,
  buildBalanceCardsFromLeaves,
} from '../leave/leave.utils';

class ProfileLeaveView extends Component {
  constructor(props) {
    super(props);
    this.state = {
      permission: accessUtils.getLeaveAccessControl(),
      loading: true,
      leaves: [],
      balances: [],
      leaveTypes: [],
      calculation: null,
    };
  }

  componentDidMount() {
    this.loadAll();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.employee && this.props.employee && prevProps.employee.id !== this.props.employee.id) {
      this.loadAll();
    }
  }

  loadAll = () => {
    const { employee } = this.props;
    const moduleEnabled = shouldUseLeaveManagement();
    const permission = accessUtils.getLeaveAccessControl();

    if (!employee || !employee.id || !moduleEnabled || !permission.viewEnabled) {
      this.setState({ loading: false, leaves: [], balances: [], calculation: null });
      return;
    }

    this.setState({ loading: true });
    const typePromise = employee.userTeamId
      ? leaveService.listLeaveTypes(employee.userTeamId)
      : Promise.resolve({ payload: [] });

    Promise.all([
      leaveService.listByEmployee(employee.id),
      leaveService.getBalances(employee.id),
      leaveService.getBalanceCalculation(employee.id),
      typePromise,
    ])
      .then(([leaveRes, balRes, calcRes, typesRes]) => {
        const leaves = (leaveRes && leaveRes.payload) || [];
        const balances = (balRes && balRes.payload) || [];
        this.setState({
          leaves,
          balances,
          calculation: (calcRes && calcRes.payload) || null,
          leaveTypes: (typesRes && typesRes.payload) || [],
          loading: false,
        });
        if (this.props.onDataLoaded) {
          this.props.onDataLoaded(leaves, balances);
        }
      })
      .catch(() => {
        this.setState({ loading: false, leaves: [], balances: [], calculation: null });
      });
  };

  renderLinks = () => {
    const { permission } = this.state;
    const { readOnly, employee } = this.props;
    const isSelf = employee && String(employee.id) === String(commonUtils.getCurrentUserId());

    return (
      <nav className="lux-profile-leave-links" aria-label="Leave quick links">
        {isSelf && (
          <Link to="/people/leaves" className="lux-onb-action lux-onb-action--primary lux-onb-action--sm">
            <i className="fe fe-calendar" aria-hidden /> My leave workspace
          </Link>
        )}
        {permission.policyAdminEnabled && (
          <>
            <Link to="/admin/leave-policies" className="lux-onb-action lux-onb-action--ghost lux-onb-action--sm">
              Leave policies
            </Link>
            <Link to="/admin/employee-leave-config" className="lux-onb-action lux-onb-action--ghost lux-onb-action--sm">
              HR balance config
            </Link>
          </>
        )}
        {!readOnly && permission.viewEnabled && (
          <Link to="/people/leaves" className="btn btn-link btn-sm">
            Open full leave page
          </Link>
        )}
      </nav>
    );
  };

  render() {
    const { employee, readOnly } = this.props;
    const { permission, loading, leaves, balances, leaveTypes, calculation } = this.state;
    const moduleEnabled = shouldUseLeaveManagement();

    if (!moduleEnabled || !permission.viewEnabled) {
      return (
        <p className="text-muted">
          Native leave management is not enabled for this organization. ZingHR synced leave may still
          appear on the timesheet.
        </p>
      );
    }

    const historyCards = buildBalanceCardsFromLeaves(leaves);
    const apiCards = buildBalanceCardsFromApi(balances, leaveTypes);
    const balanceCards = mergeBalanceCards(apiCards, historyCards);
    const summary = buildLeaveSummary(leaves);
    const canApply =
      !readOnly &&
      employee &&
      String(employee.id) === String(commonUtils.getCurrentUserId()) &&
      permission.createEnabled;

    return (
      <div className="lux-profile-leave-view">
        {this.renderLinks()}

        <div className="lux-profile-leave-view__kpis">
          <article>
            <span>Pending</span>
            <strong>{summary.pending}</strong>
          </article>
          <article>
            <span>Approved</span>
            <strong>{summary.approved}</strong>
          </article>
          <article>
            <span>Days approved</span>
            <strong>{summary.totalDaysApproved}</strong>
          </article>
        </div>

        <LeaveBalanceCards
          cards={balanceCards}
          loading={loading}
          onApplyClick={canApply ? () => window.location.assign("/people/leaves") : null}
        />

        <LeaveBalanceCalculationPanel
          breakdown={calculation}
          leaveTypes={leaveTypes}
          loading={loading}
        />

        <section className="lux-profile-leave-view__history">
          <header>
            <h3>Leave history</h3>
            <p>Tracopus requests and ZingHR synced records</p>
          </header>
          <LeaveHistoryTable
            leaves={leaves}
            loading={loading}
            currentUserId={commonUtils.getCurrentUserId()}
            viewedEmployeeId={employee && employee.id}
            permission={permission}
          />
        </section>
      </div>
    );
  }
}

export default ProfileLeaveView;
