
import { axiosUtils, commonUtils } from '../_helpers';
import urlConfig from 'url.config'
import {
  AnalyticsEvents,
  trackAttendanceAction,
  trackHolidayAction,
} from "config/analytics-events.config";

export const employeeService = {
    createEmployee,
    updateEmployee,
    updateEmployeeExitDate,
    deleteEmployee,
    activateEmployee,
    removeEmployee,
    updateEmployeeRoles,
    syncEmployeeLeaves,
    getAllEmployees,
    getTeamsEmployees,
    getEmployeeById,
    getTeamsAttendance,
    listPendingAttendance,
    createAttendance,
    approveAttendance,
    rejectAttendance,
    requestAttendanceRemoval,
    deleteAttendance,
    getHolidays,
    createHolidayItem,
    updateHolidayItem,
    importHolidayItems,
    removeHolidayItem
};

async function getAllEmployees(userTeamIds) {
    return await axiosUtils.get(urlConfig.EMPLOYEE_GET_ALL+`/true`, {});
 }

 async function getTeamsEmployees(userTeamIds) {
    // undefined/null → current teams; explicit [] → no call (empty payload)
    const ids = commonUtils.resolveUserTeamIds(
      userTeamIds === undefined ? null : userTeamIds
    );
    if (!ids.length) {
      return { payload: [] };
    }
    return await axiosUtils.getWithParam(urlConfig.EMPLOYEE_TEAMS_ALL, {
      userTeamIds: ids,
    });
 }

async function getEmployeeById(employeeId) {
   return await axiosUtils.get(urlConfig.EMPLOYEE_GET_INFO+`/${employeeId}`);
}

async function createEmployee(employeeRequest) {
    return await axiosUtils.post(urlConfig.EMPLOYEE_CREATE,employeeRequest);
}

async function syncEmployeeLeaves(employee, startDate, endDate) {
    return await axiosUtils.put(urlConfig.EMPLOYEE_LEAVE_SYNC+ `?employeeCode=${employee.empCode}&startDate=${startDate}&endDate=${endDate}`);
}

async function updateEmployeeRoles(selectedEmployeesAndRoles) {
    return await axiosUtils.put(urlConfig.EMPLOYEE_USER_ROLE_UPDATE,{"userRoles" : selectedEmployeesAndRoles});
}

async function updateEmployee(employeeRequest) {
    return await axiosUtils.put(urlConfig.EMPLOYEE_UPDATE,employeeRequest);
}

async function updateEmployeeExitDate(employeeRequest) {
    return await axiosUtils.put(urlConfig.EMPLOYEE_GET_INFO+`/${employeeRequest.employeeId}/exit?exitDate=${employeeRequest.exitDate != undefined ? employeeRequest.exitDate : ""}`,{});
}

async function deleteEmployee(employeeId, isDelete) {
   return await axiosUtils.remove(urlConfig.EMPLOYEE_DELETE+`/${employeeId}/${isDelete}`);
}

async function removeEmployee(employeeId) {
    return await axiosUtils.remove(urlConfig.EMPLOYEE_REMOVE+`/${employeeId}`);
 }

 async function activateEmployee(employeeId, isActive) {
    return await axiosUtils.put(urlConfig.EMPLOYEE_ACTIVATE+`/${employeeId}/${isActive}`);
 }
 
async function getTeamsAttendance(request) {
    const ids = commonUtils.resolveUserTeamIds(request && request.userTeamIds);
    if (!ids.length) {
      return { payload: [] };
    }
    const allowed = request.allowedTeamIds != null
        ? request.allowedTeamIds
        : ids;
    let url = urlConfig.GET_TEAM_ATTENDANCE
        + `?userTeamIds=${ids}&startDate=${request.startDate}&endDate=${request.endDate}`;
    if (allowed != null && allowed !== "") {
        url += `&allowedTeamIds=${allowed}`;
    }
    return await axiosUtils.get(url);
}

async function listPendingAttendance({ userTeamIds, startDate, endDate, approverId }) {
    const ids = commonUtils.resolveUserTeamIds(userTeamIds);
    if (!ids.length) {
      return { payload: [] };
    }
    return await axiosUtils.getWithParam(urlConfig.GET_TEAM_ATTENDANCE + "/pending", {
      userTeamIds: ids,
      startDate,
      endDate,
      approverId,
    });
}

async function createAttendance(request) {
    const result = await axiosUtils.put(
        urlConfig.MARK_ATTENDANCE + `/${request.employeeId}?date=${request.markDate}`,
        {
            markTime: request.markTime,
            hours: request.hours,
            checkoutTime: request.checkoutTime,
            markedBy: request.markedBy,
        }
    );
    trackAttendanceAction(AnalyticsEvents.ATTENDANCE_MARK, result && result.id);
    return result;
}

async function approveAttendance(request) {
    const result = await axiosUtils.put(
        urlConfig.APPROVE_ATTENDANCE + `/${request.id}/approve?approverId=${request.approverId}`,
        { approvalComment: request.approvalComment || null }
    );
    trackAttendanceAction(AnalyticsEvents.ATTENDANCE_APPROVE, request && request.id);
    return result;
}

async function rejectAttendance(request) {
    const result = await axiosUtils.put(
        urlConfig.REJECT_ATTENDANCE + `/${request.id}/reject?approverId=${request.approverId}`,
        { approvalComment: request.approvalComment || null }
    );
    trackAttendanceAction(AnalyticsEvents.ATTENDANCE_REJECT, request && request.id);
    return result;
}

async function requestAttendanceRemoval(request) {
    return await axiosUtils.put(
        urlConfig.REQUEST_ATTENDANCE_REMOVAL + `/${request.id}/request-removal?requestedBy=${request.requestedBy}`
    );
}

async function deleteAttendance(attendaceId) {
   return await axiosUtils.remove(urlConfig.DELETE_ATTENDANCE + `/${attendaceId}`);
}

async function getHolidays(request) {
    return await axiosUtils.get(urlConfig.HOLIDAY_PATH + `?startDate=${request.startDate}&endDate=${request.endDate}`);
}

async function createHolidayItem(request) {
    const result = await axiosUtils.post(urlConfig.HOLIDAY_PATH, request);
    trackHolidayAction(AnalyticsEvents.HOLIDAY_CREATE, result && result.id);
    return result;
}

async function updateHolidayItem(request) {
    const result = await axiosUtils.put(urlConfig.HOLIDAY_PATH, request);
    trackHolidayAction(AnalyticsEvents.HOLIDAY_UPDATE, request && request.id);
    return result;
}

async function importHolidayItems(request) {
    return await axiosUtils.post(urlConfig.HOLIDAY_IMPORT_PATH, request);
}

async function removeHolidayItem(holidayId) {
   const result = await axiosUtils.remove(urlConfig.HOLIDAY_PATH + `/${holidayId}`);
   trackHolidayAction(AnalyticsEvents.HOLIDAY_DELETE, holidayId);
   return result;
}

