import { shouldUseAccessRequestsAdmin, shouldUseAssetRegister } from "config/tracopus-pilot.config";
import envconfig from "env.config";

export const ASSET_TYPES = {
  LAPTOP: { id: "LAPTOP", label: "Laptop" },
  MONITOR: { id: "MONITOR", label: "Monitor" },
  MOBILE: { id: "MOBILE", label: "Mobile phone" },
  ACCESS: { id: "ACCESS", label: "Access card" },
  SOFTWARE: { id: "SOFTWARE", label: "Software license" },
  PERIPHERAL: { id: "PERIPHERAL", label: "Peripheral" },
  OTHER: { id: "OTHER", label: "Other" },
};

export const ASSET_STATUSES = {
  AVAILABLE: "Available",
  ASSIGNED: "Assigned",
  IN_REPAIR: "In repair",
  RETIRED: "Retired",
  LOST: "Lost",
};

export const ACCESS_REQUEST_STATUSES = {
  PENDING: "Pending",
  APPROVED: "Approved",
  REJECTED: "Rejected",
  FULFILLED: "Fulfilled",
};

export function isAssetRegisterEnabled() {
  return shouldUseAssetRegister();
}

export function isAccessRequestsAdminEnabled() {
  return shouldUseAccessRequestsAdmin();
}

export function shouldUseAssetRegisterApi() {
  return envconfig.USE_ASSET_REGISTER_API === true;
}

export function getAssetTypeLabel(typeId) {
  const meta = ASSET_TYPES[typeId];
  return (meta && meta.label) || typeId || "Asset";
}

export function normalizeAsset(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    tag: row.tag || "",
    name: row.name || "Unnamed asset",
    type: row.type || "OTHER",
    typeLabel: row.typeLabel || getAssetTypeLabel(row.type),
    serialNumber: row.serialNumber || "",
    status: row.status || ASSET_STATUSES.AVAILABLE,
    condition: row.condition || "Good",
    assigneeId: row.assigneeId || null,
    assigneeName: row.assigneeName || "",
    assignedAt: row.assignedAt || null,
    returnedAt: row.returnedAt || null,
    warrantyExpiresAt: row.warrantyExpiresAt || null,
    cost: row.cost != null ? row.cost : null,
    location: row.location || "",
    offboardingBlocker: row.offboardingBlocker === true,
    notes: row.notes || "",
  };
}

export function normalizeAccessRequest(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    type: row.type || "ACCESS",
    title: row.title || "Access request",
    requesterId: row.requesterId || null,
    requesterName: row.requesterName || "",
    status: normalizeAccessRequestStatus(row.status),
    priority: row.priority || "NORMAL",
    submittedAt: row.submittedAt || null,
    assetTag: row.assetTag || "",
    notes: row.notes || "",
  };
}

export function normalizeAccessRequestStatus(status) {
  const normalized = String(status || "").trim().toUpperCase();
  if (!normalized || normalized === "SUBMITTED" || normalized === "PENDING") {
    return ACCESS_REQUEST_STATUSES.PENDING;
  }
  if (normalized === "APPROVED" || normalized === "ACTIVE") {
    return ACCESS_REQUEST_STATUSES.APPROVED;
  }
  if (normalized === "REJECTED" || normalized === "REVOKED") {
    return ACCESS_REQUEST_STATUSES.REJECTED;
  }
  if (normalized === "FULFILLED" || normalized === "CLOSED") {
    return ACCESS_REQUEST_STATUSES.FULFILLED;
  }
  return status || ACCESS_REQUEST_STATUSES.PENDING;
}

/** Map UI queue labels to canonical API lifecycle tokens for PATCH /status. */
export function toApiAccessRequestStatus(status) {
  const normalized = String(status || "").trim().toUpperCase();
  if (normalized === "PENDING" || normalized === ACCESS_REQUEST_STATUSES.PENDING.toUpperCase()) {
    return "PENDING";
  }
  if (normalized === "APPROVED" || normalized === ACCESS_REQUEST_STATUSES.APPROVED.toUpperCase()) {
    return "APPROVED";
  }
  if (normalized === "REJECTED" || normalized === ACCESS_REQUEST_STATUSES.REJECTED.toUpperCase()) {
    return "REJECTED";
  }
  if (
    normalized === "FULFILLED" ||
    normalized === ACCESS_REQUEST_STATUSES.FULFILLED.toUpperCase() ||
    normalized === "CLOSED"
  ) {
    return "FULFILLED";
  }
  return normalized || "PENDING";
}
