import { auditConstants, AUDIT_DEFAULT_PAGE_SIZE } from '_constants/audit.constants';
import { auditService } from '_services/audit.service';
import { buildAuditScopeKey, normalizeAuditEvent } from '_helpers/audit.utils';

export const auditActions = {
  loadActorTimeline,
  loadEntityTimeline,
  loadProjectAudit,
  loadPurchaseOrderAudit,
  loadEmployeeAudit,
  loadDeliverableAudit,
  loadLeaveAudit,
  loadAttendanceAudit,
  loadTimesheetWeekAudit,
  setTimelineFilters,
  clearTimeline,
};

function parseTimelineResponse(response) {
  const payload = response && response.payload;
  if (Array.isArray(payload)) {
    return {
      items: payload.map(normalizeAuditEvent).filter(Boolean),
      pageInfo: null,
    };
  }
  const items = (payload && (payload.items || payload.events)) || [];
  return {
    items: items.map(normalizeAuditEvent).filter(Boolean),
    pageInfo: (payload && payload.pageInfo) || null,
  };
}

function loadTimeline(scopeKey, loader, params = {}) {
  const page = params.page || 1;
  const pageSize = params.pageSize || AUDIT_DEFAULT_PAGE_SIZE;
  const requestParams = { ...params, page, pageSize };

  return (dispatch) => {
    dispatch(request(scopeKey, page, pageSize));
    return loader(requestParams)
      .then((response) => {
        const { items, pageInfo } = parseTimelineResponse(response);
        dispatch(success(scopeKey, items, pageInfo, page, pageSize));
        return items;
      })
      .catch((error) => {
        dispatch(failure(scopeKey, error));
        // Keep rejection handled — AuditTrailSection reads failure state; do not
        // rethrow or the browser reports Uncaught (in promise) "Item not available".
        return [];
      });
  };

  function request(key, nextPage, nextPageSize) {
    return {
      type: auditConstants.LOAD_TIMELINE_REQUEST,
      scopeKey: key,
      page: nextPage,
      pageSize: nextPageSize,
    };
  }
  function success(key, items, pageInfo, nextPage, nextPageSize) {
    return {
      type: auditConstants.LOAD_TIMELINE_SUCCESS,
      scopeKey: key,
      items,
      pageInfo,
      page: (pageInfo && pageInfo.page) || nextPage,
      pageSize: (pageInfo && pageInfo.pageSize) || nextPageSize,
    };
  }
  function failure(key, error) {
    return { type: auditConstants.LOAD_TIMELINE_FAILURE, scopeKey: key, error };
  }
}

function loadActorTimeline(actorUserId, params = {}) {
  const scopeKey = buildAuditScopeKey('actor', { actorUserId });
  return loadTimeline(scopeKey, () => auditService.getActorTimeline(actorUserId, params), params);
}

function loadEntityTimeline(entityType, entityId, params = {}) {
  const scopeKey = buildAuditScopeKey('entity', { entityType, entityId });
  return loadTimeline(
    scopeKey,
    () => auditService.getEntityTimeline(entityType, entityId, params),
    params
  );
}

