import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  mapLeavePhase2State,
  renderLeavePhase2Nav,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const NAV = [
  { path: '/admin/leave/integrations', label: 'Connectors', icon: 'fe fe-link', exact: true },
  { path: '/admin/leave/integration-runs', label: 'Runs', icon: 'fe fe-play' },
  { path: '/admin/leave/integration-errors', label: 'Errors / DLQ', icon: 'fe fe-alert-triangle' },
];

const EMPTY_CONNECTOR = { name: '', connectorType: 'PAYROLL' };

function sectionFromPath(pathname) {
  if (pathname.includes('integration-runs')) return 'runs';
  if (pathname.includes('integration-errors')) return 'errors';
  return 'connectors';
}

class LeaveIntegrationsPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    connectors: [],
    runs: [],
    dlq: [],
    staging: [],
    saving: false,
    connectorForm: { ...EMPTY_CONNECTOR },
  };

  fetchSectionData = async (teamId) => {
    const section = sectionFromPath(this.props.location.pathname);
    if (section === 'connectors') {
      const connectors = (await api.listIntegrationConnectors(teamId)) || [];
      this.setState({ connectors: Array.isArray(connectors) ? connectors : [] });
      return;
    }
    if (section === 'runs') {
      const runs = (await api.listIntegrationRuns(teamId)) || [];
      this.setState({ runs: Array.isArray(runs) ? runs : [] });
      return;
    }
    const dlq = (await api.listIntegrationDlq(teamId)) || [];
    this.setState({ dlq: Array.isArray(dlq) ? dlq : [] });
  };

  saveConnector = (event) => {
    event.preventDefault();
    const { connectorForm } = this.state;
    const name = (connectorForm.name || '').trim();
    if (!name) return;
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    api
      .saveIntegrationConnector({
        userTeamId: teamId,
        actorId: this.actorId(),
        name,
        connectorType: connectorForm.connectorType || 'PAYROLL',
        active: true,
      })
      .then(() => {
        this.setState({
          saving: false,
          notice: 'Connector saved.',
          connectorForm: { ...EMPTY_CONNECTOR },
        });
        return this.loadAll();
      })
      .catch((e) => {
        this.setState({
          saving: false,
          error: getApiErrorMessage(e, 'Could not save connector.'),
        });
      });
  };

  render() {
    const { loading, connectors, runs, dlq, connectorForm, saving } = this.state;
    const section = sectionFromPath(this.props.location.pathname);
    const kpiCards = [
      { id: 'conn', label: 'Connectors', value: connectors.length, tone: 'primary', icon: 'fe fe-link' },
      { id: 'runs', label: 'Runs', value: runs.length, tone: 'blue', icon: 'fe fe-play' },
      { id: 'dlq', label: 'DLQ', value: dlq.length, tone: 'amber', icon: 'fe fe-alert-triangle' },
    ];

    return this.renderChrome({
      testId: 'page-leave-integrations',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-link',
        eyebrow: 'Admin · Leave',
        titleLead: 'Leave',
        titleAccent: 'Integrations',
        lede: 'Register connectors, review runs/DLQ. Add a connector below; credentials stay in approved secret stores.',
      },
      heroNav: renderLeavePhase2Nav(NAV, this.props.location.pathname),
      children: (
        <>
          {section === 'connectors' && (
            <>
              <LeavePhase2Panel title="Add connector" subtitle="Minimal shell — configure secrets outside the UI.">
                <form className="lux-glp-form" onSubmit={this.saveConnector} data-testid="glp21-add-connector-form">
                  <label>
                    Name
                    <input
                      required
                      value={connectorForm.name}
                      onChange={(e) =>
                        this.setState({ connectorForm: { ...connectorForm, name: e.target.value } })
                      }
                      placeholder="Payroll outbound"
                    />
                  </label>
                  <label>
                    Type
                    <select
                      value={connectorForm.connectorType}
                      onChange={(e) =>
                        this.setState({
                          connectorForm: { ...connectorForm, connectorType: e.target.value },
                        })
                      }
                    >
                      <option value="PAYROLL">Payroll</option>
                      <option value="HRIS">HRIS</option>
                      <option value="CALENDAR">Calendar</option>
                    </select>
                  </label>
                  <div className="lux-glp-form__actions">
                    <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                      Save connector
                    </AdminActionButton>
                  </div>
                </form>
              </LeavePhase2Panel>
              <LeavePhase2Panel title="Connectors" subtitle="Payroll outbound, inbound reconciliation, and calendar sync.">
                <LeavePhase2Register
                  loading={loading}
                  rows={connectors}
                  testId="glp21-connectors-register"
                  emptyTitle="No connectors configured"
                  emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                  columns={[
                    { key: 'id', label: 'ID' },
                    { key: 'name', label: 'Name' },
                    { key: 'connectorType', label: 'Type', render: (r) => cell(r.connectorType || r.type) },
                    { key: 'status', label: 'Health' },
                    { key: 'lastSyncAt', label: 'Last sync' },
                  ]}
                />
              </LeavePhase2Panel>
            </>
          )}
          {section === 'runs' && (
            <LeavePhase2Panel title="Integration runs" subtitle="Outbound staging and inbound reconciliation history.">
              <LeavePhase2Register
                loading={loading}
                rows={runs}
                testId="glp21-runs-register"
                emptyTitle="No integration runs"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'Run' },
                  { key: 'connectorId', label: 'Connector' },
                  { key: 'direction', label: 'Direction' },
                  { key: 'status', label: 'Status' },
                  { key: 'startedAt', label: 'Started' },
                ]}
              />
            </LeavePhase2Panel>
          )}
          {section === 'errors' && (
            <LeavePhase2Panel title="Errors & dead-letter queue" subtitle="Failed messages eligible for replay.">
              <LeavePhase2Register
                loading={loading}
                rows={dlq}
                testId="glp21-dlq-register"
                emptyTitle="No DLQ items"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'DLQ' },
                  { key: 'connectorId', label: 'Connector' },
                  { key: 'status', label: 'Status' },
                  { key: 'errorCode', label: 'Error' },
                  { key: 'createdAt', label: 'Failed at' },
                ]}
              />
            </LeavePhase2Panel>
          )}
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(LeaveIntegrationsPage));
