import {
  AI_AGENT_RUN_STATUSES,
  AI_AGENT_STATUSES,
  AI_CONFIDENCE_BANDS,
  AI_RECOMMENDATION_STATUSES,
} from "config/ai-work-intelligence.config";
import { canRunAgent, maskAgentEvidence } from "config/ai-work-intelligence-security.utils";

export function normalizeAgent(agent) {
  if (!agent) {
    return null;
  }
  return {
    id: agent.id,
    name: agent.name || "Agent",
    domain: agent.domain || "governance",
    status: agent.status || AI_AGENT_STATUSES.ACTIVE,
    description: agent.description || "",
    icon: agent.icon || "fe fe-cpu",
    tone: agent.tone || "violet",
    route: agent.route || "/ai/agents",
    personas: Array.isArray(agent.personas) ? agent.personas : [],
    lastRunAt: agent.lastRunAt || null,
    runCount: Number(agent.runCount) || 0,
    acceptanceRate: Number(agent.acceptanceRate) || 0,
    evidenceTemplates: Array.isArray(agent.evidenceTemplates) ? agent.evidenceTemplates : [],
  };
}

export function normalizeAgentRun(run) {
  if (!run) {
    return null;
  }
  return {
    id: run.id,
    agentId: run.agentId,
    agentName: run.agentName || "",
    status: run.status || AI_AGENT_RUN_STATUSES.COMPLETED,
    startedAt: run.startedAt,
    completedAt: run.completedAt || null,
    durationMs: Number(run.durationMs) || 0,
    summary: run.summary || "",
    confidence: Number(run.confidence) || 0,
    recommendationCount: Number(run.recommendationCount) || 0,
    triggeredBy: run.triggeredBy || "system",
  };
}

export function normalizeRecommendation(rec, activePersona) {
  if (!rec) {
    return null;
  }
  const confidence = Number(rec.confidence) || 0;
  return {
    id: rec.id,
    agentId: rec.agentId,
    agentName: rec.agentName || "",
    title: rec.title || "Recommendation",
    body: rec.body || "",
    status: rec.status || AI_RECOMMENDATION_STATUSES.DRAFT,
    confidence,
    confidenceBand: resolveConfidenceBand(confidence),
    domain: rec.domain || "",
    createdAt: rec.createdAt,
    decidedAt: rec.decidedAt || null,
    decidedBy: rec.decidedBy || null,
    rationale: rec.rationale || "",
    evidence: maskAgentEvidence(rec.evidence, activePersona),
  };
}

export function resolveConfidenceBand(confidence) {
  const value = Number(confidence) || 0;
  if (value >= AI_CONFIDENCE_BANDS.HIGH.min) {
    return AI_CONFIDENCE_BANDS.HIGH;
  }
  if (value >= AI_CONFIDENCE_BANDS.MEDIUM.min) {
    return AI_CONFIDENCE_BANDS.MEDIUM;
  }
  return AI_CONFIDENCE_BANDS.LOW;
}

export function buildAgentConsoleOverview({ agents = [], runs = [], recommendations = [] } = {}) {
  const normalizedAgents = agents.map(normalizeAgent).filter(Boolean);
  const normalizedRuns = runs.map(normalizeAgentRun).filter(Boolean);
  const pending = recommendations.filter((r) => r.status === AI_RECOMMENDATION_STATUSES.DRAFT);
  const accepted = recommendations.filter((r) => r.status === AI_RECOMMENDATION_STATUSES.ACCEPTED);

  return {
    agentCount: normalizedAgents.length,
    activeAgentCount: normalizedAgents.filter((a) => a.status === AI_AGENT_STATUSES.ACTIVE).length,
    runCount: normalizedRuns.length,
    pendingRecommendationCount: pending.length,
    acceptanceRate: recommendations.length
      ? Math.round((accepted.length / recommendations.length) * 100)
      : 0,
    lastRunAt: (normalizedRuns[0] && normalizedRuns[0].startedAt) || null,
  };
}

export function buildAgentConsoleKpis(overview) {
  const o = overview || {};
  return [
    { id: "agents", label: "Registered agents", value: o.agentCount != null ? o.agentCount : 0, icon: "fe fe-cpu" },
    { id: "active", label: "Active agents", value: o.activeAgentCount != null ? o.activeAgentCount : 0, icon: "fe fe-zap" },
    { id: "pending", label: "Pending recommendations", value: o.pendingRecommendationCount != null ? o.pendingRecommendationCount : 0, icon: "fe fe-inbox" },
    { id: "acceptance", label: "Acceptance rate", value: `${o.acceptanceRate != null ? o.acceptanceRate : 0}%`, icon: "fe fe-check-circle" },
  ];
}

export function filterAgentsByPersona(agents, activePersona) {
  return (agents || [])
    .map(normalizeAgent)
    .filter(Boolean)
    .filter((agent) => canRunAgent(activePersona, agent));
}

export function buildAgentRunDraft(agent, context = {}) {
  const normalized = normalizeAgent(agent);
  if (!normalized) {
    return null;
  }
  const now = new Date().toISOString();
  const confidence = 0.72 + Math.random() * 0.22;
  return {
    id: `run-${Date.now()}`,
    agentId: normalized.id,
    agentName: normalized.name,
    status: AI_AGENT_RUN_STATUSES.COMPLETED,
    startedAt: now,
    completedAt: now,
    durationMs: 1200 + Math.floor(Math.random() * 2800),
    summary: `Completed ${normalized.name} run for ${context.scope || "portfolio scope"}.`,
    confidence,
    recommendationCount: 1 + Math.floor(Math.random() * 3),
    triggeredBy: context.triggeredBy || "user",
  };
}

export function formatConfidencePercent(confidence) {
  return `${Math.round((Number(confidence) || 0) * 100)}%`;
}

export function filterRecommendations(recommendations, { status, agentId, query } = {}) {
  return (recommendations || [])
    .filter((rec) => !status || rec.status === status)
    .filter((rec) => !agentId || rec.agentId === agentId)
    .filter((rec) => {
      if (!query) {
        return true;
      }
      const q = String(query).toLowerCase();
      return (
        String(rec.title || "").toLowerCase().includes(q) ||
        String(rec.body || "").toLowerCase().includes(q) ||
        String(rec.agentName || "").toLowerCase().includes(q)
      );
    });
}
