import React, { Component } from "react";
import { NavLink } from "react-router-dom";
import dateUtils from "_helpers/date.utils";
import classNames from "classnames/bind";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import {
  PO_STATUS_OPTIONS,
  formatPoClientLine,
  getPoProjectTypeMeta,
  getPoStatusMeta,
  getPoStatusSelectValue,
} from "./purchaseOrderList.utils";

class PurchaseOrderInfoLine extends Component {
  constructor(props) {
    super(props);
    this.state = { menuOpen: false, confirmRemove: false };
    this.rowRef = React.createRef();
    this.menuTriggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmRemove: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen, confirmRemove: false }));
  };

  closeMenu = () => this.setState({ menuOpen: false, confirmRemove: false });

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemovePurchaseOrder(this.props.item.id);
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true });
  };

  renderMenuItem = (item) => (
    <button
      key={item.key}
      type="button"
      className={classNames("lux-emp-card__menu-item", item.tone && `is-${item.tone}`)}
      role="menuitem"
      onClick={this.runMenuAction(item.onClick)}
    >
      <span className={classNames("lux-emp-card__menu-icon", item.tone && `is-${item.tone}`)}>
        <i className={item.icon} aria-hidden="true" />
      </span>
      <span className="lux-emp-card__menu-copy">
        <strong>{item.label}</strong>
      </span>
    </button>
  );

  getMenuSections = () => {
    const { item, permission } = this.props;
    const primary = [];
    if (permission.viewEnabled) {
      primary.push({
        key: "view",
        icon: "fe fe-eye",
        label: "View contract",
        onClick: () => this.props.onViewPurchaseOrder(item.id),
      });
    }
    if (!item.archived && permission.editEnabled) {
      primary.push({
        key: "edit",
        icon: "fe fe-edit-2",
        label: "Edit contract",
        onClick: () => this.props.handleEditPurchaseOrder(item.id, item.userTeamId),
      });
    }
    if (permission.duplicateEnabled) {
      primary.push({
        key: "duplicate",
        icon: "fe fe-copy",
        label: "Duplicate",
        onClick: () => this.props.handleDuplicatePurchaseOrder(item.id, item.userTeamId),
      });
    }

    const secondary = [];
    if (permission.archiveEnabled) {
      secondary.push({
        key: "archive",
        icon: item.archived ? "fe fe-inbox" : "fe fe-archive",
        label: item.archived ? "Unarchive" : "Archive",
        onClick: () => this.props.handleArchivePurchaseOrder(item.id, !item.archived),
      });
    }
    if (permission.deleteEnabled) {
      secondary.push({
        key: "delete",
        icon: item.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2",
        label: item.deleted ? "Undo delete" : "Delete",
        tone: "danger",
        onClick: () => this.props.handleDeletePurchaseOrder(item.id, !item.deleted),
      });
    }
    if (permission.removeEnabled) {
      secondary.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fe fe-check" : "fe fe-x",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove permanently",
        tone: "danger",
        onClick: this.handleRemove,
      });
    }
    return { primary, secondary };
  };

  render() {
    const { item, permission } = this.props;
    const { menuOpen } = this.state;
    const statusMeta = getPoStatusMeta(item.status);
    const typeMeta = getPoProjectTypeMeta(item.projectType);
    const clientLine = formatPoClientLine(item);
    const { primary, secondary } = this.getMenuSections();

    return (
      <article
        ref={this.rowRef}
        className={classNames("lux-bid-list__item", {
          "is-archived": item.archived,
          "is-deleted": item.deleted,
          "is-menu-open": menuOpen,
          [`is-status-${statusMeta.tone}`]: true,
        })}
        role="listitem"
      >
        <span className="lux-bid-list__accent" aria-hidden="true" />

        <div className="lux-bid-list__col lux-bid-list__col--id">
          <span className="lux-bid-list__ref">{item.itemIdUserTeamPrefix}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--created">
          <time className="lux-bid-list__date" dateTime={item.createdDate}>
            {dateUtils.convertDateFormat(item.createdDate)}
          </time>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--study">
          <div className="lux-bid-list__study">
            <div className="lux-bid-list__study-top">
              {item.deleted && (
                <span className="lux-bid-list__deleted-badge" title="Soft-deleted — use Undo delete to restore">
                  <i className="fe fe-trash-2" aria-hidden="true" />
                  Deleted
                </span>
              )}
              <span className={classNames("lux-bid-list__status-pill", `is-${statusMeta.tone}`)}>
                {statusMeta.label}
              </span>
              {typeMeta && (
                <span className={classNames("lux-bid-list__type-pill", `is-${typeMeta.tone}`)}>
                  {typeMeta.label}
                </span>
              )}
              {item.source === "SF" && (
                <span className="lux-po-list__sf-badge" title="Imported from Salesforce">
                  <i className="fa fa-cloud" aria-hidden="true" />
                  SF
                </span>
              )}
            </div>
            <NavLink
              to={`/sales/purchaseorder/${item.itemIdUserTeamPrefix}`}
              className="lux-bid-list__study-link"
              title={item.name}
            >
              {item.name}
              <i className="fe fe-arrow-up-right" aria-hidden="true" />
            </NavLink>
            {clientLine && (
              <span className="lux-bid-list__study-meta">
                <i className="fe fe-users" aria-hidden="true" />
                {clientLine}
              </span>
            )}
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--sfId">
          {item.proposalNumber ? (
            <span className="lux-bid-list__sf-id">{item.proposalNumber}</span>
          ) : (
            <span className="lux-bid-list__empty">—</span>
          )}
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--kind">
          {item.bidId ? (
            <span className="lux-bid-list__sf-id">{item.bidId}</span>
          ) : (
            <span className="lux-bid-list__empty">—</span>
          )}
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--countries">
          <span className="lux-bid-list__chip lux-bid-list__chip--geo">
            {item.accountName || "—"}
          </span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--dates">
          <span className="lux-po-list__date-chip is-start">
            {dateUtils.convertDateFormat(item.estStartTime)}
          </span>
          <span className="lux-po-list__date-chip is-end">
            {dateUtils.convertDateFormat(item.estCompletionTime)}
          </span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--status is-center">
          <div className={classNames("lux-bid-list__status-select", `is-${statusMeta.tone}`)}>
            <SelectInput
              options={PO_STATUS_OPTIONS}
              value={getPoStatusSelectValue(item.status)}
              allowLevelDown={permission.allowStatusLevelDown}
              changeableStatus={permission.changeableStatus}
              isReadOnly={!permission.allowStatusChange || this.props.readOnly}
              itemId={item.id}
              onChange={this.props.handleUpdateStatus}
              className="lux-bid-list__status-input"
            />
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--actions">
          <div className="lux-bid-list__actions">
            <button
              ref={this.menuTriggerRef}
              type="button"
              className="lux-bid-list__menu-trigger"
              onClick={this.toggleMenu}
              aria-expanded={menuOpen}
              aria-haspopup="menu"
              aria-label={`Actions for ${item.name || item.itemIdUserTeamPrefix}`}
            >
              <i className="fe fe-more-horizontal" aria-hidden="true" />
            </button>

            <LuxListRowMenuPortal
              open={menuOpen}
              anchorRef={this.menuTriggerRef}
              className="lux-bid-list__menu-panel"
            >
              <header className="lux-emp-card__menu-head">
                <span className="lux-emp-card__menu-head-icon" aria-hidden="true">
                  <i className="fe fe-file-text" />
                </span>
                <div>
                  <span className="lux-emp-card__menu-eyebrow">Purchase contract</span>
                  <strong title={item.name}>{item.name || item.itemIdUserTeamPrefix}</strong>
                </div>
                <button
                  type="button"
                  className="lux-emp-card__menu-close"
                  onClick={this.runMenuAction(null)}
                  aria-label="Close menu"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </header>
              <div className="lux-emp-card__menu-body">
                {primary.map((entry) => this.renderMenuItem(entry))}
                {secondary.length > 0 && primary.length > 0 && (
                  <div className="lux-emp-card__menu-divider" aria-hidden="true" />
                )}
                {secondary.map((entry) => this.renderMenuItem(entry))}
              </div>
            </LuxListRowMenuPortal>
          </div>
        </div>
      </article>
    );
  }
}

export default PurchaseOrderInfoLine;
