import React from "react";
import { useMsal } from "@azure/msal-react";
import { userActions } from "_actions";
import { store } from "_helpers";

/**
 * Renders a sign-out button
 */
export const MicrosoftSignOutButton = () => {
    const { instance } = useMsal();


    const handleLogout = (logoutType) => {
        if (logoutType === "popup") {
            instance.logoutPopup({
                postLogoutRedirectUri: "/",
                mainWindowRedirectUri: "/"
            }).then(response => {
                store.dispatch(userActions.logout());

            });
        } else if (logoutType === "redirect") {
            instance.logoutRedirect({
                postLogoutRedirectUri: "/",
            }).then(response => {
                store.dispatch(userActions.logout());

            });
        }
    }
    return (
        <button
            type="button"
            className="link lux-header-dropdown__item is-danger"
            onClick={() => handleLogout("popup")}
            data-ga-action="logout_microsoft"
            data-ga-category="auth"
            data-ga-label="Microsoft Sign out"
        >
            <span className="lux-header-dropdown__item-icon is-danger" aria-hidden="true">
                <i className="fe fe-log-out" />
            </span>
            <span className="lux-header-dropdown__item-copy">
                <strong>Sign out</strong>
                <span>Microsoft account</span>
            </span>
        </button>
    )
}