import React, { Component } from "react";
import classNames from "classnames/bind";
import { ORG_MASTER_LISTS } from "config/org-structure.config";
import { AdminActionButton } from "views/admin/components/AdminLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class OrgMasterListsPanel extends Component {
  state = {
    drafts: {},
    filter: "",
  };

  getDraft = (key) => String(this.state.drafts[key] || "");

  setDraft = (key, value) => {
    this.setState((prev) => ({
      drafts: { ...prev.drafts, [key]: value },
    }));
  };

  handleAdd = (key) => {
    const value = this.getDraft(key).trim();
    if (!value || !this.props.onCreate) {
      return;
    }
    this.props.onCreate(key, value);
    this.setDraft(key, "");
  };

  render() {
    const { masterLists, activeKey, onSelectKey, saving, removingValue, error, success } = this.props;
    const filter = String(this.state.filter || "").trim().toLowerCase();

    return (
      <div className="lux-org-masters" data-testid="org-master-lists-panel">
        <div className="lux-org-masters__toolbar">
          <div className="lux-admin-atelier__search">
            <i className="fe fe-search" aria-hidden="true" />
            <input
              type="search"
              className="lux-admin-atelier__search-input"
              placeholder="Filter list values"
              value={this.state.filter}
              onChange={(event) => this.setState({ filter: event.target.value })}
            />
          </div>
        </div>
        <div className="lux-org-masters__grid">
          {ORG_MASTER_LISTS.map((meta) => {
            const values = masterLists[meta.key] || [];
            const visible = filter
              ? values.filter((value) => String(value).toLowerCase().includes(filter))
              : values;
            const isActive = activeKey === meta.key;
            return (
              <article
                key={meta.key}
                className={classNames("lux-org-master-card", meta.tone && `is-${meta.tone}`, {
                  "is-active": isActive,
                })}
              >
                <header className="lux-org-master-card__head">
                  <button
                    type="button"
                    className="lux-org-master-card__identity"
                    onClick={() => onSelectKey && onSelectKey(meta.key)}
                  >
                    <span className={classNames("lux-org-master-card__icon", `is-${meta.tone}`)} aria-hidden="true">
                      <i className={meta.icon} />
                    </span>
                    <span>
                      <strong>{meta.label}</strong>
                      <small>{meta.hint}</small>
                    </span>
                  </button>
                  <span className="lux-org-master-card__count">{values.length}</span>
                </header>
                <div className="lux-org-master-card__add">
                  <input
                    type="text"
                    className="lux-org-reassign__control"
                    placeholder={`Add ${meta.singular}`}
                    value={this.getDraft(meta.key)}
                    onChange={(event) => this.setDraft(meta.key, event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault();
                        this.handleAdd(meta.key);
                      }
                    }}
                    aria-label={`New ${meta.singular}`}
                  />
                  <AdminActionButton
                    variant="primary"
                    onClick={() => this.handleAdd(meta.key)}
                    disabled={saving || !this.getDraft(meta.key).trim()}
                  >
                    {saving && isActive ? "Saving…" : "Add"}
                  </AdminActionButton>
                </div>
                {visible.length === 0 ? (
                  <LuxRegisterEmptyState
                    className="lux-register-empty--compact"
                    icon={meta.icon}
                    title={filter ? "No matches" : `No ${meta.label.toLowerCase()} yet`}
                    description={
                      filter
                        ? "Clear the filter to see the full Application Config list."
                        : `Stored in Application Config (HRMS). Used when mapping employees.`
                    }
                  />
                ) : (
                  <ul className="lux-org-master-card__chips" role="list">
                    {visible.map((value) => (
                      <li key={value} className="lux-org-master-chip" role="listitem">
                        <span>{value}</span>
                        <button
                          type="button"
                          className="lux-org-master-chip__remove"
                          aria-label={`Remove ${value}`}
                          disabled={Boolean(removingValue) || saving}
                          onClick={() => this.props.onRemove && this.props.onRemove(meta.key, value)}
                        >
                          <i className="fe fe-x" aria-hidden="true" />
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </article>
            );
          })}
        </div>
        {error ? (
          <p className="lux-org-structure-detail__error" role="alert">
            {error}
          </p>
        ) : null}
        {success ? (
          <p className="lux-org-structure-detail__success" role="status">
            {success}
          </p>
        ) : null}
      </div>
    );
  }
}

export default OrgMasterListsPanel;
