import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  isWorkspaceNotificationsEnabled,
  buildNotificationMetrics,
  buildNotificationInsights,
  filterNotifications,
  NOTIFICATION_TYPES,
} from "config/workspace.config";
import { workspaceService } from "_services/workspace.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import NotificationsRegister from "views/workspace/components/NotificationsRegister";
import {
  WorkspaceActionButton,
  WorkspaceKpiStrip,
  WorkspacePanelHead,
} from "views/workspace/components/WorkspaceLuxShared";
import WorkspaceSavedViewBar from "views/workspace/components/WorkspaceSavedViewBar";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class NotificationsPage extends Component {
  state = {
    notifications: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "UNREAD",
    typeFilter: "ALL",
    query: "",
    acting: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Notifications");
    this.loadNotifications();
  }

  loadNotifications = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await workspaceService.getNotifications();
      this.setState({
        notifications: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load notifications.",
        notifications: [],
      });
    }
  };

  handleMarkRead = async (notification) => {
    this.setState({ acting: true });
    try {
      await workspaceService.markNotificationRead(notification.id);
      await this.loadNotifications();
    } finally {
      this.setState({ acting: false });
    }
  };

  handleMarkAllRead = async () => {
    this.setState({ acting: true });
    try {
      await workspaceService.markAllNotificationsRead();
      await this.loadNotifications();
    } finally {
      this.setState({ acting: false });
    }
  };

  getFilteredNotifications = () => {
    const { notifications, statusFilter, typeFilter, query } = this.state;
    return filterNotifications(notifications, {
      status: statusFilter === "ALL" ? null : statusFilter,
      type: typeFilter,
      query,
    });
  };

  renderInsights = () => {
    const { notifications, loading } = this.state;
    if (loading) {
      return null;
    }
    const insights = buildNotificationInsights(notifications);
    if (insights.length === 0) {
      return null;
    }
    return (
      <div className="lux-notifications-insights" role="list">
        {insights.map((insight) => {
          const content = (
            <>
              <span className="lux-hrms-dash__alert-icon" aria-hidden="true"><i className={insight.icon} /></span>
              <span className="lux-notifications-insight__copy">
                <strong>{insight.title}</strong>
                <small>{insight.copy}</small>
              </span>
              {insight.path && <i className="fe fe-chevron-right lux-notifications-insight__chevron" aria-hidden="true" />}
            </>
          );
          return insight.path ? (
            <Link
              key={insight.id}
              to={insight.path}
              className={classNames("lux-hrms-dash__alert lux-notifications-insight", `is-${insight.tone}`)}
              role="listitem"
            >
              {content}
            </Link>
          ) : (
            <article key={insight.id} className={classNames("lux-hrms-dash__alert lux-notifications-insight", `is-${insight.tone}`)} role="listitem">
              {content}
            </article>
          );
        })}
      </div>
    );
  };

  render() {
    if (!isWorkspaceNotificationsEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Notifications"
          reason="Workspace notifications center is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, dataSource, statusFilter, typeFilter, query, acting } = this.state;
    const filtered = this.getFilteredNotifications();
    const metrics = buildNotificationMetrics(this.state.notifications);
    const kpiCards = [
      { id: "unread", label: "Unread", value: metrics.unread, hint: "Needs attention", tone: "amber", icon: "fe fe-bell" },
      { id: "high", label: "Urgent", value: metrics.highPriority, hint: "High priority unread", tone: "rose", icon: "fe fe-alert-triangle" },
      { id: "today", label: "Today", value: metrics.today, hint: "Received today", tone: "primary", icon: "fe fe-calendar" },
      { id: "total", label: "Total", value: metrics.total, hint: `${metrics.read} read`, tone: "slate", icon: "fe fe-layers" },
    ];

    return (
      <div className="lux-notifications-page lux-register-page">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.notifications}
          actions={
            <>
              <WorkspaceActionButton to="/workspace/approvals" icon="fe fe-inbox" variant="ghost">
                Approvals
              </WorkspaceActionButton>
              {!acting && metrics.unread > 0 ? (
                <WorkspaceActionButton
                  icon="fe fe-check-circle"
                  variant="primary"
                  onClick={(e) => {
                    e.preventDefault();
                    this.handleMarkAllRead();
                  }}
                >
                  Mark all read
                </WorkspaceActionButton>
              ) : null}
            </>
          }
        />

        <div className="lux-register-page__body">
        <WorkspaceKpiStrip cards={kpiCards} loading={loading} className="lux-notifications-kpi-strip" />

        {loadError && (
          <div className="lux-employee-360__error lux-notifications__error" role="alert">
            <span>{loadError}</span>
            <WorkspaceActionButton variant="ghost" onClick={this.loadNotifications}>
              Retry
            </WorkspaceActionButton>
          </div>
        )}

        {this.renderInsights()}

        <section className="lux-hrms-dash__panel lux-notifications-panel">
          <WorkspacePanelHead
            title="Notification inbox"
            subtitle="Filter by status or type, then open the linked workspace action"
          />

          <WorkspaceSavedViewBar
            surface="NOTIFICATIONS"
            currentFilters={{ status: statusFilter, type: typeFilter, query }}
            onApply={(nextFilters) =>
              this.setState({
                statusFilter: nextFilters.status || "UNREAD",
                typeFilter: nextFilters.type || "ALL",
                query: nextFilters.query || "",
              })
            }
          />

          <div className="lux-notifications-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search notifications, actors, or modules"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{filtered.length}</strong> notification{filtered.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-notifications-panel__filters">
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Status</span>
                <div className="lux-hrms-dash__filter-group">
                  {["UNREAD", "READ", "ARCHIVED", "ALL"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": statusFilter === value })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value.charAt(0) + value.slice(1).toLowerCase()}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Type</span>
                <div className="lux-hrms-dash__filter-group">
                  <button
                    type="button"
                    className={classNames("lux-hrms-dash__filter-chip", { "is-active": typeFilter === "ALL" })}
                    onClick={() => this.setState({ typeFilter: "ALL" })}
                  >
                    All
                  </button>
                  {Object.values(NOTIFICATION_TYPES).map((type) => (
                    <button
                      key={type.id}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", { "is-active": typeFilter === type.id })}
                      onClick={() => this.setState({ typeFilter: type.id })}
                    >
                      {type.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading notifications"
                description="Fetching your workspace alerts and system messages."
              />
            ) : filtered.length === 0 ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                icon="fe fe-bell"
                title="No notifications"
                description="You're caught up — new alerts will appear here when triggered."
              />
            ) : (
              <NotificationsRegister
                notifications={filtered}
                acting={acting}
                onMarkRead={this.handleMarkRead}
              />
            )}
          </div>
        </section>
        </div>
      </div>
    );
  }
}

export default NotificationsPage;
