export const DOCK_DEFAULT_BOTTOM = 72;
export const DOCK_MIN_BOTTOM = 48;
export const DOCK_STORAGE_KEY = "luxAssistDockBottom";

export function clampDockBottom(value) {
  if (typeof window === "undefined") {
    return DOCK_DEFAULT_BOTTOM;
  }
  const maxBottom = Math.max(DOCK_MIN_BOTTOM, window.innerHeight - 220);
  return Math.min(Math.max(value, DOCK_MIN_BOTTOM), maxBottom);
}

export function readStoredDockBottom() {
  try {
    const raw = localStorage.getItem(DOCK_STORAGE_KEY);
    if (raw == null) {
      return DOCK_DEFAULT_BOTTOM;
    }
    const parsed = parseInt(raw, 10);
    return Number.isFinite(parsed) ? clampDockBottom(parsed) : DOCK_DEFAULT_BOTTOM;
  } catch (e) {
    return DOCK_DEFAULT_BOTTOM;
  }
}

export function storeDockBottom(value) {
  try {
    localStorage.setItem(DOCK_STORAGE_KEY, String(clampDockBottom(value)));
  } catch (e) {
    /* ignore storage errors */
  }
}

/**
 * Bottom-right panel anchored to the assist dock trigger.
 * Uses flex on the overlay so positioning is not broken by modal defaults / ScaleUp.
 */
export function getAssistPanelModalStyle(anchor, options) {
  const bottom =
    anchor && Number.isFinite(anchor.bottom) ? anchor.bottom : DOCK_DEFAULT_BOTTOM + 98;
  const right =
    anchor && Number.isFinite(anchor.right) ? anchor.right : 0;
  const width = (options && options.width) || "400px";
  const maxWidth = (options && options.maxWidth) || "100%";
  const maxHeight =
    (options && options.maxHeight) || `calc(100vh - ${bottom + 20}px)`;
  const borderRadius = (options && options.borderRadius) || "16px 16px 0 0";

  return {
    overlay: {
      backgroundColor: "rgba(15, 23, 42, 0.12)",
      pointerEvents: "auto",
      backdropFilter: "blur(2px)",
      display: "flex",
      flexDirection: "column",
      justifyContent: "flex-end",
      alignItems: "flex-end",
      padding: `0 ${right}px ${bottom}px 16px`,
      zIndex: "var(--lux-z-overlay, 10040)",
    },
    content: {
      position: "relative",
      top: "auto",
      left: "auto",
      right: "auto",
      bottom: "auto",
      width: width,
      maxWidth: maxWidth,
      maxHeight: maxHeight,
      margin: 0,
      padding: 0,
      overflow: "hidden",
      display: "flex",
      flexDirection: "column",
      border: "none",
      borderRadius: borderRadius,
      boxShadow:
        "0 -4px 32px rgba(15, 23, 42, 0.18), 0 8px 24px rgba(15, 23, 42, 0.12)",
      pointerEvents: "auto",
      flexShrink: 0,
      zIndex: "var(--lux-z-overlay-panel, 10041)",
    },
  };
}

/**
 * Large centered assist panel (Flag Guide) — viewport-centered, clears sticky page header.
 * minHeight:0 lets the flex item shrink so a tall panel cannot sit under #page_top.
 */
export function getCenteredAssistPanelModalStyle(options) {
  const width = (options && options.width) || "min(94vw, 1080px)";
  const maxWidth = (options && options.maxWidth) || "1080px";
  const maxHeight = (options && options.maxHeight) || "min(82vh, 820px)";

  return {
    overlay: {
      backgroundColor: "rgba(15, 23, 42, 0.45)",
      pointerEvents: "auto",
      backdropFilter: "blur(4px)",
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      alignItems: "center",
      overflowY: "auto",
      overflowX: "hidden",
      WebkitOverflowScrolling: "touch",
      padding:
        "max(48px, env(safe-area-inset-top, 0px)) 16px max(32px, env(safe-area-inset-bottom, 0px))",
      boxSizing: "border-box",
      zIndex: "var(--lux-z-overlay, 10040)",
    },
    content: {
      position: "relative",
      top: "auto",
      left: "auto",
      right: "auto",
      bottom: "auto",
      width: width,
      maxWidth: maxWidth,
      height: "auto",
      maxHeight: maxHeight,
      minHeight: 0,
      margin: "auto",
      padding: 0,
      overflow: "hidden",
      display: "flex",
      flexDirection: "column",
      border: "none",
      borderRadius: "18px",
      boxShadow:
        "0 24px 64px rgba(15, 23, 42, 0.28), 0 8px 24px rgba(15, 23, 42, 0.16)",
      pointerEvents: "auto",
      flexShrink: 1,
      alignSelf: "center",
      zIndex: "var(--lux-z-overlay-panel, 10041)",
    },
  };
}
