import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPortfolioControlTowerEnabled } from "config/portfolio-control-tower.config";
import { portfolioControlTowerService } from "_services/portfolioControlTower.service";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import PortfolioLuxPage, { PortfolioLuxPanel } from "views/project/components/PortfolioLuxShared";
import PortfolioExecutiveSnapshotStrip from "views/project/components/PortfolioExecutiveSnapshotStrip";
import PortfolioProgramRegister from "views/project/components/PortfolioProgramRegister";
import PortfolioProjectHealthRegister from "views/project/components/PortfolioProjectHealthRegister";
import PortfolioHierarchyPanel from "views/project/components/PortfolioHierarchyPanel";
import PortfolioRoadmapPanel from "views/project/components/PortfolioRoadmapPanel";
import PortfolioCrossRollupsPanel from "views/project/components/PortfolioCrossRollupsPanel";
import PortfolioAnalyticsPanel from "views/project/components/PortfolioAnalyticsPanel";
import PortfolioExecutiveBriefingPanel from "views/project/components/PortfolioExecutiveBriefingPanel";
import { PORTFOLIO_PAGE_VARIANTS } from "config/portfolio-control-tower-nav.config";

const DEFAULT_PORTFOLIO_ID = "pf-enterprise";

class PortfolioControlTowerPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    rollup: null,
    executiveMetrics: [],
    hierarchy: null,
    roadmaps: [],
    crossRollups: null,
    analytics: null,
    briefing: null,
    selectedPortfolioId: DEFAULT_PORTFOLIO_ID,
  };

  componentDidMount() {
    this.loadData();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.location.pathname !== this.props.location.pathname) {
      this.loadData();
    }
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const portfolioId = this.state.selectedPortfolioId || DEFAULT_PORTFOLIO_ID;
      const isExecutive = this.resolveVariant() === PORTFOLIO_PAGE_VARIANTS.EXECUTIVE;

      const baseRequests = [
        portfolioControlTowerService.getPortfolioRollup(portfolioId),
        portfolioControlTowerService.getExecutiveMetrics(),
        portfolioControlTowerService.getProgramHierarchy(portfolioId),
        portfolioControlTowerService.getProgramRoadmap(portfolioId),
        portfolioControlTowerService.getCrossProjectRollups(portfolioId),
        portfolioControlTowerService.getPortfolioAnalytics(portfolioId),
      ];

      if (isExecutive) {
        baseRequests.push(portfolioControlTowerService.getExecutiveBriefing(portfolioId));
      }

      const results = await Promise.all(baseRequests);
      const [
        rollupResult,
        metricsResult,
        hierarchyResult,
        roadmapResult,
        crossRollupsResult,
        analyticsResult,
        briefingResult,
      ] = results;

      this.setState({
        loading: false,
        rollup: rollupResult.payload,
        executiveMetrics: metricsResult.payload || [],
        hierarchy: hierarchyResult.payload,
        roadmaps: roadmapResult.payload || [],
        crossRollups: crossRollupsResult.payload,
        analytics: analyticsResult.payload,
        briefing: briefingResult ? briefingResult.payload : null,
        dataSource: rollupResult.source || metricsResult.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load portfolio roll-up.",
      });
    }
  };

  resolveVariant = () => {
    const path = this.props.location && this.props.location.pathname;
    if (path && path.indexOf("/analytics/") === 0) {
      return PORTFOLIO_PAGE_VARIANTS.EXECUTIVE;
    }
    return PORTFOLIO_PAGE_VARIANTS.PORTFOLIO;
  };

  handleExportBriefing = () => {
    const portfolioId = this.state.selectedPortfolioId || DEFAULT_PORTFOLIO_ID;
    return portfolioControlTowerService.exportExecutiveBriefing(portfolioId);
  };

  renderExecutiveHeroActions = () => (
    <>
      <ResourcesActionButton to="/analytics/hub" icon="fe fe-grid" variant="ghost">
        Analytics hub
      </ResourcesActionButton>
      <ResourcesActionButton to="/analytics/report-builder" icon="fe fe-edit-3" variant="ghost">
        Report builder
      </ResourcesActionButton>
      <ResourcesActionButton to="/project/governance" icon="fe fe-shield" variant="primary">
        Governance hub
      </ResourcesActionButton>
    </>
  );

  renderPortfolioHeroActions = () => (
    <>
      <ResourcesActionButton to="/project/portfolio/scenarios" icon="fe fe-git-branch" variant="ghost">
        Scenarios
      </ResourcesActionButton>
      <ResourcesActionButton to="/project/governance" icon="fe fe-shield" variant="ghost">
        Governance hub
      </ResourcesActionButton>
      <ResourcesActionButton to="/project/dashboard" icon="fe fe-activity" variant="primary">
        Project dashboard
      </ResourcesActionButton>
    </>
  );

  render() {
    if (!isPortfolioControlTowerEnabled()) {
      return <PersonaAccessDenied featureLabel="Portfolio control tower" />;
    }

    const {
      loading,
      loadError,
      rollup,
      executiveMetrics,
      dataSource,
      hierarchy,
      roadmaps,
      crossRollups,
      analytics,
      briefing,
    } = this.state;
    const variant = this.resolveVariant();
    const isExecutive = variant === PORTFOLIO_PAGE_VARIANTS.EXECUTIVE;

    const hierarchyPanel = (
      <PortfolioLuxPanel
        title="Program hierarchy"
        meta={rollup ? `${rollup.programCount} programs · ${rollup.projectCount} governed projects` : "Program roll-up"}
        icon="fe fe-layers"
        accent="indigo"
        className={isExecutive ? "lux-portfolio-lux__panel--duo" : undefined}
      >
        <PortfolioHierarchyPanel hierarchy={hierarchy} loading={loading} />
      </PortfolioLuxPanel>
    );

    const roadmapPanel = (
      <PortfolioLuxPanel
        title="Program roadmaps"
        meta="Milestone and gate lanes across portfolio programs"
        icon="fe fe-map"
        accent="blue"
        className={isExecutive ? "lux-portfolio-lux__panel--duo" : undefined}
      >
        <PortfolioRoadmapPanel roadmaps={roadmaps} loading={loading} />
      </PortfolioLuxPanel>
    );

    const analyticsPanel = (
      <PortfolioLuxPanel
        title="Portfolio analytics"
        meta="Health distribution, slippage, and program scorecards"
        icon="fe fe-trending-up"
        accent="green"
        className={isExecutive ? "lux-portfolio-lux__panel--duo" : undefined}
      >
        <PortfolioAnalyticsPanel analytics={analytics} loading={loading} />
      </PortfolioLuxPanel>
    );

    const rollupsPanel = (
      <PortfolioLuxPanel
        title="Cross-project roll-ups"
        meta="Risk heatmap, resource utilization, and finance outlook"
        icon="fe fe-pie-chart"
        accent="amber"
        className={isExecutive ? "lux-portfolio-lux__panel--duo" : undefined}
      >
        <PortfolioCrossRollupsPanel rollups={crossRollups} loading={loading} />
      </PortfolioLuxPanel>
    );

    return (
      <PortfolioLuxPage
        variant={variant}
        dataSource={dataSource}
        demoLabel="Demo portfolio roll-up"
        loading={loading}
        rollup={rollup}
        executiveMetrics={executiveMetrics}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={isExecutive ? this.renderExecutiveHeroActions() : this.renderPortfolioHeroActions()}
      >
        {loadError ? (
          <PortfolioLuxPanel title="Portfolio load issue" meta={loadError} accent="rose">
            <button type="button" className="lux-onb-action lux-onb-action--primary" onClick={this.loadData}>
              Retry
            </button>
          </PortfolioLuxPanel>
        ) : null}

        {isExecutive ? <PortfolioExecutiveSnapshotStrip rollup={rollup} loading={loading} /> : null}

        {isExecutive ? (
          <PortfolioLuxPanel
            title="Executive briefing"
            meta="Leadership narrative with steering priorities and export"
            icon="fe fe-file-text"
            accent="violet"
            className="lux-portfolio-lux__panel--featured"
          >
            <PortfolioExecutiveBriefingPanel briefing={briefing} loading={loading} onExport={this.handleExportBriefing} />
          </PortfolioLuxPanel>
        ) : null}

        {isExecutive ? (
          <div className="lux-portfolio-lux__duo">
            {analyticsPanel}
            {rollupsPanel}
          </div>
        ) : (
          <>
            {hierarchyPanel}
            {roadmapPanel}
          </>
        )}

        {isExecutive ? (
          <div className="lux-portfolio-lux__duo">
            {hierarchyPanel}
            {roadmapPanel}
          </div>
        ) : null}

        {!isExecutive ? (
          <>
            <PortfolioLuxPanel
              title="Program register"
              meta="Status, health, and delivery signals per program"
              icon="fe fe-list"
              accent="indigo"
            >
              <PortfolioProgramRegister programs={(rollup && rollup.programs) || []} loading={loading} />
            </PortfolioLuxPanel>

            {rollupsPanel}
            {analyticsPanel}
          </>
        ) : (
          <PortfolioLuxPanel
            title="Program register"
            meta="Status, health, and delivery signals per program"
            icon="fe fe-list"
            accent="indigo"
          >
            <PortfolioProgramRegister programs={(rollup && rollup.programs) || []} loading={loading} />
          </PortfolioLuxPanel>
        )}

        <PortfolioLuxPanel
          title="Project health snapshots"
          meta="Cross-project delivery, risk, issue, and gate compliance signals"
          icon="fe fe-activity"
          accent="blue"
        >
          <PortfolioProjectHealthRegister rows={(rollup && rollup.projectHealth) || []} loading={loading} />
        </PortfolioLuxPanel>
      </PortfolioLuxPage>
    );
  }
}

export default PortfolioControlTowerPage;
