import React from "react";
import { createPortal } from "react-dom";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";

/**
 * Luxury slide-over panel for creating or editing a feedback request (portal to body).
 */
export default function LuxFeedbackRequestCreatePanel({
  show,
  editMode,
  onClose,
  children,
}) {
  const panel = (
    <LuxCreatePanelShell
      show={show === true}
      onClose={onClose}
      panelId="lux-feedback-request-create"
      className="lux-create-panel--feedback-request lux-feedback-request-create-panel"
      kicker={editMode ? "Edit campaign" : "New campaign"}
      title={editMode ? "Edit feedback request" : "New feedback request"}
      subtitle="Set up campaign details, recipients, schedule, and template."
    >
      {show === true && (
        <div className="lux-feedback-request-panel__body">{children}</div>
      )}
    </LuxCreatePanelShell>
  );

  if (typeof document !== "undefined") {
    return createPortal(panel, document.body);
  }
  return panel;
}
