import {
  ORG_MASTER_LISTS,
  ORG_UNIT_TYPE_META,
  ORG_UNIT_TYPES,
  normalizeOrgUnit,
  normalizeReportingLine,
} from "config/org-structure.config";
import { EMPLOYEES } from "mock/data/enterprise.mock";

export function getOrgUnitTypeMeta(type) {
  const key = String(type || "").toUpperCase();
  return ORG_UNIT_TYPE_META[key] || {
    label: type || "Unit",
    icon: "fe fe-circle",
    tone: "slate",
  };
}

export function buildReportingLinesFromEmployees(employees) {
  const byName = {};
  (employees || []).forEach((row) => {
    byName[row.name] = row;
  });

  return (employees || [])
    .map((row) => {
      const manager = row.manager && row.manager !== "—" ? byName[row.manager] : null;
      return normalizeReportingLine({
        employeeId: row.id,
        employeeName: row.name,
        designation: row.designation,
        department: row.department,
        managerId: manager ? manager.id : null,
        managerName: manager ? manager.name : null,
        location: row.location,
        status: row.status,
      });
    })
    .filter(Boolean);
}

export function buildOrgChartTree(employees) {
  const rows = employees || [];
  const nodes = rows.map((row) => ({
    id: row.id,
    name: row.name,
    designation: row.designation,
    department: row.department,
    location: row.location,
    status: row.status,
    managerName: row.manager,
    directReports: 0,
    children: [],
  }));

  const nodeById = {};
  nodes.forEach((node) => {
    nodeById[node.id] = node;
  });

  const roots = [];
  nodes.forEach((node) => {
    const employee = rows.find((row) => row.id === node.id);
    const managerName = employee && employee.manager;
    if (!managerName || managerName === "—" || managerName === "-") {
      roots.push(node);
      return;
    }
    const manager = rows.find((row) => row.name === managerName);
    if (manager && nodeById[manager.id]) {
      nodeById[manager.id].children.push(node);
      nodeById[manager.id].directReports += 1;
    } else {
      roots.push(node);
    }
  });

  const sortNodes = (list) => {
    list.sort((a, b) => a.name.localeCompare(b.name));
    list.forEach((node) => sortNodes(node.children));
  };
  sortNodes(roots);
  return roots;
}

export function flattenOrgChartTree(nodes, depth = 0, parentId = null) {
  const rows = [];
  (nodes || []).forEach((node) => {
    rows.push({ ...node, depth, parentId });
    rows.push(...flattenOrgChartTree(node.children, depth + 1, node.id));
  });
  return rows;
}

export function filterActiveEmployees(employees, { activeOnly = true } = {}) {
  const rows = employees || [];
  if (!activeOnly) {
    return rows;
  }
  return rows.filter((row) => {
    if (row.active === false || row.active === "false") {
      return false;
    }
    const status = String(row.status || "").toUpperCase();
    if (status === "INACTIVE" || status === "TERMINATED" || status === "EXITED" || status === "INACTIVE_EXIT") {
      return false;
    }
    return true;
  });
}

export function filterOrgChartEmployees(employees, filters = {}) {
  const { department = "ALL", query = "", activeOnly = true } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();
  const activeRows = filterActiveEmployees(employees, { activeOnly });

  return activeRows.filter((row) => {
    if (department !== "ALL" && row.department !== department) {
      return false;
    }
    if (!normalizedQuery) {
      return true;
    }
    const haystack = [row.name, row.designation, row.department, row.manager, row.location]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return haystack.includes(normalizedQuery);
  });
}

export function filterOrgUnits(orgUnits, filters = {}) {
  const { type = "ALL", query = "" } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();

  return (orgUnits || []).filter((row) => {
    if (type !== "ALL" && row.type !== type) {
      return false;
    }
    if (!normalizedQuery) {
      return true;
    }
    const haystack = [row.name, row.type, row.headEmployeeName, row.costCenter, row.location, row.department]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return haystack.includes(normalizedQuery);
  });
}

export function getOrgDepartments(employees) {
  const set = new Set((employees || []).map((row) => row.department).filter(Boolean));
  return Array.from(set).sort();
}

export function computeSpanOfControl(employees) {
  const counts = {};
  (employees || []).forEach((row) => {
    if (row.manager && row.manager !== "—" && row.manager !== "-") {
      counts[row.manager] = (counts[row.manager] || 0) + 1;
    }
  });
  return counts;
}

export function buildOrgChartMetrics(employees, orgUnits, options = {}) {
  const { activeOnly = true } = options;
  const rows = filterActiveEmployees(employees || EMPLOYEES, { activeOnly });
  const units = orgUnits || [];
  const spans = computeSpanOfControl(rows);
  const spanValues = Object.values(spans);
  const maxSpan = spanValues.length ? Math.max(...spanValues) : 0;
  const avgSpan = spanValues.length
    ? (spanValues.reduce((sum, value) => sum + value, 0) / spanValues.length).toFixed(1)
    : "0";
  const tree = buildOrgChartTree(rows);
  const flat = flattenOrgChartTree(tree);
  const maxDepth = flat.length ? Math.max(...flat.map((row) => row.depth)) + 1 : 0;

  return {
    headcount: rows.length,
    departments: getOrgDepartments(rows).length,
    orgUnits: units.length,
    managers: Object.keys(spans).length,
    maxSpan,
    avgSpan,
    maxDepth,
    vacantHeads: units.filter((unit) => !unit.headEmployeeId).length,
    activeOnly,
  };
}

export function buildOrgChartInsights(employees, orgUnits) {
  const rows = employees || [];
  const units = orgUnits || [];
  const metrics = buildOrgChartMetrics(rows, units);
  const spans = computeSpanOfControl(rows);
  const insights = [];

  const wideSpan = Object.entries(spans).find((entry) => entry[1] >= 5);
  if (wideSpan) {
    insights.push({
      id: "wide-span",
      tone: "amber",
      icon: "fe fe-alert-triangle",
      title: `${wideSpan[0]} has ${wideSpan[1]} direct reports`,
      copy: "Review span of control for manager capacity and approval routing.",
    });
  }
  if (metrics.vacantHeads > 0) {
    insights.push({
      id: "vacant-head",
      tone: "rose",
      icon: "fe fe-user-x",
      title: `${metrics.vacantHeads} org unit(s) without a named head`,
      copy: "Assign leaders in org structure admin to complete the hierarchy.",
    });
  }
  if (metrics.maxDepth >= 4) {
    insights.push({
      id: "depth",
      tone: "blue",
      icon: "fe fe-git-branch",
      title: `Reporting depth reaches ${metrics.maxDepth} levels`,
      copy: "Deep hierarchies may slow approvals — validate escalation paths.",
    });
  }
  if (insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-users",
      title: `${metrics.headcount} employees across ${metrics.departments} departments`,
      copy: `Average span of control ${metrics.avgSpan}; ${metrics.orgUnits} org units on file.`,
    });
  }
  return insights.slice(0, 3);
}

export function inferOrgUnitTypeFromDepth(depth) {
  const level = Number(depth) || 0;
  if (level <= 0) return ORG_UNIT_TYPES.COMPANY;
  if (level === 1) return ORG_UNIT_TYPES.DIVISION;
  if (level === 2) return ORG_UNIT_TYPES.DEPARTMENT;
  return ORG_UNIT_TYPES.TEAM;
}

function countNestedDescendants(children) {
  return (children || []).reduce((sum, child) => {
    return sum + 1 + countNestedDescendants(child && child.children);
  }, 0);
}

function flattenNestedOrgUnits(rows, parentId, depth) {
  const out = [];
  (rows || []).forEach((row) => {
    if (!row) return;
    const children = Array.isArray(row.children) ? row.children : [];
    const resolvedDepth = row.depth != null ? Number(row.depth) : depth;
    const resolvedParent = row.parentId != null && row.parentId !== "" ? row.parentId : parentId;
    const subtree = 1 + countNestedDescendants(children);
    const normalized = normalizeOrgUnit({
      ...row,
      parentId: resolvedParent,
      type: row.type || inferOrgUnitTypeFromDepth(resolvedDepth),
      headcount: row.headcount != null ? row.headcount : subtree,
      depth: resolvedDepth,
      childCount: children.length,
    });
    if (normalized) {
      out.push({
        ...normalized,
        depth: resolvedDepth,
        childCount: children.length,
      });
    }
    if (children.length) {
      out.push(...flattenNestedOrgUnits(children, normalized ? normalized.id : null, resolvedDepth + 1));
    }
  });
  return out;
}

/** Flatten nested EmployeeModel unit forests; pass through already-flat lists. */
export function flattenOrgUnitForest(rows) {
  const list = (rows || []).filter(Boolean);
  if (!list.length) return [];
  const nested = list.some((row) => Array.isArray(row.children) && row.children.length > 0);
  if (nested) {
    return flattenNestedOrgUnits(list, null, 0);
  }
  return list
    .map((row) => {
      const normalized = normalizeOrgUnit(row);
      if (!normalized) return null;
      return {
        ...normalized,
        depth: row.depth != null ? Number(row.depth) : 0,
        childCount: row.childCount != null ? Number(row.childCount) : 0,
      };
    })
    .filter(Boolean);
}

export function resolveOrgUnitEmployeeId(unit) {
  if (!unit) return null;
  if (unit.sourceEntityId) return String(unit.sourceEntityId);
  if (unit.headEmployeeId) return String(unit.headEmployeeId);
  const id = unit.id != null ? String(unit.id) : "";
  if (id.startsWith("emp-root-")) {
    return id.slice("emp-root-".length);
  }
  return null;
}

export function enrichOrgUnitsWithEmployees(units, employees) {
  const byId = {};
  (employees || []).forEach((row) => {
    if (row && row.id != null) {
      byId[String(row.id)] = row;
    }
  });
  return (units || []).map((unit) => {
    const empId = resolveOrgUnitEmployeeId(unit);
    const emp = empId ? byId[String(empId)] : null;
    if (!emp) return unit;
    return {
      ...unit,
      location: unit.location || emp.location || null,
      department: unit.department || emp.department || null,
      headEmployeeName: unit.headEmployeeName || emp.name || null,
      headEmployeeId: unit.headEmployeeId || String(emp.id),
    };
  });
}

export function buildOrgUnitTree(flatUnits) {
  const nodes = (flatUnits || []).map((row) => ({ ...row, children: [] }));
  const byId = {};
  nodes.forEach((node) => {
    if (node.id != null) {
      byId[String(node.id)] = node;
    }
  });
  const roots = [];
  nodes.forEach((node) => {
    const parentKey = node.parentId != null ? String(node.parentId) : "";
    if (parentKey && byId[parentKey] && byId[parentKey] !== node) {
      byId[parentKey].children.push(node);
    } else {
      roots.push(node);
    }
  });
  return roots;
}

export function isOrphanEmployee(row) {
  if (!row) return false;
  if (row.managerId) return false;
  const manager = row.managerName || row.manager;
  return !manager || manager === "—" || manager === "-";
}

export function filterReportingEmployees(employees, filters = {}) {
  const { department = "ALL", query = "", orphansOnly = false } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();
  return (employees || []).filter((row) => {
    if (orphansOnly && !isOrphanEmployee(row)) {
      return false;
    }
    if (department !== "ALL" && row.department !== department) {
      return false;
    }
    if (!normalizedQuery) {
      return true;
    }
    const haystack = [row.name, row.designation, row.department, row.manager, row.managerName, row.location]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return haystack.includes(normalizedQuery);
  });
}

export function collectDescendantIds(tree, nodeId) {
  const ids = new Set();
  const node = findNodeInOrgTree(tree, (row) => String(row.id) === String(nodeId));
  const walk = (current) => {
    (current.children || []).forEach((child) => {
      ids.add(String(child.id));
      walk(child);
    });
  };
  if (node) {
    walk(node);
  }
  return ids;
}

export function filterManagerCandidates(employees, employeeId, tree) {
  const blocked = tree ? collectDescendantIds(tree, employeeId) : new Set();
  if (employeeId != null && employeeId !== "") {
    blocked.add(String(employeeId));
  }
  return (employees || []).filter((row) => row && !blocked.has(String(row.id)));
}

export function listDirectReports(employees, manager) {
  if (!manager) return [];
  const managerName = manager.name || manager.employeeName;
  const managerId = manager.id != null ? String(manager.id) : null;
  return (employees || []).filter((row) => {
    if (managerId && row.managerId != null && String(row.managerId) === managerId) {
      return true;
    }
    const mgr = row.manager || row.managerName;
    return Boolean(managerName) && mgr === managerName;
  });
}

export function buildOrgStructureAdminMetrics(orgUnits, employees = []) {
  const units = (orgUnits || []).map((row) => normalizeOrgUnit(row)).filter(Boolean);
  const people = filterActiveEmployees(employees || [], { activeOnly: true });
  const chart = people.length ? buildOrgChartMetrics(people, units) : null;
  const unitHeadcount = units.reduce((sum, row) => sum + (row.headcount || 0), 0);
  return {
    totalUnits: units.length,
    departments: units.filter((row) => row.type === ORG_UNIT_TYPES.DEPARTMENT).length,
    divisions: units.filter((row) => row.type === ORG_UNIT_TYPES.DIVISION).length,
    headcount: people.length ? people.length : unitHeadcount,
    vacantHeads: units.filter((row) => !row.headEmployeeId).length,
    people: people.length,
    managers: chart ? chart.managers : 0,
    avgSpan: chart ? chart.avgSpan : "0",
    maxSpan: chart ? chart.maxSpan : 0,
    maxDepth: chart ? chart.maxDepth : 0,
    orphans: people.filter(isOrphanEmployee).length,
  };
}

export function buildOrgStructureAdminInsights(orgUnits, employees = [], masterLists = {}) {
  const metrics = buildOrgStructureAdminMetrics(orgUnits, employees);
  const insights = [];
  const people = employees || [];

  if (metrics.orphans > 1) {
    insights.push({
      id: "orphans",
      tone: "amber",
      icon: "fe fe-git-branch",
      title: `${metrics.orphans} people have no manager`,
      copy: "Reassign reporting lines so approvals and the org chart keep a single root.",
    });
  }

  if (people.length) {
    const spans = computeSpanOfControl(people);
    const wideSpan = Object.entries(spans).find((entry) => entry[1] >= 5);
    if (wideSpan) {
      insights.push({
        id: "wide-span",
        tone: "amber",
        icon: "fe fe-alert-triangle",
        title: `${wideSpan[0]} has ${wideSpan[1]} direct reports`,
        copy: "Review span of control before adding more reports to this manager.",
      });
    }
  }

  if (metrics.vacantHeads > 0) {
    insights.push({
      id: "vacant",
      tone: "amber",
      icon: "fe fe-user-x",
      title: `${metrics.vacantHeads} unit(s) need a department head`,
      copy: "Assign leaders before publishing org changes to employees.",
    });
  }

  const emptyMasters = ORG_MASTER_LISTS.filter((item) => !(masterLists[item.key] || []).length);
  if (emptyMasters.length && insights.length < 3) {
    insights.push({
      id: "masters",
      tone: "blue",
      icon: "fe fe-list",
      title: `${emptyMasters.length} master list${emptyMasters.length === 1 ? "" : "s"} still empty`,
      copy: `Add ${emptyMasters.map((row) => row.singular).join(", ")} values used on employee records.`,
    });
  }

  if (!insights.length && (metrics.people > 0 || metrics.totalUnits > 0)) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-users",
      title: `${metrics.people || metrics.headcount} people · ${metrics.totalUnits} hierarchy nodes`,
      copy: `Average span ${metrics.avgSpan}; depth ${metrics.maxDepth}. Reporting writes persist on EmployeeModel.`,
    });
  }

  return insights.slice(0, 3);
}

export function findNodeInOrgTree(nodes, predicate) {
  for (let i = 0; i < (nodes || []).length; i += 1) {
    const node = nodes[i];
    if (predicate(node)) {
      return node;
    }
    const child = findNodeInOrgTree(node.children, predicate);
    if (child) {
      return child;
    }
  }
  return null;
}

export function getEmployeeInitials(name) {
  const parts = String(name || "?")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}
