import React, { Component } from "react";
import { Link, withRouter } from "react-router-dom";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  SYSTEM_ERRORS_PAGE_META,
  SYSTEM_ERROR_SOURCE_FILTERS,
  SYSTEM_ERROR_STATUS_FILTERS,
  buildSystemErrorKpis,
  isSystemErrorsEnabled,
} from "config/system-errors.config";
import { systemErrorsService } from "_services/systemErrors.service";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  AdminActionButton,
  AdminKpiStrip,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";

function formatWhen(iso) {
  if (!iso) return "—";
  try {
    return new Date(iso).toLocaleString();
  } catch (e) {
    return iso;
  }
}

function DetailDrawer({ open, event, busy, onClose, onAck, onResolve }) {
  if (!open || !event) return null;
  const detail = event.detail || {};
  const detailEntries = Object.keys(detail).map((key) => ({ key, value: detail[key] }));

  return createPortal(
    <div className="lux-dev-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className="lux-dev-drawer lux-dev-drawer--rose"
        role="dialog"
        aria-modal="true"
        aria-label="System error details"
        onClick={(e) => e.stopPropagation()}
      >
        <header className="lux-dev-drawer__head">
          <div className="lux-dev-drawer__head-copy">
            <span className="lux-dev-drawer__eyebrow">
              {event.source} · {event.severity} · {event.status}
            </span>
            <h2>{event.title}</h2>
          </div>
          <button type="button" className="lux-dev-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" />
          </button>
        </header>
        <div className="lux-dev-drawer__body">
          <section className="lux-syserr-detail-block">
            <h3>Why this failed</h3>
            <p>{event.summary || "No summary provided."}</p>
            <p className="lux-syserr-detail-meta">
              Code <code>{event.code}</code>
              {" · "}Seen {event.occurrenceCount || 1}×
              {" · "}First {formatWhen(event.firstSeenAt)}
              {" · "}Last {formatWhen(event.lastSeenAt)}
            </p>
          </section>
          <section className="lux-syserr-detail-block">
            <h3>What to do</h3>
            <p>{event.suggestedAction || "Review related systems and retry after fixing the root cause."}</p>
            {event.relatedPath ? (
              <Link to={event.relatedPath} className="lux-int-connection-card__link">
                Open related screen
              </Link>
            ) : null}
          </section>
          {detailEntries.length ? (
            <section className="lux-syserr-detail-block">
              <h3>Technical context</h3>
              <dl className="lux-syserr-detail-grid">
                {detailEntries.map((row) => (
                  <div key={row.key}>
                    <dt>{row.key}</dt>
                    <dd>
                      {typeof row.value === "object"
                        ? JSON.stringify(row.value)
                        : String(row.value == null ? "—" : row.value)}
                    </dd>
                  </div>
                ))}
              </dl>
            </section>
          ) : null}
        </div>
        <footer className="lux-dev-drawer__footer">
          <AdminActionButton onClick={onClose}>Close</AdminActionButton>
          {event.status === "OPEN" ? (
            <AdminActionButton variant="ghost" disabled={busy} onClick={() => onAck(event)}>
              Acknowledge
            </AdminActionButton>
          ) : null}
          {event.status !== "RESOLVED" ? (
            <AdminActionButton variant="primary" disabled={busy} onClick={() => onResolve(event)}>
              Mark resolved
            </AdminActionButton>
          ) : null}
        </footer>
      </aside>
    </div>,
    document.body
  );
}

class SystemErrorsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    overview: {},
    events: [],
    statusFilter: "OPEN",
    sourceFilter: "ALL",
    query: "",
    selected: null,
    drawerOpen: false,
    busy: false,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("System errors");
    }
    this.loadAll();
  }

  loadAll = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [overviewResult, listResult] = await Promise.all([
        systemErrorsService.getOverview(),
        systemErrorsService.listEvents({
          status: this.state.statusFilter,
          source: this.state.sourceFilter,
          q: this.state.query,
        }),
      ]);
      this.setState({
        loading: false,
        dataSource: listResult.source,
        overview: overviewResult.payload || {},
        events: (listResult.payload && listResult.payload.events) || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load system errors.",
      });
    }
  };

  handleFilter = (patch) => {
    this.setState(patch, this.loadAll);
  };

  openEvent = async (event) => {
    this.setState({ selected: event, drawerOpen: true });
    try {
      const result = await systemErrorsService.getEvent(event.eventRef);
      if (result.payload) {
        this.setState({ selected: result.payload });
      }
    } catch (e) {
      // keep list row
    }
  };

  updateStatus = async (event, status) => {
    this.setState({ busy: true, loadError: null });
    try {
      await systemErrorsService.updateEventStatus(event.eventRef, status);
      this.setState({ drawerOpen: false, selected: null, busy: false });
      await this.loadAll();
    } catch (error) {
      this.setState({
        busy: false,
        loadError: (error && error.message) || "Unable to update status.",
      });
    }
  };

  render() {
    if (!isSystemErrorsEnabled()) {
      return (
        <PersonaAccessDenied
          denial={{
            pageName: "System errors",
            moduleName: "System errors",
            message: "System errors is disabled for your role. An admin can turn it on under Roles → adminModules.systemErrorsEnabled.",
          }}
        />
      );
    }

    const {
      loading,
      loadError,
      dataSource,
      overview,
      events,
      statusFilter,
      sourceFilter,
      query,
      selected,
      drawerOpen,
      busy,
    } = this.state;

    return (
      <AdminLuxPage
        pageMeta={SYSTEM_ERRORS_PAGE_META}
        testId="page-admin-system-errors"
        dataSource={dataSource}
        loading={loading}
        onRefresh={this.loadAll}
        refreshLoading={loading}
        heroActions={
          <>
            <AdminActionButton to="/integrations/connections" icon="fe fe-settings" variant="ghost">
              Connections
            </AdminActionButton>
            <AdminActionButton to="/integrations/sync-health" icon="fe fe-activity" variant="ghost">
              Sync health
            </AdminActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}

        <AdminKpiStrip cards={buildSystemErrorKpis(overview)} loading={loading} />

        <div className="lux-syserr-toolbar" role="toolbar" aria-label="Filter system errors">
          <div className="lux-syserr-chips">
            {SYSTEM_ERROR_STATUS_FILTERS.map((chip) => (
              <button
                key={chip.id}
                type="button"
                className={classNames("lux-admin-atelier__chip", {
                  "is-active": statusFilter === chip.id,
                })}
                onClick={() => this.handleFilter({ statusFilter: chip.id })}
              >
                {chip.label}
              </button>
            ))}
          </div>
          <div className="lux-syserr-chips">
            {SYSTEM_ERROR_SOURCE_FILTERS.map((chip) => (
              <button
                key={chip.id}
                type="button"
                className={classNames("lux-admin-atelier__chip", {
                  "is-active": sourceFilter === chip.id,
                })}
                onClick={() => this.handleFilter({ sourceFilter: chip.id })}
              >
                {chip.label}
              </button>
            ))}
          </div>
          <label className="lux-syserr-search">
            <span className="sr-only">Search</span>
            <input
              type="search"
              placeholder="Search title, code, summary…"
              value={query}
              onChange={(e) => this.setState({ query: e.target.value })}
              onKeyDown={(e) => {
                if (e.key === "Enter") this.loadAll();
              }}
            />
            <AdminActionButton variant="ghost" icon="fe fe-search" onClick={this.loadAll}>
              Search
            </AdminActionButton>
          </label>
        </div>

        <section className="lux-syserr-register" aria-label="System error register">
          {loading ? (
            <p>Loading system errors…</p>
          ) : events.length === 0 ? (
            <LuxRegisterEmptyState
              variant="bid-requests"
              eyebrow="All clear"
              title="No system errors in this view"
              description="When Salesforce, ZingHR, credentials, schedulers, or health checks fail, they appear here with a clear explanation."
              showSecondary
              secondaryLabel="Check connections"
              secondaryIcon="fe fe-link"
              onSecondary={() => {
                if (this.props.history) this.props.history.push("/integrations/connections");
              }}
            />
          ) : (
            <ul className="lux-syserr-list">
              {events.map((event) => (
                <li key={event.eventRef}>
                  <button
                    type="button"
                    className={classNames("lux-syserr-row", `is-${event.severity || "error"}`)}
                    onClick={() => this.openEvent(event)}
                  >
                    <span className="lux-syserr-row__severity">{event.severity}</span>
                    <span className="lux-syserr-row__main">
                      <strong>{event.title}</strong>
                      <span>{event.summary}</span>
                    </span>
                    <span className="lux-syserr-row__meta">
                      <span>{event.source}</span>
                      <span>{event.occurrenceCount || 1}×</span>
                      <span>{formatWhen(event.lastSeenAt)}</span>
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>

        <DetailDrawer
          open={drawerOpen}
          event={selected}
          busy={busy}
          onClose={() => this.setState({ drawerOpen: false, selected: null })}
          onAck={(event) => this.updateStatus(event, "ACKNOWLEDGED")}
          onResolve={(event) => this.updateStatus(event, "RESOLVED")}
        />
      </AdminLuxPage>
    );
  }
}

export default withRouter(SystemErrorsPage);
