import React, { Component } from "react";
import { Link } from "react-router-dom";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";

class ProjectDetailsFiles extends Component {
  render() {
    const { projectInfo } = this.props;
    const ref = projectInfo && projectInfo.itemIdUserTeamPrefix;

    return (
      <ProjectDetailsTabShell
        icon="fe fe-folder"
        eyebrow="Documents"
        title="Project files"
        subtitle="Attachments and folders for this project will appear here when a files API is connected."
        stats={[
          { key: "files", label: "Files", value: 0, hint: "No API data" },
          { key: "storage", label: "Storage", value: "—", hint: "Not synced" },
        ]}
      >
        <LuxRegisterEmptyState
          variant="files"
          eyebrow="No data"
          title="No files for this project"
          description="There is no project-scoped file list in the API yet. Use the workspace file manager for shared documents, or attach files on deliverables and comments."
          hints={[
            "Uploads on deliverables appear in their detail view",
            "Workspace file manager lists shared team files",
          ]}
          className="lux-pd-tab__empty"
        />
        <p className="lux-pd-files__links">
          <Link to="/project/filemanager">Open file manager</Link>
          {ref && (
            <>
              <span aria-hidden="true"> · </span>
              <Link to={`/project/deliverables/${ref}`}>View deliverables</Link>
            </>
          )}
        </p>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsFiles;
