
import { axiosUtils } from '../_helpers';
import urlConfig from 'url.config'

export const invoiceService = {
    getAllInvoices,
    getInvoiceInfo,
    createInvoice,
    updateInvoice,
    updateInvoiceStatus,
    recordPayment,
    getCollectionsAging,
    removeInvoice,
    listTracopusClients
};

/** Famstack often returns HTTP 200 with ServiceResponse.error — treat as failure. */
function extractServiceError(response) {
    if (!response || typeof response !== 'object' || !response.error) {
        return null;
    }
    const first = Array.isArray(response.error) ? response.error[0] : response.error;
    if (!first) {
        return null;
    }
    if (typeof first === 'string') {
        return first;
    }
    return first.message || first.code || 'Request failed';
}

function assertServiceSuccess(response) {
    if (typeof response === 'string') {
        throw new Error(response || 'Request failed');
    }
    const serviceError = extractServiceError(response);
    if (serviceError) {
        const error = new Error(serviceError);
        error.response = { data: response, status: 200 };
        throw error;
    }
    return response;
}

async function getAllInvoices(limit = 12) {
    const safeLimit = Math.max(1, Number(limit) || 12);
    return await axiosUtils.get(urlConfig.INVOICE_PATH + `/list/${safeLimit}`);
}

async function getInvoiceInfo(invoiceId, hasAccess) {
    return await axiosUtils.get(urlConfig.INVOICE_PATH+ `/${invoiceId}`);
}

async function createInvoice(invoiceRequest) {
    return await axiosUtils.post(urlConfig.INVOICE_PATH, invoiceRequest);
}

async function updateInvoice(invoiceRequest) {
    return await axiosUtils.put(urlConfig.INVOICE_PATH, invoiceRequest);
}
async function updateInvoiceStatus(invoiceId, status, employeeId) {
    return await axiosUtils.put(urlConfig.INVOICE_PATH + `/status/${invoiceId}/${status}?employeeId=`+ employeeId);
}

async function recordPayment(invoiceId, paidAmount, employeeId) {
    return await axiosUtils.put(
        urlConfig.INVOICE_PATH + `/${invoiceId}/payment?paidAmount=${encodeURIComponent(paidAmount)}&employeeId=${employeeId}`
    );
}

async function listTracopusClients() {
    return await axiosUtils.get(urlConfig.TRACOPUS_CLIENTS_PATH);
}

async function getCollectionsAging(howMany = 500) {
    const safeLimit = Math.max(1, Number(howMany) || 500);
    // AccountsController: GET /api/v2/accounts/collections/aging
    const response = await axiosUtils.get(`${urlConfig.ACCOUNTS_LIST}/collections/aging?howMany=${safeLimit}`);
    return assertServiceSuccess(response);
}

async function removeInvoice(invoiceId) {
    return await axiosUtils.remove(urlConfig.INVOICE_PATH + `/${invoiceId}`);
}
