import React, { useEffect, useRef, useState } from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";

function LifecycleDepartmentSelect({ value, departments, onChange }) {
  const [open, setOpen] = useState(false);
  const [filterText, setFilterText] = useState("");
  const rootRef = useRef(null);
  const panelRef = useRef(null);
  const showSearch = departments.length > 5;

  useEffect(() => {
    const handleOutsideClick = (event) => {
      if (!open) {
        return;
      }
      const panel = panelRef.current;
      const root = rootRef.current;
      if (
        panel &&
        !panel.contains(event.target) &&
        root &&
        !root.contains(event.target)
      ) {
        setOpen(false);
        setFilterText("");
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);
    return () => document.removeEventListener("mousedown", handleOutsideClick);
  }, [open]);

  const closePanel = () => {
    setOpen(false);
    setFilterText("");
  };

  const togglePanel = () => {
    setOpen((prev) => {
      if (prev) {
        setFilterText("");
      }
      return !prev;
    });
  };

  const selectValue = (nextValue) => {
    onChange(nextValue);
    closePanel();
  };

  const selectedLabel = value === "ALL" ? "All departments" : value || "All departments";
  const filtered = departments.filter(
    (dept) => !filterText || commonUtils.stringContainsString(dept, filterText)
  );

  return (
    <div
      className="lux-att-employee-filter is-header lux-onb-dept-filter"
      ref={rootRef}
    >
      <button
        type="button"
        className={classNames("lux-att-employee-filter__trigger", { "is-open": open })}
        onClick={togglePanel}
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-label="Filter by department"
        title="Filter by department"
      >
        <i className="fe fe-briefcase" aria-hidden />
        <span className="lux-att-employee-filter__label">{selectedLabel}</span>
        <i className="fe fe-chevron-down lux-att-employee-filter__chevron" aria-hidden />
      </button>

      {open && (
        <div className="lux-att-employee-filter__panel" ref={panelRef}>
          <header className="lux-att-employee-filter__panel-head">
            <strong>Filter by department</strong>
            <button
              type="button"
              className="lux-att-employee-filter__panel-close"
              onClick={closePanel}
              aria-label="Close department filter"
            >
              <i className="fe fe-x" aria-hidden />
            </button>
          </header>

          {showSearch && (
            <label className="lux-att-employee-filter__search">
              <i className="fe fe-search" aria-hidden />
              <input
                type="search"
                value={filterText}
                onChange={(e) => setFilterText(e.target.value)}
                placeholder="Search departments..."
              />
            </label>
          )}

          <ul className="lux-att-employee-filter__list" role="listbox" aria-label="Department options">
            <li>
              <button
                type="button"
                className={classNames("lux-att-employee-filter__option", {
                  "is-selected": value === "ALL",
                })}
                onClick={() => selectValue("ALL")}
              >
                <i className="fe fe-layers" aria-hidden />
                <span>All departments</span>
              </button>
            </li>
            {filtered.map((dept) => (
              <li key={dept}>
                <button
                  type="button"
                  className={classNames("lux-att-employee-filter__option", {
                    "is-selected": value === dept,
                  })}
                  onClick={() => selectValue(dept)}
                >
                  <i className="fe fe-briefcase" aria-hidden />
                  <span>{dept}</span>
                </button>
              </li>
            ))}
            {showSearch && filtered.length === 0 && (
              <li className="lux-att-employee-filter__empty">
                No departments match your search.
              </li>
            )}
          </ul>
        </div>
      )}
    </div>
  );
}

export default LifecycleDepartmentSelect;
