/**
 * F04 — Leave enhancement feature flags.
 * Enablement and live API use follow Application Config (org leaveAdditional).
 */
import { shouldUseLeaveEnhancements } from "config/tracopus-pilot.config";

export function isLeaveEnhancementsEnabled() {
  return shouldUseLeaveEnhancements();
}

/** Live leave impact/coverage APIs when org leaveEnhancementsEnabled is on. */
export function shouldUseLeaveImpactApi() {
  return isLeaveEnhancementsEnabled();
}
