import React, { Component } from "react";
import classNames from "classnames/bind";

const USER_TEAM_META = {
  label: "User team",
  icon: "fe-users",
  tone: "violet",
  drillLabel: "Browse accounts",
  drillHint: "Open accounts for this team, then add teams and clients underneath",
  createLabel: "Add account",
};

const TYPE_META = {
  ACCOUNT: {
    label: "Account",
    icon: "fe-briefcase",
    tone: "indigo",
    drillLabel: "Browse teams",
    drillHint: "View and manage delivery teams under this account",
    createLabel: "Add team",
  },
  TEAM: {
    label: "Team",
    icon: "fe-users",
    tone: "sky",
    drillLabel: "Browse clients",
    drillHint: "View end clients linked to this team",
    createLabel: "Add client",
  },
  CLIENT: {
    label: "Client",
    icon: "fe-user",
    tone: "teal",
    drillLabel: null,
    drillHint: "Leaf node in the account hierarchy",
    createLabel: null,
  },
};

class AccountDetailPopover extends Component {
  componentDidMount() {
    document.addEventListener("keydown", this.handleKeyDown);
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
  }

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.show) {
      this.props.onClose();
    }
  };

  renderMetric = (icon, value, label, tone) => (
    <div className={classNames("lux-acct-popover__metric", tone && `is-${tone}`)}>
      <span className="lux-acct-popover__metric-icon" aria-hidden="true">
        <i className={`fe ${icon}`} />
      </span>
      <div>
        <strong>{value}</strong>
        <span>{label}</span>
      </div>
    </div>
  );

  render() {
    const {
      show,
      item,
      parentItem,
      viewName,
      hierarchyEnabled,
      createEnabled,
      permission,
      confirmRemove,
      onClose,
      onDrillDown,
      onCreateChild,
      onRemove,
      onDetach,
      viewByAccounts,
    } = this.props;

    if (!show || !item) return null;

    const isUserTeam = viewName === "USERTEAMS" && !item.type;
    const meta = isUserTeam
      ? USER_TEAM_META
      : TYPE_META[item.type] || {
          label: item.type || "Record",
          icon: "fe-folder",
          tone: "slate",
          drillLabel: "Open",
          drillHint: "",
          createLabel: null,
        };
    const canDrill =
      hierarchyEnabled &&
      !isUserTeam &&
      item.type !== "CLIENT" &&
      item.source !== "SALES_FORCE" &&
      meta.drillLabel;
    const canDrillUserTeam = hierarchyEnabled && isUserTeam;
    const canCreateChild =
      hierarchyEnabled && createEnabled && onCreateChild && (isUserTeam || meta.createLabel);
    const teams = Number(item.noOfTeams) || 0;
    const clients = Number(item.noOfClients) || 0;

    return (
      <>
        <button
          type="button"
          className="lux-acct-popover__backdrop"
          aria-label="Close account details"
          onClick={onClose}
        />
        <div
          className="lux-acct-popover"
          role="dialog"
          aria-modal="true"
          aria-labelledby="lux-acct-popover-title"
        >
          <div className="lux-acct-popover__glow" aria-hidden="true" />

          <header className={classNames("lux-acct-popover__hero", `is-${meta.tone}`)}>
            <div className="lux-acct-popover__hero-mesh" aria-hidden="true" />
            <div className="lux-acct-popover__hero-top">
              <div className="lux-acct-popover__hero-brand">
                <span className={classNames("lux-acct-popover__icon", `is-${meta.tone}`)} aria-hidden="true">
                  {item.source === "SALES_FORCE" ? (
                    <img src="/assets/images/custom/sf_nobg.png" alt="" width={28} height={28} />
                  ) : (
                    <i className={`fe ${meta.icon}`} />
                  )}
                </span>
                <div>
                  <p className="lux-acct-popover__kicker">{meta.label}</p>
                  <h2 id="lux-acct-popover-title">{item.name}</h2>
                  <p className="lux-acct-popover__meta-line">
                    <span>ID {item.id}</span>
                    {parentItem && parentItem.name && (
                      <>
                        <span className="lux-acct-popover__meta-sep">·</span>
                        <span>
                          <i className="fe fe-git-branch" aria-hidden="true" /> Under {parentItem.name}
                        </span>
                      </>
                    )}
                  </p>
                </div>
              </div>
              <button type="button" className="lux-acct-popover__close" onClick={onClose} aria-label="Close">
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            </div>

            {isUserTeam && (
              <div className="lux-acct-popover__metrics-row">
                {this.renderMetric("fe-layers", "—", "Accounts", "violet")}
                {this.renderMetric("fe-git-branch", "3 levels", "Hierarchy", "sky")}
              </div>
            )}
            {(item.type === "ACCOUNT" || item.type === "TEAM") && (
              <div className="lux-acct-popover__metrics-row">
                {item.type === "ACCOUNT" &&
                  this.renderMetric("fe-users", teams, "Teams", "sky")}
                {this.renderMetric("fe-briefcase", clients, "Clients", "teal")}
              </div>
            )}
          </header>

          <div className="lux-acct-popover__body">
            {item.source === "SALES_FORCE" && (
              <div className="lux-acct-popover__callout lux-acct-popover__callout--sf">
                <img src="/assets/images/custom/sf_nobg.png" alt="" width={22} height={22} />
                <div>
                  <strong>Salesforce linked</strong>
                  <span>{item.extAccountId || "External ID on file"}</span>
                </div>
              </div>
            )}

            {(canDrill || canDrillUserTeam) && (
              <div className="lux-acct-popover__callout lux-acct-popover__callout--hierarchy">
                <i className="fe fe-layers" aria-hidden="true" />
                <div>
                  <strong>Hierarchy</strong>
                  <span>{meta.drillHint}</span>
                </div>
              </div>
            )}

            <div className="lux-acct-popover__details">
              <h3 className="lux-acct-popover__details-title">Record details</h3>
              <dl className="lux-acct-popover__dl">
                <div className="lux-acct-popover__dl-row">
                  <dt>Type</dt>
                  <dd>{meta.label}</dd>
                </div>
                {item.itemType && (
                  <div className="lux-acct-popover__dl-row">
                    <dt>Billing</dt>
                    <dd>{item.itemType === "BILLABLE" ? "Billable" : "Non billable"}</dd>
                  </div>
                )}
                {item.poc && (
                  <div className="lux-acct-popover__dl-row">
                    <dt>Owner</dt>
                    <dd>{item.poc}</dd>
                  </div>
                )}
                {item.email && (
                  <div className="lux-acct-popover__dl-row">
                    <dt>Email</dt>
                    <dd>
                      <a href={`mailto:${item.email}`}>{item.email}</a>
                    </dd>
                  </div>
                )}
                {viewName && (
                  <div className="lux-acct-popover__dl-row">
                    <dt>Current view</dt>
                    <dd>{viewName}</dd>
                  </div>
                )}
              </dl>
              {item.description && (
                <div className="lux-acct-popover__notes">
                  <span className="lux-acct-popover__label">Description</span>
                  <p>{item.description}</p>
                </div>
              )}
            </div>
          </div>

          <footer className="lux-acct-popover__foot">
            <div className="lux-acct-popover__foot-primary">
              {(canDrill || canDrillUserTeam) && (
                <button
                  type="button"
                  className="lux-acct-popover__btn lux-acct-popover__btn--primary"
                  onClick={onDrillDown}
                >
                  <i className="fe fe-chevrons-right" aria-hidden="true" />
                  {meta.drillLabel}
                </button>
              )}
              {canCreateChild && (
                <button
                  type="button"
                  className="lux-acct-popover__btn lux-acct-popover__btn--accent"
                  onClick={onCreateChild}
                >
                  <i className="fe fe-plus-circle" aria-hidden="true" />
                  {isUserTeam ? "Add account" : meta.createLabel}
                </button>
              )}
            </div>
            <div className="lux-acct-popover__foot-secondary">
              <button type="button" className="lux-acct-popover__btn lux-acct-popover__btn--ghost" onClick={onClose}>
                Close
              </button>
              {permission && permission.removeEnabled && viewByAccounts && onRemove && (
                <button
                  type="button"
                  className={classNames("lux-acct-popover__btn", "lux-acct-popover__btn--danger", {
                    "is-confirm": confirmRemove,
                  })}
                  onClick={() => onRemove(!confirmRemove)}
                >
                  <i
                    className={classNames("fe", confirmRemove ? "fe-check blink_text" : "fe-trash-2")}
                    aria-hidden="true"
                  />
                  {confirmRemove ? "Confirm remove" : "Remove"}
                </button>
              )}
              {permission && permission.deleteEnabled && !viewByAccounts && onDetach && (
                <button type="button" className="lux-acct-popover__btn lux-acct-popover__btn--danger" onClick={onDetach}>
                  <i className="fe fe-link-2" aria-hidden="true" />
                  Detach
                </button>
              )}
            </div>
          </footer>
        </div>
      </>
    );
  }
}

export default AccountDetailPopover;
