import {
  INTEGRATION_CONNECTOR_STATUSES,
  INTEGRATION_LOG_LEVELS,
  INTEGRATION_SYNC_JOB_STATUSES,
} from "config/integration-center.config";

export function normalizeConnector(row) {
  if (!row) {
    return null;
  }
  const statusRaw = String(row.status || "").toLowerCase();
  const status =
    statusRaw === "healthy"
      ? INTEGRATION_CONNECTOR_STATUSES.HEALTHY
      : statusRaw === "degraded"
        ? INTEGRATION_CONNECTOR_STATUSES.DEGRADED
        : statusRaw === "failed"
          ? INTEGRATION_CONNECTOR_STATUSES.FAILED
          : INTEGRATION_CONNECTOR_STATUSES.PAUSED;
  return {
    id: row.id,
    name: row.name || "Connector",
    type: row.type || "CRM",
    status,
    statusLabel: row.status || status,
    trustScore: Number(row.trustScore) || 0,
    lastSync: row.lastSync || row.lastSyncAt || "—",
    lastSyncAt: row.lastSyncAt || null,
    recordsSynced: Number(row.recordsSynced) || 0,
    description: row.description || "",
    authType: row.authType || "OAuth2",
    direction: row.direction || "bidirectional",
    errorRatePct: Number(row.errorRatePct) || 0,
    avgLatencyMs: Number(row.avgLatencyMs) || 0,
    icon: row.icon || "fe fe-link",
    tone: row.tone || "blue",
    legacyKey: row.legacyKey || null,
    healthSource: row.healthSource || null,
    lastError: row.lastError || null,
    credentialsReady: row.credentialsReady === true,
  };
}

export function normalizeSyncJob(job) {
  if (!job) {
    return null;
  }
  return {
    id: job.id,
    connectorId: job.connectorId,
    connectorName: job.connectorName || "",
    jobType: job.jobType || "incremental",
    status: job.status || INTEGRATION_SYNC_JOB_STATUSES.COMPLETED,
    startedAt: job.startedAt,
    completedAt: job.completedAt || null,
    recordsProcessed: Number(job.recordsProcessed) || 0,
    errorCount: Number(job.errorCount) || 0,
    retryCount: Number(job.retryCount) || 0,
  };
}

export function normalizeFieldMapping(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    connectorId: row.connectorId,
    connectorName: row.connectorName || "",
    sourceObject: row.sourceObject || "",
    targetObject: row.targetObject || "",
    fieldCount: Number(row.fieldCount) || 0,
    coveragePct: Number(row.coveragePct) || 0,
    lastValidatedAt: row.lastValidatedAt || null,
    status: row.status || "active",
  };
}

export function normalizeIntegrationLog(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    connectorId: row.connectorId,
    connectorName: row.connectorName || "",
    level: row.level || INTEGRATION_LOG_LEVELS.INFO,
    message: row.message || "",
    createdAt: row.createdAt,
    correlationId: row.correlationId || "",
  };
}

export function buildIntegrationHealthSummary(connectors) {
  const rows = (connectors || []).map(normalizeConnector).filter(Boolean);
  const healthy = rows.filter((c) => c.status === INTEGRATION_CONNECTOR_STATUSES.HEALTHY).length;
  const degraded = rows.filter((c) => c.status === INTEGRATION_CONNECTOR_STATUSES.DEGRADED).length;
  const failed = rows.filter((c) => c.status === INTEGRATION_CONNECTOR_STATUSES.FAILED).length;
  const avgTrustScore = rows.length
    ? Math.round(rows.reduce((sum, c) => sum + c.trustScore, 0) / rows.length)
    : 0;
  const avgLatencyMs = rows.length
    ? Math.round(rows.reduce((sum, c) => sum + c.avgLatencyMs, 0) / rows.length)
    : 0;

  return {
    total: rows.length,
    healthy,
    degraded,
    failed,
    avgTrustScore,
    avgLatencyMs,
    recordsSynced: rows.reduce((sum, c) => sum + c.recordsSynced, 0),
  };
}

export function buildIntegrationHubKpis(summary) {
  const s = summary || {};
  return [
    { id: "total", label: "Connectors", value: s.total != null ? s.total : 0, icon: "fe fe-link", tone: "blue" },
    { id: "healthy", label: "Healthy", value: s.healthy != null ? s.healthy : 0, icon: "fe fe-check-circle", tone: "green" },
    { id: "degraded", label: "Degraded", value: s.degraded != null ? s.degraded : 0, icon: "fe fe-alert-triangle", tone: "amber" },
    { id: "trust", label: "Avg trust", value: `${s.avgTrustScore != null ? s.avgTrustScore : 0}%`, icon: "fe fe-shield", tone: "violet" },
  ];
}

export function buildJobsKpis(jobs) {
  const rows = jobs || [];
  const failed = rows.filter((job) => job.status === INTEGRATION_SYNC_JOB_STATUSES.FAILED).length;
  const running = rows.filter((job) => job.status === INTEGRATION_SYNC_JOB_STATUSES.RUNNING).length;
  const records = rows.reduce((sum, job) => sum + (Number(job.recordsProcessed) || 0), 0);
  return [
    { id: "jobs", label: "Sync jobs", value: rows.length, icon: "fe fe-repeat", tone: "amber" },
    { id: "running", label: "Running", value: running, icon: "fe fe-loader", tone: "blue" },
    { id: "failed", label: "Failed", value: failed, icon: "fe fe-x-circle", tone: "rose" },
    { id: "records", label: "Records", value: records, icon: "fe fe-database", tone: "green" },
  ];
}

export function buildMappingKpis(mappings) {
  const rows = (mappings || []).map(normalizeFieldMapping).filter(Boolean);
  const avgCoverage = rows.length
    ? Math.round(rows.reduce((sum, row) => sum + row.coveragePct, 0) / rows.length)
    : 0;
  const fields = rows.reduce((sum, row) => sum + row.fieldCount, 0);
  return [
    { id: "maps", label: "Field maps", value: rows.length, icon: "fe fe-shuffle", tone: "indigo" },
    { id: "coverage", label: "Avg coverage", value: `${avgCoverage}%`, icon: "fe fe-percent", tone: "violet" },
    { id: "connectors", label: "Connectors", value: new Set(rows.map((row) => row.connectorId)).size, icon: "fe fe-link", tone: "blue" },
    { id: "fields", label: "Mapped fields", value: fields, icon: "fe fe-layers", tone: "green" },
  ];
}

export function buildLogsKpis(logs) {
  const rows = logs || [];
  const errors = rows.filter((row) => row.level === INTEGRATION_LOG_LEVELS.ERROR).length;
  const warnings = rows.filter((row) => row.level === INTEGRATION_LOG_LEVELS.WARN).length;
  const info = rows.filter((row) => row.level === INTEGRATION_LOG_LEVELS.INFO).length;
  return [
    { id: "events", label: "Events", value: rows.length, icon: "fe fe-file-text", tone: "blue" },
    { id: "info", label: "Info", value: info, icon: "fe fe-info", tone: "green" },
    { id: "warn", label: "Warnings", value: warnings, icon: "fe fe-alert-triangle", tone: "amber" },
    { id: "error", label: "Errors", value: errors, icon: "fe fe-alert-octagon", tone: "rose" },
  ];
}

export function buildJobInsights(jobs) {
  const failed = (jobs || []).filter((job) => job.status === INTEGRATION_SYNC_JOB_STATUSES.FAILED);
  if (!failed.length) {
    return [];
  }
  return [
    {
      id: "failed-jobs",
      title: "Retry recommended",
      copy: `${failed.length} job(s) failed — use retry controls or inspect integration logs for correlation IDs.`,
      tone: "danger",
    },
  ];
}

export function buildMappingInsights(mappings) {
  const rows = (mappings || []).map(normalizeFieldMapping).filter(Boolean);
  const lowCoverage = rows.filter((row) => row.coveragePct < 85);
  if (!lowCoverage.length) {
    return [];
  }
  return [
    {
      id: "low-coverage",
      title: "Mapping coverage gaps",
      copy: `${lowCoverage.length} map(s) are below 85% coverage — validate canonical objects before the next sync window.`,
      tone: "warning",
    },
  ];
}

export function buildSyncHealthInsights(summary, jobs) {
  const insights = [];
  if ((summary && summary.degraded) > 0) {
    insights.push({
      id: "degraded",
      title: "Degraded connectors",
      copy: `${summary.degraded} connector(s) need attention — review sync monitor and retry failed jobs.`,
      tone: "warning",
    });
  }
  const failedJobs = (jobs || []).filter((j) => j.status === INTEGRATION_SYNC_JOB_STATUSES.FAILED);
  if (failedJobs.length) {
    insights.push({
      id: "failed-jobs",
      title: "Failed sync jobs",
      copy: `${failedJobs.length} job(s) failed in the last window. Inspect integration logs for correlation IDs.`,
      tone: "danger",
    });
  }
  return insights;
}

export function filterConnectors(connectors, { status, query } = {}) {
  return (connectors || [])
    .map(normalizeConnector)
    .filter(Boolean)
    .filter((row) => !status || row.status === status)
    .filter((row) => {
      if (!query) {
        return true;
      }
      const q = String(query).toLowerCase();
      return (
        String(row.name).toLowerCase().includes(q) ||
        String(row.type).toLowerCase().includes(q)
      );
    });
}

export function exportConnectorsCsv(connectors) {
  const rows = (connectors || []).map(normalizeConnector).filter(Boolean);
  const header = "id,name,type,status,trustScore,recordsSynced,lastSync";
  const body = rows
    .map((row) =>
      [row.id, row.name, row.type, row.statusLabel, row.trustScore, row.recordsSynced, row.lastSync]
        .map((cell) => `"${String(cell || "").replace(/"/g, '""')}"`)
        .join(",")
    )
    .join("\n");
  return `${header}\n${body}`;
}
