import React from "react";
import { Link } from "react-router-dom";

export default function TicketAiPanel({ suggestion, loading }) {
  if (loading) {
    return <div className="lux-ticket-ai lux-ticket-ai--loading" aria-busy="true" />;
  }
  if (!suggestion) {
    return null;
  }
  return (
    <section className="lux-ticket-ai">
      <header>
        <i className="fe fe-zap" aria-hidden="true" />
        <span>AI classification</span>
      </header>
      <p className="lux-ticket-ai__hint">{suggestion.resolutionHint}</p>
      {suggestion.similarTickets && suggestion.similarTickets.length ? (
        <p className="lux-ticket-ai__similar">
          Similar: {suggestion.similarTickets.join(", ")}
        </p>
      ) : null}
      {suggestion.rcaLink ? (
        <Link to={suggestion.rcaLink} className="lux-ticket-ai__link">
          View related RCA
        </Link>
      ) : null}
    </section>
  );
}
