import {
  MILESTONE_STATUSES,
  RISK_SEVERITIES,
  RISK_STATUSES,
  ISSUE_STATUSES,
  GATE_STATUSES,
} from "config/project-governance.config";
import {
  buildMilestoneMetrics,
  buildRiskMetrics,
  buildIssueMetrics,
  buildGateMetrics,
  buildRiskHeatmap,
} from "config/project-governance.utils";
import {
  PROJECT_HEALTH_BANDS,
  PROGRAM_STATUSES,
  normalizeExecutiveMetric,
  normalizeProjectHealthSnapshot,
} from "config/portfolio-control-tower.config";

const OPEN_RISK_STATUSES = new Set([RISK_STATUSES.OPEN, RISK_STATUSES.MITIGATING, RISK_STATUSES.ESCALATED]);
const OPEN_ISSUE_STATUSES = new Set([ISSUE_STATUSES.OPEN, ISSUE_STATUSES.IN_PROGRESS]);

const RISK_SEVERITY_WEIGHT = {
  CRITICAL: 4,
  HIGH: 3,
  MEDIUM: 2,
  LOW: 1,
};

export function collectPortfolioProjectIds(portfolio, programs = []) {
  const programMap = new Map(programs.map((row) => [row.id, row]));
  const ids = new Set();
  (portfolio.programIds || []).forEach((programId) => {
    const program = programMap.get(programId);
    if (program && program.projectIds) {
      program.projectIds.forEach((projectId) => ids.add(projectId));
    }
  });
  return Array.from(ids);
}

export function filterRowsByProject(rows = [], projectId) {
  if (!projectId) {
    return rows;
  }
  return rows.filter((row) => row.projectId === projectId);
}

function computeMilestoneSlippageDays(milestones = []) {
  const today = new Date().toISOString().slice(0, 10);
  let total = 0;
  let count = 0;
  milestones.forEach((row) => {
    if (!row.plannedEnd || row.status === MILESTONE_STATUSES.COMPLETE) {
      return;
    }
    if (row.plannedEnd < today || row.status === MILESTONE_STATUSES.AT_RISK || row.status === MILESTONE_STATUSES.BLOCKED) {
      const planned = new Date(`${row.plannedEnd}T00:00:00`);
      const ref = new Date(`${today}T00:00:00`);
      const days = Math.max(0, Math.round((ref - planned) / (1000 * 60 * 60 * 24)));
      if (days > 0) {
        total += days;
        count += 1;
      }
    }
  });
  return count ? Math.round(total / count) : 0;
}

function resolveHealthBand(score) {
  if (score >= 80) {
    return PROJECT_HEALTH_BANDS.HEALTHY;
  }
  if (score >= 60) {
    return PROJECT_HEALTH_BANDS.WATCH;
  }
  return PROJECT_HEALTH_BANDS.CRITICAL;
}

function safeHealthFactor(value, fallback = 100) {
  const num = Number(value);
  return Number.isFinite(num) ? num : fallback;
}

function computeProjectHealthScore({ milestoneMetrics, riskMetrics, issueMetrics, gateMetrics, criticalRisks = 0 }) {
  const factors = [
    safeHealthFactor(milestoneMetrics.completionRate, 0),
    safeHealthFactor(milestoneMetrics.atRisk > 0 ? Math.max(0, 100 - milestoneMetrics.atRisk * 12) : 100),
    safeHealthFactor(
      riskMetrics.open > 0 ? Math.max(0, 100 - riskMetrics.open * 10 - criticalRisks * 8) : 100
    ),
    safeHealthFactor(issueMetrics.actionSlaRate),
    safeHealthFactor(gateMetrics.complianceRate, gateMetrics.total > 0 ? 0 : 100),
  ];
  const score = Math.round(factors.reduce((sum, value) => sum + value, 0) / factors.length);
  return Math.max(0, Math.min(100, score));
}

export function buildProjectHealthSnapshot(projectMeta, context = {}) {
  const {
    milestones = [],
    risks = [],
    issues = [],
    gates = [],
    program = null,
    portfolio = null,
    resourceUtilization = null,
    marginPct = null,
    forecastVariancePct = null,
  } = context;

  const projectId = projectMeta.projectId || projectMeta.id;
  const scopedMilestones = filterRowsByProject(milestones, projectId);
  const scopedRisks = filterRowsByProject(risks, projectId);
  const scopedIssues = filterRowsByProject(issues, projectId);
  const scopedGates = filterRowsByProject(gates, projectId);

  const scopedDependencies = filterRowsByProject(context.dependencies || [], projectId);
  const scopedIssueIds = new Set(scopedIssues.map((row) => row.id));
  const scopedActions = (context.actions || []).filter((row) => scopedIssueIds.has(row.issueId));
  const milestoneMetrics = buildMilestoneMetrics(scopedMilestones, scopedDependencies, { projectId });
  const riskMetrics = buildRiskMetrics(scopedRisks);
  const issueMetrics = buildIssueMetrics(scopedIssues, scopedActions);
  const gateMetrics = buildGateMetrics(scopedGates);
  const criticalRisks = scopedRisks.filter(
    (row) => row.severity === RISK_SEVERITIES.CRITICAL && OPEN_RISK_STATUSES.has(row.status)
  ).length;
  const healthScore = computeProjectHealthScore({
    milestoneMetrics,
    riskMetrics,
    issueMetrics,
    gateMetrics,
    criticalRisks,
  });

  return normalizeProjectHealthSnapshot({
    projectId,
    projectCode: projectMeta.projectCode || projectMeta.code || "",
    projectName: projectMeta.projectName || projectMeta.name || "Project",
    programId: program ? program.id : null,
    programName: program ? program.name : "",
    portfolioId: portfolio ? portfolio.id : null,
    healthScore,
    healthBand: resolveHealthBand(healthScore),
    milestoneSlippageDays: computeMilestoneSlippageDays(scopedMilestones),
    openRisks: scopedRisks.filter((row) => OPEN_RISK_STATUSES.has(row.status)).length,
    criticalRisks: scopedRisks.filter((row) => row.severity === RISK_SEVERITIES.CRITICAL).length,
    openIssues: scopedIssues.filter((row) => OPEN_ISSUE_STATUSES.has(row.status)).length,
    gateComplianceRate: gateMetrics.complianceRate,
    resourceUtilization,
    marginPct,
    forecastVariancePct,
    updatedAt: new Date().toISOString().slice(0, 10),
  });
}

export function buildProgramRollup(program, context = {}) {
  const { portfolios = [], projectCatalog = [] } = context;
  const portfolio = portfolios.find((row) => row.id === program.portfolioId) || null;
  const catalogMap = new Map(projectCatalog.map((row) => [row.projectId || row.id, row]));

  const snapshots = (program.projectIds || []).map((projectId) => {
    const meta = catalogMap.get(projectId) || { projectId, projectName: projectId };
    return buildProjectHealthSnapshot(meta, {
      ...context,
      program,
      portfolio,
    });
  });

  const healthScore = snapshots.length
    ? Math.round(snapshots.reduce((sum, row) => sum + row.healthScore, 0) / snapshots.length)
    : program.healthScore || 0;

  let status = program.status || PROGRAM_STATUSES.ON_TRACK;
  if (healthScore < 60) {
    status = PROGRAM_STATUSES.OFF_TRACK;
  } else if (healthScore < 80 || snapshots.some((row) => row.criticalRisks > 0)) {
    status = PROGRAM_STATUSES.AT_RISK;
  }

  return {
    ...program,
    healthScore,
    status,
    projectCount: snapshots.length,
    openRisks: snapshots.reduce((sum, row) => sum + row.openRisks, 0),
    openIssues: snapshots.reduce((sum, row) => sum + row.openIssues, 0),
    avgSlippageDays: snapshots.length
      ? Math.round(snapshots.reduce((sum, row) => sum + row.milestoneSlippageDays, 0) / snapshots.length)
      : 0,
    projectHealth: snapshots,
  };
}

export function buildPortfolioRollup(portfolio, context = {}) {
  const { programs = [] } = context;
  const linkedPrograms = programs.filter((row) => (portfolio.programIds || []).includes(row.id));
  const programRollups = linkedPrograms.map((program) => buildProgramRollup(program, context));
  const snapshots = programRollups.flatMap((row) => row.projectHealth || []);

  const healthScore = snapshots.length
    ? Math.round(snapshots.reduce((sum, row) => sum + row.healthScore, 0) / snapshots.length)
    : portfolio.healthScore || 0;

  return {
    ...portfolio,
    healthScore,
    programCount: programRollups.length,
    projectCount: snapshots.length,
    openRisks: snapshots.reduce((sum, row) => sum + row.openRisks, 0),
    openIssues: snapshots.reduce((sum, row) => sum + row.openIssues, 0),
    criticalProjects: snapshots.filter((row) => row.healthBand === PROJECT_HEALTH_BANDS.CRITICAL).length,
    avgSlippageDays: snapshots.length
      ? Math.round(snapshots.reduce((sum, row) => sum + row.milestoneSlippageDays, 0) / snapshots.length)
      : 0,
    programs: programRollups,
    projectHealth: snapshots,
  };
}

export function buildExecutiveMetrics(context = {}) {
  const { portfolios = [], programs = [], projectHealth = [] } = context;
  const healthy = projectHealth.filter((row) => row.healthBand === PROJECT_HEALTH_BANDS.HEALTHY).length;
  const critical = projectHealth.filter((row) => row.healthBand === PROJECT_HEALTH_BANDS.CRITICAL).length;
  const avgHealth = projectHealth.length
    ? Math.round(projectHealth.reduce((sum, row) => sum + row.healthScore, 0) / projectHealth.length)
    : 0;
  const avgSlippage = projectHealth.length
    ? Math.round(projectHealth.reduce((sum, row) => sum + row.milestoneSlippageDays, 0) / projectHealth.length)
    : 0;
  const openRisks = projectHealth.reduce((sum, row) => sum + row.openRisks, 0);
  const openIssues = projectHealth.reduce((sum, row) => sum + row.openIssues, 0);
  const atRiskPrograms = programs.filter((row) => row.status === PROGRAM_STATUSES.AT_RISK || row.status === PROGRAM_STATUSES.OFF_TRACK)
    .length;

  return [
    normalizeExecutiveMetric({
      id: "portfolios",
      label: "Active portfolios",
      value: portfolios.filter((row) => row.status !== "CLOSED").length,
      tone: "indigo",
      hint: `${programs.length} programs in flight`,
    }),
    normalizeExecutiveMetric({
      id: "health",
      label: "Portfolio health",
      value: avgHealth,
      unit: "%",
      tone: avgHealth >= 80 ? "green" : avgHealth >= 60 ? "amber" : "rose",
      hint: `${healthy} healthy · ${critical} critical`,
    }),
    normalizeExecutiveMetric({
      id: "slippage",
      label: "Avg slippage",
      value: avgSlippage,
      unit: "d",
      tone: avgSlippage > 5 ? "amber" : "blue",
      hint: "Milestone schedule variance",
    }),
    normalizeExecutiveMetric({
      id: "risks",
      label: "Open risks",
      value: openRisks,
      tone: openRisks > 6 ? "rose" : "amber",
      hint: "Across governed projects",
    }),
    normalizeExecutiveMetric({
      id: "issues",
      label: "Open issues",
      value: openIssues,
      tone: openIssues > 4 ? "rose" : "violet",
      hint: "Blockers and actions",
    }),
    normalizeExecutiveMetric({
      id: "programs",
      label: "Programs at risk",
      value: atRiskPrograms,
      tone: atRiskPrograms > 0 ? "amber" : "green",
      hint: "Needs steering attention",
    }),
  ].filter(Boolean);
}

export function buildPortfolioInsights(rollup) {
  if (!rollup) {
    return [];
  }
  const insights = [];
  if (rollup.criticalProjects > 0) {
    insights.push({
      id: "critical-projects",
      tone: "rose",
      title: `${rollup.criticalProjects} project${rollup.criticalProjects === 1 ? "" : "s"} in critical health`,
      body: "Review milestone slippage, escalated risks, and gate readiness before the next steering meeting.",
      path: "/project/governance",
    });
  }
  if (rollup.avgSlippageDays >= 5) {
    insights.push({
      id: "slippage",
      tone: "amber",
      title: `Average milestone slippage is ${rollup.avgSlippageDays} days`,
      body: "Prioritize critical-path recovery on programs with AT_RISK milestones.",
      path: "/project/timeline",
    });
  }
  if (rollup.openRisks > 0) {
    insights.push({
      id: "risks",
      tone: "violet",
      title: `${rollup.openRisks} open delivery risks across the portfolio`,
      body: "Validate mitigation owners and escalation paths in the risk register.",
      path: "/project/risks",
    });
  }
  if (!insights.length) {
    insights.push({
      id: "stable",
      tone: "green",
      title: "Portfolio health is stable",
      body: "No critical slippage or risk spikes detected in the current governance snapshot.",
      path: "/project/governance",
    });
  }
  return insights;
}

