export function validatePortfolioPayload(payload = {}) {
  if (!payload.name || !String(payload.name).trim()) {
    throw new Error("Portfolio name is required");
  }
  return true;
}

export function validateProgramPayload(payload = {}) {
  if (!payload.name || !String(payload.name).trim()) {
    throw new Error("Program name is required");
  }
  if (!payload.portfolioId) {
    throw new Error("Program portfolioId is required");
  }
  return true;
}

export function validateScenarioPayload(payload = {}) {
  if (!payload.name || !String(payload.name).trim()) {
    throw new Error("Scenario name is required");
  }
  if (!payload.portfolioId) {
    throw new Error("Scenario portfolioId is required");
  }
  return true;
}

/** F16-T3 — Program hierarchy tree */
export function buildProgramHierarchyTree(portfolio, context = {}) {
  const { programs = [], initiatives = [], projectCatalog = [] } = context;
  const catalogMap = new Map(projectCatalog.map((row) => [row.projectId || row.id, row]));
  const linkedPrograms = programs.filter((row) => (portfolio.programIds || []).includes(row.id));

  return {
    portfolio,
    programs: linkedPrograms.map((program) => {
      const programRollup = buildProgramRollup(program, context);
      const programInitiatives = initiatives.filter((row) => row.programId === program.id);
      return {
        ...programRollup,
        initiatives: programInitiatives,
        projects: (program.projectIds || []).map((projectId) => {
          const meta = catalogMap.get(projectId) || { projectId };
          const health = (programRollup.projectHealth || []).find((row) => row.projectId === projectId);
          return {
            projectId,
            projectCode: meta.projectCode || "",
            projectName: meta.projectName || projectId,
            healthScore: health ? health.healthScore : null,
            healthBand: health ? health.healthBand : null,
          };
        }),
      };
    }),
  };
}

/** F16-T3 — Roadmap lanes from milestones and gate stages */
export function buildProgramRoadmapModel(context = {}) {
  const { programs = [], milestones = [], gates = [] } = context;
  const phases = ["Initiate", "Plan", "Deliver", "Close", "Scale"];

  return programs.map((program) => {
    const projectIds = new Set(program.projectIds || []);
    const programMilestones = milestones.filter((row) => projectIds.has(row.projectId));
    const programGates = gates.filter((row) => projectIds.has(row.projectId));
    const lanes = phases.map((phase) => {
      const milestoneItems = programMilestones
        .filter((row) => phase === program.roadmapPhase || phase === "Deliver")
        .slice(0, 2)
        .map((row) => ({
          id: row.id,
          type: "milestone",
          label: row.name,
          date: row.plannedEnd || row.plannedStart,
          status: row.status,
          projectName: row.projectName,
        }));
      const gateItems = programGates
        .filter((row) => row.stage === phase)
        .map((row) => ({
          id: row.id,
          type: "gate",
          label: row.name,
          date: row.dueDate,
          status: row.status,
          projectName: row.projectName,
        }));
      return { phase, items: [...gateItems, ...milestoneItems] };
    });

    return {
      programId: program.id,
      programName: program.name,
      roadmapPhase: program.roadmapPhase,
      lanes,
    };
  });
}

/** F16-T4 — Cross-project risk, resource, and finance rollups */
export function buildCrossProjectRollups(context = {}) {
  const {
    risks = [],
    projectHealth = [],
    projectCatalog = [],
  } = context;

  const catalogMap = new Map(projectCatalog.map((row) => [row.projectId, row]));
  const riskHeatmap = buildRiskHeatmap(risks);
  const topRisks = risks
    .filter((row) => row.status !== RISK_STATUSES.CLOSED)
    .sort((a, b) => (RISK_SEVERITY_WEIGHT[b.severity] || 0) - (RISK_SEVERITY_WEIGHT[a.severity] || 0))
    .slice(0, 6);

  const resourceRows = projectHealth.map((row) => {
    const meta = catalogMap.get(row.projectId) || {};
    return {
      projectId: row.projectId,
      projectName: row.projectName,
      utilization: meta.resourceUtilization != null ? meta.resourceUtilization : row.resourceUtilization,
      programName: row.programName,
    };
  });
  const avgUtilization = resourceRows.length
    ? Math.round(resourceRows.reduce((sum, row) => sum + (row.utilization || 0), 0) / resourceRows.length)
    : 0;

  const financeRows = projectHealth.map((row) => {
    const meta = catalogMap.get(row.projectId) || {};
    return {
      projectId: row.projectId,
      projectName: row.projectName,
      marginPct: meta.marginPct != null ? meta.marginPct : row.marginPct,
      forecastVariancePct: meta.forecastVariancePct != null ? meta.forecastVariancePct : row.forecastVariancePct,
      programName: row.programName,
    };
  });
  const avgMargin = financeRows.length
    ? Math.round(financeRows.reduce((sum, row) => sum + (row.marginPct || 0), 0) / financeRows.length)
    : 0;

  return {
    risk: { heatmap: riskHeatmap, topRisks, openCount: risks.filter((r) => r.status !== RISK_STATUSES.CLOSED).length },
    resource: { rows: resourceRows, avgUtilization },
    finance: { rows: financeRows, avgMargin },
  };
}

/** F16-T5 — Compare baseline portfolio vs saved scenario */
export function buildScenarioComparison(baselineRollup, scenario) {
  if (!baselineRollup || !scenario) {
    return null;
  }
  return {
    baselineHealth: baselineRollup.healthScore,
    scenarioHealth: scenario.scenarioHealth != null ? scenario.scenarioHealth : baselineRollup.healthScore + (scenario.slippageDeltaDays || 0) * -2,
    healthDelta: (scenario.scenarioHealth != null ? scenario.scenarioHealth : baselineRollup.healthScore) - baselineRollup.healthScore,
    slippageDeltaDays: scenario.slippageDeltaDays || 0,
    riskDelta: scenario.riskDelta || 0,
    marginDeltaPct: scenario.marginDeltaPct || 0,
    assumptions: scenario.assumptions || [],
  };
}

/** F16-T6 — Executive briefing narrative */
export function buildExecutiveBriefing(rollup, crossRollups = {}, executiveMetrics = []) {
  if (!rollup) {
    return null;
  }
  const metricsMap = new Map(executiveMetrics.map((row) => [row.id, row]));
  const healthMetric = metricsMap.get("health");
  const paragraphs = [
    `Portfolio "${rollup.name || "Enterprise"}" is operating at ${rollup.healthScore}% composite health across ${rollup.programCount} programs and ${rollup.projectCount} governed projects.`,
    rollup.criticalProjects > 0
      ? `${rollup.criticalProjects} project(s) are in critical health and require steering intervention this week.`
      : "No projects are currently in critical health band.",
    rollup.avgSlippageDays > 0
      ? `Average milestone slippage is ${rollup.avgSlippageDays} days; prioritize critical-path recovery on AT_RISK programs.`
      : "Schedule slippage is within acceptable tolerance across active programs.",
    crossRollups.resource
      ? `Resource utilization averages ${crossRollups.resource.avgUtilization}% with ${crossRollups.risk.openCount} open delivery risks tracked portfolio-wide.`
      : `${rollup.openRisks} open risks and ${rollup.openIssues} open issues remain on the portfolio register.`,
    crossRollups.finance
      ? `Blended project margin is ${crossRollups.finance.avgMargin}% with finance forecast variance monitored per project.`
      : "Finance roll-ups will populate when project financials are linked.",
  ];

  const actions = [];
  if (rollup.criticalProjects > 0) {
    actions.push({ id: "critical", label: "Review critical projects", path: "/project/governance", tone: "rose" });
  }
  if (rollup.openRisks > 3) {
    actions.push({ id: "risks", label: "Open risk register", path: "/project/risks", tone: "amber" });
  }
  if ((healthMetric && Number(healthMetric.value) < 75) || rollup.healthScore < 75) {
    actions.push({ id: "timeline", label: "Inspect delivery timeline", path: "/project/timeline", tone: "blue" });
  }
  actions.push({ id: "scenarios", label: "Run portfolio scenarios", path: "/project/portfolio/scenarios", tone: "violet" });

  return {
    generatedAt: new Date().toISOString().slice(0, 10),
    healthScore: rollup.healthScore,
    summary: paragraphs.join(" "),
    paragraphs,
    recommendedActions: actions.slice(0, 4),
    kpis: executiveMetrics,
  };
}

export function exportExecutiveBriefingCsv(briefing) {
  if (!briefing) {
    return "";
  }
  const lines = [
    "section,content",
    `generatedAt,${briefing.generatedAt}`,
    `healthScore,${briefing.healthScore}`,
    `summary,"${String(briefing.summary).replace(/"/g, '""')}"`,
  ];
  (briefing.paragraphs || []).forEach((row, index) => {
    lines.push(`paragraph_${index + 1},"${String(row).replace(/"/g, '""')}"`);
  });
  (briefing.recommendedActions || []).forEach((row) => {
    lines.push(`action,${row.label},${row.path}`);
  });
  return lines.join("\n");
}

/** F16-T7 — Portfolio analytics dashboard */
export function buildPortfolioAnalyticsDashboard(rollup, context = {}) {
  if (!rollup) {
    return null;
  }
  const crossRollups = buildCrossProjectRollups({
    ...context,
    projectHealth: rollup.projectHealth || [],
  });

  const healthRows = (rollup.projectHealth || []).map((row) => ({
    id: row.projectId,
    label: row.projectName,
    value: row.healthScore,
    band: row.healthBand,
  }));
  const maxHealth = 100;
  const slippageRows = (rollup.projectHealth || []).map((row) => ({
    id: row.projectId,
    label: row.projectName,
    days: row.milestoneSlippageDays,
  }));
  const maxSlippage = Math.max(1, ...slippageRows.map((row) => row.days), 1);

  return {
    healthScore: rollup.healthScore,
    healthRows,
    maxHealth,
    slippageRows,
    maxSlippage,
    avgSlippage: rollup.avgSlippageDays,
    riskHeatmap: crossRollups.risk.heatmap,
    resourceRows: crossRollups.resource.rows,
    financeRows: crossRollups.finance.rows,
    programHealth: (rollup.programs || []).map((row) => ({
      id: row.id,
      label: row.name,
      healthScore: row.healthScore,
      status: row.status,
    })),
  };
}

/** F16-T8 — Large portfolio dataset for performance tests */
export function generateLargePortfolioDataset(programCount = 40, projectsPerProgram = 5) {
  const programs = [];
  const projectCatalog = [];
  const milestones = [];
  const risks = [];

  for (let p = 0; p < programCount; p += 1) {
    const programId = `pg-perf-${p}`;
    const projectIds = [];
    for (let j = 0; j < projectsPerProgram; j += 1) {
      const projectId = `proj-perf-${p}-${j}`;
      projectIds.push(projectId);
      projectCatalog.push({
        projectId,
        projectCode: `PRF-${p}-${j}`,
        projectName: `Performance Project ${p}-${j}`,
        resourceUtilization: 60 + ((p + j) % 35),
        marginPct: 15 + ((p * j) % 20),
        forecastVariancePct: ((p - j) % 10) - 5,
      });
      for (let m = 0; m < 4; m += 1) {
        milestones.push({
          id: `ms-perf-${p}-${j}-${m}`,
          projectId,
          projectName: `Performance Project ${p}-${j}`,
          name: `Milestone ${m}`,
          plannedStart: "2026-01-01",
          plannedEnd: "2026-06-30",
          status: m % 3 === 0 ? MILESTONE_STATUSES.COMPLETE : MILESTONE_STATUSES.IN_PROGRESS,
          percentComplete: m * 25,
        });
      }
      if (j % 2 === 0) {
        risks.push({
          id: `risk-perf-${p}-${j}`,
          projectId,
          projectName: `Performance Project ${p}-${j}`,
          title: `Risk ${j}`,
          severity: j % 2 === 0 ? RISK_SEVERITIES.HIGH : RISK_SEVERITIES.MEDIUM,
          status: RISK_STATUSES.OPEN,
        });
      }
    }
    programs.push({
      id: programId,
      portfolioId: "pf-perf",
      name: `Program ${p}`,
      code: `PG-${p}`,
      projectIds,
      roadmapPhase: "Deliver",
      status: PROGRAM_STATUSES.ON_TRACK,
    });
  }

  const portfolio = {
    id: "pf-perf",
    name: "Performance Portfolio",
    programIds: programs.map((row) => row.id),
  };

  return { portfolio, programs, projectCatalog, milestones, risks, dependencies: [], issues: [], actions: [], gates: [] };
}
