import React, { Component } from "react";
import { Link } from "react-router-dom";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isWorkGraphEnabled, WORK_GRAPH_ROUTES } from "config/work-graph.config";
import { ENTERPRISE_SEARCH_PAGE_META } from "config/work-graph-nav.config";
import { workGraphService } from "_services/workGraph.service";
import WorkGraphLuxPage, { WorkGraphActionButton } from "views/workgraph/components/WorkGraphLuxShared";
import GraphSearchResults from "views/workgraph/components/GraphSearchResults";

class EnterpriseSearchPage extends Component {
  state = {
    query: "",
    moduleFilter: "ALL",
    hits: [],
    searching: false,
    searched: false,
    dataSource: null,
  };

  handleSearch = async (event) => {
    if (event) {
      event.preventDefault();
    }
    const { query, moduleFilter } = this.state;
    if (!String(query).trim()) {
      return;
    }
    this.setState({ searching: true, searched: true });
    try {
      const filters = moduleFilter !== "ALL" ? { module: moduleFilter } : {};
      const result = await workGraphService.search(query, filters);
      this.setState({
        searching: false,
        hits: result.payload || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({ searching: false, hits: [] });
    }
  };

  render() {
    if (!isWorkGraphEnabled()) {
      return <PersonaAccessDenied featureLabel="Enterprise search" />;
    }

    const { query, moduleFilter, hits, searching, searched, dataSource } = this.state;

    return (
    <WorkGraphLuxPage
      pageMeta={ENTERPRISE_SEARCH_PAGE_META}
      dataSource={dataSource}
      pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
      shellTitle="Enterprise search"
      heroActions={
        <WorkGraphActionButton to={WORK_GRAPH_ROUTES.WORK_GRAPH} icon="fe fe-git-merge">
          Work graph
        </WorkGraphActionButton>
      }
    >
      <div className="lux-wg-search-shell">
      <form className="lux-wg-search-form" onSubmit={this.handleSearch}>
        <div className="lux-wg-search-form__row">
          <input
            type="search"
            className="form-control lux-wg-search-input"
            placeholder="Search people, projects, tickets, approvals…"
            value={query}
            onChange={(e) => this.setState({ query: e.target.value })}
          />
          <select
            className="form-control lux-wg-search-filter"
            value={moduleFilter}
            onChange={(e) => this.setState({ moduleFilter: e.target.value })}
          >
            <option value="ALL">All modules</option>
            <option value="delivery">Delivery</option>
            <option value="people">People</option>
            <option value="service">Service</option>
            <option value="finance">Finance</option>
            <option value="approvals">Approvals</option>
            <option value="ai">AI</option>
          </select>
          <button type="submit" className="lux-onb-action lux-onb-action--primary lux-wg-action" disabled={searching}>
            <i className="fe fe-search" aria-hidden="true" />
            Search
          </button>
        </div>
        <p className="lux-wg-search-form__hint">
          Classic project search remains at{" "}
          <Link to={WORK_GRAPH_ROUTES.PROJECT_SEARCH}>project search</Link>.
        </p>
      </form>
      </div>
      <GraphSearchResults hits={hits} loading={searching} query={searched ? query : ""} />
    </WorkGraphLuxPage>
    );
  }
}

export default EnterpriseSearchPage;
