import React from "react";
import classNames from "classnames/bind";

export function PlannerLuxActionButton({ icon, label, sublabel, onClick, variant, disabled }) {
  return (
    <button
      type="button"
      className={classNames("lux-planner-lux-btn", variant && `lux-planner-lux-btn--${variant}`)}
      onClick={onClick}
      disabled={disabled}
    >
      <span className="lux-planner-lux-btn__icon">
        <i className={`fe ${icon}`} aria-hidden />
      </span>
      <span className="lux-planner-lux-btn__text">
        <strong>{label}</strong>
        {sublabel && <small>{sublabel}</small>}
      </span>
      <i className="fe fe-chevron-right lux-planner-lux-btn__chev" aria-hidden />
    </button>
  );
}

export default function PlannerLuxActions({ actions }) {
  if (!actions || actions.length === 0) return null;
  return (
    <div className="lux-planner-lux-actions">
      {actions.map((action) => (
        <PlannerLuxActionButton key={action.key || action.label} {...action} />
      ))}
    </div>
  );
}
