import React, { Component } from "react";
import { Route, Switch, Redirect } from "react-router-dom";
import { NotificationContainer } from 'react-notifications';
import { connect } from "react-redux";
import 'react-notifications/lib/notifications.css'
import routes from "routes.js";
import PageHeader from "views/common/PageHeader";
import PageFooter from "views/common/PageFooter";
import VersionHistoryPage from "views/workspace/VersionHistoryPage";
import { VERSION_HISTORY_ROUTE_PATH } from "config/version-history.routes";
import PageLeftMenubar from "views/common/PageLeftMenubar";
import PageLeftMenu from "views/common/PageLeftMenu";
import ThemeDiv from "views/common/ThemeDiv";
import UserDiv from "views/common/UserDiv";
import Notification from "../views/common/fragments/Notification";
import LuxuryAssistDock from "views/common/LuxuryAssistDock";
import { accessUtils } from "_helpers";
import { notificationActions } from "_actions";
import { initLuxTheme } from "_helpers/theme.utils";
import { initUiSettings } from "_helpers/settings.utils";
import { loadGuidedNavigationConfig } from "_helpers/guidedTour.config";
import SettingsRightSidebar from "views/common/SettingsRightSidebar";
import TodayActivitySidebar from "views/common/TodayActivitySidebar";
import NotesPendingOverlay from "views/common/NotesPendingOverlay";
import ProjectDetailsReturnTracker from "views/common/ProjectDetailsReturnTracker";
import DeliverableDetailsReturnTracker from "views/common/DeliverableDetailsReturnTracker";
import ProfileDetailsReturnTracker from "views/common/ProfileDetailsReturnTracker";
import ConnectionErrorPage from "views/common/ConnectionErrorPage";
import PersonaGuardedRoute from "components/persona/PersonaGuardedRoute";
import { isRouteFlagEnabledForModule } from "config/route-flag.utils";
import { PageChromeProvider, usePageChrome } from "views/common/PageChromeContext";
import { NAVIGATION_MENU_CHANGED } from "_services/navigation.service";
import { TRACOPUS_PILOT_CONFIG_CHANGED } from "config/tracopus-pilot.config";
import { buildNavigationAliasRoutes } from "components/navigation/NavigationRouteAliases";
import { buildNavigationModuleRedirects } from "components/navigation/NavigationModuleRedirects";
import { closeOffcanvasNav } from "_helpers/luxPhone.utils";

function ConnectedPageHeader(props) {
	const { pageDataSource, pageHealthPulse } = usePageChrome();
	return <PageHeader {...props} pageDataSource={pageDataSource} pageHealthPulse={pageHealthPulse} />;
}

class MainLayout extends Component {
	constructor() {
		super()
		this.state = {
			pageHeader: '',
			permission: accessUtils.getMenuAccessControl()
		};
	}

	componentDidMount() {
		initLuxTheme();
		initUiSettings();
		document.body.classList.add('lux-shell');
		loadGuidedNavigationConfig();
		this.syncConnectionErrorBodyClass(this.props.notification.connectionError);
		this.handleNavigationMenuChanged = (event) => {
			const nextPermission = event && event.detail && event.detail.menuAccessControl;
			if (nextPermission) {
				this.setState({ permission: nextPermission });
			}
		};
		window.addEventListener(NAVIGATION_MENU_CHANGED, this.handleNavigationMenuChanged);
		this.handlePilotConfigChanged = () => {
			this.setState({ permission: accessUtils.getMenuAccessControl() });
		};
		window.addEventListener(TRACOPUS_PILOT_CONFIG_CHANGED, this.handlePilotConfigChanged);
		this.handleOffcanvasKeydown = (event) => {
			if (event.key === "Escape") {
				closeOffcanvasNav();
			}
		};
		window.addEventListener("keydown", this.handleOffcanvasKeydown);
	}

	componentDidUpdate(prevProps) {
		if (prevProps.notification.connectionError !== this.props.notification.connectionError) {
			this.syncConnectionErrorBodyClass(this.props.notification.connectionError);
		}
	}

	componentWillUnmount() {
		document.body.classList.remove('lux-connection-error-open');
		closeOffcanvasNav();
		if (this.handleNavigationMenuChanged) {
			window.removeEventListener(NAVIGATION_MENU_CHANGED, this.handleNavigationMenuChanged);
		}
		if (this.handlePilotConfigChanged) {
			window.removeEventListener(TRACOPUS_PILOT_CONFIG_CHANGED, this.handlePilotConfigChanged);
		}
		if (this.handleOffcanvasKeydown) {
			window.removeEventListener("keydown", this.handleOffcanvasKeydown);
		}
	}

	syncConnectionErrorBodyClass = (isOpen) => {
		document.body.classList.toggle('lux-connection-error-open', !!isOpen);
	};

	setPageHeader = pageHeaderName => this.setState({
		pageHeader: pageHeaderName,
	});

	dismissPageAlert = () => {
		this.props.clearNotification();
	};

	handleConnectionRetry = () => {
		this.props.clearNotification();
		window.location.reload();
	};

	/**
	 * Prefer explicit flagModule (e.g. peopleModules for /recruiting/*).
	 * Layout-derived keys like recruitingModules / npdModules do not exist in menuAccess.
	 */
	resolveRouteModuleKey = (prop) => {
		if (prop && prop.flagModule) {
			return prop.flagModule;
		}
		if (prop && prop.layout) {
			return prop.layout.substring(1) + "Modules";
		}
		return null;
	};

	isLayoutModuleActive = (layoutOrProp) => {
		const permission = this.state.permission;
		if (!permission) {
			return false;
		}
		const moduleKey =
			typeof layoutOrProp === "string"
				? layoutOrProp.substring(1) + "Modules"
				: this.resolveRouteModuleKey(layoutOrProp);
		const mod = moduleKey ? permission[moduleKey] : null;
		return mod && mod.active === true;
	};

	isRouteFlagEnabled = (prop) => {
		const moduleKey = this.resolveRouteModuleKey(prop);
		const mod = this.state.permission && moduleKey ? this.state.permission[moduleKey] : null;
		return isRouteFlagEnabledForModule(prop, mod);
	};

	getRoutes = routes => {
		return routes.map((prop, key) => {
			const available =
				prop && prop.alwaysAvailable === true
					? true
					: this.state.permission && this.isLayoutModuleActive(prop) && this.isRouteFlagEnabled(prop);
			if (!available) {
				return null;
			}
			return (
				<Route
					exact path={prop.layout + prop.path}
					render={props => (
						<PersonaGuardedRoute
							component={prop.component}
							routeProp={prop}
							pageHeaderNameChangeHandler={this.setPageHeader}
							{...props}
						/>
					)}
					key={key} />
			);
		});
	};

	renderVersionHistory = (routeProps) => {
		const modulePrefix = routeProps.match && routeProps.match.params
			? routeProps.match.params.modulePrefix
			: "workspace";
		return (
			<PersonaGuardedRoute
				component={VersionHistoryPage}
				routeProp={{
					name: "Version history",
					path: "/version-history",
					layout: `/${modulePrefix}`,
					skipRouteFlag: true,
					alwaysAvailable: true,
				}}
				pageHeaderNameChangeHandler={this.setPageHeader}
				{...routeProps}
			/>
		);
	};

	render() {
		if (this.props.notification.connectionError) {
			return (
				<div id="main_content" className="lux-connection-error-shell">
					<ConnectionErrorPage onRetry={this.handleConnectionRetry} />
				</div>
			);
		}

		return (
		<PageChromeProvider>
		<div id="main_content">
			<ProjectDetailsReturnTracker />
			<DeliverableDetailsReturnTracker />
			<ProfileDetailsReturnTracker />
			{this.props.notification.message &&
				<Notification />
			}
			{this.props.notification.pageMessage && !this.props.notification.connectionError &&
				<div className="lux-page-alert lux-page-alert--danger" role="alert">
					<div className="lux-page-alert__icon" aria-hidden="true">
						<i className="fe fe-alert-triangle" />
					</div>
					<p className="lux-page-alert__message">{this.props.notification.pageMessage}</p>
					<button
						type="button"
						className="lux-page-alert__dismiss"
						onClick={this.dismissPageAlert}
						aria-label="Dismiss alert"
					>
						<i className="fe fe-x" aria-hidden="true" />
					</button>
				</div>
			}
			<PageLeftMenubar {...this.props} routes={routes} />
			<PageLeftMenu {...this.props} routes={routes} menuAccessControl={this.state.permission} />
			<button
				type="button"
				className="lux-nav-scrim"
				data-testid="lux-nav-scrim"
				aria-label="Close navigation menu"
				onClick={() => closeOffcanvasNav()}
			/>
			<SettingsRightSidebar {...this.props} routes={routes} />
			<TodayActivitySidebar {...this.props} routes={routes} />
			<NotesPendingOverlay />
			<ThemeDiv {...this.props} routes={routes} />
			<UserDiv {...this.props} routes={routes} />
			<div className="page justify-content-between flex-column d-flex h-100vh">
				<div className="vleft">
					<ConnectedPageHeader pageName={this.state.pageHeader} showProjectActions={true} />
					<div className="lux-page-canvas" data-tour="lux-register">
					<Switch>
						{buildNavigationAliasRoutes()}
						{buildNavigationModuleRedirects(this.state.permission)}
						<Route
							exact
							path={VERSION_HISTORY_ROUTE_PATH}
							render={this.renderVersionHistory}
						/>
						{this.getRoutes(routes)}
						{this.state.permission.projectModules.active === true &&
							<Redirect exact from="/project" to={"/project/" + this.state.permission.projectModules.defaultRedirectPage} />
						}
						{this.state.permission.peopleModules.active === true &&
							<Redirect exact from="/hrms" to={"/people/" + (this.state.permission.peopleModules.defaultRedirectPage || "dashboard")} />
						}
						{this.state.permission.salesModules.active === true &&
							<Redirect exact from="/sales" to={"/sales/" + this.state.permission.salesModules.defaultRedirectPage} />
						}
						{this.state.permission.workspaceModules && this.state.permission.workspaceModules.active === true &&
							<Redirect exact from="/workspace" to={"/workspace/" + (this.state.permission.workspaceModules.defaultRedirectPage || "home")} />
						}
					</Switch>
					</div>
				</div>
				<div className="vright">
					<PageFooter />
				</div>
			</div>
			<NotificationContainer />
			<LuxuryAssistDock />
		</div>
		</PageChromeProvider>
		);
	}
}

const mapStateToProps = state => ({
	notification: state.notification,
});

const mapDispatchToProps = {
	clearNotification: notificationActions.clear,
};

export default connect(
	mapStateToProps,
	mapDispatchToProps
)(MainLayout);