import { commonUtils } from './common.utils';

export const AUDIT_CONFIG_KEY = 'auditAdditional';
export const AUDIT_ENABLED_KEY = 'auditEnabled';
export const AUDIT_UI_ENABLED_KEY = 'auditUiEnabled';
export const AUDIT_CONFIG_CHANGED = 'famstack-audit-config-changed';

let orgAuditEnabled = false;
let orgAuditUiEnabled = false;
let configLoaded = false;

export function readAuditFlag(configList, flagKey, defaultValue = false) {
  const group = commonUtils.getAppConfigValue(configList, AUDIT_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    return defaultValue;
  }
  if (group[flagKey] === true) {
    return true;
  }
  if (group[flagKey] === false) {
    return false;
  }
  return defaultValue;
}

export function applyAuditConfig(configList) {
  orgAuditEnabled = readAuditFlag(configList, AUDIT_ENABLED_KEY, false);
  orgAuditUiEnabled = readAuditFlag(configList, AUDIT_UI_ENABLED_KEY, true);
  configLoaded = true;
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent(AUDIT_CONFIG_CHANGED));
  }
  return orgAuditUiEnabled;
}

export function isAuditOrgEnabled() {
  return orgAuditEnabled;
}

export function isAuditUiEnabled() {
  if (!configLoaded) return true;
  return orgAuditUiEnabled;
}

export function isAuditConfigLoaded() {
  return configLoaded;
}

export function setAuditConfigFromList(configList) {
  return applyAuditConfig(configList);
}
