import React, { Component } from "react";
import { connect } from "react-redux";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import LuxCreateFieldGroup, { LuxCreateField } from "views/common/create/LuxCreateFieldGroup";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import { commonUtils } from "_helpers";
import { validationUtils } from "_helpers";

class CreateHolidayModel extends Component {
  constructor() {
    super();
    this.state = {
      holidayItemmRequest: {},
      formErrors: {},
      hasFormError: false,
    };
  }

  componentDidMount() {
    document.addEventListener("keydown", this.handleKeyDown);
    if (this.props.show) {
      this.initializeRequest();
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
  }

  componentDidUpdate(prevProps) {
    if (prevProps.show !== this.props.show && this.props.show) {
      this.initializeRequest();
    }
    if (prevProps.editMode !== this.props.editMode && this.props.show) {
      this.initializeRequest();
    }
  }

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.show) {
      this.props.onCloseCreateItem();
    }
  };

  onResetFormError = () => {
    this.setState({ hasFormError: false });
  };

  initializeRequest = () => {
    const holidayItemmRequest = this.props.editMode
      ? { ...(this.props.selectedHolidayInfo || {}) }
      : { defaultTeam: commonUtils.getCurrentUserTeamId() };
    if (this.props.editMode) {
      const desc = String(holidayItemmRequest.description || "");
      holidayItemmRequest.halfDay = /half-day/i.test(desc);
    }
    this.setState({
      holidayItemmRequest,
      formErrors: {},
      hasFormError: false,
    });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();
    this.setState((prevState) => ({
      holidayItemmRequest: {
        ...prevState.holidayItemmRequest,
        [fieldName]: value,
      },
    }));
  };

  handleSubmit = (isCreateAnotherEnabled) => {
    const isValid = validationUtils.isValidRequest(
      this.props.fieldConfig,
      this.state.holidayItemmRequest,
      this.state.formErrors
    );
    if (isValid) {
      const request = { ...this.state.holidayItemmRequest };
      // Persist half-day via description token (fs_holiday_model has no halfDay column).
      if (request.halfDay) {
        const desc = String(request.description || request.name || "").trim();
        request.description = /half-day/i.test(desc) ? desc : `${desc || request.name} · half-day`.trim();
      }
      delete request.halfDay;
      this.props.handleSubmit(
        request,
        this.props.editMode,
        isCreateAnotherEnabled,
        !this.props.editMode ? this.initializeRequest : null
      );
      if (!isCreateAnotherEnabled && !this.props.editMode) {
        this.props.onCloseCreateItem();
      }
    } else {
      this.setState({ hasFormError: true });
    }
  };

  render() {
    if (this.props.show !== true) {
      return null;
    }

    const title = this.props.editMode ? "Update holiday" : "Add holiday";
    const titleId = "lux-activity-holiday-popover-title";

    return (
      <>
        <button
          type="button"
          className="lux-activity-holiday-popover__backdrop"
          aria-label="Close add holiday"
          onClick={this.props.onCloseCreateItem}
        />
        <div
          className="lux-activity-holiday-popover"
          role="dialog"
          aria-modal="true"
          aria-labelledby={titleId}
        >
          <header className="lux-activity-holiday-popover__head">
            <div className="lux-activity-holiday-popover__head-main">
              <span className="lux-activity-holiday-popover__status is-green" aria-hidden="true">
                <i className="fe fe-calendar" />
              </span>
              <div className="lux-activity-holiday-popover__title-copy">
                <span className="lux-activity-holiday-popover__eyebrow">Organization holidays</span>
                <h2 id={titleId}>{title}</h2>
                <p>Schedule a team-wide holiday for selected locations.</p>
              </div>
            </div>
            <button
              type="button"
              className="lux-activity-holiday-popover__close"
              onClick={this.props.onCloseCreateItem}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-activity-holiday-popover__body lux-create-form">
            <LuxCreateFieldGroup columns={2}>
              <LuxCreateField>
                <CustomInput
                  inputtype="text"
                  label="Name"
                  name="name"
                  fieldConfig={this.props.fieldConfig}
                  mappingObject={this.state.holidayItemmRequest}
                  onChange={this.onChange}
                  onFormError={this.onFormError}
                  placeholder="Holiday name…"
                  datatype="alpnumspl"
                />
              </LuxCreateField>
              <LuxCreateField>
                <CustomInput
                  readOnly={this.props.readOnly}
                  type="dateselect"
                  label="Holiday date"
                  name="holidayDate"
                  fieldConfig={this.props.fieldConfig}
                  mappingObject={this.state.holidayItemmRequest}
                  onChange={this.onChange}
                  time={false}
                  onFormError={this.onFormError}
                  minDate={new Date(2018, 0, 1)}
                  maxDate={new Date(2100, 0, 1)}
                  currentDate={new Date()}
                />
              </LuxCreateField>
              <LuxCreateField span="full">
                <CustomInput
                  readOnly={this.props.readOnly}
                  type="select"
                  label="Locations"
                  name="locations"
                  fieldConfig={this.props.fieldConfig}
                  mappingObject={this.state.holidayItemmRequest}
                  onChange={this.onChange}
                  placeholder="Select locations…"
                  isAppConfig={true}
                  createConfig={this.props.createConfig}
                  onFormError={this.onFormError}
                  configName="location"
                  multi={true}
                />
              </LuxCreateField>
              <LuxCreateField span="full">
                <label className="lux-create-check">
                  <input
                    type="checkbox"
                    checked={!!this.state.holidayItemmRequest.halfDay}
                    onChange={(e) => this.onChange("halfDay", e.target.checked)}
                  />
                  <span>Half-day holiday (leave day-count treats this as 0.5)</span>
                </label>
              </LuxCreateField>
            </LuxCreateFieldGroup>
          </div>

          <LuxCreateFooter
            handleSubmit={this.handleSubmit}
            editMode={this.props.editMode}
            initializeRequest={this.initializeRequest}
            hasFormError={this.state.hasFormError}
            onResetFormError={this.onResetFormError}
            createButtonLabel={this.props.editMode ? "Save holiday" : "Add holiday"}
          />
        </div>
      </>
    );
  }
}

const mapStateToProps = (state) => ({
  taskInfo: state.tasks.selectedTaskInfo,
  isLoading: state.tasks.loading,
  fieldConfig: state.employees.holidayFieldConfig,
  createConfig: state.employees.createConfig,
});

export default connect(mapStateToProps)(CreateHolidayModel);
