import React from "react";
import classNames from "classnames/bind";
import { getApprovalAttentionMeta } from "config/approvalAttention.utils";
import {
  hasApprovalChainMetadata,
  isBulkSelectableApprovalItem,
} from "config/universal-approval.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ApprovalActingForBadge from "views/hrms/components/delegation/ApprovalActingForBadge";
import UniversalApprovalAttentionBadge from "./UniversalApprovalAttentionBadge";
import UniversalApprovalStatusBadge from "./UniversalApprovalStatusBadge";
import UniversalApprovalSlaBadge from "./UniversalApprovalSlaBadge";
import "./UniversalApprovalWorkflow.css";

function getInitials(name = "") {
  return String(name || "")
    .split(/[\s·]+/)
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function getRequesterParts(item) {
  const meta = (item && item.metadata) || {};
  const name =
    (meta.employeeName && String(meta.employeeName).trim()) ||
    String((item && item.requester) || "")
      .split(" · ")[0]
      .trim() ||
    "Unknown";
  const metaLine = [
    meta.empCode ? `Code ${meta.empCode}` : null,
    meta.employeeId != null ? `ID ${meta.employeeId}` : null,
  ]
    .filter(Boolean)
    .join(" · ");
  return { name, metaLine };
}

function formatChainDate(value) {
  if (!value) {
    return null;
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return String(value);
  }
  return date.toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function formatChainState(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/_/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function UniversalApprovalRegister({
  items,
  loading,
  onSelect,
  onClearFilters,
  bulkActionsEnabled = false,
  selectedItemIds = [],
  onToggleItem,
  onToggleAll,
  maxSelection = 50,
}) {
  if (loading) {
    return <div className="lux-appr-register__skeleton" aria-busy="true" role="status" />;
  }

  if (!items.length) {
    return (
      <div data-testid="approval-register-empty">
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-appr-empty"
          icon="fe fe-inbox"
          title="Inbox clear"
          description="No approvals match your filters. Try broadening status or domain, or check back when new requests arrive."
          showSecondary={typeof onClearFilters === "function"}
          secondaryLabel="Reset to pending"
          secondaryIcon="fe fe-rotate-ccw"
          onSecondary={onClearFilters}
        />
      </div>
    );
  }

  const selectedIds = new Set(selectedItemIds || []);
  const selectableItems = bulkActionsEnabled
    ? items.filter(isBulkSelectableApprovalItem)
    : [];
  const selectableBatch = selectableItems.slice(0, maxSelection);
  const allSelectableChecked =
    selectableBatch.length > 0 &&
    selectableBatch.every((item) => selectedIds.has(item.id));

  return (
    <div className="lux-appr-register-wrap" data-testid="approval-register">
      <table
        className={classNames("lux-appr-register", {
          "has-selection": bulkActionsEnabled,
        })}
      >
        <colgroup>
          {bulkActionsEnabled && (
            <col className="lux-appr-register__col lux-appr-register__col--select" />
          )}
          <col className="lux-appr-register__col lux-appr-register__col--request" />
          <col className="lux-appr-register__col lux-appr-register__col--domain" />
          <col className="lux-appr-register__col lux-appr-register__col--priority" />
          <col className="lux-appr-register__col lux-appr-register__col--due" />
          <col className="lux-appr-register__col lux-appr-register__col--status" />
        </colgroup>
        <thead>
          <tr>
            {bulkActionsEnabled && (
              <th className="lux-appr-register__select-cell">
                <input
                  type="checkbox"
                  aria-label={`Select up to ${maxSelection} pending approvals`}
                  checked={allSelectableChecked}
                  onChange={(event) =>
                    onToggleAll && onToggleAll(selectableItems, event.target.checked)
                  }
                  disabled={!selectableItems.length}
                  data-testid="approval-select-all"
                />
              </th>
            )}
            <th>Request</th>
            <th>Domain</th>
            <th>Priority</th>
            <th>Due</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {items.map((item) => {
            const requesterParts = getRequesterParts(item);
            const attention = getApprovalAttentionMeta(item);
            const domainKey = String(item.domain || "").toLowerCase();
            const hasChain = hasApprovalChainMetadata(item);
            const selectable = bulkActionsEnabled && isBulkSelectableApprovalItem(item);
            const selected = selectedIds.has(item.id);
            return (
            <tr
              key={item.id}
              className={classNames("lux-appr-register__row", {
                "is-high": item.priority === "HIGH" && !attention,
                "is-delegate": item.actingAsDelegate,
                "is-attention": Boolean(attention),
                "is-selected": selected,
                "has-chain": hasChain,
                [`is-attention-${attention && attention.level}`]: Boolean(attention),
                [`is-domain-${domainKey}`]: Boolean(attention),
              })}
              data-testid={`approval-row-${String(item.domain || "UNKNOWN").toLowerCase()}`}
              data-approval-domain={item.domain || ""}
              onClick={() => onSelect(item)}
              onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                  event.preventDefault();
                  onSelect(item);
                }
              }}
              tabIndex={0}
              role="button"
              aria-label={`Open approval for ${item.subject}`}
            >
              {bulkActionsEnabled && (
                <td
                  className="lux-appr-register__select-cell"
                  onClick={(event) => event.stopPropagation()}
                  onKeyDown={(event) => event.stopPropagation()}
                >
                  <input
                    type="checkbox"
                    aria-label={`Select ${item.subject || item.domainLabel || "approval"}`}
                    checked={selected}
                    disabled={
                      !selectable || (!selected && selectedIds.size >= maxSelection)
                    }
                    onChange={(event) =>
                      onToggleItem && onToggleItem(item, event.target.checked)
                    }
                    data-testid={`approval-select-${item.id}`}
                  />
                </td>
              )}
              <td>
                <div className="lux-appr-register__request">
                  <span
                    className={classNames(
                      "lux-appr-register__avatar",
                      item.moduleTone && `is-${item.moduleTone}`
                    )}
                    aria-hidden="true"
                  >
                    {getInitials(requesterParts.name)}
                  </span>
                  <span className="lux-appr-register__request-copy">
                    <strong>{requesterParts.name}</strong>
                    {requesterParts.metaLine ? (
                      <em className="lux-appr-register__requester-meta">{requesterParts.metaLine}</em>
                    ) : null}
                    <span className="lux-appr-register__subject">{item.subject}</span>
                    {hasChain && (
                      <span className="lux-appr-register__chain-step">
                        <i className="fe fe-git-branch" aria-hidden="true" />
                        <strong>{item.currentStepLabel || item.currentStepKey}</strong>
                        {item.currentStepLabel && item.currentStepKey ? (
                          <em>{item.currentStepKey}</em>
                        ) : null}
                      </span>
                    )}
                    {item.actingAsDelegate && (
                      <ApprovalActingForBadge
                        record={item}
                        className="lux-appr-register__delegate"
                      />
                    )}
                  </span>
                </div>
              </td>
              <td>
                <span className="lux-appr-register__domain">
                  <span className="lux-appr-register__domain-icon" aria-hidden="true">
                    <i className={item.domainIcon} />
                  </span>
                  <span className="lux-appr-register__domain-copy">
                    <strong>{item.domainLabel}</strong>
                    {hasChain && item.policyRef ? (
                      <em className="lux-appr-register__policy">
                        {item.policyRef}
                        {item.policyVersion != null ? ` · v${item.policyVersion}` : ""}
                      </em>
                    ) : null}
                  </span>
                </span>
              </td>
              <td>
                <div className="lux-appr-register__priority-cell">
                  {attention ? (
                    <UniversalApprovalAttentionBadge item={item} compact />
                  ) : (
                    <UniversalApprovalStatusBadge variant="priority" priority={item.priority} />
                  )}
                  {hasChain && (
                    <span className="lux-appr-register__authority">
                      <em>{(item.assignedApproverIds || []).length} assigned</em>
                      {(item.delegateApproverIds || []).length > 0 ? (
                        <em className="is-delegate">
                          {(item.delegateApproverIds || []).length} delegate
                          {(item.delegateApproverIds || []).length === 1 ? "" : "s"}
                        </em>
                      ) : null}
                    </span>
                  )}
                </div>
              </td>
              <td>
                <div className="lux-appr-register__due-cell">
                  <span className="lux-appr-register__due">
                    {(hasChain && formatChainDate(item.chainDueAt)) || item.dueLabel || "—"}
                  </span>
                  {hasChain && item.chainSlaState ? (
                    <span
                      className={`lux-appr-register__chain-sla is-${String(
                        item.chainSlaState
                      ).toLowerCase()}`}
                    >
                      {formatChainState(item.chainSlaState)}
                    </span>
                  ) : (
                    <UniversalApprovalSlaBadge item={item} />
                  )}
                </div>
              </td>
              <td>
                <UniversalApprovalStatusBadge status={item.status} />
              </td>
            </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default UniversalApprovalRegister;
