import {
  toAreaChart,
  toDonutChart,
  toGroupedBarChart,
} from "views/hrms/components/dashboard/employeeDashboard.utils";

const STATUS_COLORS = {
  NEW: "#0ea5e9",
  ASSIGNED: "#6366f1",
  INPROGRESS: "#f59e0b",
  COMPLETED: "#10b981",
  CLOSED: "#64748b",
};

const PRIORITY_COLORS = {
  URGENT: "#f43f5e",
  HIGH: "#f59e0b",
  MEDIUM: "#6366f1",
  LOW: "#94a3b8",
};

const CHECKLIST_COLORS = {
  COMPLETED: "#10b981",
  INPROGRESS: "#6366f1",
  NOT_STARTED: "#f59e0b",
  NONE: "#cbd5e1",
};

const TYPE_COLORS = {
  PROJECT: "#6366f1",
  NON_PROJECT: "#14b8a6",
  OTHER: "#94a3b8",
};

const OUTCOME_COLORS = {
  COMPLETED: "#10b981",
  INPROGRESS: "#f59e0b",
  OPEN: "#0ea5e9",
};

const TYPE_PALETTE = ["#6366f1", "#14b8a6", "#f59e0b", "#f43f5e", "#94a3b8", "#8b5cf6"];

const LUX_CHART_FONT = {
  fontFamily: "Inter, system-ui, sans-serif",
  fontSize: "11px",
  fontWeight: 600,
};

function applyLuxChartBase(options) {
  return {
    ...options,
    chart: { ...(options.chart || {}), fontFamily: LUX_CHART_FONT.fontFamily, toolbar: { show: false } },
    grid: { borderColor: "rgba(226,232,240,0.85)", strokeDashArray: 4, ...(options.grid || {}) },
  };
}

function withDonutCenter(chart, centerLabel, centerValue) {
  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "76%",
        labels: {
          show: true,
          name: { show: true, fontSize: "11px", fontWeight: 600, color: "#64748b" },
          value: { show: true, fontSize: "15px", fontWeight: 800, color: "#0f172a" },
          total: {
            show: true,
            label: centerLabel,
            fontSize: "11px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => String(centerValue),
          },
        },
      },
    },
  };
  chart.options.legend = {
    position: "bottom",
    fontSize: "10px",
    fontWeight: 600,
    labels: { colors: "#475569" },
  };
  chart.options.stroke = { width: 2, colors: ["#fff"] };
  return chart;
}

function mixToDonut(mix, colorMap, centerLabel, centerValue) {
  if (!mix || !mix.length) return null;
  const labels = mix.map((s) => s.label);
  const series = mix.map((s) => s.count);
  const colors = mix.map((s, i) => colorMap[s.key] || TYPE_PALETTE[i % TYPE_PALETTE.length]);
  const total = centerValue != null ? centerValue : series.reduce((a, b) => a + b, 0);
  return withDonutCenter(toDonutChart(labels, series, colors), centerLabel, total);
}

export function buildActivityStatusDonutChart(stat) {
  return mixToDonut(stat.statusMix, STATUS_COLORS, "Activities", stat.total);
}

export function buildActivityOutcomeDonutChart(stat) {
  return mixToDonut(stat.outcomeMix, OUTCOME_COLORS, "Filtered", stat.total);
}

export function buildActivityPriorityBarChart(stat) {
  const mix = stat.priorityMix;
  if (!mix || !mix.length) return null;
  return {
    series: [{ name: "Activities", data: mix.map((s) => s.count) }],
    options: applyLuxChartBase({
      chart: { type: "bar" },
      plotOptions: { bar: { horizontal: true, borderRadius: 6, barHeight: "68%" } },
      dataLabels: { enabled: false },
      xaxis: { categories: mix.map((s) => s.label) },
      colors: mix.map((s) => PRIORITY_COLORS[s.key] || "#6366f1"),
    }),
  };
}

export function buildActivityCategoryBarChart(stat) {
  const mix = stat.categoryMix;
  if (!mix || !mix.length) return null;
  return {
    series: [{ name: "Activities", data: mix.map((s) => s.count) }],
    options: applyLuxChartBase({
      chart: { type: "bar" },
      plotOptions: { bar: { horizontal: true, borderRadius: 6, barHeight: "68%" } },
      dataLabels: { enabled: false },
      xaxis: { categories: mix.map((s) => s.label) },
      colors: mix.map((_, i) => TYPE_PALETTE[i % TYPE_PALETTE.length]),
    }),
  };
}

export function buildActivityTypeDonutChart(stat) {
  return mixToDonut(stat.typeMix, TYPE_COLORS, "Scope", stat.total);
}

export function buildActivityChecklistDonutChart(stat) {
  return mixToDonut(stat.checklistMix, CHECKLIST_COLORS, "Checklists", stat.total);
}

export function buildActivityHoursCompareChart(stat) {
  const logged = stat.loggedHoursNum || 0;
  const estimated = stat.estimatedHoursNum || 0;
  if (!logged && !estimated) return null;
  const utilizationRate = stat.utilizationRate || 0;
  return {
    series: [{ name: "Hours", data: [logged, estimated] }],
    options: applyLuxChartBase({
      chart: { type: "bar" },
      plotOptions: {
        bar: {
          borderRadius: 8,
          columnWidth: "48%",
          distributed: true,
          dataLabels: { position: "top" },
        },
      },
      dataLabels: {
        enabled: true,
        formatter: (val) => `${val}h`,
        style: { fontSize: "11px", fontWeight: 800, colors: ["#0f172a"] },
        offsetY: -4,
      },
      xaxis: {
        categories: ["Logged (actual)", "Estimated (plan)"],
        labels: { style: { fontSize: "10px", fontWeight: 700 } },
      },
      yaxis: {
        title: { text: "Hours", style: { fontSize: "10px", fontWeight: 700, color: "#64748b" } },
        labels: { formatter: (val) => `${val}h` },
      },
      colors: ["#10b981", "#94a3b8"],
      legend: { show: false },
      tooltip: {
        y: { formatter: (val) => `${val} hours (${utilizationRate}% of plan logged)` },
      },
    }),
  };
}

export function buildActivityCompletionDonutChart(stat) {
  const completed = stat.completed || 0;
  const open = stat.openCount != null ? stat.openCount : Math.max((stat.total || 0) - completed, 0);
  if (!stat.total) return null;
  return withDonutCenter(
    toDonutChart(
      [`Finished (${completed})`, `Still open (${open})`],
      [completed, open],
      ["#10b981", "#e2e8f0"]
    ),
    "Finished",
    `${completed}/${stat.total}`
  );
}

export function buildActivityLoggedHoursTrendChart(stat) {
  const trend = stat.loggedHoursTrend;
  if (!trend || !trend.some((b) => b.hours > 0)) return null;
  const chart = toAreaChart(
    trend.map((b) => b.label),
    [{ name: "Logged hours", data: trend.map((b) => b.hours) }],
    ["#5b5ff4"]
  );
  return { series: chart.series, options: applyLuxChartBase(chart.options) };
}

export function buildActivityOwnerBarChart(stat) {
  const mix = stat.ownerMix;
  if (!mix || !mix.length) return null;
  return {
    series: [{ name: "Activities", data: mix.map((s) => s.count) }],
    options: applyLuxChartBase({
      chart: { type: "bar" },
      plotOptions: { bar: { horizontal: true, borderRadius: 6, barHeight: "68%" } },
      dataLabels: { enabled: false },
      xaxis: { categories: mix.map((s) => s.label) },
      colors: ["#0ea5e9"],
    }),
  };
}
