import React from "react";
import classNames from "classnames/bind";
import { TIMESHEET_LATE_REASON_OPTIONS } from "./timesheetGovernance.utils";
import "./TimesheetGovernanceBanner.css";

export default function TimesheetLateReasonFields({
  lateReason,
  lateReasonDetail,
  required,
  onChange,
  compact,
}) {
  const showDetail = String(lateReason || "").toUpperCase() === "OTHER";
  return (
    <div
      className={classNames("lux-ts-late-reason", { "is-compact": compact })}
      data-testid="timesheet-late-reason"
    >
      <label className="lux-ts-late-reason__field">
        <span>
          Late reason
          {required ? <em aria-hidden="true">*</em> : null}
        </span>
        <select
          className="lux-ts-late-reason__control"
          value={lateReason || ""}
          onChange={(event) =>
            onChange &&
            onChange({
              lateReason: event.target.value,
              lateReasonDetail:
                event.target.value === "OTHER" ? lateReasonDetail : "",
            })
          }
          aria-required={required === true}
        >
          <option value="">Select a reason</option>
          {TIMESHEET_LATE_REASON_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      </label>
      {showDetail ? (
        <label className="lux-ts-late-reason__field">
          <span>
            Detail
            <em aria-hidden="true">*</em>
          </span>
          <input
            type="text"
            className="lux-ts-late-reason__control"
            maxLength={500}
            value={lateReasonDetail || ""}
            onChange={(event) =>
              onChange &&
              onChange({
                lateReason,
                lateReasonDetail: event.target.value,
              })
            }
            placeholder="Short explanation"
          />
        </label>
      ) : (
        <p className="lux-ts-late-reason__hint">
          Route is policy-owned. This reason is captured for audit only.
        </p>
      )}
    </div>
  );
}
