import React from "react";
import classNames from "classnames/bind";
import { DeveloperLuxPanel, DeveloperStatusBadge } from "views/developer/components/DeveloperLuxShared";

export default function WebhookDeliveryPanel({ deliveries, loading, selectedSubscriptionId }) {
  const list = (deliveries || []).filter((row) => !selectedSubscriptionId || row.subscriptionId === selectedSubscriptionId);

  return (
    <DeveloperLuxPanel title="Delivery log" meta="HTTP status and retry trace" icon="fe fe-terminal" accent="slate">
      {loading ? (
        <div className="lux-dev-skeleton lux-dev-skeleton--panel" />
      ) : !list.length ? (
        <div className="lux-dev-empty">Select a subscription to inspect deliveries.</div>
      ) : (
        <ul className="lux-dev-delivery-list">
          {list.map((row) => (
            <li key={row.id} className={classNames("lux-dev-delivery-row", row.tone && `is-${row.tone}`)}>
              <div className="lux-dev-delivery-row__main">
                <strong>{row.eventType}</strong>
                <span>{row.subscriptionName}</span>
              </div>
              <div className="lux-dev-delivery-row__meta">
                <DeveloperStatusBadge status={row.status} />
                <span>HTTP {row.httpStatus}</span>
                <span>{row.durationMs}ms</span>
                <span>{row.deliveredAt}</span>
              </div>
              {row.errorMessage ? <p className="lux-dev-delivery-row__error">{row.errorMessage}</p> : null}
            </li>
          ))}
        </ul>
      )}
    </DeveloperLuxPanel>
  );
}
