import React, { Component } from "react";
import { Modal } from "views/common/plugins/model/Modal";
import { Effect } from "views/common/plugins/model";
import SparklesIcon from "./fragments/SparklesIcon";
import { brandUtils } from "_helpers";
import { getAssistPanelModalStyle } from "./assistDock.utils";
import "./FamstackAIChatModal.css";

class FamstackAIChatModal extends Component {
  constructor(props) {
    super(props);
    this.state = {
      accessRequestSubmitted: false,
    };
  }

  render() {
    const { onRequestClose, dockAnchor } = this.props;
    const appName = brandUtils.getAppBrandName();

    return (
      <Modal
        onRequestClose={onRequestClose}
        effect={Effect.ScaleUp}
        style={getAssistPanelModalStyle(dockAnchor)}
      >
        <div className="famstack-ai-chat-modal lux-assist-panel lux-assist-panel--ai">
          <div className="lux-assist-panel__hero famstack-ai-chat-modal__header">
            <div className="lux-assist-panel__hero-bg" aria-hidden="true" />
            <div className="lux-assist-panel__hero-top">
              <div className="lux-assist-panel__brand">
                <span className="lux-assist-panel__brand-icon">
                  <SparklesIcon size={22} />
                </span>
                <div>
                  <span className="lux-assist-panel__kicker">Intelligence</span>
                  <h4 className="lux-assist-panel__title mb-0">{appName} AI</h4>
                </div>
              </div>
              <button
                type="button"
                onClick={onRequestClose}
                className="lux-assist-panel__close"
                aria-label="Close AI panel"
              >
                <i className="fa fa-times" />
              </button>
            </div>
            <p className="lux-assist-panel__hero-lead">
              Your workspace copilot for summaries, insights, and faster decisions.
            </p>
          </div>

          <div className="lux-assist-panel__body famstack-ai-chat-modal__body">
            {!this.state.accessRequestSubmitted ? (
              <>
                <div className="lux-assist-panel__feature-grid">
                  <div className="lux-assist-panel__feature">
                    <i className="fa fa-bolt" aria-hidden="true" />
                    <span>Smart summaries</span>
                  </div>
                  <div className="lux-assist-panel__feature">
                    <i className="fa fa-chart-line" aria-hidden="true" />
                    <span>Data insights</span>
                  </div>
                  <div className="lux-assist-panel__feature">
                    <i className="fa fa-magic" aria-hidden="true" />
                    <span>Workflow help</span>
                  </div>
                </div>

                <div className="lux-assist-panel__card ai-access-message">
                  <div className="ai-icon-large mb-3">
                    <SparklesIcon
                      size={56}
                      strokeWidth={1.5}
                      className="ai-icon-large__sparkles"
                    />
                  </div>
                  <h5 className="famstack-ai-chat-modal__section-title">
                    Access required
                  </h5>
                  <p className="famstack-ai-chat-modal__lead">
                    {appName} AI is not yet enabled for your account. Request access
                    and your administrator will review it shortly.
                  </p>
                  <button
                    type="button"
                    className="famstack-ai-chat-modal__btn-access lux-assist-panel__cta"
                    onClick={() => {
                      this.setState({ accessRequestSubmitted: true });
                    }}
                  >
                    <i className="fa fa-paper-plane mr-2" aria-hidden="true" />
                    Request access
                  </button>
                </div>
              </>
            ) : (
              <div className="lux-assist-panel__card lux-assist-panel__card--success ai-access-message text-center">
                <div className="famstack-ai-chat-modal__success-icon mb-3" aria-hidden="true">
                  <i className="fa fa-check-circle" />
                </div>
                <h5 className="famstack-ai-chat-modal__section-title">
                  Request submitted
                </h5>
                <p className="famstack-ai-chat-modal__lead mb-0">
                  Your access request is in review. You will be notified once
                  {appName} AI is enabled for your account.
                </p>
              </div>
            )}
          </div>
        </div>
      </Modal>
    );
  }
}

export default FamstackAIChatModal;

