import React, { Component } from "react";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import { userActions } from "_actions";
import {
  authGetItem,
  commonUtils,
} from "_helpers";
import AuthPageShell from "./components/AuthPageShell";
import AuthLoginCard from "./components/AuthLoginCard";
import LoginPageFooter from "./LoginPageFooter";

const MIN_PASSWORD_LENGTH = 9;

function readForceChangeIdentity() {
  let email = authGetItem("forcePasswordChangeEmail") || "";
  let employeeId = authGetItem("forcePasswordChangeEmployeeId") || null;
  if (employeeId != null && employeeId !== "") {
    const parsed = Number(employeeId);
    employeeId = Number.isFinite(parsed) ? parsed : null;
  } else {
    employeeId = null;
  }

  if (!email || employeeId == null) {
    try {
      const user = commonUtils.getCurrentUser() || {};
      email = email || user.email || "";
      if (employeeId == null && user.id != null) {
        employeeId = user.id;
      }
    } catch (_err) {
      // encrypted profile may be unavailable; form can still use typed email
    }
  }

  return { email, employeeId };
}

class ForceChangePasswordPage extends Component {
  constructor(props) {
    super(props);
    const identity = readForceChangeIdentity();
    this.state = {
      passwordType: "password",
      submitted: false,
      currentPassword: "",
      newPassword: "",
      confirmPassword: "",
      email: identity.email || "",
      employeeId: identity.employeeId,
      localError: "",
    };
  }

  togglePasswordType = () => {
    this.setState((prev) => ({
      passwordType: prev.passwordType === "text" ? "password" : "text",
    }));
  };

  onChange = (e) => {
    const { name, value } = e.target;
    this.setState({ [name]: value, submitted: false, localError: "" });
  };

  onSubmit = (e) => {
    e.preventDefault();
    const { email, employeeId, currentPassword, newPassword, confirmPassword } = this.state;
    this.setState({ submitted: true, localError: "" });

    if (!email) {
      this.setState({ localError: "Account email is missing. Sign in again, then retry." });
      return;
    }
    if (!currentPassword || !newPassword || newPassword.length < MIN_PASSWORD_LENGTH) {
      this.setState({
        localError: `Enter your current password and a new password of at least ${MIN_PASSWORD_LENGTH} characters.`,
      });
      return;
    }
    if (newPassword !== confirmPassword) {
      this.setState({ localError: "New password and confirmation do not match." });
      return;
    }
    if (currentPassword === newPassword) {
      this.setState({
        localError: "Choose a new password that is different from the temporary password.",
      });
      return;
    }

    // updatePassword is already bound by connect — do not wrap in store.dispatch again.
    this.props.updatePassword(
      {
        email,
        employeeId,
        currentPassword,
        newPassword,
      },
      { redirectTo: "/" }
    );
  };

  render() {
    const { authentication } = this.props;
    const {
      passwordType,
      submitted,
      currentPassword,
      newPassword,
      confirmPassword,
      email,
      localError,
    } = this.state;
    const apiError = authentication && authentication.updatePasswordError;
    const showError = Boolean(localError || (submitted && apiError));

    return (
      <AuthPageShell>
        <AuthLoginCard
          eyebrow="Security"
          title="Choose a new password"
          subtitle="Your account requires a password change before you can continue."
          footer={<LoginPageFooter />}
        >
          <form className="auth-login__form" onSubmit={this.onSubmit} noValidate>
            {email ? (
              <p className="text-muted mb-3" data-testid="force-change-email">
                Signed in as <strong>{email}</strong>
              </p>
            ) : null}

            {showError && (
              <div className="alert alert-danger" role="alert">
                {localError ||
                  "Password update failed. Check your current password and try again."}
              </div>
            )}

            <div className="form-group">
              <label className="form-label" htmlFor="force-current-password">
                Current password
              </label>
              <div className="input-group input-group-merge">
                <input
                  id="force-current-password"
                  type={passwordType}
                  name="currentPassword"
                  className="form-control"
                  autoComplete="current-password"
                  value={currentPassword}
                  onChange={this.onChange}
                  required
                />
              </div>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="force-new-password">
                New password
              </label>
              <div className="input-group input-group-merge">
                <input
                  id="force-new-password"
                  type={passwordType}
                  name="newPassword"
                  className="form-control"
                  autoComplete="new-password"
                  value={newPassword}
                  onChange={this.onChange}
                  required
                  minLength={MIN_PASSWORD_LENGTH}
                />
                <button
                  type="button"
                  className="input-group-text"
                  onClick={this.togglePasswordType}
                  aria-label="Toggle password visibility"
                >
                  <i
                    className={`fe fe-${passwordType === "text" ? "eye-off" : "eye"}`}
                    aria-hidden="true"
                  />
                </button>
              </div>
              <small className="form-text text-muted">
                Minimum {MIN_PASSWORD_LENGTH} characters.
              </small>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="force-confirm-password">
                Confirm new password
              </label>
              <input
                id="force-confirm-password"
                type={passwordType}
                name="confirmPassword"
                className="form-control"
                autoComplete="new-password"
                value={confirmPassword}
                onChange={this.onChange}
                required
              />
            </div>

            <button
              type="submit"
              className="btn btn-primary btn-block"
              data-ga-action="force_change_password_submit"
              data-testid="force-change-submit"
            >
              Save and continue
            </button>
          </form>
        </AuthLoginCard>
      </AuthPageShell>
    );
  }
}

ForceChangePasswordPage.propTypes = {
  updatePassword: PropTypes.func.isRequired,
  authentication: PropTypes.object,
};

ForceChangePasswordPage.defaultProps = {
  authentication: {},
};

function mapState(state) {
  return { authentication: state.authentication };
}

export default connect(mapState, { updatePassword: userActions.updatePassword })(
  ForceChangePasswordPage
);
