import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  buildDelegationScopePills,
  formatDelegationDateRange,
  getDelegationStatus,
  getDelegationStatusMeta,
  getEmployeeInitials,
  sortDelegationsForDisplay,
} from "_helpers/approvalDelegation.utils";

function getStatusBadgeTone(statusMeta) {
  if (statusMeta.tone === "active") {
    return "success";
  }
  if (statusMeta.tone === "upcoming") {
    return "warning";
  }
  return "slate";
}

export default function DelegationActingRegister({ delegations, loading }) {
  const rows = sortDelegationsForDisplay(delegations || []);

  if (loading) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="Loading acting coverage"
        description="Fetching managers who delegated approvals to you."
      />
    );
  }

  if (!rows.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        icon="fe fe-shield"
        title="Not acting for anyone"
        description="When a manager delegates approvals to you, their pending items appear in your inbox with an acting-for badge."
      />
    );
  }

  return (
    <div className="lux-delegation-register-wrap">
      <table className="lux-delegation-register">
        <thead>
          <tr>
            <th>Manager</th>
            <th>Period</th>
            <th>Scope</th>
            <th>Status</th>
            <th aria-hidden="true" />
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const status = getDelegationStatus(row);
            const statusMeta = getDelegationStatusMeta(status);
            const managerName = row.delegatorName || row.managerName || "Manager";
            const pills = buildDelegationScopePills(row.approvalTypes);
            const isActive = status === "active";

            return (
              <tr
                key={row.id || `${managerName}-${row.startDate}`}
                className={classNames("lux-delegation-register__row", {
                  "is-attention": isActive,
                })}
              >
                <td>
                  <div className="lux-delegation-register__primary">
                    <span className="lux-delegation-register__avatar is-violet" aria-hidden="true">
                      {getEmployeeInitials(managerName)}
                    </span>
                    <span className="lux-delegation-register__primary-copy">
                      <strong className="lux-delegation-register__primary-title">{managerName}</strong>
                      <span className="lux-delegation-register__primary-meta">Acting-for coverage</span>
                    </span>
                  </div>
                </td>
                <td>
                  <span className="lux-delegation-register__date">{formatDelegationDateRange(row)}</span>
                </td>
                <td>
                  <div className="lux-delegation-admin__scopes">
                    {pills.length
                      ? pills.map((pill) => (
                          <span key={pill.id} className={`lux-delegation-admin__scope is-${pill.id.toLowerCase()}`}>
                            <i className={`fe ${pill.icon}`} aria-hidden="true" />
                            {pill.label}
                          </span>
                        ))
                      : "—"}
                  </div>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${getStatusBadgeTone(statusMeta)}`)}>
                    {statusMeta.label}
                  </span>
                </td>
                <td>
                  <Link to="/workspace/approvals" className="lux-delegation-register__open" aria-label={`Open approvals for ${managerName}`}>
                    <i className="fe fe-chevron-right" aria-hidden="true" />
                  </Link>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
