import React, { Component } from "react";
import classNames from "classnames/bind";
import ProjectServiceLinePicker, {
  ProjectServiceLineEstimateTable,
} from "./ProjectServiceLinePicker";
import { commonUtils } from "_helpers";
import {
  normalizeServiceLinesToOptions,
  resolveProjectServiceLineOptions,
  resolveSelectedServiceLineValues,
  resolveServiceLineLabel,
  formatEstimateHoursDisplay,
  formatEstimateRateDisplay,
  formatEstimateCostDisplay,
  getServiceLineEstimatePermissionFlags,
  getServiceLineEstimatePermissionNotes,
} from "./projectServiceLine.utils";

const POPOVER_ID = "lux-project-svc-popover-dialog";

class ProjectServiceScopeField extends Component {
  constructor(props) {
    super(props);
    this.state = { popoverOpen: false };
    this.rootRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.popoverOpen) return;
    if (
      event.target.closest(".custom-select__menu") ||
      event.target.closest(".custom-select__menu-portal")
    ) {
      return;
    }
    const dialog = document.getElementById(POPOVER_ID);
    if (
      this.rootRef.current &&
      !this.rootRef.current.contains(event.target) &&
      dialog &&
      !dialog.contains(event.target)
    ) {
      this.setState({ popoverOpen: false });
    }
  };

  getMode = () => {
    const { createConfig } = this.props;
    if (commonUtils.getAppConfigValue(createConfig, "enableServiceLineEstimate")) {
      return "estimate";
    }
    if (commonUtils.getAppConfigValue(createConfig, "enableServiceLineSelection")) {
      return "serviceLines";
    }
    if (commonUtils.getAppConfigValue(createConfig, "enableCategorySelection")) {
      return "category";
    }
    return null;
  };

  getFieldName = () => {
    const mode = this.getMode();
    if (mode === "category") return "category";
    return "serviceLines";
  };

  getOptions = () => {
    const { createConfig, serviceLineOptions, mappingObject, parentServiceLineEstimate } =
      this.props;
    const mode = this.getMode();

    if (mode === "estimate" || mode === "serviceLines") {
      const resolved =
        (serviceLineOptions && serviceLineOptions.length && serviceLineOptions) ||
        resolveProjectServiceLineOptions({
          projectRequest: mappingObject,
          purchaseOrderServiceLines: this.props.purchaseOrderServiceLines,
          purchaseOrderServiceLineEstimate: parentServiceLineEstimate,
          createConfig,
        });
      return resolved || [];
    }

    if (mode === "category") {
      return (
        normalizeServiceLinesToOptions(
          commonUtils.mapKeysToList(commonUtils.getAppConfigValue(createConfig, "categoryMap"))
        ) || []
      );
    }

    return [];
  };

  getSelectedValues = () => {
    const mode = this.getMode();
    return resolveSelectedServiceLineValues(this.props.mappingObject, mode);
  };

  getTitle = () => {
    const mode = this.getMode();
    if (mode === "estimate") return "Service lines & estimates";
    if (mode === "serviceLines") return "Service types";
    if (mode === "category") return "Project categories";
    return "Service scope";
  };

  getSubtitle = () => {
    const mode = this.getMode();
    if (mode === "estimate") {
      return "Choose service lines, then enter hours and rates for each selection.";
    }
    if (mode === "serviceLines") {
      return "Select every service type that applies to this project.";
    }
    return "Select all categories that describe the work delivered on this project.";
  };

  openPopover = () => {
    if (!this.props.readOnly) this.setState({ popoverOpen: true });
  };

  closePopover = () => this.setState({ popoverOpen: false });

  applySelection = (selectedServiceLines) => {
    const { onChange, name, serviceLineEstimate, parentServiceLineEstimate } = this.props;
    const fieldName = this.getFieldName();
    const mode = this.getMode();

    let updatedServiceLineEstimate = null;
    if (mode === "estimate") {
      updatedServiceLineEstimate = {};
      if (selectedServiceLines) {
        selectedServiceLines.forEach((serviceLine) => {
          const existing =
            (serviceLineEstimate && serviceLineEstimate[serviceLine]) ||
            (parentServiceLineEstimate && parentServiceLineEstimate[serviceLine]) ||
            { estHours: 0, estHourlyRate: 0 };
          updatedServiceLineEstimate[serviceLine] = { ...existing };
        });
      }
      onChange("serviceLines", selectedServiceLines);
      onChange(name, updatedServiceLineEstimate);
      if (selectedServiceLines && selectedServiceLines.length) {
        onChange("category", selectedServiceLines[0]);
      }
      return;
    }

    onChange(fieldName, selectedServiceLines);
    if (mode === "serviceLines" && selectedServiceLines && selectedServiceLines.length) {
      onChange("category", selectedServiceLines[0]);
    }
  };

  onLineEstimateChange = (line, row) => {
    const { onChange, name, serviceLineEstimate } = this.props;
    onChange(name, {
      ...(serviceLineEstimate || {}),
      [line]: row,
    });
  };

  renderSummaryChips = () => {
    const values = this.getSelectedValues();
    const options = this.getOptions();
    if (!values.length) {
      return (
        <span className="lux-bid-tg-field__empty">
          No service types selected — open the editor to choose what this project delivers.
        </span>
      );
    }
    return (
      <ul className="lux-bid-tg-field__chips" aria-label="Selected service types">
        {values.map((value) => (
          <li key={value} className="lux-bid-tg-field__chip">
            {resolveServiceLineLabel(value, options)}
          </li>
        ))}
      </ul>
    );
  };

  getEstimatePermissions = () =>
    getServiceLineEstimatePermissionFlags(this.props.permission);

  renderEstimatePermissionNotes = (flags) => {
    const notes = getServiceLineEstimatePermissionNotes(flags);
    if (!notes.length) return null;
    return (
      <div className="lux-project-svc-field__perm-notes" role="status">
        {notes.map((note) => (
          <span key={note} className="lux-project-svc-field__perm-note">
            <i className="fe fe-lock" aria-hidden="true" />
            {note}
          </span>
        ))}
      </div>
    );
  };

  renderEstimateSummary = () => {
    const { mappingObject } = this.props;
    const values = this.getSelectedValues();
    const options = this.getOptions();
    const estimate = mappingObject.serviceLineEstimate || {};
    if (!values.length) return null;

    const flags = this.getEstimatePermissions();
    const gridClass = classNames(
      "lux-project-svc-field__summary-table",
      "has-hours",
      "has-rate"
    );

    return (
      <>
        {this.renderEstimatePermissionNotes(flags)}
        <div className={gridClass} aria-label="Service line estimates">
          <div className="lux-project-svc-field__summary-head">
            <span>Service type</span>
            <span>Est. hours</span>
            <span>Hourly rate</span>
            <span>Est. cost</span>
          </div>
          {values.map((line) => {
            const row = estimate[line] || {};
            const hoursDisplay = flags.hoursView
              ? formatEstimateHoursDisplay(row.estHours)
              : { text: "--", isPlaceholder: true };
            const rateDisplay = flags.costView
              ? formatEstimateRateDisplay(row.estHourlyRate)
              : { text: "$--", isPlaceholder: true };
            const costDisplay = flags.costView
              ? formatEstimateCostDisplay(row.estHours, row.estHourlyRate)
              : { text: "$--", isPlaceholder: true };
            return (
              <div key={line} className="lux-project-svc-field__summary-row">
                <span className="lux-project-svc-field__summary-name">
                  {resolveServiceLineLabel(line, options)}
                </span>
                <span
                  className={classNames("lux-project-svc-field__summary-val", {
                    "is-placeholder": hoursDisplay.isPlaceholder,
                  })}
                >
                  {hoursDisplay.text}
                </span>
                <span
                  className={classNames("lux-project-svc-field__summary-val", {
                    "is-placeholder": rateDisplay.isPlaceholder,
                  })}
                >
                  {rateDisplay.text}
                </span>
                <span
                  className={classNames("lux-project-svc-field__summary-cost", {
                    "is-placeholder": costDisplay.isPlaceholder,
                  })}
                >
                  {costDisplay.text}
                </span>
              </div>
            );
          })}
        </div>
      </>
    );
  };

  renderSurfaceContent = () => {
    const mode = this.getMode();
    const selectedCount = this.getSelectedValues().length;

    if (!selectedCount) {
      return (
        <span className="lux-bid-tg-field__empty">
          No service types selected — open the editor to choose what this project delivers.
        </span>
      );
    }

    if (mode === "estimate") {
      return this.renderEstimateSummary();
    }

    return this.renderSummaryChips();
  };

  renderPopoverBody = () => {
    const mode = this.getMode();
    const {
      readOnly,
      mappingObject,
      serviceLineEstimate,
      parentServiceLineEstimate,
      permission,
    } = this.props;
    const options = this.getOptions();
    const selected = this.getSelectedValues();
    const fieldName = this.getFieldName();
    const pickerValue =
      fieldName === "category" ? mappingObject.category : mappingObject.serviceLines;

    return (
      <>
        <ProjectServiceLinePicker
          options={options}
          value={pickerValue || selected}
          readOnly={readOnly}
          onChange={this.applySelection}
          sectionTitle="1 · Select service types"
          sectionHint="Choose every service type that applies to this project."
          emptyMessage={
            mode === "category"
              ? "No project categories found in application configuration."
              : "No service lines available. Link a purchase contract or configure service lines in app settings."
          }
        />
        {mode === "estimate" && selected.length > 0 && (
          <ProjectServiceLineEstimateTable
            readOnly={readOnly}
            permissionFlags={getServiceLineEstimatePermissionFlags(permission)}
            selectedLines={selected}
            serviceLineEstimate={serviceLineEstimate}
            parentServiceLineEstimate={parentServiceLineEstimate}
            onLineEstimateChange={this.onLineEstimateChange}
            options={options}
          />
        )}
      </>
    );
  };

  renderPopover = () => {
    if (!this.state.popoverOpen || this.props.readOnly) return null;

    return (
      <>
        <button
          type="button"
          className="lux-bid-tg-popover__backdrop"
          aria-label="Close service scope editor"
          onClick={this.closePopover}
        />
        <div
          id={POPOVER_ID}
          className={classNames("lux-bid-tg-popover", "lux-project-svc-popover")}
          role="dialog"
          aria-labelledby="lux-project-svc-popover-title"
        >
          <header className="lux-bid-tg-popover__head">
            <div>
              <h4 id="lux-project-svc-popover-title">{this.getTitle()}</h4>
              <p>{this.getSubtitle()}</p>
            </div>
            <button
              type="button"
              className="lux-bid-tg-popover__close"
              onClick={this.closePopover}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>
          <div className="lux-bid-tg-popover__body lux-project-svc-popover__body">
            {this.renderPopoverBody()}
          </div>
          <footer className="lux-bid-tg-popover__foot">
            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--ghost"
              onClick={this.closePopover}
            >
              Cancel
            </button>
            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--primary"
              onClick={this.closePopover}
            >
              Done
            </button>
          </footer>
        </div>
      </>
    );
  };

  render() {
    const mode = this.getMode();
    if (!mode) return null;

    const { readOnly, fieldConfig } = this.props;
    const selectedCount = this.getSelectedValues().length;
    const fieldName = this.getFieldName();
    const isMandatory =
      fieldConfig && fieldConfig.some((f) => f.name === fieldName && f.mandatory);
    const label =
      mode === "estimate"
        ? "Service lines & effort"
        : mode === "category"
        ? "Project categories"
        : "Service types";

    return (
      <div className="lux-project-svc-field lux-bid-tg-field" ref={this.rootRef}>
        <div className="lux-bid-tg-field__label-row">
          <label className="lux-bid-tg-field__label">
            {label}
            {isMandatory && <span className="lux-bid-tg-field__required">*</span>}
          </label>
          {!readOnly && (
            <button
              type="button"
              className={classNames("lux-bid-tg-field__edit-btn", {
                "is-open": this.state.popoverOpen,
              })}
              onClick={this.openPopover}
            >
              <i className="fe fe-layers" aria-hidden="true" />
              {selectedCount > 0 ? "Edit selection" : "Choose service types"}
            </button>
          )}
        </div>

        <div
          className={classNames("lux-bid-tg-field__surface lux-project-svc-field__surface", {
            "is-filled": selectedCount > 0,
          })}
        >
          <div className="lux-bid-tg-field__surface-head">
            <span className="lux-bid-tg-field__count">
              <strong>{selectedCount}</strong>
              <span>
                {mode === "category"
                  ? selectedCount === 1
                    ? "category"
                    : "categories"
                  : selectedCount === 1
                  ? "service type"
                  : "service types"}
              </span>
            </span>
          </div>
          <div className="lux-project-svc-field__surface-body">{this.renderSurfaceContent()}</div>
        </div>

        {this.renderPopover()}
      </div>
    );
  }
}

export default ProjectServiceScopeField;
