import envconfig from "env.config";
import { shouldUsePayrollManagement } from "config/tracopus-pilot.config";

export function isPayrollReadinessAiEnabled() {
  return envconfig.PAYROLL_READINESS_AI_ENABLED === true && shouldUsePayrollManagement();
}

export function shouldUsePayrollReadinessAiApi() {
  return envconfig.USE_PAYROLL_READINESS_AI_API === true && isPayrollReadinessAiEnabled();
}
