import React from "react";
import classNames from "classnames/bind";
import {
  WIZARD_STEP_STATUS,
  getWizardStatusLabel,
  summarizeWizardProgress,
} from "./createPanel.utils";

function LuxCreateWizardNav({
  stepStatuses,
  activeIndex,
  onSelect,
  disabled,
  layout = "rail",
}) {
  if (!stepStatuses || !stepStatuses.length) return null;

  const progress = summarizeWizardProgress(stepStatuses);

  return (
    <nav
      className={classNames("lux-create-wizard", `lux-create-wizard--${layout}`)}
      aria-label="Form progress"
    >
      <div className="lux-create-wizard__progress-head">
        <span className="lux-create-wizard__progress-label">Progress</span>
        <strong className="lux-create-wizard__progress-value">
          {progress.requiredTotal > 0
            ? `${progress.complete}/${progress.requiredTotal} required`
            : "No required steps"}
        </strong>
      </div>
      <div
        className="lux-create-wizard__progress-track"
        role="progressbar"
        aria-valuenow={progress.percent}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={`${progress.percent}% of steps complete`}
      >
        <span
          className="lux-create-wizard__progress-fill"
          style={{ width: `${progress.percent}%` }}
        />
      </div>

      <ol className="lux-create-wizard__list">
        {stepStatuses.map((step) => {
          const isActive = step.index === activeIndex;
          const statusLabel = getWizardStatusLabel(step.status);

          return (
            <li key={step.id} className="lux-create-wizard__item">
              <button
                type="button"
                className={classNames("lux-create-wizard__step", `is-${step.status}`, {
                  "is-active": isActive,
                })}
                disabled={disabled}
                onClick={() => onSelect(step.index)}
                aria-current={isActive ? "step" : undefined}
                title={`${step.title} — ${statusLabel}`}
              >
                <span className="lux-create-wizard__marker" aria-hidden="true">
                  {step.status === WIZARD_STEP_STATUS.COMPLETE && (
                    <i className="fe fe-check" />
                  )}
                  {step.status === WIZARD_STEP_STATUS.ATTENTION && (
                    <i className="fe fe-alert-circle" />
                  )}
                  {step.status === WIZARD_STEP_STATUS.ACTIVE && (
                    <span className="lux-create-wizard__marker-dot" />
                  )}
                  {step.status === WIZARD_STEP_STATUS.PENDING && (
                    <span className="lux-create-wizard__marker-num">{step.index + 1}</span>
                  )}
                  {step.status === WIZARD_STEP_STATUS.OPTIONAL && (
                    <i className="fe fe-circle" />
                  )}
                </span>
                <span className="lux-create-wizard__copy">
                  <strong>{step.title}</strong>
                  <span
                    className={classNames("lux-create-wizard__status", `is-${step.status}`)}
                  >
                    {statusLabel}
                  </span>
                </span>
                {layout === "rail" && (
                  <i className="fe fe-chevron-right lux-create-wizard__chevron" aria-hidden="true" />
                )}
              </button>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

export default LuxCreateWizardNav;
