/**
 * F25-T3–T6 — HR policy hub, versioning, campaigns, and AI assistant.
 */
import envconfig from "env.config";
import {
  shouldUseDocumentVault,
  shouldUsePolicyVersioningOrg,
  shouldUsePolicyCampaignsOrg,
} from "config/tracopus-pilot.config";

export const POLICY_VERSION_STATUSES = {
  DRAFT: "Draft",
  PUBLISHED: "Published",
  ARCHIVED: "Archived",
};

export const POLICY_CAMPAIGN_STATUSES = {
  SCHEDULED: "Scheduled",
  ACTIVE: "Active",
  COMPLETED: "Completed",
};

export const POLICY_AUDIT_ACTIONS = {
  PUBLISHED: "POLICY_PUBLISHED",
  ACKNOWLEDGED: "POLICY_ACKNOWLEDGED",
};

export function isPolicyHubEnabled() {
  return shouldUseDocumentVault();
}

export function shouldUsePolicyVersioning() {
  if (envconfig.POLICY_VERSIONING_ENABLED === true && isPolicyHubEnabled()) {
    return true;
  }
  return shouldUsePolicyVersioningOrg() && isPolicyHubEnabled();
}

export function shouldUsePolicyCampaigns() {
  if (envconfig.POLICY_CAMPAIGNS_ENABLED === true && isPolicyHubEnabled()) {
    return true;
  }
  return shouldUsePolicyCampaignsOrg() && isPolicyHubEnabled();
}

export function shouldUsePolicyAi() {
  // W1-E04 / DOC-008 — no live policy AI gateway; keep fail-closed until gateway exists.
  return false;
}

export function normalizePolicyVersion(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    policyId: row.policyId,
    version: row.version || "1.0",
    status: row.status || POLICY_VERSION_STATUSES.DRAFT,
    summary: row.summary || "",
    changes: Array.isArray(row.changes) ? row.changes : [],
    publishedAt: row.publishedAt || null,
    publishedBy: row.publishedBy || "",
    effectiveFrom: row.effectiveFrom || null,
  };
}

export function normalizePolicy(row) {
  if (!row) {
    return null;
  }
  const versions = (row.versions || []).map(normalizePolicyVersion).filter(Boolean);
  return {
    id: row.id,
    title: row.title || "Policy",
    category: row.category || "General",
    currentVersion: row.currentVersion || (versions[0] && versions[0].version) || "1.0",
    status: row.status || POLICY_VERSION_STATUSES.PUBLISHED,
    owner: row.owner || "HR Admin",
    updatedAt: row.updatedAt || null,
    summary: row.summary || "",
    versions,
    assignedCount: row.assignedCount != null ? row.assignedCount : null,
    acknowledgedCount: row.acknowledgedCount != null ? row.acknowledgedCount : null,
  };
}

export function normalizePolicyCampaign(row) {
  if (!row) {
    return null;
  }
  return {
    id: row.id,
    policyId: row.policyId,
    policyTitle: row.policyTitle || row.title || "Policy",
    version: row.version || "",
    status: row.status || POLICY_CAMPAIGN_STATUSES.ACTIVE,
    dueDate: row.dueDate || null,
    launchedAt: row.launchedAt || null,
    launchedBy: row.launchedBy || "HR Admin",
    audience: row.audience || "All employees",
    assignedCount: row.assignedCount != null ? row.assignedCount : 0,
    acknowledgedCount: row.acknowledgedCount != null ? row.acknowledgedCount : 0,
    description: row.description || "",
  };
}
