import { shouldUseIntegrationCenter } from "config/tracopus-pilot.config";
import { isDeveloperPortalEnabled } from "config/developer-portal.config";
import envconfig from "env.config";
import { isMockDataEnabled } from "mock/mock.config";

/** F18 — Integration center and connector adapters. */

export function isIntegrationCenterEnabled() {
  if (shouldUseIntegrationCenter()) {
    return true;
  }
  if (isMockDataEnabled()) {
    return true;
  }
  return envconfig.ENV_NAME === "development";
}

export function buildIntegrationsModuleAccess(roleIntegrationsModules) {
  const pilotOn = isIntegrationCenterEnabled();
  const role = roleIntegrationsModules || {};
  const roleOn = (key) => role[key] === true;
  const gate = (key, orgGate = pilotOn) => orgGate && roleOn(key);
  return {
    active:
      gate("hubEnabled") ||
      gate("syncHealthEnabled") ||
      gate("adaptersEnabled") ||
      gate("marketplaceEnabled", pilotOn && isDeveloperPortalEnabled()) ||
      gate("apiAccessEnabled", pilotOn && isDeveloperPortalEnabled()) ||
      gate("connectionsEnabled"),
    hubEnabled: gate("hubEnabled"),
    syncHealthEnabled: gate("syncHealthEnabled"),
    mappingEnabled: gate("mappingEnabled"),
    jobsEnabled: gate("jobsEnabled"),
    logsEnabled: gate("logsEnabled"),
    adaptersEnabled: gate("adaptersEnabled"),
    marketplaceEnabled: gate("marketplaceEnabled", pilotOn && isDeveloperPortalEnabled()),
    apiAccessEnabled: gate("apiAccessEnabled", pilotOn && isDeveloperPortalEnabled()),
    connectionsEnabled: gate("connectionsEnabled"),
  };
}

export function shouldUseIntegrationCenterApi() {
  return envconfig.USE_INTEGRATION_CENTER_API === true;
}

