import React, { useEffect } from "react";
import { createPortal } from "react-dom";
import { Link } from "react-router-dom";
import PropTypes from "prop-types";
import envconfig from "env.config";
import { listReleaseHistory, getCurrentAppVersion } from "config/app-release-history";
import { getVersionHistoryHref } from "config/version-history.routes";
import ReleaseHistoryList from "./ReleaseHistoryList";

function WhatsNewModal({ show, onClose, pathname }) {
  const appName = envconfig.APP_NAME || "Tracopus";
  const currentVersion = getCurrentAppVersion();
  const releases = listReleaseHistory();
  const historyHref = getVersionHistoryHref(pathname);

  useEffect(() => {
    if (!show) return undefined;

    const onKeyDown = (event) => {
      if (event.key === "Escape") onClose();
    };

    document.addEventListener("keydown", onKeyDown);
    document.body.classList.add("lux-legal-modal-open");

    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.classList.remove("lux-legal-modal-open");
    };
  }, [show, onClose]);

  if (!show || typeof document === "undefined") return null;

  return createPortal(
    <div
      className="lux-legal-modal lux-whats-new-modal"
      role="dialog"
      aria-modal="true"
      aria-labelledby="lux-whats-new-title"
      data-testid="whats-new-modal"
    >
      <button
        type="button"
        className="lux-legal-modal__backdrop"
        onClick={onClose}
        aria-label="Close what's new"
      />
      <div className="lux-legal-modal__panel">
        <header className="lux-legal-modal__head">
          <div className="lux-legal-modal__head-copy">
            <p className="lux-legal-modal__eyebrow">Release</p>
            <h2 id="lux-whats-new-title" className="lux-legal-modal__title">
              What&apos;s new
            </h2>
            <p className="lux-legal-modal__lede">
              {appName} v{currentVersion} · all previous versions included
            </p>
          </div>
          <div className="lux-legal-modal__head-actions">
            <button
              type="button"
              className="lux-legal-modal__close"
              onClick={onClose}
              aria-label="Close"
              data-testid="whats-new-modal-close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
        </header>
        <div className="lux-legal-modal__body">
          <ReleaseHistoryList releases={releases} currentVersion={currentVersion} compact />
        </div>
        <footer className="lux-legal-modal__footer lux-whats-new-modal__footer">
          <Link
            to={historyHref}
            className="lux-whats-new-modal__history"
            data-testid="whats-new-view-history"
            onClick={onClose}
          >
            View version history
          </Link>
          <button
            type="button"
            className="lux-legal-modal__done"
            onClick={onClose}
            data-testid="whats-new-modal-done"
          >
            Done
          </button>
        </footer>
      </div>
    </div>,
    document.body
  );
}

WhatsNewModal.propTypes = {
  show: PropTypes.bool,
  onClose: PropTypes.func.isRequired,
  pathname: PropTypes.string,
};

WhatsNewModal.defaultProps = {
  show: false,
  pathname: "",
};

export default WhatsNewModal;
