import React from "react";
import classNames from "classnames/bind";
import { PerformanceStatusBadge } from "views/performance/components/PerformanceLuxShared";

export default function ReviewCycleRegister({ cycles, loading }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  if (!cycles || !cycles.length) {
    return (
      <div className="lux-perf-empty">
        <i className="fe fe-calendar" aria-hidden="true" />
        <p>No review cycles yet.</p>
      </div>
    );
  }
  return (
    <div className="lux-perf-register">
      {cycles.map((cycle, index) => (
        <article key={cycle.id} className="lux-perf-register__row">
          <span className="lux-perf-register__index">{index + 1}</span>
          <span className={classNames("lux-perf-register__rail", cycle.tone && `is-${cycle.tone}`)}>
            <i className="fe fe-calendar" aria-hidden="true" />
          </span>
          <div className="lux-perf-register__main">
            <span className="lux-perf-register__eyebrow">{cycle.templateName}</span>
            <h3>{cycle.name}</h3>
            <p>{cycle.ownerName}</p>
            <div className="lux-perf-register__meta">
              <PerformanceStatusBadge status={cycle.status} />
              <span>{cycle.participantCount} participants</span>
              <span>{cycle.completionRate}% complete</span>
              {cycle.startDate && cycle.endDate ? <span>{cycle.startDate} → {cycle.endDate}</span> : null}
            </div>
          </div>
        </article>
      ))}
    </div>
  );
}
