import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";

export const systemErrorsService = {
  getOverview,
  listEvents,
  getEvent,
  updateEventStatus,
};

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function getOverview() {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.ADMIN_SYSTEM_ERRORS_API_PATH}/overview`,
    teamQuery()
  );
  return { payload: (response && response.payload) || response || {}, source: "api" };
}

async function listEvents(filters = {}) {
  const response = await axiosUtils.getWithParam(
    urlConfig.ADMIN_SYSTEM_ERRORS_API_PATH,
    teamQuery({
      status: filters.status === "ALL" ? undefined : filters.status,
      source: filters.source === "ALL" ? undefined : filters.source,
      severity: filters.severity,
      q: filters.q,
    })
  );
  const payload = (response && response.payload) || response || {};
  return {
    payload: {
      events: payload.events || [],
      count: payload.count != null ? payload.count : (payload.events || []).length,
    },
    source: "api",
  };
}

async function getEvent(eventRef) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.ADMIN_SYSTEM_ERRORS_API_PATH}/${eventRef}`,
    teamQuery()
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function updateEventStatus(eventRef, status) {
  const response = await axiosUtils.patch(
    `${urlConfig.ADMIN_SYSTEM_ERRORS_API_PATH}/${eventRef}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    { status }
  );
  return { payload: (response && response.payload) || response, source: "api" };
}
