import React from "react";
import { Link } from "react-router-dom";
import OnboardingStatusBadge from "./OnboardingStatusBadge";
import { getOnboardingCasePath, getOffboardingCasePath } from "config/onboarding.utils";

function getInitials(name = "") {
  return name
    .split(" ")
    .filter(Boolean)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function LifecycleCaseCard({ caseItem, lifecycle }) {
  const isOffboarding = lifecycle === "offboarding";
  const name = isOffboarding ? caseItem.employeeName : caseItem.candidateName;
  const path = isOffboarding
    ? getOffboardingCasePath(caseItem.id)
    : getOnboardingCasePath(caseItem.id);
  const pct = caseItem.readinessPct || 0;
  const blockedCount = (caseItem.tasks || []).filter((task) => task.status === "blocked").length;

  return (
    <Link to={path} className={`lux-onb-case-card ${isOffboarding ? "lux-onb-case-card--exit" : ""}`}>
      <div className="lux-onb-case-card__top">
        <div className="lux-onb-case-card__identity">
          <span className="lux-onb-case-card__avatar" aria-hidden>
            {getInitials(name)}
          </span>
          <div>
            <strong className="lux-onb-case-card__name">{name}</strong>
            <span className="lux-onb-case-card__role">{caseItem.role}</span>
          </div>
        </div>
        <OnboardingStatusBadge status={caseItem.status} lifecycle={lifecycle} />
      </div>

      <div className="lux-onb-case-card__meta">
        <span><i className="fe fe-briefcase" aria-hidden /> {caseItem.department}</span>
        <span><i className="fe fe-map-pin" aria-hidden /> {caseItem.location}</span>
        <span>
          <i className={`fe ${isOffboarding ? "fe-calendar" : "fe-flag"}`} aria-hidden />
          {isOffboarding ? `Last day ${caseItem.lastDay}` : `Starts ${caseItem.startDate}`}
        </span>
      </div>

      <div className="lux-onb-case-card__progress">
        <div className="lux-onb-case-card__progress-track" aria-hidden>
          <div className="lux-onb-case-card__progress-fill" style={{ width: `${pct}%` }} />
        </div>
        <div className="lux-onb-case-card__progress-labels">
          <span>{pct}% ready</span>
          <span>
            {caseItem.completedTasks != null && caseItem.totalTasks != null
              ? `${caseItem.completedTasks}/${caseItem.totalTasks} tasks`
              : `${caseItem.overdueCount || 0} overdue`}
          </span>
        </div>
      </div>

      <footer className="lux-onb-case-card__foot">
        <span className="lux-onb-case-card__owner">
          <i className="fe fe-user" aria-hidden /> {caseItem.owner || "HR"}
        </span>
        {isOffboarding && blockedCount > 0 && (
          <span className="lux-onb-case-card__alert">
            <i className="fe fe-alert-triangle" aria-hidden /> {blockedCount} blocked
          </span>
        )}
        {!isOffboarding && (caseItem.overdueCount || 0) > 0 && (
          <span className="lux-onb-case-card__alert">
            <i className="fe fe-clock" aria-hidden /> {caseItem.overdueCount} overdue
          </span>
        )}
        <span className="lux-onb-case-card__open">
          Open checklist <i className="fe fe-arrow-right" aria-hidden />
        </span>
      </footer>
    </Link>
  );
}

function LifecycleCaseCardGrid({ cases, loading, lifecycle }) {
  if (loading) {
    return (
      <div className="lux-onb-case-grid lux-onb-case-grid--loading" aria-busy="true">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-onb-case-card lux-onb-case-card--skeleton" />
        ))}
      </div>
    );
  }

  if (!cases.length) {
    return null;
  }

  return (
    <div className="lux-onb-case-grid">
      {cases.map((item) => (
        <LifecycleCaseCard key={item.id} caseItem={item} lifecycle={lifecycle} />
      ))}
    </div>
  );
}

export default LifecycleCaseCardGrid;
