import React, { PureComponent } from "react";
import classNames from "classnames/bind";

function getInitials(email) {
  if (!email) return "?";
  const local = email.split("@")[0] || "";
  const parts = local.replace(/[._-]/g, " ").split(" ").filter(Boolean);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return local.slice(0, 2).toUpperCase();
}

class InvoiceEmployeesModal extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { filterText: "" };
  }

  componentDidMount() {
    document.addEventListener("keydown", this.handleKeyDown);
    document.body.classList.add("lux-inv-emp-modal-open");
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
    document.body.classList.remove("lux-inv-emp-modal-open");
  }

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({ filterText: "" });
    }
  }

  handleKeyDown = (event) => {
    if (event.key === "Escape" && this.props.open) {
      this.props.onClose();
    }
  };

  onFilterChange = (event) => {
    this.setState({ filterText: event.target.value });
  };

  getFilteredEntries = () => {
    const { usersMap } = this.props;
    const entries = usersMap ? Object.keys(usersMap) : [];
    const needle = (this.state.filterText || "").trim().toLowerCase();
    if (!needle) return entries;
    return entries.filter(
      (id) =>
        id.toLowerCase().includes(needle) ||
        (usersMap[id] && usersMap[id].toLowerCase().includes(needle))
    );
  };

  render() {
    const { open, onClose, usersMap, invoiceLabel } = this.props;
    if (!open) return null;

    const filtered = this.getFilteredEntries();
    const total = usersMap ? Object.keys(usersMap).length : 0;

    return (
      <div
        className="lux-inv-emp-modal"
        role="dialog"
        aria-modal="true"
        aria-label="Billed employees"
      >
        <button
          type="button"
          className="lux-inv-emp-modal__backdrop"
          onClick={onClose}
          aria-label="Close billed employees"
        />

        <div className="lux-inv-emp-modal__dialog">
          <header className="lux-inv-emp-modal__header">
            <div className="lux-inv-emp-modal__header-main">
              <div className="lux-inv-emp-modal__icon">
                <i className="fe fe-users" aria-hidden="true" />
              </div>
              <div>
                <span className="lux-inv-emp-modal__eyebrow">Billed employees</span>
                <h2>{invoiceLabel || "Invoice"}</h2>
                <p>
                  {total} user{total === 1 ? "" : "s"} included in this billing cycle
                </p>
              </div>
            </div>
            <button
              type="button"
              className="lux-inv-emp-modal__close"
              onClick={onClose}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-inv-emp-modal__search-wrap">
            <label className="lux-inv-emp-modal__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                value={this.state.filterText}
                onChange={this.onFilterChange}
                placeholder="Search by employee ID or email…"
                aria-label="Search billed employees"
              />
              {this.state.filterText && (
                <button
                  type="button"
                  className="lux-inv-emp-modal__search-clear"
                  onClick={() => this.setState({ filterText: "" })}
                  aria-label="Clear search"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              )}
            </label>
            <span className="lux-inv-emp-modal__count-pill">
              {filtered.length} of {total}
            </span>
          </div>

          <div className="lux-inv-emp-modal__list" role="list">
            {filtered.map((employeeId, index) => {
              const email = usersMap[employeeId];
              return (
                <article
                  key={employeeId}
                  className="lux-inv-emp-modal__row"
                  role="listitem"
                >
                  <span className="lux-inv-emp-modal__avatar">{getInitials(email)}</span>
                  <div className="lux-inv-emp-modal__row-copy">
                    <strong>{employeeId}</strong>
                    <a href={`mailto:${email}`}>{email}</a>
                  </div>
                  <span className="lux-inv-emp-modal__row-index">#{index + 1}</span>
                </article>
              );
            })}
            {!filtered.length && (
              <div className="lux-inv-emp-modal__empty">
                <i className="fe fe-user-x" aria-hidden="true" />
                <span>No employees match your search.</span>
              </div>
            )}
          </div>

          <footer className="lux-inv-emp-modal__footer">
            <span>
              <i className="fe fe-info" aria-hidden="true" />
              These users were counted for the monthly licence fee on this invoice.
            </span>
            <button type="button" className="lux-inv-emp-modal__done-btn" onClick={onClose}>
              Done
            </button>
          </footer>
        </div>
      </div>
    );
  }
}

export default InvoiceEmployeesModal;
