import React from "react";
import classNames from "classnames/bind";
import TimesheetLuxuryDialog from "./TimesheetLuxuryDialog";

const COPY = {
  clear: {
    ariaLabel: "Confirm clear week hours",
    kicker: "Destructive action",
    kickerIcon: "fe-alert-triangle",
    title: "Clear week hours?",
    badge: { tone: "rose", label: "Cannot undo" },
    lead:
      "This removes draft and editable hours for the selected week. Approved and pending-approval days are not cleared.",
    bullets: [
      "Draft and rejected editable entries are deleted for this week",
      "Approved day batches stay locked — managers must reopen them first",
      "Days awaiting manager approval are not removed",
      "Export or copy hours elsewhere first if you may need them later",
    ],
    confirmLabel: "Yes, clear all hours",
    cancelLabel: "Keep my hours",
    tone: "danger",
  },
  withdraw: {
    ariaLabel: "Confirm withdraw timesheet",
    kicker: "Pending submission",
    kickerIcon: "fe-rotate-ccw",
    title: "Withdraw timesheet?",
    badge: { tone: "amber", label: "Reversible" },
    lead:
      "Pull this week back from manager approval. Your logged hours stay intact so you can edit and submit again.",
    bullets: [
      "The pending approval request is cancelled",
      "Hours remain on the board as an editable draft",
      "You can fix entries and resubmit when ready",
      "Managers will no longer see this week in their pending queue",
    ],
    confirmLabel: "Yes, withdraw submission",
    cancelLabel: "Keep pending",
    tone: "info",
  },
};

function TimesheetDiscardConfirmDialog({
  show,
  type,
  weekLabel,
  inProgress,
  onConfirm,
  onDismiss,
}) {
  const variant = COPY[type === "withdraw" ? "withdraw" : "clear"];

  return (
    <TimesheetLuxuryDialog
      show={show}
      onClose={onDismiss}
      ariaLabel={variant.ariaLabel}
      kicker={variant.kicker}
      kickerIcon={variant.kickerIcon}
      title={variant.title}
      subtitle={weekLabel ? `Week · ${weekLabel}` : "This week"}
      badge={variant.badge}
      panelClassName={classNames("lux-ts-discard-dialog", `is-${variant.tone}`)}
      footer={
        <div className="lux-ts-discard-dialog__actions">
          <button
            type="button"
            className="lux-ts-discard-dialog__btn is-ghost"
            disabled={inProgress}
            onClick={onDismiss}
          >
            {variant.cancelLabel}
          </button>
          <button
            type="button"
            className={classNames("lux-ts-discard-dialog__btn", {
              "is-danger": variant.tone === "danger",
              "is-primary": variant.tone !== "danger",
              "is-loading": inProgress,
            })}
            disabled={inProgress}
            onClick={onConfirm}
            data-testid="timesheet-discard-confirm"
          >
            {inProgress ? "Working…" : variant.confirmLabel}
          </button>
        </div>
      }
    >
      <div
        className={classNames("lux-ts-discard-dialog__alert", `is-${variant.tone}`)}
        role="alert"
      >
        <span className="lux-ts-discard-dialog__alert-icon" aria-hidden="true">
          <i className={`fe ${variant.kickerIcon}`} />
        </span>
        <div className="lux-ts-discard-dialog__alert-copy">
          <strong>Please confirm before continuing</strong>
          <p>{variant.lead}</p>
        </div>
      </div>
      <section className="lux-ts-discard-dialog__impacts" aria-label="What will happen">
        <h4>What happens next</h4>
        <ul>
          {variant.bullets.map((line) => (
            <li key={line}>
              <i className="fe fe-chevron-right" aria-hidden="true" />
              <span>{line}</span>
            </li>
          ))}
        </ul>
      </section>
    </TimesheetLuxuryDialog>
  );
}

export default TimesheetDiscardConfirmDialog;
