import React from "react";

/**
 * Prev / today / next month controls (shared with page header calendar nav styles).
 */
export default function LuxCalendarNav({
  onBack,
  onToday,
  onNext,
  disabled,
  className,
}) {
  return (
    <div
      className={["lux-page-header__calendar-nav", className].filter(Boolean).join(" ")}
      role="group"
      aria-label="Calendar navigation"
    >
      <button
        type="button"
        className="lux-page-header__calendar-btn"
        onClick={onBack}
        disabled={disabled}
        title="Previous month"
        aria-label="Previous month"
      >
        <i className="fa fa-chevron-left" aria-hidden="true" />
      </button>
      <button
        type="button"
        className="lux-page-header__calendar-btn"
        onClick={onToday}
        disabled={disabled}
        title="Current month"
        aria-label="Current month"
      >
        <i className="fa fa-home" aria-hidden="true" />
      </button>
      <button
        type="button"
        className="lux-page-header__calendar-btn"
        onClick={onNext}
        disabled={disabled}
        title="Next month"
        aria-label="Next month"
      >
        <i className="fa fa-chevron-right" aria-hidden="true" />
      </button>
    </div>
  );
}
