import React, { Component } from "react";
import { vendorInvoicesService } from "_services/vendorInvoices.service";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";

/**
 * Thin detail view for /vendors/invoices/:id (ref).
 */
class VendorInvoiceDetailPage extends Component {
  state = {
    loading: true,
    loadError: null,
    invoice: null,
    documentRef: "",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Vendor invoice");
    }
    this.loadData();
  }

  resolveRef = () => {
    const { match } = this.props;
    return match && match.params ? match.params.id : null;
  };

  loadData = async () => {
    const ref = this.resolveRef();
    this.setState({ loading: true, loadError: null });
    if (!ref) {
      this.setState({ loading: false, loadError: new Error("Missing invoice ref") });
      return;
    }
    const result = await vendorInvoicesService.getByRef(ref);
    if (result.source === "api" && result.payload) {
      this.setState({
        loading: false,
        invoice: result.payload,
        documentRef: result.payload.documentRef || "",
        loadError: null,
      });
    } else {
      this.setState({
        loading: false,
        invoice: null,
        loadError: result.error || new Error("Unable to load invoice"),
      });
    }
  };

  handleAttach = async (event) => {
    event.preventDefault();
    const ref = this.resolveRef();
    const { documentRef } = this.state;
    if (!ref || !documentRef) return;
    const result = await vendorInvoicesService.attachDocument(ref, documentRef);
    if (result.source === "api") {
      this.loadData();
    } else {
      this.setState({ loadError: result.error || new Error("Attach failed") });
    }
  };

  render() {
    const { loading, loadError, invoice, documentRef } = this.state;
    return (
      <FinanceLuxPage
        testId="vendor-invoice-detail-page"
        pageMeta={{
          tone: "slate",
          icon: "fe fe-file",
          eyebrow: "Vendors",
          titleLead: "Invoice",
          titleAccent: invoice ? invoice.vendorInvoiceRef : "detail",
          lede: "Vendor invoice detail with Document Vault link attach.",
        }}
        dataSource="api"
        demoLabel={null}
        loading={loading}
      >
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load vendor invoice."
          onDismiss={() => this.setState({ loadError: null })}
        />
        {invoice && (
          <FinanceLuxPanel title="Details">
            <dl className="row small mb-0">
              <dt className="col-sm-3">Status</dt>
              <dd className="col-sm-9">{invoice.status}</dd>
              <dt className="col-sm-3">Vendor</dt>
              <dd className="col-sm-9">{invoice.vendorId}</dd>
              <dt className="col-sm-3">Invoice #</dt>
              <dd className="col-sm-9">{invoice.invoiceNumber}</dd>
              <dt className="col-sm-3">Project</dt>
              <dd className="col-sm-9">{invoice.projectId}</dd>
              <dt className="col-sm-3">PO / Task</dt>
              <dd className="col-sm-9">
                {invoice.purchaseOrderId || "—"} / {invoice.taskId || "—"}
              </dd>
              <dt className="col-sm-3">Amount</dt>
              <dd className="col-sm-9">
                {invoice.currency || "USD"} {invoice.amount}
              </dd>
              <dt className="col-sm-3">Payment</dt>
              <dd className="col-sm-9">{invoice.paymentStatus || "UNPAID"}</dd>
              <dt className="col-sm-3">Document</dt>
              <dd className="col-sm-9">{invoice.documentRef || "—"}</dd>
            </dl>
          </FinanceLuxPanel>
        )}
        <FinanceLuxPanel title="Attach Document Vault ref" className="mt-3">
          <form onSubmit={this.handleAttach} className="d-flex flex-wrap gap-2 align-items-end">
            <label className="small mb-0 flex-grow-1">
              documentRef
              <input
                className="form-control form-control-sm"
                value={documentRef}
                onChange={(e) => this.setState({ documentRef: e.target.value })}
                required
              />
            </label>
            <FinanceActionButton type="submit" variant="primary">
              Attach
            </FinanceActionButton>
          </form>
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default VendorInvoiceDetailPage;
