import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { INTEGRATION_HUB_PAGE_META } from "config/integration-center-nav.config";
import { buildIntegrationHubKpis } from "config/integration-center.utils";
import { integrationCenterService } from "_services/integrationCenter.service";
import IntegrationsLuxPage, {
  IntegrationActionButton,
  IntegrationInsightPanel,
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import ConnectorRegister, { ConnectorDetailDrawer } from "views/integrations/components/ConnectorRegister";
import { SyncHealthSnapshot, SyncJobsRegister } from "views/integrations/components/IntegrationRegisters";

class IntegrationHubPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    kpiCards: [],
    insights: [],
    connectors: [],
    summary: null,
    recentJobs: [],
    selectedConnector: null,
    drawerConnector: null,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await integrationCenterService.getHubOverview();
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        kpiCards: buildIntegrationHubKpis(payload.summary),
        insights: payload.insights || [],
        connectors: payload.connectors || [],
        summary: payload.summary || null,
        recentJobs: payload.recentJobs || [],
        selectedConnector: (payload.connectors && payload.connectors[0]) || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load integration hub.",
      });
    }
  };

  handleExport = async () => {
    try {
      const result = await integrationCenterService.exportConnectorsCsv();
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "connectors.csv";
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to export connectors." });
    }
  };

  render() {
    if (!isIntegrationCenterEnabled()) {
      return <PersonaAccessDenied title="Integration hub" message="Integration center is not enabled for this organization." />;
    }

    const {
      loading,
      loadError,
      dataSource,
      kpiCards,
      insights,
      connectors,
      summary,
      recentJobs,
      selectedConnector,
      drawerConnector,
    } = this.state;

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_HUB_PAGE_META}
        pageId="hub"
        shellTitle="Integration hub"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><IntegrationActionButton icon="fe fe-download" onClick={this.handleExport}>
              Export CSV
            </IntegrationActionButton>
          </>}
      >
        {loadError ? <p className="lux-integ-error">{loadError}</p> : null}
        <IntegrationInsightPanel insights={insights} />
        <SyncHealthSnapshot summary={summary} loading={loading} />

        <IntegrationLuxPanel
          title="Connector registry"
          meta="Trust scores, sync posture, and adapter metadata"
          icon="fe fe-link"
          accent="blue"
          featured
        >
          <ConnectorRegister
            connectors={connectors}
            loading={loading}
            selectedId={selectedConnector && selectedConnector.id}
            onSelect={(row) => this.setState({ drawerConnector: row, selectedConnector: row })}
          />
        </IntegrationLuxPanel>

        <IntegrationLuxPanel title="Recent sync jobs" meta="Latest import/export activity" icon="fe fe-repeat" accent="amber">
          <SyncJobsRegister jobs={recentJobs} loading={loading} />
        </IntegrationLuxPanel>

        <ConnectorDetailDrawer connector={drawerConnector} onClose={() => this.setState({ drawerConnector: null })} />
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationHubPage;
