/**
 * @param {string} moduleId - SIDEBAR_GROUPS id (e.g. "people")
 * @param {{ path?: string, navGroup?: string, navGroupLabel?: string }} item
 * @returns {SidebarNavGroup}
 */
export function resolveSidebarNavGroup(moduleId, item) {
  if (item && item.navGroup) {
    return {
      id: String(item.navGroup),
      label: item.navGroupLabel != null ? item.navGroupLabel : String(item.navGroup),
    };
  }
  const path = (item && item.path) || "";
  const rules = MODULE_NAV_GROUP_RULES[moduleId] || [];
  for (let i = 0; i < rules.length; i += 1) {
    if (rules[i].test(path, item)) {
      return { id: rules[i].id, label: rules[i].label };
    }
  }
  return { id: "general", label: null };
}

/**
 * Annotate visible items with group metadata for separator rendering.
 * Preserves input order. Headers only at the start of each consecutive run.
 *
 * @param {string} moduleId
 * @param {Array} items
 * @returns {Array<{ item: object, group: SidebarNavGroup, showGroupHeader: boolean }>}
 */
export function annotateSidebarItemsWithNavGroups(moduleId, items) {
  const list = Array.isArray(items) ? items : [];
  let prevId = null;
  return list.map((item) => {
    const group = resolveSidebarNavGroup(moduleId, item);
    const showGroupHeader = Boolean(group.label) && group.id !== prevId;
    prevId = group.id;
    return { item, group, showGroupHeader };
  });
}

/**
 * Fold items into ordered sections — one section per group id.
 * Section order follows MODULE_NAV_GROUP_RULES; within a section, catalog order is kept.
 *
 * @param {string} moduleId
 * @param {Array} items
 * @returns {Array<{ id: string, label: string|null, items: Array }>}
 */
export function groupSidebarItemsByNavGroup(moduleId, items) {
  const list = Array.isArray(items) ? items : [];
  if (!list.length) {
    return [];
  }

  const rules = MODULE_NAV_GROUP_RULES[moduleId] || [];
  const ruleOrder = rules.map((rule) => rule.id);
  const buckets = new Map();

  list.forEach((item) => {
    const group = resolveSidebarNavGroup(moduleId, item);
    if (!buckets.has(group.id)) {
      buckets.set(group.id, {
        id: group.id,
        label: group.label,
        items: [],
      });
    }
    buckets.get(group.id).items.push(item);
  });

  const sections = [];
  const seen = new Set();

  ruleOrder.forEach((id) => {
    if (!buckets.has(id) || seen.has(id)) {
      return;
    }
    seen.add(id);
    sections.push(buckets.get(id));
  });

  buckets.forEach((section, id) => {
    if (seen.has(id)) {
      return;
    }
    sections.push(section);
  });

  return sections.filter((section) => section.items && section.items.length);
}

/**
 * Pinned daily-use links shown first and always expanded.
 * Display order follows `paths` (not raw catalog order).
 * Uses id "pinned" so it never clashes with feature-group ids.
 */
export const PINNED_CORE_BY_MODULE = {
  people: {
    id: "pinned",
    label: null,
    paths: [
      "/people/dashboard",
      "/people/employees",
      "/people/attendance",
      "/people/leaves",
      "/people/timesheet",
    ],
  },
  payroll: {
    id: "pinned",
    label: null,
    paths: [
      "/payroll/dashboard",
      "/payroll/groups",
      "/payroll/runs",
      "/payroll/paychecks",
    ],
  },
  projects: {
    id: "pinned",
    label: null,
    paths: ["/project/dashboard", "/project/list", "/project/portfolio"],
  },
  finance: {
    id: "pinned",
    label: null,
    paths: [
      "/finance/dashboard",
      "/finance/accounts",
      "/finance/purchaseorders",
      "/finance/invoice",
    ],
  },
  resources: {
    id: "pinned",
    label: null,
    paths: [
      "/project/capacity",
      "/resources/staffing-requests",
      "/resources/skills",
    ],
  },
};

/**
 * @param {string} pathname
 * @param {Array<{ id: string, items: Array }>} sections
 * @returns {string|null}
 */
export function findActiveSidebarNavSectionId(pathname, sections) {
  const path = (pathname || "").split("?")[0];
  if (!path || !Array.isArray(sections)) {
    return null;
  }
  for (let i = 0; i < sections.length; i += 1) {
    const section = sections[i];
    const hit = (section.items || []).some((item) => {
      const itemPath = item && item.path;
      return itemPath && (path === itemPath || path.startsWith(`${itemPath}/`));
    });
    if (hit) {
      return section.id;
    }
  }
  return sections[0] ? sections[0].id : null;
}

/**
 * Build context-menu sections: pinned core first (always open), then
 * collapsible feature groups for the remaining catalog items.
 *
 * @param {string} moduleId
 * @param {Array} items
 * @returns {Array<{ id: string, label: string|null, items: Array, pinned: boolean }>}
 */
export function buildModuleContextSections(moduleId, items) {
  const list = Array.isArray(items) ? items : [];
  const pinnedConfig = PINNED_CORE_BY_MODULE[moduleId];
  if (!pinnedConfig || !pinnedConfig.paths || !pinnedConfig.paths.length) {
    return groupSidebarItemsByNavGroup(moduleId, list).map((section) => ({
      ...section,
      pinned: false,
    }));
  }

  const byPath = new Map();
  list.forEach((item) => {
    if (item && item.path && !byPath.has(item.path)) {
      byPath.set(item.path, item);
    }
  });

  const pinnedPathSet = new Set(pinnedConfig.paths);
  const pinnedItems = pinnedConfig.paths
    .map((path) => byPath.get(path))
    .filter(Boolean);
  const rest = list.filter((item) => item && item.path && !pinnedPathSet.has(item.path));

  const sections = [];
  if (pinnedItems.length) {
    sections.push({
      id: pinnedConfig.id || "pinned",
      label: pinnedConfig.label != null ? pinnedConfig.label : null,
      items: pinnedItems,
      pinned: true,
    });
  }

  groupSidebarItemsByNavGroup(moduleId, rest).forEach((section) => {
    if (!section.items || !section.items.length) {
      return;
    }
    sections.push({
      ...section,
      pinned: false,
    });
  });

  return sections;
}
