import React from "react";
import classNames from "classnames/bind";
import { ONBOARDING_TASK_CATEGORIES } from "config/onboarding.config";
import {
  getDueDateDelta,
  groupTasksByCategory,
  isTaskOverdue,
  resolveTaskStatusMeta,
} from "config/onboarding.utils";

function taskIcon(status) {
  if (status === "completed") return "fe-check-circle";
  if (status === "in_progress") return "fe-loader";
  if (status === "blocked") return "fe-alert-circle";
  return "fe-circle";
}

function categoryTone(categoryId) {
  const tones = {
    Documents: "violet",
    Payroll: "green",
    Training: "primary",
    HR: "amber",
    IT: "rose",
    Manager: "neutral",
  };
  return tones[categoryId] || "primary";
}

function SelfServiceTaskPanel({ tasks, statusFilter, onTaskSelect, loading }) {
  const filtered = tasks || [];
  const groups = groupTasksByCategory(filtered, ONBOARDING_TASK_CATEGORIES);

  if (loading) {
    return (
      <section className="lux-onb-self-service__panel">
        <div className="lux-onb-self-service__skeleton" aria-hidden>
          {[1, 2, 3].map((key) => (
            <div key={key} className="lux-onb-self-service__skeleton-card" />
          ))}
        </div>
      </section>
    );
  }

  if (!filtered.length) {
    return (
      <section className="lux-onb-self-service__panel">
        <div className="lux-onb-self-service__empty">
          <span className="lux-onb-self-service__empty-icon" aria-hidden>
            <i className="fe fe-check-circle" />
          </span>
          <h3>
            {statusFilter === "COMPLETED"
              ? "No completed tasks yet"
              : statusFilter === "ACTION"
                ? "You're all caught up"
                : "No tasks assigned"}
          </h3>
          <p>
            {statusFilter === "ACTION"
              ? "Great work — check back if HR adds new onboarding steps."
              : "Your onboarding checklist will appear here when tasks are assigned to you."}
          </p>
        </div>
      </section>
    );
  }

  return (
    <section className="lux-onb-self-service__panel" aria-label="My onboarding tasks">
      {groups.map((group) => {
        const tone = categoryTone(group.id);
        const completed = group.tasks.filter(
          (task) => task.status === "completed" || task.status === "skipped"
        ).length;
        const pct = group.tasks.length
          ? Math.round((completed / group.tasks.length) * 100)
          : 0;

        return (
          <article
            key={group.id}
            className={classNames("lux-onb-checklist__group", `lux-onb-checklist__group--${tone}`)}
          >
            <header className="lux-onb-checklist__group-head">
              <div className="lux-onb-checklist__group-brand">
                <span className="lux-onb-checklist__group-icon" aria-hidden>
                  <i className={group.icon || "fe fe-check-square"} />
                </span>
                <div>
                  <h3 className="lux-onb-checklist__group-title">{group.label}</h3>
                  <p className="lux-onb-checklist__group-sub">
                    {completed} of {group.tasks.length} complete
                  </p>
                </div>
              </div>
              <span className="lux-onb-checklist__group-pill">{pct}%</span>
            </header>

            <div className="lux-onb-checklist__group-progress" aria-hidden>
              <div
                className="lux-onb-checklist__group-progress-fill"
                style={{ width: `${pct}%` }}
              />
            </div>

            <ul className="lux-onb-checklist__tasks">
              {group.tasks.map((task, index) => {
                const overdue = isTaskOverdue(task);
                const dueDelta = getDueDateDelta(task);
                const statusMeta = resolveTaskStatusMeta(task.status);
                const isActionable =
                  task.status !== "completed" &&
                  task.status !== "skipped" &&
                  task.status !== "blocked";

                return (
                  <li key={task.id}>
                    <button
                      type="button"
                      className={classNames("lux-onb-task lux-onb-task--self-service", `lux-onb-task--${tone}`, {
                        "is-overdue": overdue,
                        "is-completed": task.status === "completed" || task.status === "skipped",
                        "is-actionable": isActionable,
                      })}
                      onClick={() => onTaskSelect(task)}
                    >
                      <span className="lux-onb-task__index">{index + 1}</span>
                      <span className={`lux-onb-task__state fe ${taskIcon(task.status)}`} aria-hidden />
                      <span className="lux-onb-task__body">
                        <strong className="lux-onb-task__title">{task.title}</strong>
                        <span className="lux-onb-task__meta">
                          <span className={classNames("lux-onb-task__status-chip", `is-${statusMeta.tone}`)}>
                            {statusMeta.label}
                          </span>
                          {dueDelta && (
                            <span
                              className={classNames("lux-onb-task__due-chip", {
                                "is-overdue": overdue,
                              })}
                            >
                              {dueDelta.label}
                            </span>
                          )}
                          {task.required && (
                            <span className="lux-onb-task__required-chip">Required</span>
                          )}
                        </span>
                      </span>
                      <span className="lux-onb-task__cta">
                        {isActionable ? "Open" : "View"}
                        <i className="fe fe-chevron-right" aria-hidden />
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </article>
        );
      })}
    </section>
  );
}

export default SelfServiceTaskPanel;
