import React from "react";
import classNames from "classnames/bind";

export default function FileManagerBreadcrumb({ trail, onNavigate }) {
  if (!trail || trail.length === 0) return null;

  return (
    <nav className="lux-file-breadcrumb" aria-label="Folder path">
      <ol className="lux-file-breadcrumb__list">
        {trail.map((crumb, index) => {
          const isLast = index === trail.length - 1;
          return (
            <li key={crumb.id} className="lux-file-breadcrumb__item">
              {index > 0 && (
                <span className="lux-file-breadcrumb__sep" aria-hidden="true">
                  /
                </span>
              )}
              {isLast ? (
                <span
                  className={classNames("lux-file-breadcrumb__current", {
                    "is-root": index === 0,
                  })}
                  aria-current="page"
                >
                  {index === 0 && <i className="fe fe-home" aria-hidden="true" />}
                  {crumb.name}
                </span>
              ) : (
                <button
                  type="button"
                  className="lux-file-breadcrumb__link"
                  onClick={() => onNavigate && onNavigate(crumb.id)}
                >
                  {index === 0 && <i className="fe fe-home" aria-hidden="true" />}
                  {crumb.name}
                </button>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}
