import React from "react";
import PropTypes from "prop-types";
import classNames from "classnames/bind";

function ReleaseHistoryList({ releases, currentVersion, compact }) {
  const rows = Array.isArray(releases) ? releases : [];

  if (rows.length === 0) {
    return (
      <p className="lux-release-history__empty" data-testid="release-history-empty">
        No release notes have been published yet.
      </p>
    );
  }

  return (
    <ol
      className={classNames("lux-release-history", compact && "is-compact")}
      data-testid="release-history-list"
    >
      {rows.map((release) => {
        const isCurrent = release.version === currentVersion;
        const highlights = Array.isArray(release.highlights) ? release.highlights : [];
        return (
          <li
            key={release.version}
            className={classNames("lux-release-history__item", isCurrent && "is-current")}
            data-testid={`release-history-item-${release.version}`}
          >
            <header className="lux-release-history__head">
              <div className="lux-release-history__identity">
                <p className="lux-release-history__version">v{release.version}</p>
                {release.date ? (
                  <p className="lux-release-history__date">{release.date}</p>
                ) : null}
              </div>
              {isCurrent ? (
                <span className="lux-release-history__badge">Current</span>
              ) : null}
            </header>
            {highlights.length > 0 ? (
              <ul className="lux-release-history__highlights">
                {highlights.map((item, index) => (
                  <li key={`${release.version}-${index}`}>{item}</li>
                ))}
              </ul>
            ) : (
              <p className="lux-release-history__empty-notes">No highlights recorded for this version.</p>
            )}
          </li>
        );
      })}
    </ol>
  );
}

ReleaseHistoryList.propTypes = {
  releases: PropTypes.arrayOf(
    PropTypes.shape({
      version: PropTypes.string.isRequired,
      date: PropTypes.string,
      highlights: PropTypes.arrayOf(PropTypes.string),
    })
  ),
  currentVersion: PropTypes.string,
  compact: PropTypes.bool,
};

ReleaseHistoryList.defaultProps = {
  releases: [],
  currentVersion: "",
  compact: false,
};

export default ReleaseHistoryList;
