export const LUX_PHONE_MQ = "(max-width: 767px)";
export const LUX_PHONE_CLASS = "lux-phone";
export const OFFCANVAS_CLASS = "offcanvas-active";
export const LUX_NAV_OPEN_CLASS = "lux-nav-open";
export const LUX_OFFCANVAS_CHANGED = "lux-offcanvas-changed";

function resolveDocument(doc) {
  return doc || (typeof document !== "undefined" ? document : null);
}

function resolveWindow(win) {
  return win || (typeof window !== "undefined" ? window : null);
}

export function isLuxPhone(win) {
  const mediaWindow = resolveWindow(win);
  return !!(mediaWindow && mediaWindow.matchMedia && mediaWindow.matchMedia(LUX_PHONE_MQ).matches);
}

export function applyLuxPhoneClass(matches, doc) {
  const target = resolveDocument(doc);
  if (!target || !target.body) {
    return false;
  }
  target.body.classList.toggle(LUX_PHONE_CLASS, !!matches);
  return !!matches;
}

export function isOffcanvasNavOpen(doc) {
  const target = resolveDocument(doc);
  return !!(target && target.body && target.body.classList.contains(OFFCANVAS_CLASS));
}

function emitOffcanvasChanged(open, doc) {
  const target = resolveDocument(doc);
  const mediaWindow = (target && target.defaultView) || resolveWindow();
  if (!mediaWindow || typeof mediaWindow.dispatchEvent !== "function") {
    return;
  }
  mediaWindow.dispatchEvent(
    new CustomEvent(LUX_OFFCANVAS_CHANGED, {
      detail: { open: !!open },
    })
  );
}

export function setOffcanvasNavOpen(open, doc) {
  const target = resolveDocument(doc);
  if (!target || !target.body) {
    return false;
  }
  const next = open === true;
  target.body.classList.toggle(OFFCANVAS_CLASS, next);
  target.body.classList.toggle(LUX_NAV_OPEN_CLASS, next);
  emitOffcanvasChanged(next, target);
  return next;
}

export function toggleOffcanvasNav(doc) {
  return setOffcanvasNavOpen(!isOffcanvasNavOpen(doc), doc);
}

export function closeOffcanvasNav(doc) {
  return setOffcanvasNavOpen(false, doc);
}

export function bindLuxPhoneMedia(win, doc) {
  const mediaWindow = resolveWindow(win);
  const target = resolveDocument(doc);
  if (!mediaWindow || !mediaWindow.matchMedia) {
    return () => {};
  }
  const mq = mediaWindow.matchMedia(LUX_PHONE_MQ);
  const sync = () => applyLuxPhoneClass(mq.matches, target);
  sync();
  if (typeof mq.addEventListener === "function") {
    mq.addEventListener("change", sync);
    return () => {
      mq.removeEventListener("change", sync);
      applyLuxPhoneClass(false, target);
    };
  }
  if (typeof mq.addListener === "function") {
    mq.addListener(sync);
    return () => {
      mq.removeListener(sync);
      applyLuxPhoneClass(false, target);
    };
  }
  return () => applyLuxPhoneClass(false, target);
}
