import React, { Component } from "react";
import { commonUtils } from "_helpers";
import { projectService } from "_services/project.service";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";

/**
 * W1-E02 — Project closure readiness + initiate + sign-off against live APIs.
 */
class ProjectClosurePanel extends Component {
  state = {
    projectId: "",
    readiness: null,
    loading: false,
    actionBusy: false,
    error: null,
    actionMessage: null,
    dataSource: null,
    signOffNote: "",
  };

  componentDidMount() {
    const options = this.props.projectOptions || [];
    const first = options.find((row) => row.id && row.id !== "ALL");
    if (first) {
      this.setState({ projectId: String(first.id) }, () => this.loadReadiness());
    }
  }

  componentDidUpdate(prevProps) {
    const prevIds = (prevProps.projectOptions || []).map((r) => r.id).join(",");
    const nextIds = (this.props.projectOptions || []).map((r) => r.id).join(",");
    if (prevIds !== nextIds && !this.state.projectId) {
      const first = (this.props.projectOptions || []).find((row) => row.id && row.id !== "ALL");
      if (first) {
        this.setState({ projectId: String(first.id) }, () => this.loadReadiness());
      }
    }
  }

  loadReadiness = async () => {
    const { projectId } = this.state;
    if (!projectId) {
      this.setState({ readiness: null, error: "Select a project to load closure readiness." });
      return;
    }
    this.setState({ loading: true, error: null, actionMessage: null });
    const result = await projectService.getClosureReadiness(projectId);
    if (!result || result.source === "api-error" || !result.payload) {
      this.setState({
        loading: false,
        readiness: null,
        dataSource: "api-error",
        error: "Unable to load closure readiness from the live API.",
      });
      return;
    }
    this.setState({
      loading: false,
      readiness: result.payload,
      dataSource: result.source,
    });
  };

  handleProjectChange = (event) => {
    this.setState({ projectId: event.target.value, readiness: null, actionMessage: null }, () => {
      if (event.target.value) {
        this.loadReadiness();
      }
    });
  };

  handleInitiate = async (force = false) => {
    const { projectId } = this.state;
    this.setState({ actionBusy: true, error: null, actionMessage: null });
    const result = await projectService.initiateClosure(projectId, { force });
    if (!result || result.source === "api-error" || !result.payload) {
      const err = result && result.error;
      const responseData = err && err.response && err.response.data;
      const message =
        (err && (err.message || (responseData && responseData.message))) ||
        "Closure initiate failed. Resolve blockers or retry with force if authorized.";
      this.setState({ actionBusy: false, error: String(message) });
      return;
    }
    this.setState({
      actionBusy: false,
      readiness: result.payload,
      actionMessage: `Closure initiated · workflow ${result.payload.workflowStatus || "updated"}`,
      dataSource: result.source,
    });
  };

  handleSignOff = async () => {
    const { projectId, signOffNote } = this.state;
    this.setState({ actionBusy: true, error: null, actionMessage: null });
    const result = await projectService.recordClosureSignOff(projectId, {
      actorId: commonUtils.getCurrentUserId(),
      note: signOffNote || undefined,
    });
    if (!result || result.source === "api-error" || !result.payload) {
      const err = result && result.error;
      const responseData = err && err.response && err.response.data;
      const message =
        (err && (err.message || (responseData && responseData.message))) ||
        "Closure sign-off failed. Initiate closure first when readiness allows.";
      this.setState({ actionBusy: false, error: String(message) });
      return;
    }
    const statusNote = result.payload.statusClosed
      ? " · project status CLOSED"
      : result.payload.archived
        ? " · archived"
        : "";
    this.setState({
      actionBusy: false,
      readiness: result.payload,
      actionMessage: `Sign-off recorded${statusNote}`,
      dataSource: result.source,
    });
    if (typeof this.props.onClosed === "function") {
      this.props.onClosed(result.payload);
    }
  };

  renderBlockers(readiness) {
    const blockers = Array.isArray(readiness && readiness.blockers) ? readiness.blockers : [];
    const checks = (readiness && (readiness.checks || readiness.checklist)) || null;
    if (blockers.length === 0 && !checks) {
      return <p className="lux-gov-closure__ok">No open blockers reported.</p>;
    }
    return (
      <div className="lux-gov-closure__lists">
        {blockers.length > 0 ? (
          <ul className="lux-gov-closure__blockers" aria-label="Closure blockers">
            {blockers.map((item, index) => (
              <li key={`blocker-${index}`}>{typeof item === "string" ? item : JSON.stringify(item)}</li>
            ))}
          </ul>
        ) : null}
        {checks && typeof checks === "object" ? (
          <ul className="lux-gov-closure__checks" aria-label="Closure checks">
            {Object.keys(checks).map((key) => (
              <li key={key}>
                <strong>{key}</strong>: {String(checks[key])}
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    );
  }

  render() {
    const { projectOptions = [] } = this.props;
    const { projectId, readiness, loading, actionBusy, error, actionMessage, dataSource, signOffNote } =
      this.state;
    const options = projectOptions.filter((row) => row.id && row.id !== "ALL");
    const ready = readiness && readiness.ready === true;
    const workflowStatus = (readiness && readiness.workflowStatus) || "NOT_STARTED";
    const canSignOff =
      readiness &&
      ["INITIATED", "READY_TO_CLOSE", "AWAITING_SIGN_OFF"].includes(String(workflowStatus).toUpperCase());

    return (
      <div className="lux-gov-closure" data-testid="project-closure-panel">
        <div className="lux-gov-closure__controls">
          <label>
            Project
            <select value={projectId} onChange={this.handleProjectChange} disabled={loading || actionBusy}>
              <option value="">Select project</option>
              {options.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label || option.name || option.id}
                </option>
              ))}
            </select>
          </label>
          <ResourcesActionButton
            type="button"
            icon="fe fe-refresh-cw"
            variant="ghost"
            onClick={this.loadReadiness}
            disabled={!projectId || loading || actionBusy}
          >
            Refresh readiness
          </ResourcesActionButton>
        </div>

        {loading ? <p className="lux-gov-closure__status">Loading closure readiness…</p> : null}
        {error ? <p className="lux-gov-closure__error" role="alert">{error}</p> : null}
        {actionMessage ? <p className="lux-gov-closure__ok">{actionMessage}</p> : null}

        {readiness ? (
          <>
            <div className="lux-gov-closure__summary" aria-live="polite">
              <span className={ready ? "is-ready" : "is-blocked"}>
                {ready ? "Ready for closure" : "Not ready"}
              </span>
              <span>Workflow: {workflowStatus}</span>
              {dataSource ? <span>Source: {dataSource}</span> : null}
            </div>
            {this.renderBlockers(readiness)}
            <div className="lux-gov-closure__actions">
              <ResourcesActionButton
                type="button"
                icon="fe fe-flag"
                onClick={() => this.handleInitiate(false)}
                disabled={!projectId || actionBusy || String(workflowStatus).toUpperCase() === "SIGNED_OFF"}
              >
                Initiate closure
              </ResourcesActionButton>
              {!ready ? (
                <ResourcesActionButton
                  type="button"
                  icon="fe fe-alert-triangle"
                  variant="ghost"
                  onClick={() => this.handleInitiate(true)}
                  disabled={!projectId || actionBusy}
                >
                  Force initiate
                </ResourcesActionButton>
              ) : null}
              <label className="lux-gov-closure__note">
                Sign-off note
                <input
                  type="text"
                  value={signOffNote}
                  onChange={(e) => this.setState({ signOffNote: e.target.value })}
                  disabled={!canSignOff || actionBusy}
                  placeholder="Optional note"
                />
              </label>
              <ResourcesActionButton
                type="button"
                icon="fe fe-check-circle"
                onClick={this.handleSignOff}
                disabled={!canSignOff || actionBusy}
              >
                Record sign-off
              </ResourcesActionButton>
            </div>
          </>
        ) : null}
      </div>
    );
  }
}

export default ProjectClosurePanel;
