import moment from "moment";
import dateUtils from "_helpers/date.utils";
import { TIMESHEET_TYPE_KEYS } from "./timesheetSummary.utils";
import { formatEntryTotalLabel, getDayHeaderMeta } from "./timesheetBoard.utils";
import {
  normalizeTimesheetStatus,
  readAttributeValue,
} from "./timesheetSummary.utils";
import {
  buildApprovalReviewContext,
  resolveApprovalReviewHighlightDates,
  toIsoDate,
} from "./timesheetApproval.utils";

export function resolveTimesheetApprovalItemContext(item) {
  const meta = (item && item.metadata) || {};
  const sourceId = String((item && item.sourceId) || "");
  let submissionId =
    meta.submissionId != null && meta.submissionId !== "" ? meta.submissionId : null;
  let weekId = meta.weekId != null && meta.weekId !== "" ? meta.weekId : null;

  if (!submissionId && sourceId.toUpperCase().startsWith("SUBMISSION:")) {
    submissionId = sourceId.slice("SUBMISSION:".length);
  }
  if (!weekId && sourceId.toUpperCase().startsWith("WEEK:")) {
    weekId = sourceId.slice("WEEK:".length);
  }
  if (!weekId && !submissionId && sourceId && !sourceId.includes(":")) {
    weekId = sourceId;
  }

  const activityDates = Array.isArray(meta.activityDates)
    ? meta.activityDates.map(toIsoDate).filter(Boolean)
    : [];

  const employeeId = resolveTimesheetApprovalEmployeeId(meta, item);
  const weekStartDate = resolveTimesheetApprovalWeekStartDate(meta, item, activityDates);
  const weekEndDate =
    toIsoDate(meta.weekEndDate) ||
    toIsoDate(meta.dateTo) ||
    toIsoDate(item && item.dueLabel) ||
    null;

  return {
    weekId,
    submissionId,
    employeeId,
    weekStartDate,
    weekEndDate,
    activityDates,
    employeeName:
      meta.employeeName ||
      (item && item.requester && String(item.requester).split(" · ")[0].trim()) ||
      (item && item.requester) ||
      null,
  };
}

export function resolveTimesheetApprovalEmployeeId(meta = {}, item) {
  if (meta.employeeId != null && meta.employeeId !== "") {
    return meta.employeeId;
  }
  if (item && item.requesterId != null && item.requesterId !== "") {
    return item.requesterId;
  }
  return null;
}

/** Derive ISO week-start (yyyy-MM-dd) when API/live inbox metadata omits weekStartDate. */
export function resolveTimesheetApprovalWeekStartDate(meta = {}, item, activityDates = []) {
  const direct = toIsoDate(meta.weekStartDate || meta.week_start_date);
  if (direct) {
    return moment(direct).startOf("isoWeek").format("YYYY-MM-DD");
  }

  const dateFrom = toIsoDate(meta.dateFrom || meta.date_from);
  if (dateFrom) {
    return moment(dateFrom).startOf("isoWeek").format("YYYY-MM-DD");
  }

  const dates = activityDates.length
    ? activityDates
    : Array.isArray(meta.activityDates)
      ? meta.activityDates.map(toIsoDate).filter(Boolean)
      : [];
  if (dates.length) {
    return moment(dates[0]).startOf("isoWeek").format("YYYY-MM-DD");
  }

  const weekEnd =
    toIsoDate(meta.weekEndDate || meta.week_end_date) || toIsoDate(item && item.dueLabel);
  if (weekEnd) {
    return moment(weekEnd).startOf("isoWeek").format("YYYY-MM-DD");
  }

  return null;
}

export function enrichTimesheetApprovalInboxItem(item) {
  if (!item || item.domain !== "TIMESHEET") {
    return item;
  }
  const meta = { ...(item.metadata || {}) };
  const employeeId = resolveTimesheetApprovalEmployeeId(meta, item);
  const activityDates = Array.isArray(meta.activityDates)
    ? meta.activityDates.map(toIsoDate).filter(Boolean)
    : [];
  const weekStartDate = resolveTimesheetApprovalWeekStartDate(meta, item, activityDates);

  if (employeeId != null) {
    meta.employeeId = employeeId;
  }
  if (weekStartDate) {
    meta.weekStartDate = weekStartDate;
  }
  if (!meta.weekEndDate && item.dueLabel) {
    meta.weekEndDate = item.dueLabel;
  }

  const detailPath =
    item.detailPath && String(item.detailPath).includes("approvalReview=1")
      ? item.detailPath
      : buildTimesheetApprovalDetailPath({
          weekId: meta.weekId,
          employeeId,
          weekStartDate,
          submissionId: meta.submissionId,
          activityDates: meta.activityDates,
        });

  return {
    ...item,
    requesterId: item.requesterId != null ? item.requesterId : employeeId,
    metadata: meta,
    detailPath,
  };
}

export function buildTimesheetApprovalDetailPath(weekOrContext) {
  if (!weekOrContext) {
    return "/people/timesheet";
  }
  const params = new URLSearchParams();
  const employeeId = weekOrContext.employeeId;
  const weekStartDate = toIsoDate(weekOrContext.weekStartDate);
  const weekId = weekOrContext.weekId != null ? weekOrContext.weekId : weekOrContext.id;
  const submissionId = weekOrContext.submissionId;

  if (employeeId != null && employeeId !== "") {
    params.set("employeeId", String(employeeId));
  }
  if (weekStartDate) {
    params.set("weekStart", weekStartDate);
  }
  if (weekId != null && weekId !== "") {
    params.set("weekId", String(weekId));
  }
  if (submissionId != null && submissionId !== "") {
    params.set("submissionId", String(submissionId));
  }
  params.set("approvalReview", "1");

  const query = params.toString();
  return query ? `/people/timesheet?${query}` : "/people/timesheet";
}

export function parseTimesheetApprovalReviewSearch(search) {
  if (!search) {
    return null;
  }
  const params = new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
  if (params.get("approvalReview") !== "1") {
    return null;
  }
  const weekId = params.get("weekId");
  const submissionId = params.get("submissionId");
  const employeeId = params.get("employeeId");
  const weekStartDate = params.get("weekStart");
  if (!employeeId || !weekStartDate) {
    return null;
  }
  return buildApprovalReviewContext({
    id: weekId,
    employeeId,
    weekStartDate,
    submissionId,
    activityDates: [],
  });
}

function isPendingApprovalEntry(entry) {
  const status = normalizeTimesheetStatus(
    readAttributeValue(entry && entry.status) || readAttributeValue(entry && entry.timesheetStatus)
  );
  return status === "PENDING" || status === "PENDING_APPROVAL";
}

function entryMatchesApprovalBatch(entry, dateKey, context, highlightDates) {
  if (!entry || entry.isDeleted === true) {
    return false;
  }
  const mins = parseInt(entry.timesheetTimeMins || 0, 10);
  if (mins <= 0) {
    return false;
  }
  const iso = toIsoDate(dateKey);
  if (!iso || !highlightDates.has(iso)) {
    return false;
  }
  if (!isPendingApprovalEntry(entry)) {
    return false;
  }
  if (context.submissionId != null && context.submissionId !== "") {
    if (
      entry.submissionId != null &&
      String(entry.submissionId) !== String(context.submissionId)
    ) {
      return false;
    }
  }
  return true;
}

function forEachPendingBatchEntry(timeSheetRequest, context, highlightDates, visitor) {
  TIMESHEET_TYPE_KEYS.forEach((sectionKey) => {
    const groups = (timeSheetRequest && timeSheetRequest[sectionKey]) || {};
    Object.entries(groups).forEach(([groupId, group]) => {
      (group.tasks || []).forEach((task) => {
        Object.entries(task.timeEntry || {}).forEach(([dateKey, entry]) => {
          if (!entryMatchesApprovalBatch(entry, dateKey, context, highlightDates)) {
            return;
          }
          visitor({
            sectionKey,
            groupId,
            group,
            task,
            dateKey,
            entry,
            iso: toIsoDate(dateKey),
          });
        });
      });
    });
  });
}

export function buildTimesheetApprovalPreviewModel(timeSheetRequest, item) {
  const context = resolveTimesheetApprovalItemContext(item);
  const reviewContext = buildApprovalReviewContext({
    id: context.weekId,
    employeeId: context.employeeId,
    weekStartDate: context.weekStartDate,
    submissionId: context.submissionId,
    activityDates: context.activityDates,
    employeeName: context.employeeName,
  });

  const weekStart = context.weekStartDate
    ? moment(context.weekStartDate)
    : moment().startOf("isoWeek");
  const weekDates = dateUtils
    .getCurrentWeekDateArray(weekStart)
    .map((dateObject) => dateObject.value);

  const highlightDates = resolveApprovalReviewHighlightDates(
    reviewContext,
    timeSheetRequest,
    weekDates
  );
  const previewDates =
    highlightDates.size > 0
      ? weekDates.filter((dateKey) => highlightDates.has(toIsoDate(dateKey)))
      : weekDates;

  const daySummaryByIso = new Map(
    previewDates.map((dateKey) => [
      toIsoDate(dateKey),
      {
        dateKey,
        iso: toIsoDate(dateKey),
        label: `${getDayHeaderMeta(dateKey).dayShort} ${getDayHeaderMeta(dateKey).dayNum}`,
        totalMins: 0,
        entryCount: 0,
      },
    ])
  );

  forEachPendingBatchEntry(timeSheetRequest, context, highlightDates, ({ iso, entry }) => {
    if (!iso || !daySummaryByIso.has(iso)) {
      return;
    }
    const summary = daySummaryByIso.get(iso);
    summary.totalMins += parseInt(entry.timesheetTimeMins || 0, 10);
    summary.entryCount += 1;
  });

  const daySummaries = Array.from(daySummaryByIso.values()).map((summary) => ({
    ...summary,
    hoursLabel: dateUtils.minuteToHourString(summary.totalMins) || "0.00",
  }));

  const entriesByKey = new Map();
  forEachPendingBatchEntry(timeSheetRequest, context, highlightDates, ({
    sectionKey,
    groupId,
    group,
    task,
    iso,
    entry,
  }) => {
    const label =
      sectionKey === "project"
        ? [task.taskName, task.workItemName].filter(Boolean).join(" · ") || group.projectName
        : task.workItemName || groupId;
    const entryKey = `${sectionKey}-${groupId}-${task.lineId || task.taskName || label}`;
    if (!entriesByKey.has(entryKey)) {
      entriesByKey.set(entryKey, {
        key: entryKey,
        sectionKey,
        groupLabel:
          sectionKey === "project"
            ? [group.projectCode, group.projectName].filter(Boolean).join(" · ")
            : groupId,
        label,
        category: task.taskActCategory || null,
        hoursByDate: {},
        totalMins: 0,
      });
    }
    const row = entriesByKey.get(entryKey);
    const mins = parseInt(entry.timesheetTimeMins || 0, 10);
    row.hoursByDate[iso] = (row.hoursByDate[iso] || 0) + mins;
    row.totalMins += mins;
  });

  const entries = Array.from(entriesByKey.values())
    .map((row) => ({
      ...row,
      totalLabel: formatEntryTotalLabel(row.totalMins),
    }))
    .sort((a, b) => a.label.localeCompare(b.label));

  const batchTotalMins = daySummaries.reduce((sum, day) => sum + day.totalMins, 0);

  return {
    context,
    reviewContext,
    previewDates,
    daySummaries,
    entries,
    batchTotalMins,
    batchTotalLabel: formatEntryTotalLabel(batchTotalMins),
    hasHours: batchTotalMins > 0,
  };
}
