import React from "react";
import classNames from "classnames/bind";
import { getFileMimeMeta } from "./fileManager.utils";

export default function FileManagerGridView({
  items,
  onOpenItem,
  onDownload,
  onShare,
}) {
  if (!items || items.length === 0) return null;

  return (
    <div className="lux-file-grid" role="list" aria-label="Files and folders grid">
      {items.map((item) => {
        const meta = getFileMimeMeta(item.mimeKind);
        const isFolder = item.type === "folder";
        return (
          <article
            key={item.id}
            className={classNames("lux-file-grid__card", `is-${meta.tone}`, {
              "is-folder": isFolder,
            })}
            role="listitem"
          >
            <button
              type="button"
              className="lux-file-grid__open"
              onClick={() => onOpenItem && onOpenItem(item)}
            >
              <span className={classNames("lux-file-grid__icon", `is-${meta.tone}`)} aria-hidden="true">
                <i className={meta.icon} />
              </span>
              <span className="lux-file-grid__name" title={item.name}>
                {item.name}
              </span>
              <span className="lux-file-grid__meta">
                {item.lastUpdatedLabel}
                {!isFolder && item.sizeLabel !== "—" && (
                  <>
                    <span className="lux-file-grid__dot">·</span>
                    {item.sizeLabel}
                  </>
                )}
              </span>
              {item.isShared && (
                <span className="lux-file-grid__badge">
                  <i className="fe fe-users" aria-hidden="true" /> Shared
                </span>
              )}
            </button>
            <div className="lux-file-grid__actions">
              {isFolder ? (
                <button
                  type="button"
                  className="lux-file-grid__action"
                  title="Open folder"
                  onClick={() => onOpenItem && onOpenItem(item)}
                >
                  <i className="fe fe-arrow-right" aria-hidden="true" />
                </button>
              ) : (
                <button
                  type="button"
                  className="lux-file-grid__action"
                  title="Download"
                  onClick={() => onDownload && onDownload(item)}
                >
                  <i className="fe fe-download" aria-hidden="true" />
                </button>
              )}
              <button
                type="button"
                className="lux-file-grid__action"
                title="Share"
                onClick={() => onShare && onShare(item)}
              >
                <i className="fe fe-share-2" aria-hidden="true" />
              </button>
            </div>
          </article>
        );
      })}
    </div>
  );
}
