import React from "react";

function LifecycleChecklistHeader({ progress, lifecycle = "onboarding" }) {
  const isOffboarding = lifecycle === "offboarding";
  const pct = progress ? Math.round((progress.completed / progress.total) * 100) : 0;

  return (
    <header className="lux-onb-checklist-hero">
      <div className="lux-onb-checklist-hero__main">
        <span className="lux-onb-checklist-hero__eyebrow">
          <i className={`fe ${isOffboarding ? "fe-user-x" : "fe-user-plus"}`} aria-hidden />
          Lifecycle checklist
        </span>
        <h2 className="lux-onb-checklist-hero__title">Task checklist</h2>
        <p className="lux-onb-checklist-hero__desc">
          Complete required steps by category. Tap a task to review details and mark complete.
        </p>
      </div>

      {progress && (
        <div className="lux-onb-checklist-hero__stats">
          <div
            className="lux-onb-checklist-hero__ring"
            style={{ "--lux-onb-pct": pct }}
            aria-label={`${pct}% complete`}
          >
            <span>{pct}%</span>
          </div>
          <div className="lux-onb-checklist-hero__figures">
            <article>
              <span>Done</span>
              <strong>{progress.completed}/{progress.total}</strong>
            </article>
            <article>
              <span>Overdue</span>
              <strong className={progress.overdue > 0 ? "is-alert" : ""}>{progress.overdue}</strong>
            </article>
          </div>
        </div>
      )}
    </header>
  );
}

export default LifecycleChecklistHeader;
