/**
 * Instant sidebar selection helpers.
 *
 * Causes this fights:
 * 1) React overwrites DOM classes on re-render before paint
 * 2) Heavy page mounts block paint after history.push
 * 3) Stale module-rail selection can show the wrong submenu for a frame
 *
 * Strategy: keep a module-level pending path + injected CSS (survives React),
 * paint that first, then navigate on the next frames.
 */

import { history } from "_helpers";

const STYLE_ID = "lux-sidebar-pending-nav-style";
let pendingPath = null;
const listeners = new Set();

export function getPendingSidebarPath() {
  return pendingPath;
}

export function subscribePendingSidebarPath(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function notifyListeners() {
  listeners.forEach((listener) => {
    try {
      listener(pendingPath);
    } catch (err) {
      // ignore subscriber errors
    }
  });
}

export function isModifiedNavClick(event) {
  return Boolean(
    event &&
      (event.metaKey ||
        event.ctrlKey ||
        event.shiftKey ||
        event.altKey ||
        event.button === 1)
  );
}

function escapeAttrSelector(value) {
  if (typeof CSS !== "undefined" && typeof CSS.escape === "function") {
    return CSS.escape(value);
  }
  return String(value).replace(/["\\]/g, "\\$&");
}

function ensurePendingStyleEl() {
  if (typeof document === "undefined") {
    return null;
  }
  let el = document.getElementById(STYLE_ID);
  if (!el) {
    el = document.createElement("style");
    el.id = STYLE_ID;
    document.head.appendChild(el);
  }
  return el;
}

export function clearPendingSidebarSelection() {
  pendingPath = null;
  if (typeof document !== "undefined") {
    const root = document.getElementById("left-sidebar");
    if (root) {
      root.removeAttribute("data-pending-nav");
    }
    const styleEl = document.getElementById(STYLE_ID);
    if (styleEl) {
      styleEl.textContent = "";
    }
  }
  notifyListeners();
}

export function setPendingSidebarSelection(path) {
  if (!path) {
    clearPendingSidebarSelection();
    return;
  }
  pendingPath = path;

  if (typeof document !== "undefined") {
    const root = document.getElementById("left-sidebar");
    if (root) {
      root.setAttribute("data-pending-nav", path);
    }

    const styleEl = ensurePendingStyleEl();
    if (styleEl) {
      const href = escapeAttrSelector(path);
      // Mirror active submenu styles without depending on React classNames.
      styleEl.textContent = `
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] a.lux-nav__child[href="${href}"],
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] a.lux-nav__child[href="${href}"] span {
  color: var(--lux-primary-dark) !important;
}
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] a.lux-nav__child[href="${href}"] {
  font-weight: 700 !important;
  background: linear-gradient(90deg, rgba(var(--lux-primary-rgb), 0.14), rgba(var(--lux-accent-rgb), 0.08)) !important;
  border: 1px solid rgba(var(--lux-primary-rgb), 0.16) !important;
  box-shadow: none !important;
}
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] a.lux-nav__child[href="${href}"]::before {
  background: var(--lux-primary) !important;
  box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb), 0.18) !important;
  transform: scale(1.05);
}
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] a.lux-nav__child.active:not([href="${href}"]),
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] li.active:not(:has(> a[href="${href}"])) > .lux-nav__child {
  color: var(--lux-muted) !important;
  font-weight: 500 !important;
  background: transparent !important;
  border-color: transparent !important;
}
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] a.lux-nav__child.active:not([href="${href}"])::before,
#left-sidebar.lux-sidebar[data-pending-nav="${href}"] li.active:not(:has(> a[href="${href}"])) > .lux-nav__child::before {
  background: rgba(148, 163, 184, 0.55) !important;
  box-shadow: none !important;
  transform: none !important;
}
`;
    }
  }

  notifyListeners();
}

export function syncPendingSidebarSelectionWithLocation(pathname) {
  if (!pendingPath || !pathname) {
    return;
  }
  if (pathname === pendingPath || pathname.startsWith(`${pendingPath}/`)) {
    clearPendingSidebarSelection();
  }
}

export function navigateWithOptimisticSidebarSelection({ event, path, markPending }) {
  if (!path) {
    return false;
  }

  setPendingSidebarSelection(path);
  if (typeof markPending === "function") {
    markPending(path);
  }

  if (isModifiedNavClick(event)) {
    return false;
  }

  if (event && typeof event.preventDefault === "function") {
    event.preventDefault();
  }

  const navHistory = history;
  if (!navHistory || typeof navHistory.push !== "function") {
    return true;
  }

  const current =
    navHistory.location && navHistory.location.pathname
      ? navHistory.location.pathname
      : "";
  if (current === path) {
    clearPendingSidebarSelection();
    return true;
  }

  const push = () => {
    navHistory.push(path);
  };

  // Yield so the pending CSS can paint before the destination page mounts.
  if (typeof window !== "undefined" && typeof window.requestAnimationFrame === "function") {
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(push);
    });
  } else {
    setTimeout(push, 0);
  }
  return true;
}
