/**
 * Version history is available on every authenticated shell prefix so the
 * home-page footer can stay in the current module. Login is excluded.
 */
export const VERSION_HISTORY_MODULES = [
  "workspace",
  "people",
  "hrms",
  "project",
  "sales",
  "finance",
  "resources",
  "payroll",
  "performance",
  "analytics",
  "admin",
  "recruiting",
  "learning",
  "benefits",
  "npd",
  "dossiers",
  "vendors",
  "delivery",
  "integrations",
  "ai",
  "report",
  "client",
];

export const VERSION_HISTORY_PATH_SUFFIX = "/version-history";

export const VERSION_HISTORY_ROUTE_PATH = `/:modulePrefix(${VERSION_HISTORY_MODULES.join(
  "|"
)})${VERSION_HISTORY_PATH_SUFFIX}`;

export const VERSION_HISTORY_CANONICAL_HREF = "/workspace/version-history";

export function isVersionHistoryPath(pathname) {
  const path = String(pathname || "")
    .split("?")[0]
    .replace(/\/+$/, "");
  return VERSION_HISTORY_MODULES.some((modulePrefix) => path === `/${modulePrefix}${VERSION_HISTORY_PATH_SUFFIX}`);
}

export function getVersionHistoryHref(pathname) {
  const segment = String(pathname || "")
    .split("/")
    .filter(Boolean)[0];
  if (segment && VERSION_HISTORY_MODULES.indexOf(segment) >= 0) {
    return `/${segment}${VERSION_HISTORY_PATH_SUFFIX}`;
  }
  return VERSION_HISTORY_CANONICAL_HREF;
}
