import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isEmployeeFinanceEnabled } from "config/employee-finance.config";
import { EMPLOYEE_FINANCE_PAGE_META } from "config/employee-finance-nav.config";
import { employeeFinanceService } from "_services/employeeFinance.service";
import EmployeeFinanceLuxPage, {
  EmployeeFinanceActionButton,
  EmployeeFinanceInsightPanel,
  EmployeeFinanceLuxPanel,
} from "views/payroll/components/EmployeeFinanceLuxShared";
import BenefitPlansPanel from "views/payroll/components/BenefitPlansPanel";

class BenefitsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    dataSource: null,
    plans: [],
    kpiCards: [],
    insights: [],
    filters: { query: "", status: "ALL" },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Benefits");
    }
    this.loadData();
  }

  loadData = async (filters = this.state.filters) => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await employeeFinanceService.getBenefitsOverview(filters);
      const overview = result.payload || {};
      this.setState({
        loading: false,
        plans: overview.plans || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load benefit plans.",
      });
    }
  };

  handleFilterChange = (patch) => {
    const filters = { ...this.state.filters, ...patch };
    this.setState({ filters }, () => this.loadData(filters));
  };

  handleCreatePlan = async () => {
    this.setState({ saving: true });
    try {
      await employeeFinanceService.saveBenefitPlan({
        name: "Wellness expansion pilot",
        code: "WELL-PILOT",
        category: "WELLNESS",
        provider: "Internal",
        status: "DRAFT",
        employerContributionUsd: 100,
        employeeContributionUsd: 0,
        enrolledCount: 0,
        effectiveFrom: "2026-10-01",
      });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to create benefit plan." });
    } finally {
      this.setState({ saving: false });
    }
  };

  render() {
    if (!isEmployeeFinanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Benefits" />;
    }

    const { loading, loadError, saving, dataSource, plans, kpiCards, insights, filters } = this.state;
    const meta = EMPLOYEE_FINANCE_PAGE_META.benefits;

    return (
      <EmployeeFinanceLuxPage
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo benefit plans"
        loading={loading}
        kpiCards={kpiCards}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={
          <>
            <EmployeeFinanceActionButton to="/payroll/compensation" icon="fe fe-trending-up" variant="ghost">
              Compensation
            </EmployeeFinanceActionButton>
            <EmployeeFinanceActionButton to="/payroll/employee-finance" icon="fe fe-pie-chart" variant="primary">
              Employee finance
            </EmployeeFinanceActionButton>
          </>
        }
      >
        <EmployeeFinanceInsightPanel insights={insights} />
        {loadError ? (
          <EmployeeFinanceLuxPanel title="Benefits load issue" meta={loadError} accent="rose">
            <EmployeeFinanceActionButton icon="fe fe-refresh-cw" variant="primary" onClick={() => this.loadData()}>
              Retry
            </EmployeeFinanceActionButton>
          </EmployeeFinanceLuxPanel>
        ) : null}
        <EmployeeFinanceLuxPanel title={meta.panelTitle} meta={meta.panelMeta} icon="fe fe-heart" accent="green">
          <BenefitPlansPanel
            plans={plans}
            loading={loading}
            filters={filters}
            onFilterChange={this.handleFilterChange}
            onCreatePlan={this.handleCreatePlan}
            saving={saving}
          />
        </EmployeeFinanceLuxPanel>
      </EmployeeFinanceLuxPage>
    );
  }
}

export default BenefitsPage;
