import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPaychecksEnabled, isPayslipPdfEnabled, shouldUsePayrollApi } from "config/payroll.config";
import { canDownloadPayslipPdf, canPublishPaycheck, canRetractPaycheck, resolveIndianFinancialYear } from "config/paycheck.utils";
import { commonUtils } from "_helpers";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import PayslipDetailView from "views/payroll/components/PayslipDetailView";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
} from "views/payroll/components/PayrollLuxShared";

class PaycheckDetailPage extends Component {
  state = {
    paycheck: null,
    loading: true,
    loadError: null,
    dataSource: null,
    acting: false,
    downloading: false,
    downloadingForm16: false,
  };

  componentDidMount() {
    this.loadPaycheck();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.match.params.paycheckId !== this.props.match.params.paycheckId) {
      this.loadPaycheck();
    }
  }

  loadPaycheck = async () => {
    const { paycheckId } = this.props.match.params;
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.getPaycheck(paycheckId);
      const paycheck = result.payload;
      this.setState({
        paycheck,
        loading: false,
        dataSource: result.source || null,
        loadError: paycheck ? null : "Paycheck not found.",
      });
      if (paycheck) {
        this.props.pageHeaderNameChangeHandler(`${paycheck.employeeName} · ${paycheck.periodLabel}`);
      }
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load paycheck.", paycheck: null });
    }
  };

  handlePublish = async () => {
    const { paycheck } = this.state;
    if (!paycheck) return;
    this.setState({ acting: true });
    try {
      await payrollService.publishPaycheck(paycheck.id);
      await this.loadPaycheck();
    } finally {
      this.setState({ acting: false });
    }
  };

  handleRetract = async () => {
    const { paycheck } = this.state;
    if (!paycheck) return;
    this.setState({ acting: true });
    try {
      await payrollService.retractPaycheck(paycheck.id);
      await this.loadPaycheck();
    } finally {
      this.setState({ acting: false });
    }
  };

  handleDownloadPdf = async () => {
    const { paycheck } = this.state;
    if (!paycheck || !canDownloadPayslipPdf(paycheck) || !isPayslipPdfEnabled()) {
      return;
    }
    this.setState({ downloading: true });
    try {
      await payrollService.downloadPaycheckPdf(paycheck.id);
    } catch (e) {
      this.setState({ loadError: "Unable to download payslip PDF." });
    } finally {
      this.setState({ downloading: false });
    }
  };

  handleDownloadForm16 = async () => {
    const { paycheck } = this.state;
    if (!paycheck || !shouldUsePayrollApi()) {
      this.setState({ loadError: "Form 16 estimate requires payroll API." });
      return;
    }
    const employeeId = paycheck.employeeId || commonUtils.getCurrentUserId();
    const fy = resolveIndianFinancialYear(paycheck.payDate || paycheck.periodEnd);
    this.setState({ downloadingForm16: true, loadError: null });
    try {
      const result = await payrollService.downloadForm16(employeeId, fy);
      if (!result || !result.payload) {
        this.setState({ loadError: "Unable to download Form 16 estimate." });
      }
    } catch (e) {
      this.setState({ loadError: "Unable to download Form 16 estimate." });
    } finally {
      this.setState({ downloadingForm16: false });
    }
  };

  render() {
    if (!isPaychecksEnabled()) {
      return <PersonaAccessDenied moduleName="Paycheck detail" reason="Paycheck management is not enabled." />;
    }

    const { paycheck, loading, loadError, dataSource, acting, downloading, downloadingForm16 } = this.state;
    const employeeView = this.props.location.pathname.indexOf("/workspace/") === 0;
    const showPdfDownload =
      isPayslipPdfEnabled() && canDownloadPayslipPdf(paycheck);
    const showForm16Download = shouldUsePayrollApi() && paycheck;

    const backTo = employeeView ? "/workspace/my-paychecks" : "/payroll/paychecks";
    const pageMeta = {
      tone: "green",
      icon: "fe fe-dollar-sign",
      eyebrow: employeeView ? "My paychecks" : "Payroll · Paycheck",
      titleLead: paycheck ? paycheck.employeeName || "Paycheck" : "Paycheck",
      titleAccent: paycheck && paycheck.periodLabel ? paycheck.periodLabel : "detail",
      lede: "Earnings, deductions, and year-to-date totals for this payslip.",
    };
    const backAction = (
      <PayrollActionButton to={backTo} icon="fe fe-arrow-left" variant="ghost">
        {loadError || !paycheck ? "Back to paychecks" : "Back"}
      </PayrollActionButton>
    );

    if (loading) {
      return (
        <PayrollLuxPage
          testId="page-paycheck-detail"
          className="lux-paycheck-page"
          pageMeta={pageMeta}
          showHubNav={!employeeView}
          heroActions={backAction}
        >
          <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading payslip" description="Fetching paycheck details." />
        </PayrollLuxPage>
      );
    }

    if (loadError || !paycheck) {
      return (
        <PayrollLuxPage
          testId="page-paycheck-detail"
          className="lux-paycheck-page"
          pageMeta={pageMeta}
          showHubNav={!employeeView}
          heroActions={backAction}
        >
          <LuxRegisterEmptyState className="lux-register-empty--compact" icon="fe fe-dollar-sign" title="Paycheck not found" description={loadError || "This payslip may have been removed."} />
        </PayrollLuxPage>
      );
    }

    return (
      <PayrollLuxPage
        testId="page-paycheck-detail"
        className="lux-paycheck-page"
        dataSource={dataSource}
        pageMeta={pageMeta}
        showHubNav={!employeeView}
        heroActions={
          <>
            {backAction}
            {canPublishPaycheck(paycheck) && !employeeView && (
              <PayrollActionButton icon="fe fe-send" variant="primary" onClick={this.handlePublish} disabled={acting}>
                Publish
              </PayrollActionButton>
            )}
            {canRetractPaycheck(paycheck) && !employeeView && (
              <PayrollActionButton icon="fe fe-slash" variant="ghost" onClick={this.handleRetract} disabled={acting}>
                Retract
              </PayrollActionButton>
            )}
            {showPdfDownload && (
              <PayrollActionButton
                icon="fe fe-download"
                variant="primary"
                onClick={this.handleDownloadPdf}
                disabled={downloading}
              >
                {downloading ? "Generating…" : "Download PDF"}
              </PayrollActionButton>
            )}
            {showForm16Download && (
              <PayrollActionButton
                icon="fe fe-file"
                variant="ghost"
                onClick={this.handleDownloadForm16}
                disabled={downloadingForm16}
                title="Not a statutory Form 16 — estimate only"
              >
                {downloadingForm16 ? "Form 16…" : "Form 16 estimate"}
              </PayrollActionButton>
            )}
          </>
        }
      >
        <section className="lux-hrms-dash__panel lux-paycheck-panel">
          <PayrollPanelHead title="Payslip breakdown" subtitle="Earnings, deductions, and year-to-date totals" />
          <div className="lux-hrms-dash__panel-body">
            <PayslipDetailView paycheck={paycheck} employeeView={employeeView} />
          </div>
        </section>
      </PayrollLuxPage>
    );
  }
}

export default PaycheckDetailPage;
