import React, { Component } from "react";
import LegalDocumentModal from "views/common/legal/LegalDocumentModal";
import { LEGAL_DOC_TYPES } from "views/common/legal/legalDocuments";

/**
 * Deep-link hosts for /legal/privacy and /legal/terms.
 * Renders the shared legal popup (same modal as login + app footers).
 */
function docTypeFromLocation(location, fallback) {
  const path = (location && location.pathname) || "";
  if (path.indexOf("/terms") >= 0) return LEGAL_DOC_TYPES.TERMS;
  if (path.indexOf("/privacy") >= 0) return LEGAL_DOC_TYPES.PRIVACY;
  return fallback || LEGAL_DOC_TYPES.PRIVACY;
}

class LegalDocumentRouteHost extends Component {
  constructor(props) {
    super(props);
    this.state = {
      docType: docTypeFromLocation(props.location, props.initialDocType),
    };
  }

  componentDidUpdate(prevProps) {
    const prevPath = prevProps.location && prevProps.location.pathname;
    const nextPath = this.props.location && this.props.location.pathname;
    if (prevPath !== nextPath) {
      this.setState({
        docType: docTypeFromLocation(this.props.location, this.props.initialDocType),
      });
    }
  }

  handleClose = () => {
    const { history } = this.props;
    if (history && history.length > 1) {
      history.goBack();
      return;
    }
    if (history) {
      history.replace("/");
    }
  };

  handleSwitchDoc = (docType) => {
    this.setState({ docType });
    const { history } = this.props;
    if (!history) return;
    history.replace(
      docType === LEGAL_DOC_TYPES.TERMS ? "/legal/terms" : "/legal/privacy"
    );
  };

  render() {
    return (
      <div className="lux-legal-route-host" data-testid="legal-route-host">
        <LegalDocumentModal
          show
          docType={this.state.docType}
          onClose={this.handleClose}
          onSwitchDoc={this.handleSwitchDoc}
        />
      </div>
    );
  }
}

export function PrivacyPolicyPage(props) {
  return <LegalDocumentRouteHost {...props} initialDocType={LEGAL_DOC_TYPES.PRIVACY} />;
}

export function TermsOfServicePage(props) {
  return <LegalDocumentRouteHost {...props} initialDocType={LEGAL_DOC_TYPES.TERMS} />;
}

export default LegalDocumentRouteHost;
