import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { isAdminJobsEnabled } from "config/admin-jobs.config";
import { adminJobsService } from "_services/adminJobs.service";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { AdminActionButton, AdminLuxPage } from "views/admin/components/AdminLuxShared";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";

/**
 * EH23 / W2-B02 ADMIN-017 — Scheduled jobs inventory with manual Run now / Run scan.
 */
class AdminJobsPage extends Component {
  state = {
    loading: false,
    loadError: null,
    dataSource: null,
    overview: null,
    runningType: null,
    runMessage: null,
    runError: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Scheduled jobs");
    }
    this.loadJobs();
  }

  loadJobs = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await adminJobsService.getJobsStatus();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          dataSource: "api-error",
          overview: null,
          loadError: "Unable to load jobs status from API.",
        });
        return;
      }
      this.setState({
        loading: false,
        dataSource: result.source,
        overview: result.payload,
        loadError: null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        dataSource: "api-error",
        overview: null,
        loadError: (error && error.message) || "Unable to load jobs status.",
      });
    }
  };

  runJob = async (job) => {
    if (!job || !job.scheduleType || this.state.runningType) {
      return;
    }
    const scheduleType = job.scheduleType;
    const label = job.runActionLabel || (scheduleType === "TIMESHEET_DATA_QUALITY" ? "Run scan" : "Run now");
    this.setState({ runningType: scheduleType, runError: null, runMessage: null });
    try {
      const result = await adminJobsService.runJobNow(scheduleType);
      if (!result || result.source === "api-error") {
        const detail =
          (result && result.error && (result.error.message || result.error.statusText)) ||
          `Unable to ${label.toLowerCase()} for ${scheduleType}.`;
        this.setState({ runningType: null, runError: detail });
        return;
      }
      const status = result.payload && result.payload.status ? result.payload.status : "done";
      this.setState({
        runningType: null,
        runMessage: `${label} completed for ${scheduleType} (${status}).`,
      });
      await this.loadJobs();
    } catch (error) {
      this.setState({
        runningType: null,
        runError: (error && error.message) || `Unable to ${label.toLowerCase()}.`,
      });
    }
  };

  formatStatus = (job) => {
    if (!job) {
      return "—";
    }
    return job.status || job.executionStatus || job.lastStatus || "—";
  };

  formatLastRun = (job) => {
    if (!job || !job.lastRunAt) {
      return "—";
    }
    return String(job.lastRunAt);
  };

  formatLastError = (job) => {
    if (!job || !job.lastError) {
      return "—";
    }
    return String(job.lastError);
  };

  runButtonLabel = (job) => {
    if (!job) {
      return "Run now";
    }
    if (this.state.runningType === job.scheduleType) {
      return job.scheduleType === "TIMESHEET_DATA_QUALITY" ? "Scanning…" : "Running…";
    }
    return job.runActionLabel || (job.scheduleType === "TIMESHEET_DATA_QUALITY" ? "Run scan" : "Run now");
  };

  render() {
    if (!isAdminJobsEnabled()) {
      return (
        <div className="lux-register-page lux-admin-page" data-testid="admin-jobs-flag-off">
          <div className="lux-register-page__body">
            <LuxRegisterEmptyState
              variant="employees"
              title="Jobs inventory unavailable"
              description="Enable REACT_APP_USE_ADMIN_JOBS_API to load the ScheduleType / fs_schedule_model inventory."
            />
          </div>
        </div>
      );
    }

    const { loading, loadError, overview, dataSource, runningType, runMessage, runError } = this.state;
    const jobs = (overview && (overview.jobs || overview.knownScheduleTypes)) || [];
    const kpiCards = [
      {
        id: "types",
        label: "Schedule types",
        value: overview
          ? overview.scheduleTypeCount != null
            ? overview.scheduleTypeCount
            : jobs.length
          : "—",
        hint: "Known ScheduleType values",
        tone: "slate",
        icon: "fe fe-layers",
      },
      {
        id: "instances",
        label: "Instances",
        value: overview
          ? overview.scheduleInstanceCount != null
            ? overview.scheduleInstanceCount
            : 0
          : "—",
        hint: "Live schedule rows",
        tone: "blue",
        icon: "fe fe-database",
      },
      {
        id: "failed",
        label: "Failed types",
        value: overview && overview.failedTypeCount != null ? overview.failedTypeCount : "—",
        hint: "Types with lastStatus FAILED",
        tone: overview && overview.failedTypeCount ? "amber" : "green",
        icon: "fe fe-alert-triangle",
      },
      {
        id: "source",
        label: "Data source",
        value: dataSource || "—",
        hint: "API",
        tone: "indigo",
        icon: "fe fe-activity",
      },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.jobs}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        testId="admin-jobs-page"
        onRefresh={this.loadJobs}
        refreshLoading={loading || !!runningType}
      >
        <AdminLoadAlert
          error={loadError || runError}
          fallback="Unable to load scheduled jobs."
          onDismiss={() => this.setState({ loadError: null, runError: null })}
        />
        {runMessage ? (
          <LuxInlineAlert
            tone="success"
            title="Job run"
            message={runMessage}
            testId="admin-jobs-run-message"
            onDismiss={() => this.setState({ runMessage: null })}
          />
        ) : null}

        <section className="lux-admin-panel">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading jobs"
              description="Fetching ScheduleType inventory and last-run status."
            />
          ) : jobs.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="No schedule types"
              description="No ScheduleType inventory returned from the API."
            />
          ) : (
            <div className="lux-admin-register-wrap">
              <table className="lux-admin-register" data-testid="admin-jobs-table">
                <thead>
                  <tr>
                    <th>Schedule type</th>
                    <th>Description</th>
                    <th>Status</th>
                    <th>Instances</th>
                    <th>Enabled</th>
                    <th>Last run</th>
                    <th>Last error</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {jobs.map((job) => (
                    <tr key={job.scheduleType}>
                      <td>
                        <code>{job.scheduleType}</code>
                      </td>
                      <td>{job.description || "—"}</td>
                      <td>
                        <span data-testid={`job-status-${job.scheduleType}`}>{this.formatStatus(job)}</span>
                      </td>
                      <td>{job.instanceCount || 0}</td>
                      <td>{job.enabledCount || 0}</td>
                      <td>{this.formatLastRun(job)}</td>
                      <td>
                        <span title={job.lastError || ""}>{this.formatLastError(job)}</span>
                      </td>
                      <td>
                        <AdminActionButton
                          variant="secondary"
                          icon="fe fe-play"
                          disabled={!!runningType || loading}
                          onClick={() => this.runJob(job)}
                          testId={`job-run-${job.scheduleType}`}
                        >
                          {this.runButtonLabel(job)}
                        </AdminActionButton>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </AdminLuxPage>
    );
  }
}

export default AdminJobsPage;
