import React, { Component } from "react";
import classNames from "classnames/bind";
import { benefitsService } from "_services/benefits/benefits.service";
import BenefitsLuxPage, {
  BenefitsActionButton,
  BenefitsLuxPanel,
  BenefitsQuickNav,
  BenefitsInsightPanel,
  BenefitsField,
  BenefitsFormGrid,
  BenefitsRegisterWrap,
  BenefitsRegisterPrimary,
  BenefitsToolbar,
  BenefitsStatusBadge,
  BenefitsSectionTabs,
} from "views/benefits/components/BenefitsLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

const COVERAGE_TIERS = [
  { value: "EE", label: "Employee only" },
  { value: "EE+SP", label: "Employee + spouse" },
  { value: "EE+CH", label: "Employee + children" },
  { value: "FAMILY", label: "Family" },
];

class BenefitsEnrollmentPage extends Component {
  state = {
    loading: true,
    loadError: null,
    rows: [],
    plans: [],
    saving: false,
    query: "",
    statusFilter: "ALL",
    form: { planId: "", coverageTier: "EE", payrollDeductionCode: "" },
    mapRef: "",
    mapCode: "",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Benefits enrollment");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const [enrollResult, plansResult] = await Promise.all([
      benefitsService.listEnrollments(),
      benefitsService.listPlans(),
    ]);
    const rows =
      enrollResult.source === "api" && Array.isArray(enrollResult.payload) ? enrollResult.payload : [];
    const plans =
      plansResult.source === "api" && Array.isArray(plansResult.payload) ? plansResult.payload : [];
    const loadError =
      enrollResult.source !== "api"
        ? enrollResult.error || new Error("Unable to load enrollments")
        : null;
    this.setState({ loading: false, rows, plans, loadError });
  };

  handleCreate = async (e) => {
    e.preventDefault();
    const { form } = this.state;
    if (!form.planId) return;
    this.setState({ saving: true, loadError: null });
    const result = await benefitsService.createEnrollment({
      planId: Number(form.planId),
      coverageTier: form.coverageTier,
      payrollDeductionCode: form.payrollDeductionCode || undefined,
      hrOrPayroll: true,
    });
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ form: { planId: "", coverageTier: "EE", payrollDeductionCode: "" } });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Enroll failed") });
    }
  };

  handleApprove = async (enrollmentRef) => {
    this.setState({ saving: true, loadError: null });
    const result = await benefitsService.approveEnrollment(enrollmentRef);
    this.setState({ saving: false });
    if (result && result.source === "api") {
      await this.load();
      return;
    }
    this.setState({
      loadError: (result && result.error) || new Error("Unable to approve enrollment"),
    });
  };

  handleSubmit = async (enrollmentRef) => {
    this.setState({ saving: true, loadError: null });
    const result = await benefitsService.submitEnrollment(enrollmentRef, { hrOrPayroll: true });
    this.setState({ saving: false });
    if (result && result.source === "api") {
      await this.load();
      return;
    }
    this.setState({
      loadError: (result && result.error) || new Error("Unable to submit enrollment"),
    });
  };

  handleMap = async (e) => {
    e.preventDefault();
    const { mapRef, mapCode } = this.state;
    if (!mapRef || !mapCode) return;
    this.setState({ saving: true, loadError: null });
    const result = await benefitsService.putDeductionMapping(mapRef, mapCode);
    this.setState({ saving: false });
    if (result.source === "api") {
      this.setState({ mapRef: "", mapCode: "" });
      this.load();
    } else {
      this.setState({ loadError: result.error || new Error("Deduction map failed") });
    }
  };

  planLabel = (planId) => {
    const plan = this.state.plans.find((p) => String(p.id) === String(planId));
    if (!plan) return planId || "—";
    return plan.name || plan.code || planId;
  };

  getFiltered = () => {
    const { rows, query, statusFilter } = this.state;
    const q = (query || "").trim().toLowerCase();
    return rows.filter((row) => {
      if (statusFilter !== "ALL" && String(row.status || "").toUpperCase() !== statusFilter) {
        return false;
      }
      if (!q) return true;
      const hay = [
        row.enrollmentRef,
        row.planId,
        row.employeeId,
        row.status,
        row.payrollDeductionCode,
        this.planLabel(row.planId),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return hay.includes(q);
    });
  };

  render() {
    const { loading, loadError, rows, plans, saving, form, mapRef, mapCode, query, statusFilter } =
      this.state;
    const filtered = this.getFiltered();
    const byStatus = rows.reduce((acc, row) => {
      const key = row.status || "UNKNOWN";
      acc[key] = (acc[key] || 0) + 1;
      return acc;
    }, {});

    const kpiCards = [
      {
        id: "enroll",
        label: "Enrollments",
        value: rows.length,
        hint: "All statuses",
        tone: "indigo",
        icon: "fe fe-user-check",
      },
      {
        id: "draft",
        label: "Draft",
        value: byStatus.DRAFT || 0,
        hint: "Need submit",
        tone: "slate",
        icon: "fe fe-edit-3",
      },
      {
        id: "submitted",
        label: "Submitted",
        value: byStatus.SUBMITTED || 0,
        hint: "Awaiting approval",
        tone: "amber",
        icon: "fe fe-send",
      },
      {
        id: "approved",
        label: "Approved",
        value: byStatus.APPROVED || 0,
        hint: "Ready for carrier",
        tone: "green",
        icon: "fe fe-check-circle",
      },
    ];

    return (
      <BenefitsLuxPage
        testId="benefits-enrollment-page"
        dataSource={rows.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        loading={loading}
        kpiCards={kpiCards}
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-user-check",
          eyebrow: "People · Benefits",
          titleLead: "Benefits",
          titleAccent: "enrollment",
          lede: "Coverage elections and payroll deduction mapping on existing employee-finance deductions — not a second payroll source of truth.",
        }}
        onRefresh={this.load}
        refreshLoading={loading}
        heroActions={<><BenefitsActionButton to="/benefits/plans" icon="fe fe-heart" variant="ghost">
              Plans
            </BenefitsActionButton>
          </>}
      >
        <BenefitsSectionTabs active="/benefits/enrollment" />
        <BenefitsQuickNav />
        <BenefitsInsightPanel
          insights={[
            {
              id: "plans",
              tone: "green",
              icon: "fe fe-heart",
              title: plans.length ? `${plans.length} plan(s) available` : "Create a plan first",
              copy: "Enrollments require an active benefits plan.",
              path: "/benefits/plans",
            },
            {
              id: "deduction",
              tone: "violet",
              icon: "fe fe-link",
              title: "Map payroll deductions",
              copy: "Link enrollment refs to deduction codes consumed by payroll runs.",
              path: null,
            },
            {
              id: "carrier",
              tone: "amber",
              icon: "fe fe-file-text",
              title: "Export after approval",
              copy: "Generate carrier files once enrollments are approved.",
              path: "/benefits/carrier-files",
            },
          ]}
        />

        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load enrollments">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}

        <div className="lux-benefits-split">
          <BenefitsLuxPanel
            title="Create enrollment"
            meta="Draft coverage against a plan"
            icon="fe fe-plus"
            accent="indigo"
          >
            <form className="lux-benefits-form" onSubmit={this.handleCreate}>
              <BenefitsFormGrid columns={2}>
                <BenefitsField label="Plan" hint="Select from catalog">
                  {plans.length > 0 ? (
                    <select
                      className="form-control"
                      value={form.planId}
                      onChange={(e) => this.setState({ form: { ...form, planId: e.target.value } })}
                      required
                    >
                      <option value="">Select plan…</option>
                      {plans.map((p) => (
                        <option key={p.id || p.planRef} value={p.id}>
                          {p.name || p.code || p.planRef} {p.code ? `(${p.code})` : ""}
                        </option>
                      ))}
                    </select>
                  ) : (
                    <input
                      className="form-control"
                      placeholder="Plan id"
                      value={form.planId}
                      onChange={(e) => this.setState({ form: { ...form, planId: e.target.value } })}
                      required
                    />
                  )}
                </BenefitsField>
                <BenefitsField label="Coverage tier">
                  <select
                    className="form-control"
                    value={form.coverageTier}
                    onChange={(e) => this.setState({ form: { ...form, coverageTier: e.target.value } })}
                  >
                    {COVERAGE_TIERS.map((t) => (
                      <option key={t.value} value={t.value}>
                        {t.label}
                      </option>
                    ))}
                  </select>
                </BenefitsField>
                <BenefitsField label="Payroll deduction code" hint="Optional initial map" className="is-span-2">
                  <input
                    className="form-control"
                    placeholder="e.g. BEN-MED"
                    value={form.payrollDeductionCode}
                    onChange={(e) =>
                      this.setState({ form: { ...form, payrollDeductionCode: e.target.value } })
                    }
                  />
                </BenefitsField>
              </BenefitsFormGrid>
              <div className="lux-benefits-form__actions">
                <BenefitsActionButton type="submit" icon="fe fe-check" disabled={saving || !form.planId}>
                  {saving ? "Saving…" : "Create enrollment"}
                </BenefitsActionButton>
              </div>
            </form>
          </BenefitsLuxPanel>

          <BenefitsLuxPanel
            title="Map deduction"
            meta="Links enrollment to employee-finance deduction codes"
            icon="fe fe-link"
            accent="violet"
          >
            <form className="lux-benefits-form" onSubmit={this.handleMap}>
              <BenefitsFormGrid columns={2}>
                <BenefitsField label="Enrollment ref">
                  <input
                    className="form-control"
                    placeholder="enr-…"
                    value={mapRef}
                    onChange={(e) => this.setState({ mapRef: e.target.value })}
                    required
                  />
                </BenefitsField>
                <BenefitsField label="Payroll deduction code">
                  <input
                    className="form-control"
                    placeholder="BEN-MED"
                    value={mapCode}
                    onChange={(e) => this.setState({ mapCode: e.target.value })}
                    required
                  />
                </BenefitsField>
              </BenefitsFormGrid>
              <div className="lux-benefits-form__actions">
                <BenefitsActionButton
                  type="submit"
                  variant="secondary"
                  icon="fe fe-link"
                  disabled={saving || !mapRef || !mapCode}
                >
                  Map deduction
                </BenefitsActionButton>
              </div>
            </form>
          </BenefitsLuxPanel>
        </div>

        <BenefitsLuxPanel
          title="Enrollment register"
          meta={`${filtered.length} of ${rows.length} enrollment${rows.length === 1 ? "" : "s"}`}
          icon="fe fe-list"
          accent="blue"
        >
          <BenefitsToolbar
            query={query}
            onQueryChange={(value) => this.setState({ query: value })}
            placeholder="Search ref, employee, plan…"
            countLabel={
              <>
                <strong>{filtered.length}</strong> shown
              </>
            }
          >
            <div className="lux-hrms-dash__filter-group">
              {["ALL", "DRAFT", "SUBMITTED", "APPROVED", "REJECTED"].map((value) => (
                <button
                  key={value}
                  type="button"
                  className={classNames("lux-hrms-dash__filter-chip", {
                    "is-active": statusFilter === value,
                  })}
                  onClick={() => this.setState({ statusFilter: value })}
                >
                  {value === "ALL" ? "All" : value.charAt(0) + value.slice(1).toLowerCase()}
                </button>
              ))}
            </div>
          </BenefitsToolbar>

          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading enrollments"
              description="Fetching coverage elections."
            />
          ) : filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title={rows.length === 0 ? "No enrollments yet" : "No matching enrollments"}
              description={
                rows.length === 0
                  ? "Create an enrollment against a benefits plan."
                  : "Try a different search or status filter."
              }
              showCreate={false}
            />
          ) : (
            <BenefitsRegisterWrap>
              <table className="lux-benefits-register">
                <thead>
                  <tr>
                    <th>Enrollment</th>
                    <th>Plan</th>
                    <th>Employee</th>
                    <th>Status</th>
                    <th>Deduction</th>
                    <th>Dependents</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((r) => (
                    <tr key={r.enrollmentRef || r.id}>
                      <td>
                        <BenefitsRegisterPrimary
                          title={r.enrollmentRef || `Enrollment ${r.id}`}
                          meta={r.coverageTier || "Coverage"}
                          icon="fe fe-user-check"
                          tone="indigo"
                        />
                      </td>
                      <td>{this.planLabel(r.planId)}</td>
                      <td>{r.employeeId || "—"}</td>
                      <td>
                        <BenefitsStatusBadge status={r.status} />
                      </td>
                      <td>
                        <code className="lux-benefits-code">{r.payrollDeductionCode || "—"}</code>
                      </td>
                      <td>
                        <span className="lux-benefits-muted">
                          {r.dependentsMasked ? "Masked" : r.dependentJson || "—"}
                        </span>
                      </td>
                      <td>
                        <div className="lux-benefits-row-actions">
                          {r.status === "DRAFT" && (
                            <BenefitsActionButton
                              type="button"
                              variant="ghost"
                              className="lux-onb-action--compact"
                              disabled={saving}
                              onClick={() => this.handleSubmit(r.enrollmentRef)}
                            >
                              Submit
                            </BenefitsActionButton>
                          )}
                          {(r.status === "SUBMITTED" || r.status === "DRAFT") && (
                            <BenefitsActionButton
                              type="button"
                              variant="ghost"
                              className="lux-onb-action--compact"
                              disabled={saving}
                              onClick={() => this.handleApprove(r.enrollmentRef)}
                            >
                              Approve
                            </BenefitsActionButton>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </BenefitsRegisterWrap>
          )}
        </BenefitsLuxPanel>
      </BenefitsLuxPage>
    );
  }
}

export default BenefitsEnrollmentPage;
