import envconfig from "env.config";
import catalog from "./app-release-history.json";

export function listReleaseHistory() {
  return Array.isArray(catalog) ? catalog.slice() : [];
}

export function getCurrentAppVersion() {
  const fromEnv = envconfig && envconfig.APP_VERSION;
  if (fromEnv) {
    return String(fromEnv);
  }
  const latest = listReleaseHistory()[0];
  return (latest && latest.version) || "8.0.11";
}

export function getReleaseByVersion(version) {
  const needle = String(version || "").trim();
  if (!needle) {
    return null;
  }
  return listReleaseHistory().find((row) => row && row.version === needle) || null;
}
