import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import {
  API_KEY_SCOPE_OPTIONS,
  API_KEY_FULL_ACCESS_SCOPE,
  WEBHOOK_EVENT_OPTIONS,
  sanitizeApiKeyScopes,
  isFullAccessApiKeyScopes,
} from "config/developer-portal.config";
import { DeveloperActionButton } from "views/developer/components/DeveloperLuxShared";

function DrawerBanner({ tone, icon, title, detail }) {
  return (
    <div className={classNames("lux-dev-drawer__banner", tone && `is-${tone}`)}>
      <span className="lux-dev-drawer__banner-icon" aria-hidden="true">
        <i className={icon} />
      </span>
      <div>
        {title ? <strong>{title}</strong> : null}
        {detail ? <p>{detail}</p> : null}
      </div>
    </div>
  );
}

function DrawerShell({ open, title, subtitle, accent, icon, badge, hint, onClose, children, footer }) {
  if (!open) {
    return null;
  }
  return createPortal(
    <div className="lux-dev-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className={classNames("lux-dev-drawer", accent && `lux-dev-drawer--${accent}`)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="lux-dev-drawer-title"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="lux-dev-drawer__ambient" aria-hidden="true">
          <span className="lux-dev-drawer__orb lux-dev-drawer__orb--a" />
          <span className="lux-dev-drawer__orb lux-dev-drawer__orb--b" />
        </div>
        <span className="lux-dev-drawer__accent" aria-hidden="true" />

        <header className="lux-dev-drawer__head">
          <div className="lux-dev-drawer__head-main">
            <span className="lux-dev-drawer__category-icon" aria-hidden="true">
              <i className={icon || "fe fe-code"} />
            </span>
            <div className="lux-dev-drawer__head-copy">
              <div className="lux-dev-drawer__kicker-row">
                <span className="lux-dev-drawer__eyebrow">{subtitle}</span>
                {badge ? <span className="lux-dev-drawer__pill">{badge}</span> : null}
              </div>
              <h2 id="lux-dev-drawer-title">{title}</h2>
            </div>
          </div>
          <button type="button" className="lux-dev-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-dev-drawer__body">
          {hint ? <DrawerBanner tone="info" icon="fe fe-info" title={hint.title} detail={hint.detail} /> : null}
          {children}
        </div>

        {footer ? <footer className="lux-dev-drawer__footer">{footer}</footer> : null}
      </aside>
    </div>,
    document.body
  );
}

function FormSection({ title, meta, children, scrollBody = false, bodyClassName }) {
  return (
    <section className={classNames("lux-dev-drawer__section", scrollBody && "lux-dev-drawer__section--scroll")}>
      <header className="lux-dev-drawer__section-head">
        <h3>{title}</h3>
        {meta ? <p>{meta}</p> : null}
      </header>
      <div
        className={classNames(
          "lux-dev-drawer__section-body",
          scrollBody && "lux-dev-drawer__section-body--scroll",
          bodyClassName
        )}
      >
        {children}
      </div>
    </section>
  );
}

function ChoiceChip({ label, code, access, icon, tone, selected, onToggle, compact }) {
  return (
    <button
      type="button"
      className={classNames(
        "lux-dev-drawer__chip",
        compact && "lux-dev-drawer__chip--compact",
        tone && `is-tone-${tone}`,
        selected && "is-selected"
      )}
      aria-pressed={selected}
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        onToggle();
      }}
    >
      {icon ? (
        <span className="lux-dev-drawer__chip-icon" aria-hidden="true">
          <i className={`fe ${icon}`} />
        </span>
      ) : (
        <span className="lux-dev-drawer__chip-check" aria-hidden="true">
          <i className={selected ? "fe fe-check-square" : "fe fe-square"} />
        </span>
      )}
      <span className="lux-dev-drawer__chip-copy">
        <span className="lux-dev-drawer__chip-title-row">
          <span className="lux-dev-drawer__chip-label">{label}</span>
          {access ? (
            <span className={classNames("lux-dev-drawer__chip-access", access === "Write" && "is-write")}>
              {access}
            </span>
          ) : null}
        </span>
        {code ? <span className="lux-dev-drawer__chip-code">{code}</span> : null}
      </span>
      {compact ? (
        <span className="lux-dev-drawer__chip-mark" aria-hidden="true">
          <i className={selected ? "fe fe-check" : "fe fe-plus"} />
        </span>
      ) : null}
    </button>
  );
}

function DrawerTextField({ id, label, value, onChange, placeholder, type = "text" }) {
  return (
    <div className="lux-dev-drawer__field">
      <label className="lux-dev-drawer__field-label" htmlFor={id}>
        {label}
      </label>
      <input
        id={id}
        type={type}
        className="lux-dev-drawer__input"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        autoComplete="off"
      />
    </div>
  );
}

export class ApiKeyCreateDrawer extends Component {
  state = {
    name: "",
    appName: "",
    environment: "production",
    scopes: [],
    saving: false,
    error: null,
    secretOnce: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({
        name: "",
        appName: "",
        environment: "production",
        scopes: [],
        saving: false,
        error: null,
        secretOnce: null,
      });
    }
  }

  toggleScope = (scopeId) => {
    this.setState((prev) => {
      const scopes = prev.scopes.filter((id) => id !== API_KEY_FULL_ACCESS_SCOPE);
      const index = scopes.indexOf(scopeId);
      if (index === -1) {
        scopes.push(scopeId);
      } else {
        scopes.splice(index, 1);
      }
      return { scopes };
    });
  };

  selectAllScopes = () => {
    this.setState({ scopes: API_KEY_SCOPE_OPTIONS.map((option) => option.id) });
  };

  clearScopes = () => {
    this.setState({ scopes: [] });
  };

  setEnvironment = (environment) => {
    this.setState({ environment });
  };

  handleSubmit = async () => {
    const { name, appName, environment, scopes } = this.state;
    const { onCreate } = this.props;
    if (!name.trim()) {
      this.setState({ error: "Key name is required." });
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      const result = await onCreate({
        name: name.trim(),
        appName: appName.trim() || "Custom integration",
        environment,
        scopes: sanitizeApiKeyScopes(scopes),
        ownerName: "Platform Admin",
      });
      const payload = result.payload || {};
      this.setState({
        saving: false,
        secretOnce: payload.secretOnce || null,
      });
      if (!payload.secretOnce && this.props.onCreated) {
        this.props.onCreated();
        this.props.onClose();
      }
    } catch (error) {
      this.setState({
        saving: false,
        error: (error && error.message) || "Unable to create API key.",
      });
    }
  };

  handleDone = () => {
    if (this.props.onCreated) {
      this.props.onCreated();
    }
    this.props.onClose();
  };

  render() {
    const { open, onClose } = this.props;
    const { name, appName, environment, scopes, saving, error, secretOnce } = this.state;

    return (
      <DrawerShell
        open={open}
        title={secretOnce ? "Copy your secret" : "Create API key"}
        subtitle="Admin · credentials"
        accent="indigo"
        icon="fe fe-key"
        badge={secretOnce ? "One-time reveal" : "Scoped access"}
        hint={
          secretOnce
            ? null
            : {
                title: "Credential governance",
                detail: "Production keys use the live API catalog. Sandbox only changes the tk_test_ prefix — it does not add sandbox scopes.",
              }
        }
        onClose={secretOnce ? this.handleDone : onClose}
        footer={
          secretOnce ? (
            <DeveloperActionButton variant="primary" icon="fe fe-check" onClick={this.handleDone}>
              Done
            </DeveloperActionButton>
          ) : (
            <>
              <DeveloperActionButton onClick={onClose} disabled={saving}>
                Cancel
              </DeveloperActionButton>
              <DeveloperActionButton variant="primary" icon="fe fe-key" onClick={this.handleSubmit} disabled={saving}>
                Create key
              </DeveloperActionButton>
            </>
          )
        }
      >
        {error ? <DrawerBanner tone="alert" icon="fe fe-alert-triangle" title="Unable to save" detail={error} /> : null}
        {secretOnce ? (
          <>
            <DrawerBanner
              tone="alert"
              icon="fe fe-shield"
              title="Store this secret securely"
              detail="It will not be shown again after you close this panel."
            />
            <div className="lux-dev-drawer__secret-panel">
              <span className="lux-dev-drawer__secret-label">API secret</span>
              <code className="lux-dev-drawer__secret-value">{secretOnce}</code>
            </div>
          </>
        ) : (
          <>
            <FormSection title="Identity" meta="Label the credential for audit trails">
              <DrawerTextField
                id="api-key-name"
                label="Key name"
                value={name}
                onChange={(next) => this.setState({ name: next })}
                placeholder="Ops automation prod"
              />
              <DrawerTextField
                id="api-key-app-name"
                label="App name"
                value={appName}
                onChange={(next) => this.setState({ appName: next })}
                placeholder="Custom integration"
              />
            </FormSection>

            <FormSection
              title="Environment"
              meta={environment === "production"
                ? "Live tenant data — catalog scopes only"
                : "tk_test_ prefix for integration testing — same catalog scopes"}
            >
              <div className="lux-dev-drawer__env-toggle" role="group" aria-label="Environment">
                <button
                  type="button"
                  className={classNames("lux-dev-drawer__env-btn", environment === "production" && "is-selected")}
                  aria-pressed={environment === "production"}
                  onClick={(e) => {
                    e.preventDefault();
                    this.setEnvironment("production");
                  }}
                >
                  <strong>Production</strong>
                  <span>tk_live_ · live tenant data</span>
                </button>
                <button
                  type="button"
                  className={classNames("lux-dev-drawer__env-btn", environment === "sandbox" && "is-selected")}
                  aria-pressed={environment === "sandbox"}
                  onClick={(e) => {
                    e.preventDefault();
                    this.setEnvironment("sandbox");
                  }}
                >
                  <strong>Sandbox</strong>
                  <span>tk_test_ · same API catalog</span>
                </button>
              </div>
            </FormSection>

            <FormSection
              title="Scopes"
              meta={
                isFullAccessApiKeyScopes(scopes)
                  ? "No scopes selected · full API access (except developer portal)"
                  : `${scopes.length} of ${API_KEY_SCOPE_OPTIONS.length} selected · least privilege`
              }
              bodyClassName="lux-dev-drawer__section-body--scopes"
            >
              <div className="lux-dev-drawer__scope-toolbar" role="group" aria-label="Scope presets">
                <button type="button" className="lux-dev-drawer__scope-tool" onClick={this.selectAllScopes} disabled={saving}>
                  Select all
                </button>
                <button type="button" className="lux-dev-drawer__scope-tool" onClick={this.clearScopes} disabled={saving}>
                  Clear · full access
                </button>
              </div>
              {isFullAccessApiKeyScopes(scopes) ? (
                <p className="lux-dev-drawer__scope-hint">
                  This key can call any <code>/api/*</code> route. Developer-portal key admin stays blocked.
                </p>
              ) : null}
              <div className="lux-dev-drawer__chip-grid lux-dev-drawer__chip-grid--scopes" role="group" aria-label="API scopes">
                {API_KEY_SCOPE_OPTIONS.map((option) => (
                  <ChoiceChip
                    key={option.id}
                    label={option.label}
                    access={option.access}
                    icon={option.icon}
                    tone={option.tone}
                    code={option.id}
                    compact
                    selected={scopes.indexOf(option.id) !== -1}
                    onToggle={() => this.toggleScope(option.id)}
                  />
                ))}
              </div>
            </FormSection>
          </>
        )}
      </DrawerShell>
    );
  }
}

export class WebhookCreateDrawer extends Component {
  state = {
    name: "",
    url: "",
    events: ["approval.submitted"],
    saving: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({
        name: "",
        url: "",
        events: ["approval.submitted"],
        saving: false,
        error: null,
      });
    }
  }

  toggleEvent = (eventId) => {
    this.setState((prev) => {
      const events = prev.events.slice();
      const index = events.indexOf(eventId);
      if (index === -1) {
        events.push(eventId);
      } else {
        events.splice(index, 1);
      }
      return { events };
    });
  };

  handleSubmit = async () => {
    const { name, url, events } = this.state;
    const { onCreate, onCreated, onClose } = this.props;
    if (!name.trim()) {
      this.setState({ error: "Subscription name is required." });
      return;
    }
    if (!url.trim()) {
      this.setState({ error: "Endpoint URL is required." });
      return;
    }
    if (!events.length) {
      this.setState({ error: "Select at least one event." });
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onCreate({ name: name.trim(), url: url.trim(), events });
      this.setState({ saving: false });
      if (onCreated) {
        onCreated();
      }
      onClose();
    } catch (error) {
      this.setState({
        saving: false,
        error: (error && error.message) || "Unable to create webhook.",
      });
    }
  };

  render() {
    const { open, onClose } = this.props;
    const { name, url, events, saving, error } = this.state;

    return (
      <DrawerShell
        open={open}
        title="Create webhook"
        subtitle="Admin · delivery"
        accent="violet"
        icon="fe fe-link-2"
        badge="Event subscription"
        hint={{
          title: "Signed delivery",
          detail: "Payloads include HMAC signatures. Rotate secrets from the subscription detail view.",
        }}
        onClose={onClose}
        footer={
          <>
            <DeveloperActionButton onClick={onClose} disabled={saving}>
              Cancel
            </DeveloperActionButton>
            <DeveloperActionButton variant="primary" icon="fe fe-link-2" onClick={this.handleSubmit} disabled={saving}>
              Create subscription
            </DeveloperActionButton>
          </>
        }
      >
        {error ? <DrawerBanner tone="alert" icon="fe fe-alert-triangle" title="Unable to save" detail={error} /> : null}

        <FormSection title="Subscription" meta="Name and HTTPS endpoint">
          <DrawerTextField
            id="webhook-name"
            label="Subscription name"
            value={name}
            onChange={(next) => this.setState({ name: next })}
            placeholder="Approval submitted"
          />
          <DrawerTextField
            id="webhook-url"
            label="Endpoint URL"
            type="url"
            value={url}
            onChange={(next) => this.setState({ url: next })}
            placeholder="https://hooks.example.com/tracopus"
          />
        </FormSection>

        <FormSection title="Events" meta={`${events.length} selected`} scrollBody>
          <div className="lux-dev-drawer__chip-grid">
            {WEBHOOK_EVENT_OPTIONS.map((option) => (
              <ChoiceChip
                key={option.id}
                label={option.label}
                code={option.id}
                selected={events.indexOf(option.id) !== -1}
                onToggle={() => this.toggleEvent(option.id)}
              />
            ))}
          </div>
        </FormSection>
      </DrawerShell>
    );
  }
}

export class AppRegisterDrawer extends Component {
  state = {
    name: "",
    environment: "sandbox",
    saving: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      this.setState({ name: "", environment: "sandbox", saving: false, error: null });
    }
  }

  handleSubmit = async () => {
    const { name, environment } = this.state;
    const { onCreate, onCreated, onClose } = this.props;
    if (!name.trim()) {
      this.setState({ error: "App name is required." });
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onCreate({ name: name.trim(), environment, ownerName: "Platform Admin" });
      this.setState({ saving: false });
      if (onCreated) {
        onCreated();
      }
      onClose();
    } catch (error) {
      this.setState({
        saving: false,
        error: (error && error.message) || "Unable to register app.",
      });
    }
  };

  render() {
    const { open, onClose } = this.props;
    const { name, environment, saving, error } = this.state;

    return (
      <DrawerShell
        open={open}
        title="Register app"
        subtitle="Developer portal"
        accent="cyan"
        icon="fe fe-package"
        badge="App registry"
        hint={{
          title: "Before API keys",
          detail: "Register a custom app, then issue scoped credentials and webhook subscriptions.",
        }}
        onClose={onClose}
        footer={
          <>
            <DeveloperActionButton onClick={onClose} disabled={saving}>
              Cancel
            </DeveloperActionButton>
            <DeveloperActionButton variant="primary" icon="fe fe-plus" onClick={this.handleSubmit} disabled={saving}>
              Register app
            </DeveloperActionButton>
          </>
        }
      >
        {error ? <DrawerBanner tone="alert" icon="fe fe-alert-triangle" title="Unable to save" detail={error} /> : null}

        <FormSection title="App profile" meta="Display name and runtime environment">
          <DrawerTextField
            id="app-register-name"
            label="App name"
            value={name}
            onChange={(next) => this.setState({ name: next })}
            placeholder="Finance ETL worker"
          />
          <div className="lux-dev-drawer__env-toggle" role="group" aria-label="Environment">
            <button
              type="button"
              className={classNames("lux-dev-drawer__env-btn", environment === "sandbox" && "is-selected")}
              aria-pressed={environment === "sandbox"}
              onClick={(e) => {
                e.preventDefault();
                this.setState({ environment: "sandbox" });
              }}
            >
              <strong>Sandbox</strong>
              <span>Integration testing</span>
            </button>
            <button
              type="button"
              className={classNames("lux-dev-drawer__env-btn", environment === "production" && "is-selected")}
              aria-pressed={environment === "production"}
              onClick={(e) => {
                e.preventDefault();
                this.setState({ environment: "production" });
              }}
            >
              <strong>Production</strong>
              <span>Live workloads</span>
            </button>
          </div>
        </FormSection>
      </DrawerShell>
    );
  }
}
