import React, { useMemo } from "react";
import classNames from "classnames/bind";
import { buildLifecycleQueueInsights } from "config/onboarding.utils";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import LuxChartPanelSkeleton from "views/common/fragments/LuxChartPanelSkeleton";

const CHART_COLORS = ["#5b5ff4", "#34d399", "#f59e0b", "#ef4444", "#94a3b8", "#818cf8"];

function toneForPct(pct) {
  if (pct >= 80) return "green";
  if (pct >= 50) return "primary";
  if (pct >= 25) return "amber";
  return "rose";
}

function LifecycleInsightsCharts({ cases, lifecycle = "onboarding", loading }) {
  const insights = useMemo(
    () => buildLifecycleQueueInsights(cases, lifecycle),
    [cases, lifecycle]
  );
  const hasCases = insights.caseCount > 0;
  const isOffboarding = lifecycle === "offboarding";

  const statusChart = useMemo(() => {
    if (!insights.statusMix.length) {
      return null;
    }
    return {
      series: insights.statusMix.map((item) => item.count),
      options: {
        chart: { type: "donut", height: 240 },
        labels: insights.statusMix.map((item) => item.label),
        colors: CHART_COLORS,
        legend: { position: "bottom", fontSize: "11px", fontWeight: 600 },
        dataLabels: { enabled: false },
        stroke: { width: 0 },
        plotOptions: {
          pie: {
            donut: {
              size: "68%",
              labels: {
                show: true,
                total: {
                  show: true,
                  label: "Cases",
                  fontSize: "11px",
                  fontWeight: 700,
                  formatter: () => String(insights.caseCount),
                },
              },
            },
          },
        },
      },
    };
  }, [insights]);

  return (
    <section className="lux-onb-insights" aria-label="Lifecycle readiness insights">
      <div className="lux-hrms-dash__chart-grid--duo lux-onb-insights__grid">
        <article className="lux-hrms-dash__chart-panel">
          <div className="lux-hrms-dash__panel-head">
            <div>
              <h3 className="lux-hrms-dash__panel-title">Readiness by category</h3>
              <p className="lux-hrms-dash__panel-sub">
                Checklist completion across {isOffboarding ? "exit" : "onboarding"} workstreams
              </p>
            </div>
          </div>
          <div className="lux-hrms-dash__chart-body">
            {loading && <LuxChartPanelSkeleton height={220} className="lux-hrms-dash__empty" />}
            {!loading && !hasCases && (
              <p className="lux-hrms-dash__empty">No cases to chart yet.</p>
            )}
            {!loading && hasCases && !insights.categoryReadiness.length && (
              <p className="lux-hrms-dash__empty">No checklist tasks found on open cases.</p>
            )}
            {!loading && insights.categoryReadiness.length > 0 && (
              <ul className="lux-hrms-dash__sentiment-list lux-onb-insights__bars">
                {insights.categoryReadiness.map((row) => (
                  <li
                    key={row.id}
                    className={classNames("lux-hrms-dash__sentiment-row", `is-${toneForPct(row.pct)}`)}
                  >
                    <div className="lux-hrms-dash__sentiment-head">
                      <span>{row.label}</span>
                      <strong>
                        {row.completed}/{row.total}
                      </strong>
                    </div>
                    <div className="lux-hrms-dash__sentiment-bar">
                      <span style={{ width: `${row.pct}%` }} />
                    </div>
                    <small>{row.pct}% complete</small>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </article>

        <article className="lux-hrms-dash__chart-panel">
          <div className="lux-hrms-dash__panel-head">
            <div>
              <h3 className="lux-hrms-dash__panel-title">Case status mix</h3>
              <p className="lux-hrms-dash__panel-sub">
                Distribution of {isOffboarding ? "offboarding" : "onboarding"} cases by status
              </p>
            </div>
          </div>
          <div className="lux-hrms-dash__chart-body">
            {loading && <LuxChartPanelSkeleton height={240} className="lux-hrms-dash__empty" />}
            {!loading && !statusChart && (
              <p className="lux-hrms-dash__empty">No status data to display.</p>
            )}
            {!loading && statusChart && (
              <DashboardApexChart
                type="donut"
                series={statusChart.series}
                options={statusChart.options}
                height={240}
              />
            )}
          </div>
        </article>
      </div>

      <div className="lux-onb-insights__highlights" role="list">
        <article className="lux-onb-insights__highlight is-primary" role="listitem">
          <span className="lux-onb-insights__highlight-icon" aria-hidden>
            <i className="fe fe-activity" />
          </span>
          <div>
            <span className="lux-onb-insights__highlight-label">
              {isOffboarding ? "Exit readiness" : "Onboarding-to-productivity"}
            </span>
            <strong>{insights.productivityScore}%</strong>
            <small>Average checklist readiness</small>
          </div>
        </article>

        <article className="lux-onb-insights__highlight is-green" role="listitem">
          <span className="lux-onb-insights__highlight-icon" aria-hidden>
            <i className={`fe ${isOffboarding ? "fe-lock" : "fe-file-text"}`} />
          </span>
          <div>
            <span className="lux-onb-insights__highlight-label">
              {isOffboarding ? "Access revocation" : "Document completion"}
            </span>
            <strong>
              {isOffboarding
                ? insights.accessReadinessPct != null
                  ? `${insights.accessReadinessPct}%`
                  : "—"
                : insights.documentCompletionPct != null
                  ? `${insights.documentCompletionPct}%`
                  : "—"}
            </strong>
            <small>{isOffboarding ? "Access tasks complete" : "Document tasks complete"}</small>
          </div>
        </article>

        <article className="lux-onb-insights__highlight is-violet" role="listitem">
          <span className="lux-onb-insights__highlight-icon" aria-hidden>
            <i className={`fe ${isOffboarding ? "fe-package" : "fe-monitor"}`} />
          </span>
          <div>
            <span className="lux-onb-insights__highlight-label">
              {isOffboarding ? "Asset return" : "IT access readiness"}
            </span>
            <strong>
              {isOffboarding
                ? (() => {
                    const row = insights.categoryReadiness.find((item) => item.id === "Assets");
                    return row ? `${row.pct}%` : "—";
                  })()
                : insights.accessReadinessPct != null
                  ? `${insights.accessReadinessPct}%`
                  : "—"}
            </strong>
            <small>{isOffboarding ? "Asset tasks complete" : "Provisioning tasks complete"}</small>
          </div>
        </article>

        <article
          className={classNames("lux-onb-insights__highlight", {
            "is-rose": insights.overdueTasks > 0,
            "is-neutral": insights.overdueTasks === 0,
          })}
          role="listitem"
        >
          <span className="lux-onb-insights__highlight-icon" aria-hidden>
            <i className="fe fe-clock" />
          </span>
          <div>
            <span className="lux-onb-insights__highlight-label">Overdue tasks</span>
            <strong>{insights.overdueTasks}</strong>
            <small>Across visible cases</small>
          </div>
        </article>
      </div>
    </section>
  );
}

export default LifecycleInsightsCharts;
