import moment from "moment";
import { commonUtils } from "_helpers";

export function getHolidayDateMeta(holidayDate) {
  const date = moment(holidayDate);
  const today = moment().startOf("day");
  const diff = date.diff(today, "days");

  if (diff < 0) {
    return { tone: "slate", badge: "Past", relative: date.fromNow() };
  }
  if (diff === 0) {
    return { tone: "green", badge: "Today", relative: "Today" };
  }
  if (diff === 1) {
    return { tone: "amber", badge: "Tomorrow", relative: "Tomorrow" };
  }
  if (diff <= 7) {
    return { tone: "sky", badge: "This week", relative: `In ${diff} days` };
  }
  return { tone: "indigo", badge: "Upcoming", relative: `In ${diff} days` };
}

export function summarizeHolidays(items) {
  const list = items || [];
  const today = moment().startOf("day");
  let upcoming = 0;
  let thisMonth = 0;
  let past = 0;
  let nextHoliday = null;

  list.forEach((item) => {
    const date = moment(item.holidayDate);
    if (date.isBefore(today, "day")) {
      past += 1;
    }
    if (date.isSameOrAfter(today, "day")) {
      upcoming += 1;
      if (!nextHoliday || date.isBefore(nextHoliday.date)) {
        nextHoliday = { date, name: item.name };
      }
    }
    if (date.isSame(today, "month")) {
      thisMonth += 1;
    }
  });

  return { total: list.length, upcoming, thisMonth, past, nextHoliday };
}

export const HOLIDAY_GROUP_BY = {
  MONTH: "MONTH",
  LOCATION: "LOCATION",
  YEAR: "YEAR",
};

export const HOLIDAY_VIEW_MODE = {
  CALENDAR: "CALENDAR",
  LIST: "LIST",
};

export const ALL_LOCATIONS = "ALL";
export const NO_LOCATION_KEY = "__NONE__";

export function getHolidayLocations(item) {
  if (!item) {
    return [];
  }
  if (Array.isArray(item.locations)) {
    return item.locations.map((loc) => String(loc).trim()).filter(Boolean);
  }
  if (typeof item.locations === "string" && item.locations.trim()) {
    const raw = item.locations.trim();
    if (raw.startsWith("[")) {
      try {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          return parsed.map((loc) => String(loc).trim()).filter(Boolean);
        }
      } catch (e) {
        // fall through to delimiter split
      }
    }
    return raw
      .split(/[,|;]/)
      .map((loc) => loc.trim())
      .filter(Boolean);
  }
  return [];
}

/** Map holiday items to YYYY-MM-DD → items[] for calendar cells. */
export function indexHolidaysByDate(items) {
  const map = {};
  (items || []).forEach((item) => {
    const key = moment(item.holidayDate).format("YYYY-MM-DD");
    if (!map[key]) {
      map[key] = [];
    }
    map[key].push(item);
  });
  Object.keys(map).forEach((key) => {
    map[key].sort((a, b) => String(a.name || "").localeCompare(String(b.name || "")));
  });
  return map;
}

/** Build 6-week month grid for holiday calendar (Sun–Sat headers).
 *  {@code workdays} optional ISO 1=Mon … 7=Sun; default Mon–Fri (Sat/Sun weekly off). */
export function buildHolidayMonthGrid(anchorMoment, workdays) {
  const anchor = moment(anchorMoment).startOf("month");
  const gridStart = anchor.clone().startOf("week");
  const today = moment().startOf("day");
  const workdaySet = normalizeIsoWorkdays(workdays);
  const days = [];
  for (let i = 0; i < 42; i += 1) {
    const day = gridStart.clone().add(i, "days");
    days.push({
      key: day.format("YYYY-MM-DD"),
      moment: day,
      dayOfMonth: day.date(),
      isCurrentMonth: day.isSame(anchor, "month"),
      isToday: day.isSame(today, "day"),
      isWeekend: !workdaySet.has(day.isoWeekday()),
      isPast: day.isBefore(today, "day"),
    });
  }
  return days;
}

function normalizeIsoWorkdays(workdays) {
  const defaults = new Set([1, 2, 3, 4, 5]);
  if (!Array.isArray(workdays) || !workdays.length) return defaults;
  const out = new Set(
    workdays.map(Number).filter((n) => Number.isInteger(n) && n >= 1 && n <= 7)
  );
  return out.size ? out : defaults;
}

export function collectHolidayLocationKeys(items) {
  const keys = new Set();
  (items || []).forEach((item) => {
    const locs = getHolidayLocations(item);
    if (locs.length === 0) {
      keys.add(NO_LOCATION_KEY);
      return;
    }
    locs.forEach((loc) => keys.add(loc));
  });
  return Array.from(keys).sort((a, b) => {
    if (a === NO_LOCATION_KEY) return 1;
    if (b === NO_LOCATION_KEY) return -1;
    return a.localeCompare(b);
  });
}

export function filterHolidays(items, { statusFilter = "ALL", year, query = "", locationKey = ALL_LOCATIONS } = {}) {
  const today = moment().startOf("day");
  const q = String(query || "").trim().toLowerCase();

  return (items || [])
    .filter((item) => {
      const date = moment(item.holidayDate);
      if (year && date.year() !== Number(year)) {
        return false;
      }
      if (statusFilter === "UPCOMING" && date.isBefore(today, "day")) {
        return false;
      }
      if (statusFilter === "PAST" && date.isSameOrAfter(today, "day")) {
        return false;
      }
      if (statusFilter === "THIS_MONTH" && !date.isSame(today, "month")) {
        return false;
      }
      if (locationKey && locationKey !== ALL_LOCATIONS) {
        const locs = getHolidayLocations(item);
        if (locationKey === NO_LOCATION_KEY) {
          if (locs.length > 0) {
            return false;
          }
        } else if (!locs.some((loc) => loc.toLowerCase() === String(locationKey).toLowerCase())) {
          return false;
        }
      }
      if (!q) {
        return true;
      }
      const haystack = [item.name, item.description, ...getHolidayLocations(item)]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(q);
    })
    .sort((a, b) => moment(a.holidayDate).valueOf() - moment(b.holidayDate).valueOf());
}

function pushGroupedItem(map, key, label, sortKey, item) {
  if (!map.has(key)) {
    map.set(key, { id: key, label, sortKey, items: [] });
  }
  map.get(key).items.push(item);
}

/**
 * Group filtered holidays for readable browsing.
 * @param {Array} items already filtered/sorted holidays
 * @param {"MONTH"|"LOCATION"|"YEAR"} groupBy
 */
export function groupHolidays(items, groupBy = HOLIDAY_GROUP_BY.MONTH) {
  const map = new Map();
  const list = items || [];

  if (groupBy === HOLIDAY_GROUP_BY.YEAR) {
    list.forEach((item) => {
      const date = moment(item.holidayDate);
      const year = date.year();
      pushGroupedItem(map, `year-${year}`, String(year), year, item);
    });
  } else if (groupBy === HOLIDAY_GROUP_BY.LOCATION) {
    list.forEach((item) => {
      const locs = getHolidayLocations(item);
      if (locs.length === 0) {
        pushGroupedItem(map, NO_LOCATION_KEY, "All locations (no key)", "~~~~", item);
        return;
      }
      locs.forEach((loc) => {
        pushGroupedItem(map, `loc-${loc}`, loc, loc.toLowerCase(), item);
      });
    });
  } else {
    // Default: by month (within selected year filter)
    list.forEach((item) => {
      const date = moment(item.holidayDate);
      const key = date.format("YYYY-MM");
      const label = date.format("MMMM YYYY");
      pushGroupedItem(map, `month-${key}`, label, key, item);
    });
  }

  return Array.from(map.values()).sort((a, b) => {
    if (a.sortKey < b.sortKey) return -1;
    if (a.sortKey > b.sortKey) return 1;
    return 0;
  });
}

export function buildHolidayInsights(summary) {
  const insights = [];
  if (summary.nextHoliday) {
    insights.push({
      id: "next",
      tone: "indigo",
      icon: "fe fe-calendar",
      title: `Next: ${summary.nextHoliday.name}`,
      copy: summary.nextHoliday.date.format("dddd, D MMMM YYYY"),
    });
  }
  if (summary.thisMonth > 0) {
    insights.push({
      id: "month",
      tone: "sky",
      icon: "fe fe-sun",
      title: `${summary.thisMonth} holiday${summary.thisMonth === 1 ? "" : "s"} this month`,
      copy: "Reflected in leave, timesheet, and attendance calendars",
    });
  }
  if (summary.upcoming === 0 && summary.total > 0) {
    insights.push({
      id: "none-upcoming",
      tone: "amber",
      icon: "fe fe-info",
      title: "No upcoming holidays",
      copy: "Add dates for the rest of the year to keep teams aligned",
    });
  }
  return insights;
}

export function parseHolidayImportText(text) {
  const lines = (text || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);

  return lines.map((line, index) => {
    const parts = line.split(",").map((part) => part.trim());
    if (parts.length < 2) {
      throw new Error(`Line ${index + 1}: expected name,date[,description]`);
    }
    const [name, datePart, description] = parts;
    const holidayDate = moment(datePart, ["YYYY-MM-DD", "DD/MM/YYYY", "MM/DD/YYYY"], true);
    if (!holidayDate.isValid()) {
      throw new Error(`Line ${index + 1}: invalid date "${datePart}"`);
    }
    return {
      name,
      description: description || name,
      holidayDate: holidayDate.startOf("day").format("YYYY-MM-DDTHH:mm:ss"),
      createdBy: commonUtils.getCurrentUserId(),
      userTeamId: commonUtils.getCurrentUserTeamId(),
      locations: [],
    };
  });
}
