import React from "react";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import { getProjectDetailsReturnTarget } from "../projectDetailsNavigation.utils";

export default function ProjectDetailsBackNav({ location, projectRef }) {
  const { path, label } = getProjectDetailsReturnTarget(location);

  return (
    <LuxBackNav
      to={path}
      destinationLabel={label}
      currentLabel={projectRef || undefined}
    />
  );
}
