import React, { Component } from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import { employeeActions } from "_actions";
import { employeeConstants } from "_constants";
import { accessUtils, commonUtils, store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxCalendarNav from "views/common/fragments/LuxCalendarNav";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import AttendanceCurrentUserPanel from "views/hrms/components/attendance/AttendanceCurrentUserPanel";
import AttendanceMarkPopover from "views/hrms/components/attendance/AttendanceMarkPopover";
import AttendanceDetailsPopover from "views/hrms/components/attendance/AttendanceDetailsPopover";
import CollapsibleAuditPanel from "views/common/fragments/CollapsibleAuditPanel";
import { AUDIT_ENTITY_TYPES, AUDIT_SCOPES } from "_constants/audit.constants";
import {
  getEmployeeStats,
  isAttendanceAwaitingManagerAction,
  canMarkAttendanceFor,
  canRemoveAttendanceFor,
} from "views/hrms/components/attendance/attendance.utils";
import {
  buildAttendanceTabStats,
  isEmployee360ViewingSelf,
} from "config/employee360Tab.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";

class Employee360AttendanceTab extends Component {
  state = {
    selectedDate: dateUtils.convertDateToMoment(new Date()),
    monthDays: [],
    permission: accessUtils.getEmployeeAttendanceAccessControl(),
    markPopover: null,
    detailsPopover: null,
  };

  componentDidMount() {
    this.refreshMonthDates(this.state.selectedDate);
    const userTeams = commonUtils.getUserTeams(this.props.userTeams);
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams,
    });
    this.reloadEmployeeItems(userTeams);
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.employee && prevProps.employee.id;
    const nextId = this.props.employee && this.props.employee.id;
    if (prevId !== nextId) {
      this.refreshMonthDates(this.state.selectedDate);
    }
  }

  reloadEmployeeItems = (userTeams) => {
    const selectedUserTeams = [];
    userTeams &&
      userTeams.forEach((userTeam) => {
        if (userTeam.isChecked) selectedUserTeams.push(userTeam.id);
      });
    if (selectedUserTeams.length > 0) {
      store.dispatch(
        this.props.getTeamsEmployees(selectedUserTeams, this.props.filterOptions || {})
      );
    }
  };

  refreshMonthDates = (date) => {
    this.setState(
      {
        selectedDate: date,
        monthDays: dateUtils.getDaysArrayByMonth(date),
      },
      () => this.getTeamsAttendance(commonUtils.getUserTeams(this.props.userTeams))
    );
  };

  getTeamsAttendance = (userTeams) => {
    const range = dateUtils.getFirstAndLastDayofMonth(this.state.selectedDate);
    const startDate = range[0];
    const endDate = range[1];
    const selected = (userTeams || [])
      .filter((userTeam) => userTeam && userTeam.isChecked)
      .map((userTeam) => userTeam.id);
    const selectedUserTeams = commonUtils.resolveUserTeamIds(
      selected.length ? selected : null
    );
    if (selectedUserTeams.length > 0) {
      store.dispatch(
        this.props.getTeamsAttendance({
          userTeamIds: selectedUserTeams,
          startDate: startDate.format(dateUtils.SERVER_DATE_FORMAT),
          endDate: endDate.format(dateUtils.SERVER_DATE_FORMAT),
        })
      );
    }
  };

  goToNext = () => {
    this.refreshMonthDates(this.state.selectedDate.clone().add(1, "months"));
  };

  goToBack = () => {
    this.refreshMonthDates(this.state.selectedDate.clone().subtract(1, "months"));
  };

  goToCurrent = () => {
    this.refreshMonthDates(dateUtils.getCurrentTime());
  };

  createAttendance = (request) => {
    store.dispatch(this.props.createAttendance(request));
  };

  deleteAttendance = (id) => {
    store.dispatch(this.props.deleteAttendance({ id }));
  };

  openMarkPopover = (employeeId, employeeName, markDate, existingItem = null) => {
    const { permission } = this.state;
    if (!canMarkAttendanceFor(permission, employeeId, commonUtils.getCurrentUserId())) {
      return;
    }
    this.setState({
      markPopover: { employeeId, employeeName, markDate, existingItem },
      detailsPopover: null,
    });
  };

  closeMarkPopover = () => {
    this.setState({ markPopover: null });
  };

  openDetailsPopover = (employeeId, employeeName, markDate, item) => {
    this.setState({
      detailsPopover: { employeeId, employeeName, markDate, item },
      markPopover: null,
    });
  };

  closeDetailsPopover = () => {
    this.setState({ detailsPopover: null });
  };

  resubmitAttendance = (employeeId, employeeName, markDate, item) => {
    this.openMarkPopover(employeeId, employeeName, markDate, item);
  };

  requestRemovalAttendance = (attendanceId) => {
    const { permission, detailsPopover } = this.state;
    const targetEmployeeId =
      (detailsPopover && detailsPopover.employeeId) ||
      (detailsPopover && detailsPopover.item && detailsPopover.item.employeeId);
    if (!canRemoveAttendanceFor(permission, targetEmployeeId, commonUtils.getCurrentUserId())) {
      return;
    }
    store.dispatch(
      this.props.requestAttendanceRemoval({
        id: attendanceId,
        requestedBy: commonUtils.getCurrentUserId(),
        onSuccess: () => this.closeDetailsPopover(),
      })
    );
  };

  submitMarkAttendance = (details) => {
    const { markPopover } = this.state;
    if (!markPopover) return;

    this.createAttendance({
      employeeId: markPopover.employeeId,
      markDate: details.markDate,
      markTime: details.markTime,
      hours: details.hours,
      checkoutTime: details.checkoutTime,
      markedBy: commonUtils.getCurrentUserId(),
    });
    this.closeMarkPopover();
  };

  approveAttendance = (attendanceId, approvalComment, attendanceItem) => {
    store.dispatch(
      this.props.approveAttendance({
        id: attendanceId,
        approverId: commonUtils.getCurrentUserId(),
        approvalComment: approvalComment ? approvalComment.trim() : null,
        removalRequest:
          attendanceItem && attendanceItem.status === "PENDING_REMOVAL",
        onSuccess: () => this.closeDetailsPopover(),
      })
    );
  };

  rejectAttendance = (attendanceId, approvalComment, attendanceItem) => {
    const comment = approvalComment ? approvalComment.trim() : "";
    if (!comment) return;

    store.dispatch(
      this.props.rejectAttendance({
        id: attendanceId,
        approverId: commonUtils.getCurrentUserId(),
        approvalComment: comment,
        onSuccess: () => this.closeDetailsPopover(),
      })
    );
  };

  render() {
    const { employee, items, isLoading, employees } = this.props;
    const { monthDays, permission, markPopover, detailsPopover, selectedDate } = this.state;

    if (!employee) {
      return null;
    }

    if (!permission || permission.viewEnabled !== true) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-employee-360__embed-empty"
          icon="fe fe-lock"
          title="Attendance not available"
          description="You do not have permission to view attendance for this employee."
        />
      );
    }

    const currentUserId = commonUtils.getCurrentUserId();
    const focusEmployee =
      (employees || []).find((emp) => String(emp.id) === String(employee.id)) || employee;
    const focusStats = getEmployeeStats(focusEmployee.id, items, monthDays);
    const isViewingSelf = isEmployee360ViewingSelf(focusEmployee, currentUserId);
    const stats = buildAttendanceTabStats(focusStats, selectedDate);
    const displayName = getEmployeeDisplayName(focusEmployee);

    return (
      <ProjectDetailsTabShell
        icon="fe fe-clock"
        eyebrow="Workforce time"
        title="Attendance"
        subtitle={
          isViewingSelf
            ? "Your monthly attendance marks, approvals, and compliance trail."
            : `Monthly attendance for ${displayName}.`
        }
        stats={stats}
        className="lux-employee-360__embed lux-employee-360__embed--attendance"
      >
        <div className="lux-employee-360__embed-toolbar">
          <strong className="lux-employee-360__embed-period">
            {selectedDate.format("MMMM YYYY")}
          </strong>
          <LuxCalendarNav
            onBack={this.goToBack}
            onToday={this.goToCurrent}
            onNext={this.goToNext}
            disabled={isLoading}
          />
          <Link to="/people/attendance" className="lux-employee-360__embed-link">
            Open full attendance
            <i className="fe fe-external-link" aria-hidden="true" />
          </Link>
        </div>

        {focusEmployee && !isLoading && (
          <AttendanceCurrentUserPanel
            employee={focusEmployee}
            stats={focusStats}
            monthDays={monthDays}
            items={items}
            permission={permission}
            isLoading={isLoading}
            isViewingSelf={isViewingSelf}
            currentUserId={currentUserId}
            createAttendance={this.createAttendance}
            deleteAttendance={this.deleteAttendance}
            onRequestMark={this.openMarkPopover}
            onRequestViewDetails={this.openDetailsPopover}
          />
        )}

        {isLoading && !items && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-employee-360__embed-empty"
            variant="attendance"
            title="Loading attendance"
            description="Fetching monthly marks for this employee."
          />
        )}

        <AttendanceMarkPopover
          show={!!markPopover}
          employeeId={markPopover && markPopover.employeeId}
          employeeName={markPopover && markPopover.employeeName}
          markDate={markPopover && markPopover.markDate}
          existingItem={markPopover && markPopover.existingItem}
          isLoading={isLoading}
          onClose={this.closeMarkPopover}
          onSubmit={this.submitMarkAttendance}
        />

        <AttendanceDetailsPopover
          show={!!detailsPopover}
          employeeId={detailsPopover && detailsPopover.employeeId}
          employeeName={detailsPopover && detailsPopover.employeeName}
          markDate={detailsPopover && detailsPopover.markDate}
          attendanceItem={detailsPopover && detailsPopover.item}
          isLoading={isLoading}
          canRequestRemoval={
            detailsPopover &&
            canRemoveAttendanceFor(
              permission,
              detailsPopover.employeeId,
              currentUserId
            )
          }
          canResubmit={
            detailsPopover &&
            canMarkAttendanceFor(
              permission,
              detailsPopover.employeeId,
              currentUserId
            )
          }
          canApprove={
            detailsPopover &&
            detailsPopover.item &&
            (employees || []).some(
              (emp) =>
                String(emp.id) === String(detailsPopover.item.employeeId) &&
                String(emp.managerId) === String(currentUserId)
            )
          }
          permission={permission}
          showRemindApprover={
            detailsPopover &&
            detailsPopover.item &&
            String(detailsPopover.employeeId) === String(currentUserId) &&
            isAttendanceAwaitingManagerAction(detailsPopover.item)
          }
          onClose={this.closeDetailsPopover}
          onResubmit={this.resubmitAttendance}
          onRequestRemoval={this.requestRemovalAttendance}
          onApprove={this.approveAttendance}
          onReject={this.rejectAttendance}
          employees={employees || []}
        />

        <div className="lux-page-audit-footer lux-employee-360__embed-audit">
          <CollapsibleAuditPanel
            panelKey={`employee-360-attendance-${focusEmployee.id}`}
            title={isViewingSelf ? "Your attendance audit" : `${displayName}'s attendance audit`}
            subtitle="Marks, edits, approvals, and rejections on attendance records"
            icon="fe-calendar"
            auditProps={{
              scope: AUDIT_SCOPES.ACTOR,
              actorUserId: focusEmployee.id,
              lockedEntityFilter: AUDIT_ENTITY_TYPES.ATTENDANCE,
              showEntityFilters: false,
              emptyState: {
                eyebrow: "Attendance compliance",
                title: "No attendance audit events yet",
                description:
                  "When audit logging is enabled, mark and approval actions will appear here.",
              },
            }}
          />
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

const mapStateToProps = (state) => ({
  employees: commonUtils.filterEmployees(
    state.employees.teamEmployees &&
      commonUtils.getActiveEmployees(state.employees.teamEmployees),
    state.employees.filterOptionsA
  ),
  isLoading: state.employees.attendanceLoading,
  items: state.employees.attendanceItems,
  filterOptions: state.employees.filterOptionsA,
  userTeams: commonUtils.getUserTeams(state.employees.userTeamsA),
});

const mapDispatchToProps = () => ({
  getTeamsEmployees: employeeActions.getTeamsEmployees,
  getTeamsAttendance: employeeActions.getTeamsAttendance,
  createAttendance: employeeActions.createAttendance,
  approveAttendance: employeeActions.approveAttendance,
  rejectAttendance: employeeActions.rejectAttendance,
  requestAttendanceRemoval: employeeActions.requestAttendanceRemoval,
  deleteAttendance: employeeActions.deleteAttendance,
});

export default connect(mapStateToProps, mapDispatchToProps)(Employee360AttendanceTab);
