function formatMetricValue(metric, seed) {
  const value = seed ? seed.value : 0;
  if (metric.format === METRIC_FORMATS.PERCENT) {
    return `${value}%`;
  }
  if (metric.format === METRIC_FORMATS.CURRENCY) {
    return value >= 1000 ? `$${Math.round(value / 1000)}k` : `$${value}`;
  }
  if (metric.format === METRIC_FORMATS.DAYS) {
    return `${value}d`;
  }
  return String(value);
}

export function buildMetricCatalog(metrics = []) {
  return metrics.map((row) => normalizeMetricDefinition(row)).filter(Boolean);
}

export function getMetricsForDomain(metrics = [], domain) {
  return buildMetricCatalog(metrics).filter((row) => row.domain === domain);
}

export function getDashboardConfigForDomain(configs = [], domain) {
  return normalizeDashboardConfig((configs || []).find((row) => row.domain === domain));
}

export function resolveMetricSeed(metric) {
  const domainSeeds = DOMAIN_SEED_VALUES[metric.domain] || {};
  if (domainSeeds[metric.id]) {
    return domainSeeds[metric.id];
  }
  return { value: 0, trend: "—", tone: "slate" };
}

export function buildDomainKpiCards(metrics = []) {
  return metrics.slice(0, 6).map((metric) => {
    const seed = resolveMetricSeed(metric);
    return {
      id: metric.id,
      label: metric.label,
      value: formatMetricValue(metric, seed),
      hint: seed.trend,
      tone: seed.tone,
      icon: "fe fe-activity",
    };
  });
}

export function buildDomainChartSeries(metrics = [], count = 6) {
  return metrics.slice(0, count).map((metric) => {
    const seed = resolveMetricSeed(metric);
    return {
      label: metric.label,
      value: Number(seed.value) || 0,
      tone: seed.tone,
      meta: seed.trend,
    };
  });
}

