export function buildDomainDashboardModel(domain, context = {}) {
  const { metrics = [], dashboardConfigs = [] } = context;
  const domainMetrics = getMetricsForDomain(metrics, domain);
  const config = getDashboardConfigForDomain(dashboardConfigs, domain);
  const kpiCards = buildDomainKpiCards(domainMetrics);
  const chartSeries = buildDomainChartSeries(domainMetrics);
  const insights = buildDomainInsights(domain, domainMetrics);

  const widgets = (config && config.widgets) || [
    { id: "kpi", type: DASHBOARD_WIDGET_TYPES.KPI_STRIP, title: "Key metrics" },
    { id: "chart", type: DASHBOARD_WIDGET_TYPES.BAR_CHART, title: "Trend comparison" },
    { id: "insights", type: DASHBOARD_WIDGET_TYPES.INSIGHT_STRIP, title: "Steering signals" },
  ];

  return {
    domain,
    config,
    metricCount: domainMetrics.length,
    kpiCards,
    chartSeries,
    insights,
    widgets,
    metrics: domainMetrics,
  };
}

export function buildAnalyticsHubOverview(context = {}) {
  const { metrics = [], dashboardConfigs = [] } = context;
  const domains = Object.values(ANALYTICS_DOMAINS);
  return domains.map((domain) => {
    const model = buildDomainDashboardModel(domain, { metrics, dashboardConfigs });
    return {
      domain,
      metricCount: model.metricCount,
      headline: model.kpiCards[0] ? model.kpiCards[0].value : "—",
      headlineLabel: model.kpiCards[0] ? model.kpiCards[0].label : "Metrics",
      insight: model.insights[0] ? model.insights[0].title : "Dashboard ready",
    };
  });
}

