export function validateDashboardConfigPayload(payload = {}) {
  if (!payload.domain) {
    throw new Error("Dashboard config domain is required");
  }
  if (!payload.name || !String(payload.name).trim()) {
    throw new Error("Dashboard config name is required");
  }
  return true;
}

/** F24-T3 — Execute report query against metric catalog */
export function executeReportQuery(query = {}, context = {}) {
  const { metrics = [] } = context;
  const normalized = {
    domain: query.domain || null,
    metricIds: Array.isArray(query.metricIds) ? query.metricIds : [],
    filters: query.filters || {},
  };

  let scoped = metrics;
  if (normalized.domain) {
    scoped = getMetricsForDomain(scoped, normalized.domain);
  }
  if (normalized.metricIds.length) {
    const idSet = new Set(normalized.metricIds);
    scoped = scoped.filter((row) => idSet.has(row.id));
  }

  const rows = scoped.map((metric) => {
    const seed = resolveMetricSeed(metric);
    return {
      metricId: metric.id,
      label: metric.label,
      code: metric.code,
      domain: metric.domain,
      format: metric.format,
      value: formatMetricValue(metric, seed),
      rawValue: seed.value,
      trend: seed.trend,
      sourceModule: metric.sourceModule,
      sensitive: metric.sensitive === true,
    };
  });

  return {
    generatedAt: new Date().toISOString().slice(0, 10),
    domain: normalized.domain,
    metricIds: normalized.metricIds,
    rowCount: rows.length,
    columns: [
      { id: "label", label: "Metric" },
      { id: "value", label: "Value" },
      { id: "trend", label: "Trend" },
      { id: "domain", label: "Domain" },
      { id: "sourceModule", label: "Source" },
    ],
    rows,
  };
}

export function buildReportPreview(savedReport, context = {}) {
  if (!savedReport) {
    return null;
  }
  return executeReportQuery(
    {
      domain: savedReport.domain,
      metricIds: savedReport.metricIds,
    },
    context
  );
}

export function validateReportPayload(payload = {}) {
  if (!payload.name || !String(payload.name).trim()) {
    throw new Error("Report name is required");
  }
  const metricIds = Array.isArray(payload.metricIds) ? payload.metricIds : [];
  if (!metricIds.length) {
    throw new Error("At least one metric is required");
  }
  return true;
}

export function validateScheduledReportPayload(payload = {}) {
  if (!payload.reportId && !payload.reportName) {
    throw new Error("Scheduled report requires a linked report");
  }
  if (!payload.frequency) {
    throw new Error("Schedule frequency is required");
  }
  return true;
}

export function validateSavedFilterPayload(payload = {}) {
  if (!payload.name || !String(payload.name).trim()) {
    throw new Error("Saved filter name is required");
  }
  return true;
}

export function applySavedFilterToQuery(savedFilter, baseQuery = {}) {
  if (!savedFilter) {
    return baseQuery;
  }
  return {
    ...baseQuery,
    domain: savedFilter.domain || baseQuery.domain || null,
    metricIds: savedFilter.metricIds && savedFilter.metricIds.length
      ? savedFilter.metricIds
      : baseQuery.metricIds || [],
    filters: { ...(baseQuery.filters || {}), ...(savedFilter.filters || {}) },
  };
}

export function maskSensitiveReportRows(rows = [], options = {}) {
  const includeSensitive = options.includeSensitive === true;
  if (includeSensitive) {
    return rows;
  }
  return rows.map((row) => {
    if (!row.sensitive) {
      return row;
    }
    return {
      ...row,
      value: "••••",
      rawValue: null,
      trend: "Masked",
      masked: true,
    };
  });
}

export function executeReportQueryWithSecurity(query = {}, context = {}, options = {}) {
  const result = executeReportQuery(query, context);
  return {
    ...result,
    rows: maskSensitiveReportRows(result.rows, options),
  };
}

export function exportReportResultCsv(result, options = {}) {
  const secured = result && result.rows
    ? { ...result, rows: maskSensitiveReportRows(result.rows, options) }
    : result;
  if (!secured || !secured.rows || !secured.rows.length) {
    return "";
  }
  const header = "metric,code,value,trend,domain,source_module,sensitive,masked";
  const lines = secured.rows.map((row) => {
    const cells = [
      row.label,
      row.code,
      row.value,
      row.trend,
      row.domain,
      row.sourceModule,
      row.sensitive ? "yes" : "no",
      row.masked ? "yes" : "no",
    ];
    return cells.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(",");
  });
  return [header, ...lines].join("\n");
}

/** F24-T7 — Rule-based analytics insight draft (F17 gateway deferred) */
export function buildAnalyticsAiInsightDraft(dashboard, domain) {
  if (!dashboard) {
    return null;
  }
  const kpiCards = dashboard.kpiCards || [];
  const insights = dashboard.insights || [];
  const weakKpi = kpiCards.find((row) => {
    const num = parseInt(String(row.value).replace(/[^\d.-]/g, ""), 10);
    return Number.isFinite(num) && num < 70;
  });
  const topInsight = insights[0];

  const bullets = [];
  if (weakKpi) {
    bullets.push(`${weakKpi.label} is at ${weakKpi.value} (${weakKpi.hint}) — prioritize remediation this week.`);
  }
  if (topInsight) {
    bullets.push(`${topInsight.title}: ${topInsight.copy || topInsight.body}`);
  }
  if (!bullets.length && kpiCards.length) {
    bullets.push(`${kpiCards[0].label} is ${kpiCards[0].value}; domain metrics are within expected demo tolerance.`);
  }

  return {
    domain: domain || dashboard.domain,
    summary: bullets.join(" "),
    recommendation: weakKpi
      ? `Open the ${domain || "domain"} drill-down and validate root cause before the next steering review.`
      : "Continue monitoring; no critical threshold breaches detected in the demo catalog.",
    confidence: weakKpi ? 0.78 : 0.62,
    evidence: kpiCards.slice(0, 3).map((row) => `${row.label}: ${row.value}`),
    disclaimer: "Draft insight generated locally. AI gateway will replace this stub when live.",
  };
}

/** F24-T8 — Large catalog for performance tests */
export function generateLargeAnalyticsCatalog(metricCount = 200) {
  const domains = Object.values(ANALYTICS_DOMAINS);
  const metrics = [];
  for (let i = 0; i < metricCount; i += 1) {
    const domain = domains[i % domains.length];
    metrics.push(
      normalizeMetricDefinition({
        id: `metric-perf-${i}`,
        domain,
        code: `PERF_${i}`,
        label: `Performance metric ${i}`,
        format: i % 3 === 0 ? METRIC_FORMATS.PERCENT : METRIC_FORMATS.NUMBER,
        sourceModule: "",
        sensitive: i % 17 === 0,
      })
    );
  }
  return metrics.filter(Boolean);
}
