import React from "react";
import classNames from "classnames/bind";

export default function SettingsPageNav({ tabs, activeTab, onChange }) {
  if (!tabs || tabs.length === 0) return null;

  return (
    <nav className="lux-hrms-settings__nav" aria-label="Settings sections">
      {tabs.map((tab) => (
        <button
          key={tab.id}
          type="button"
          className={classNames("lux-hrms-settings__nav-item", {
            "is-active": activeTab === tab.id,
          })}
          onClick={() => onChange && onChange(tab.id)}
          aria-current={activeTab === tab.id ? "page" : undefined}
          aria-label={
            tab.badge
              ? `${tab.label}, ${tab.badge} ${tab.badge === "1" ? "issue" : "issues"}`
              : undefined
          }
        >
          <span className="lux-hrms-settings__nav-icon" aria-hidden="true">
            <i className={tab.icon} />
          </span>
          <span className="lux-hrms-settings__nav-label">{tab.label}</span>
          {tab.badge && <span className="lux-hrms-settings__nav-badge">{tab.badge}</span>}
        </button>
      ))}
    </nav>
  );
}
