import React from "react";
import classNames from "classnames/bind";
import { getEmployeeInitials, isOrphanEmployee } from "config/org-structure.utils";

export default function OrgReportingRegister({ employees, selectedId, onSelect, spanCounts = {} }) {
  return (
    <div className="lux-org-unit-register-wrap" data-testid="org-reporting-register">
      <table className="lux-org-unit-register">
        <thead>
          <tr>
            <th>Person</th>
            <th>Title</th>
            <th>Department</th>
            <th>Reports to</th>
            <th>Span</th>
            <th>Location</th>
          </tr>
        </thead>
        <tbody>
          {(employees || []).map((row) => {
            const orphan = isOrphanEmployee(row);
            const span = spanCounts[row.name] || 0;
            return (
              <tr
                key={row.id}
                className={classNames("lux-org-unit-register__row", {
                  "is-selected": String(selectedId) === String(row.id),
                  "is-attention": orphan,
                })}
                onClick={() => onSelect && onSelect(row)}
              >
                <td>
                  <div className="lux-org-unit-register__primary">
                    <span className="lux-org-unit-register__icon is-primary" aria-hidden="true">
                      {getEmployeeInitials(row.name)}
                    </span>
                    <span className="lux-org-unit-register__primary-copy">
                      <strong>{row.name}</strong>
                      <span className="lux-org-unit-register__meta">{row.status || "Active"}</span>
                    </span>
                  </div>
                </td>
                <td>{row.designation || "—"}</td>
                <td>{row.department || "—"}</td>
                <td>
                  {orphan ? <span className="lux-org-unit-register__vacant">Unassigned</span> : row.manager || row.managerName}
                </td>
                <td>{span}</td>
                <td>{row.location || "—"}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
